window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s2-1531","number":1531,"surah":2,"verses":[25],"references":[{"surah":2,"verses":[25]}],"verseLabel":"البقرة: 25","question":"لماذا قال: ﴿وَبَشِّرِ الَّذِينَ آمَنُوا... أَنَّ لَهُمْ جَنَّاتٍ﴾ بلا باء، وقال في الأحزاب: ﴿وَبَشِّرِ الْمُؤْمِنِينَ بِأَنَّ لَهُمْ مِنَ اللَّهِ فَضْلًا كَبِيرًا﴾؟","answer":"آية البقرة موجزة مفردة في ذكر المؤمنين، فناسبها حذف الباء. أما سياق الأحزاب ففصّل في صفات المؤمنين وأحوالهم، فناسب التفصيل والتوكيد ذكر الباء.","sources":[{"label":"السامرائي، أسرار البيان في التعبير القرآني، ص44–45.","url":""}]},{"id":"s2-1532","number":1532,"surah":2,"verses":[86],"references":[{"surah":2,"verses":[86]}],"verseLabel":"البقرة: 86","question":"لماذا خُتم الوعيد هنا بـ﴿وَلَا هُمْ يُنْصَرُونَ﴾، وفي الآية 162 بـ﴿وَلَا هُمْ يُنْظَرُونَ﴾؟","answer":"جاء الأول في سياق القتل والإخراج والأسر، فناسب نفي النصر. وجاء الثاني بعد ذكر اللعنة والخلود، فناسب نفي الإمهال ونظر الرحمة عن المطرودين منها.","sources":[{"label":"السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص14–15.","url":""}]},{"id":"s2-1533","number":1533,"surah":2,"verses":[110],"references":[{"surah":2,"verses":[110]}],"verseLabel":"البقرة: 110","question":"لماذا قال: ﴿تَجِدُوهُ عِنْدَ اللَّهِ﴾، وزاد في المزمل: ﴿هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا﴾؟","answer":"ذُكرت هنا الصلاة والزكاة، وزيد عليهما في المزمل قراءة القرآن والقرض الحسن؛ فناسبت زيادة العمل زيادة الخير وعظم الأجر.","sources":[{"label":"السامرائي، مراعاة المقام في التعبير القرآني، ص11.","url":""}]},{"id":"s2-1534","number":1534,"surah":2,"verses":[143],"references":[{"surah":2,"verses":[143]}],"verseLabel":"البقرة: 143","question":"لماذا حُذف ضمير العائد في ﴿إِلَّا عَلَى الَّذِينَ هَدَى اللَّهُ﴾، وذُكر في الزمر: ﴿الَّذِينَ هَدَاهُمُ اللَّهُ﴾؟","answer":"ذكر الضمير آكد من حذفه. والمقام هنا في اتباع القبلة، أما الزمر ففي الذين يستمعون القول فيتبعون أحسنه، وهي هداية أشمل؛ فناسبها التوكيد بذكر الضمير.","sources":[{"label":"السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص21–25.","url":""}]},{"id":"s2-1535","number":1535,"surah":2,"verses":[159,161],"references":[{"surah":2,"verses":[159,161]}],"verseLabel":"البقرة: 159، 161","question":"لماذا قيل: ﴿يَلْعَنُهُمُ اللَّهُ﴾ بالفعل، ثم قيل: ﴿عَلَيْهِمْ لَعْنَةُ اللَّهِ﴾ بالاسم؟","answer":"الأولى في أحياء يكتمون ما أنزل الله، فتتجدد اللعنة باستمرار كتمانهم، ويظل باب التوبة مفتوحًا. والثانية فيمن ماتوا على الكفر وانقطع عملهم، فجاءت الجملة الاسمية لتناسب ثبوت حالهم.","sources":[{"label":"السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص26.","url":""}]},{"id":"s2-1536","number":1536,"surah":2,"verses":[245],"references":[{"surah":2,"verses":[245]}],"verseLabel":"البقرة: 245","question":"ما التوسع في التعبير بـ﴿قَرْضًا حَسَنًا﴾؟","answer":"يحتمل أن يراد بالقرض ما يُقرض، فيكون مفعولًا به، وأن يراد به الإقراض الحسن، فيكون مفعولًا مطلقًا؛ فجمع التعبير المعنيين.","sources":[{"label":"السامرائي، معاني النحو، ج2، ص162.","url":""}]},{"id":"s2-1537","number":1537,"surah":2,"verses":[282],"references":[{"surah":2,"verses":[282]}],"verseLabel":"البقرة: 282","question":"ما التوسع في قوله: ﴿وَلَا يُضَارَّ كَاتِبٌ وَلَا شَهِيدٌ﴾؟","answer":"الإدغام جمع احتمالين: ألا يوقع غيرهما الضرر بهما، وألا يضرا هما أصحاب الحقوق بتحريف أو امتناع؛ فنهى عن الضرر من الجهتين بلفظ واحد.","sources":[{"label":"السامرائي، أسرار البيان في التعبير القرآني، ص63–64.","url":""}]},{"id":"s2-1538","number":1538,"surah":2,"verses":[285],"references":[{"surah":2,"verses":[285]}],"verseLabel":"البقرة: 285","question":"ما الفرق بين «الغفران» في قوله: ﴿غُفْرَانَكَ رَبَّنَا﴾ و«المغفرة»؟","answer":"استعمل القرآن «الغفران» في طلب المغفرة من الله خاصة. أما «المغفرة» فتأتي في الخبر لا في طلبها، ولا تختص بالله، فقد تكون من العباد كقوله: ﴿قَوْلٌ مَعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِنْ صَدَقَةٍ﴾.","sources":[{"label":"https://quranpedia.net/note/44280","url":""}]},{"id":"s3-780","number":780,"surah":3,"verses":[8],"references":[{"surah":3,"verses":[8]}],"verseLabel":"آل عمران: 8","question":"ما دلالة التعبير بـ﴿بَعْدَ إِذْ هَدَيْتَنَا﴾، وما وجه ملاءمة «بعد» لمقام الدعاء على الثبات؟","answer":"«بعد» ظرف زمان، فجاءت لتصوّر خوف الراسخين من انحراف القلب بعد حصول الهداية؛ فالمطلوب ليس ابتداء الهداية فحسب، بل دوامها وعدم الرجوع عنها. وهذا يختلف عن «خلف» التي يغلب استعمالها في المكان أو فيمن يخلّف الإنسان وراءه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «بعد» و«خلف».؛ العنوان الجزئي: الفروق السياقية بين «بعد» و«خلف».","url":""}]},{"id":"s3-781","number":781,"surah":3,"verses":[8,38,147,193,194],"references":[{"surah":3,"verses":[8,38,147,193,194]}],"verseLabel":"آل عمران: 8، 38، 147، 193، 194","question":"ما دلالة تكرر نداء ﴿رَبَّنَا﴾ والدعاء في محطات متباعدة من السورة، من تثبيت القلوب إلى طلب الذرية والنصر وحسن الخاتمة؟","answer":"تتنوع مواطن الابتلاء، لكن باب الثبات فيها واحد: افتقار العبد إلى ربه. لذلك صاحَب الدعاء فتنة الزيغ، وانتظار الذرية، وشدة القتال، والتفكر في المصير؛ فصار تكرار ﴿ربنا﴾ خيطًا يصل الثبات الفكري والأسري والميداني والأخروي بربوبية الله ورعايته.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، محور الثبات وكثرة الدعاء في سورة آل عمران.؛ العنوان الجزئي: الدعاء أداة الثبات في مسارات السورة.","url":""}]},{"id":"s3-782","number":782,"surah":3,"verses":[10,12],"references":[{"surah":3,"verses":[10,12]}],"verseLabel":"آل عمران: 10، 12","question":"ما وجه الجمع بين نفي نفع الأموال والأولاد، ثم ذكر الغلبة في الدنيا والحشر إلى جهنم؟","answer":"الآيات ترسم مصيرًا كاملًا للكافرين: لا تنفعهم أسباب القوة الدنيوية، ثم يُغلبون في الدنيا، ثم يُحشرون إلى جهنم في الآخرة. فالسياق لا يحصر الخسران في الجزاء الأخروي، بل يجمع بين سقوط الحماية في الدنيا وسوء المآل في الآخرة.","sources":[{"label":"فاضل السامرائي، قبسات من البيان القرآني، ص 139–144.؛ العنوان الجزئي: امتداد عدم الإغناء من الدنيا إلى الآخرة.","url":""}]},{"id":"s3-783","number":783,"surah":3,"verses":[11],"references":[{"surah":3,"verses":[11]}],"verseLabel":"آل عمران: 11","question":"ما دلالة التعبير بـ﴿فَأَخَذَهُمُ اللَّهُ﴾ بعد ﴿بِآيَاتِنَا﴾، وعدم مجيئه بضمير الجمع: «فأخذناهم»؟","answer":"لأن القرآن لا يستعمل ضمير الجمع في مقام الأخذ والعقوبة من غير قرينة قريبة تدل على الإفراد. فجاءت «بآياتنا» بضمير العظمة، ثم أُتبعَت بـ«فأخذهم الله» لتظهر وحدة الفاعل صراحة، وليبرز إسناد الأخذ والعقوبة إلى الله تعالى.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، الجزء الثاني، ص 26.؛ العنوان الجزئي: مناسبة الإظهار في «فأخذهم الله» بعد «بآياتنا».","url":""}]},{"id":"s3-784","number":784,"surah":3,"verses":[12],"references":[{"surah":3,"verses":[12]}],"verseLabel":"آل عمران: 12","question":"ما دلالة حرف الغاية في ﴿وَتُحْشَرُونَ إِلَى جَهَنَّمَ﴾، وما الفرق بينه وبين ﴿وَحَشَرْنَا عَلَيْهِمْ﴾؟","answer":"«إلى» في آية آل عمران تبيّن جهة الانتهاء والمصير: يُجمعون إلى جهنم. أما «عليهم» في آية الأنعام فتفيد جمع الحجج والآيات في مواجهتهم وإقامتها عليهم؛ فالسياق الأول سياق مصير، والثاني سياق إقامة حجة.","sources":[{"label":"فاضل السامرائي، بلاغة «حشرنا عليهم» و«تحشرون إلى جهنم».؛ العنوان الجزئي: دلالة حروف الغاية والمواجهة في مادة «حشر».","url":""}]},{"id":"s3-785","number":785,"surah":3,"verses":[18],"references":[{"surah":3,"verses":[18]}],"verseLabel":"آل عمران: 18","question":"ما دلالة وصف الشهادة الإلهية بأنه ﴿قَائِمًا بِالْقِسْطِ﴾؟","answer":"يفيد الوصف ثبوت القيام بالقسط ودوامه، لا وقوعه في حالة عابرة. فالشهادة بالتوحيد اقترنت ببيان أن الله قائم بالعدل على وجه اللزوم والاستمرار، وفي ذلك جمع بين أصل الاعتقاد وكمال تدبير العالم.","sources":[{"label":"فاضل السامرائي، وقفة «قائمًا بالقسط».؛ العنوان الجزئي: لزوم القيام بالقسط في شهادة التوحيد.","url":""}]},{"id":"s3-786","number":786,"surah":3,"verses":[20],"references":[{"surah":3,"verses":[20]}],"verseLabel":"آل عمران: 20","question":"ما دلالة الفرق بين ﴿أَسْلَمْتُ وَجْهِيَ لِلَّهِ﴾ و﴿مَنْ يُسْلِمْ وَجْهَهُ إِلَى اللَّهِ﴾ في التعبير عن علاقة العبد بربه؟","answer":"«أسلم له» تدل على الانقياد وجعل النفس خالصة لله، وفيها معنى الاختصاص والتمليك. أما «أسلم إليه» فتحتمل معنى دفع الأمر وتفويضه إليه؛ فاختيار اللام في آية آل عمران يصور إخلاص الوجه لله، لا مجرد تفويض الأمر إليه.","sources":[{"label":"فاضل السامرائي، الفرق بين «أسلم لله» و«أسلم إليه»، لمسات بيانية.؛ العنوان الجزئي: دلالة تعدية «أسلم» باللام وبـ«إلى».","url":""}]},{"id":"s3-787","number":787,"surah":3,"verses":[21],"references":[{"surah":3,"verses":[21]}],"verseLabel":"آل عمران: 21","question":"ما سر تكرار ﴿وَضُرِبَتْ عَلَيْهِمُ﴾ في آية آل عمران 112، بعد أن جُمعت الذلة والمسكنة في آية البقرة 61؟","answer":"جمع آية البقرة الوصفين في سياق واحد، أما آل عمران ففصل بينهما وكرر الفعل: ﴿ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ ... وَضُرِبَتْ عَلَيْهِمُ الْمَسْكَنَةُ﴾. هذا التكرار يفيد التعميق والتوكيد، ويناسب سياقًا صُوِّرت فيه الجريمة والعقوبة بصورة أشد، فلا يصح وضع أحد التعبيرين مكان الآخر.","sources":[{"label":"فاضل السامرائي، المقارنة البيانية بين آيات الذلة والمسكنة.؛ العنوان الجزئي: تكرار الفعل في «ضربت عليهم الذلة» و«ضربت عليهم المسكنة».","url":""}]},{"id":"s3-788","number":788,"surah":3,"verses":[21],"references":[{"surah":3,"verses":[21]}],"verseLabel":"آل عمران: 21","question":"ما وجه اختلاف ﴿يَقْتُلُونَ النَّبِيِّينَ﴾ و﴿يَقْتُلُونَ الْأَنْبِيَاءَ﴾، وما الذي يضيفه اختلاف الجمع إلى شدة الجريمة؟","answer":"جاء «النبيين» في سياق، و«الأنبياء» في سياق آخر؛ وبيّن السامرائي أن «الأنبياء» جمع كثرة، فيوحي باتساع عدد من قتلوهم، بينما «النبيين» أضيق من جهة الصيغة. فاختيار الجمع يوافق مقدار الجريمة وسياق الحكم في كل آية.","sources":[{"label":"فاضل السامرائي، المقارنة البيانية بين آيات قتل الأنبياء.؛ العنوان الجزئي: الفرق بين «النبيين» و«الأنبياء» في سياق الجريمة.","url":""}]},{"id":"s3-789","number":789,"surah":3,"verses":[25],"references":[{"surah":3,"verses":[25]}],"verseLabel":"آل عمران: 25","question":"ما الفرق بين التعبير بـ﴿مَا عَمِلَتْ﴾ في آل عمران والنحل، وبـ﴿مَا كَسَبَتْ﴾ في البقرة عند الحديث عن جزاء النفس؟","answer":"«عملت» يركّز على الفعل نفسه وما باشرته النفس، أما «كسبت» فيركّز على ما حصّلته النفس واكتسبته من آثار ذلك العمل. فاختيار اللفظ يتبع سياق الآية: تارة يُنظر إلى مباشرة العمل، وتارة إلى ما آل إليه وصار كسبًا لصاحبه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «ما عملت» و«ما كسبت».؛ العنوان الجزئي: الفرق بين «ما عملت» و«ما كسبت».","url":""}]},{"id":"s3-790","number":790,"surah":3,"verses":[26,27],"references":[{"surah":3,"verses":[26,27]}],"verseLabel":"آل عمران: 26، 27","question":"ما سر تتابع الأفعال في قوله تعالى: ﴿تُؤْتِي﴾ و﴿تَنْزِعُ﴾ و﴿تُعِزُّ﴾ و﴿تُذِلُّ﴾ و﴿تُولِجُ﴾ و﴿تُخْرِجُ﴾ و﴿تَرْزُقُ﴾؟","answer":"التتابع بالفعل يصوّر تجدد التصرفات الإلهية وانتقال الأحوال: ملك يُعطى ويُنزع، وعز يتحول إلى ذل، وليل يدخل في نهار، وحي يخرج من ميت. فالسياق سياق تغيّر وتبديل وحركة، فجاءت الأفعال ملائمة لمقتضى الحال، لا ألفاظًا اسمية توحي بالثبات وحده.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الصيغة الفعلية في «يخرج» وسياق التغيرات.؛ العنوان الجزئي: مطابقة الصيغة الفعلية لسياق التغير والتجدد.","url":""}]},{"id":"s3-791","number":791,"surah":3,"verses":[29],"references":[{"surah":3,"verses":[29]}],"verseLabel":"آل عمران: 29","question":"ما دلالة التعبير بـ﴿مَا فِي صُدُورِكُمْ﴾ في آل عمران، مقابل ﴿مَا فِي أَنْفُسِكُمْ﴾ في البقرة؟","answer":"«الأنفس» أليق بما يختزن من شهوات وأهواء ودوافع، ولذلك وردت في سياق ما تحاسب عليه النفس. أما «الصدور» فتشير إلى مكنونات القلب من الهواجس والعواطف والوساوس والحقد والحب ونحوها؛ فاختلاف اللفظ يراعي نوع الباطن المقصود في كل سياق.","sources":[{"label":"فاضل السامرائي، قبسات من البيان القرآني، ص 167–176، مادة المقارنة بين «ما في صدوركم» و«ما في أنفسكم».؛ العنوان الجزئي: وظائف النفس والصدر في التعبير القرآني.","url":""}]},{"id":"s3-792","number":792,"surah":3,"verses":[30],"references":[{"surah":3,"verses":[30]}],"verseLabel":"آل عمران: 30","question":"ما الفرق بين ﴿أَمَدًا بَعِيدًا﴾ في آل عمران، و«المدى» في التعبير عن نهاية الشيء؟","answer":"الأمد هو غاية الشيء ومنتهى الأجل، وقد يكون قريبًا أو بعيدًا، ولذلك صح وصفه بالبعد في الآية. أما المدى فيدل على النهاية أو الغاية، وقد يوصف هو أيضًا بالقرب أو البعد؛ فاختيار «أمد» يصوّر المسافة الزمنية التي تتمنى النفس تباعدها عن سوء عملها.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين الأمد والمدى.؛ العنوان الجزئي: الفرق بين «الأمد» و«المدى».","url":""}]},{"id":"s3-793","number":793,"surah":3,"verses":[33],"references":[{"surah":3,"verses":[33]}],"verseLabel":"آل عمران: 33","question":"ما الفرق بين ﴿اصْطَفَى﴾ و«اختار» في قوله تعالى: ﴿إِنَّ اللَّهَ اصْطَفَى آدَمَ وَنُوحًا﴾؟","answer":"الاختيار يكون من أشياء غير متشابهة، كاختيار قلم من ورقة وكتاب وقلم. أما الاصطفاء فيكون من أشياء متشابهة أو متناظرة، فينتقي الله بعضها من جنسها ويخصها بفضله؛ فلفظ «اصطفى» أنسب بالسياق الذي يذكر اصطفاء أشخاص من بين أمثالهم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «اصطفى» و«اختار».؛ العنوان الجزئي: الفرق بين الاصطفاء والاختيار.","url":""}]},{"id":"s3-794","number":794,"surah":3,"verses":[33,42],"references":[{"surah":3,"verses":[33,42]}],"verseLabel":"آل عمران: 33، 42","question":"ما سر تقديم الثناء على آل عمران واصطفاء مريم قبل مناقشة عقيدة أهل الكتاب في عيسى وإبراهيم؟","answer":"أثنت السورة أولًا على من يستحق الثناء من البيت الذي ينتسب إليه عيسى، وأثبتت اصطفاء مريم وطهارتها، ثم ناقشت الغلو بالحجة. فدل ترتيبها على أن تصحيح الاعتقاد لا يقتضي انتقاص أهل الفضل، وأن الإنصاف يمهد للجدال بالحق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الثناء على الأنبياء وأهل الاصطفاء قبل المحاجة.؛ العنوان الجزئي: الإنصاف تمهيدًا لتصحيح الاعتقاد.","url":""}]},{"id":"s3-795","number":795,"surah":3,"verses":[37],"references":[{"surah":3,"verses":[37]}],"verseLabel":"آل عمران: 37","question":"كيف تتسع عبارة ﴿يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ﴾ لكل هذه المعاني في سياق رزق مريم؟","answer":"«بغير حساب» تعني أن الله لا يُسأل عما يفعل، ولا يرزق الناس على قدر طاعتهم وحدها، ولا يخشى نفاد خزائنه. وتحتمل كذلك أن يأتي العبد رزقه من حيث لا يحتسب؛ وهذا هو الظاهر في رزق مريم الذي جاءها من غير الطريق المألوف، فكانت العبارة من جوامع الكلم.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، معاني «بغير حساب».؛ العنوان الجزئي: اتساع دلالة «بغير حساب».","url":""}]},{"id":"s3-796","number":796,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"كيف ينسجم تأنيث ﴿فَنَادَتْهُ الْمَلَائِكَةُ﴾ مع اختلاف التعبير عن نزول الملائكة في مشهدي الشدة والبشرى؟","answer":"يندرج نداء زكريا في خط البشرى الذي تلائمه الصيغة المؤنثة، ونظيره ﴿تَتَنَزَّلُ عَلَيْهِمُ الْمَلَائِكَةُ﴾ في بشارة المستقيمين. أما مشهد القيامة الشديد فجاء فيه ﴿وَنُزِّلَ الْمَلَائِكَةُ﴾ بالتذكير؛ فتتساند الصيغة مع الجو النفسي للمشهد.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، نزول الملائكة بين الشدة والبشارة.؛ العنوان الجزئي: انتظام البشارة في خط التأنيث.","url":""}]},{"id":"s3-797","number":797,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"ما دلالة مجيء نداء الملائكة لزكريا مؤنث الفعل، مع ورود الأمر إليهم مذكرًا في نحو ﴿اسْجُدُوا لِآدَمَ﴾؟","answer":"إذا حكى القرآن أمرًا موجهًا إلى الملائكة جاء بضمير التذكير، وفي ذلك تثبيت حقيقتهم وردّ على زعم المشركين أنهم إناث. أما حكاية صدور البشارة عن جمع الملائكة فيجوز فيها التأنيث، فاستعمله القرآن حيث يلائم الرقة والبشرى من غير أن يمس حقيقة الملائكة.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، أوامر الملائكة وصيغ البشارة.؛ العنوان الجزئي: التذكير في التكليف والتأنيث في البشارة.","url":""}]},{"id":"s3-798","number":798,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"ما سر تأنيث الفعل في ﴿فَنَادَتْهُ الْمَلَائِكَةُ﴾، مقابل تذكيره في ﴿فَسَجَدَ الْمَلَائِكَةُ﴾؟","answer":"يجيز اللسان العربي الوجهين مع جمع التكسير، لكن الاختيار القرآني يتبع المقام. جاء التأنيث في آل عمران مع بشارة زكريا، بينما جاء التذكير مع السجود والعبادة؛ فناسب مقام البشارة اللطف، وناسب مقام العبادة التذكير الذي جرى عليه الخط التعبيري في أفعال الملائكة الدالة على التكليف والطاعة.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، التذكير والتأنيث مع الملائكة.؛ العنوان الجزئي: ملاءمة صيغة الفعل لمقام البشارة والعبادة.","url":""}]},{"id":"s3-799","number":799,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"ما سر تأنيث فعل الملائكة في بشارة زكريا، مع تذكير الفعل في بشارة إبراهيم: ﴿وَبَشَّرُوهُ بِغُلَامٍ عَلِيمٍ﴾؟","answer":"قصة إبراهيم لم تُسند الفعل فيها إلى لفظ «الملائكة»، بل قُدِّموا بوصفهم ﴿ضَيْفِ إِبْرَاهِيمَ الْمُكْرَمِينَ﴾، فجرى الضمير على الضيف. أما في آل عمران فالمذكور صراحة هو جمع «الملائكة»، فظهر فيه الاختيار التعبيري الخاص بهذا اللفظ في مقام البشرى.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، بشارة زكريا وبشارة إبراهيم.؛ العنوان الجزئي: أثر الاسم المذكور في مرجع الضمير.","url":""}]},{"id":"s3-800","number":800,"surah":3,"verses":[39],"references":[{"surah":3,"verses":[39]}],"verseLabel":"آل عمران: 39","question":"ما وجه الفرق بين لطف ﴿فَنَادَتْهُ الْمَلَائِكَةُ﴾ في بشارة زكريا، واختلاف الصيغة عند قبض أرواح الظالمين والطيبين؟","answer":"يختار القرآن للملائكة صيغة تلائم طبيعة الموقف: فمقام الخير والبشارة والطمأنينة يناسبه التأنيث، كما في نداء زكريا وقبض الطيبين؛ أما مقام الشدة والعقوبة فيناسبه التذكير. وهكذا تسهم الصيغة في تلوين المشهد قبل تفصيل مضمونه.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، صيغة الفعل بين البشرى والعقوبة.؛ العنوان الجزئي: أثر طبيعة الحدث في اختيار التذكير والتأنيث.","url":""}]},{"id":"s3-801","number":801,"surah":3,"verses":[39,42],"references":[{"surah":3,"verses":[39,42]}],"verseLabel":"آل عمران: 39، 42","question":"ما سر اتفاق بشارة زكريا وخطاب مريم على إسناد الفعل إلى الملائكة بصيغة التأنيث؟","answer":"الموضعان من سياق واحد قوامه المنح الإلهية والبشارة: ولد لزكريا واصطفاء لمريم ثم بشارتها بالمسيح. فجاء التأنيث رابطًا صوتيًا بين مشاهد الرحمة، ومميزًا لها عن مواطن الأوامر الشديدة والعبادات والعقوبات التي يغلب فيها التذكير.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، خط البشارة في إسناد أفعال الملائكة.؛ العنوان الجزئي: وحدة النبرة في مشاهد البشارة.","url":""}]},{"id":"s3-802","number":802,"surah":3,"verses":[39,42],"references":[{"surah":3,"verses":[39,42]}],"verseLabel":"آل عمران: 39، 42","question":"ما وجه المناسبة بين تأنيث فعل الملائكة في بشارتي زكريا ومريم، وتذكيره في سجود الملائكة؟","answer":"يجمع موضعا آل عمران معنى البشارة والتكريم، فجاء ﴿فَنَادَتْهُ﴾ و﴿قَالَتِ الْمَلَائِكَةُ﴾ بما يلائم رقة المقام. أما السجود فهو عبادة وتكليف، وقد جرى التعبير في أفعال الطاعة الصادرة عن الملائكة على التذكير، فاختار لكل مقام نبرته المناسبة.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، البشارة والعبادة في أفعال الملائكة.؛ العنوان الجزئي: اختلاف الصيغة باختلاف جو الحدث.","url":""}]},{"id":"s3-803","number":803,"surah":3,"verses":[40],"references":[{"surah":3,"verses":[40]}],"verseLabel":"آل عمران: 40","question":"ما دلالة تقديم عقر الزوجة في سورة مريم، وتقديم بلوغ الكِبَر في آل عمران، في وصف موانع الولادة؟","answer":"في مريم قيل: ﴿وَكَانَتِ امْرَأَتِي عَاقِرًا وَقَدْ بَلَغْتُ مِنَ الْكِبَرِ﴾، فناسب أن يبدأ بما كان مانعًا أصليًا ممتدًا في الزوجة. أما في آل عمران فقيل: ﴿وَقَدْ بَلَغَنِيَ الْكِبَرُ وَامْرَأَتِي عَاقِرٌ﴾، فناسب أن يتقدم ما طرأ على زكريا في السياق المعروض هناك؛ فالتقديم يتبع صورة المانع في كل قصة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تقديم موانع الولادة في قصتي زكريا.؛ العنوان الجزئي: تقديم موانع الولادة وتأخيرها بحسب السياق.","url":""}]},{"id":"s3-804","number":804,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"ما أثر التعبير بـ﴿إِلَّا رَمْزًا﴾ في آل عمران، مقابل ﴿سَوِيًّا﴾ في مريم، في تصوير شدة الآية وظهورها؟","answer":"«إلا رمزًا» يسلط الضوء على الاستثناء من الكلام، فيصوّر انقطاع القدرة على التخاطب مع بقاء الإشارة، وهو أوضح في إظهار الآية. أما «سويًا» في مريم فيعرض حال زكريا في تلك الليالي بوصفه سويًا، ضمن سياق مختلف. فاختلاف العبارة يوافق اختلاف زاوية التصوير، مع كون آية آل عمران أظهر وأعظم اتصالًا بعظم البشارة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، مقابلة «إلا رمزًا» و«سويًا» في قصتي زكريا.؛ العنوان الجزئي: تصوير الآية بين انقطاع الكلام وبقاء السواء.","url":""}]},{"id":"s3-805","number":805,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"ما دلالة أن يُؤمر زكريا في آل عمران بالذكر والتسبيح بنفسه، بينما يأمر قومه بالتسبيح في سورة مريم؟","answer":"في آل عمران كانت البشارة أعظم وأوصاف يحيى أكمل، فناسب أن يظهر شكر زكريا نفسه بالذكر الكثير والتسبيح. أما في مريم فالمشهد ينتقل إلى قومه، فناسب أن يخرج إليهم ويوصيهم بالتسبيح؛ فاختلاف المخاطَب يبرز اختلاف مقدار الشكر وموقعه في القصة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، من يباشر الذكر والتسبيح في قصتي زكريا.؛ العنوان الجزئي: شكر زكريا وشكر قومه بعد البشارة.","url":""}]},{"id":"s3-806","number":806,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"ما دلالة الجمع بين ﴿وَاذْكُرْ رَبَّكَ كَثِيرًا﴾ و﴿سَبِّحْ بِالْعَشِيِّ وَالْإِبْكَارِ﴾؟","answer":"الذكر أعم من التسبيح؛ فهو يشمل التسبيح والتحميد والتهليل، ولذلك أُطلق ولم يُقيد بوقت. أما التسبيح فهو نوع أخص من الذكر، فناسب أن يُذكر معه وقتاه. اجتمع العموم والخصوص في الآية ليشمل الشكر قلب زكريا ولسانه ووقته.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين الذكر والتسبيح.؛ العنوان الجزئي: عموم الذكر وخصوص التسبيح.","url":""}]},{"id":"s3-807","number":807,"surah":3,"verses":[41],"references":[{"surah":3,"verses":[41]}],"verseLabel":"آل عمران: 41","question":"ما وجه اختلاف ﴿ثَلَاثَةَ أَيَّامٍ﴾ في آل عمران عن ﴿ثَلَاثَ لَيَالٍ﴾ في مريم؟","answer":"اليوم من طلوع الشمس إلى غروبها، والليل من غروبها إلى طلوع الفجر. فجاء ذكر الأيام في آل عمران؛ لأن البشارة فيها أعظم، وظهور الآية في النهار أبين، إذ تكثر المخالطة والذكر والعبادة. أما ذكر الليالي في مريم فناسب سياق القصة هناك وما فيه من مقابلة الليل والنهار.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين ثلاثة أيام وثلاث ليال.؛ العنوان الجزئي: تقابل الليل والنهار في قصتي زكريا.","url":""}]},{"id":"s3-808","number":808,"surah":3,"verses":[42],"references":[{"surah":3,"verses":[42]}],"verseLabel":"آل عمران: 42","question":"ما أثر تأنيث الفعل في ﴿وَإِذْ قَالَتِ الْمَلَائِكَةُ يَا مَرْيَمُ﴾ في مشهد الاصطفاء والتطهير؟","answer":"التأنيث جائز مع لفظ الملائكة، واختياره هنا ينسجم مع خطاب التكريم الهادئ الموجه إلى مريم: اصطفاء وتطهير وبشارة. فليست الصيغة مجرد احتمال نحوي، بل صوت تعبيري يوافق اللطف الذي يملأ المشهد.","sources":[{"label":"فاضل السامرائي، «أسئلة بيانية في القرآن الكريم»، ج1، ص189–191، تأنيث فعل الملائكة في مقام الخير.؛ العنوان الجزئي: رقة الصيغة في خطاب الاصطفاء.","url":""}]},{"id":"s3-809","number":809,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"ما دلالة مجيء قوله تعالى: ﴿وَمِنَ الْمُقَرَّبِينَ﴾ بعد ﴿وَجِيهًا فِي الدُّنْيَا وَالْآخِرَةِ﴾؟","answer":"الوجاهة تصف المكانة الظاهرة، أما القرب فيصف المنزلة الخاصة عند الله. فجمع التعبير بين أثر الرسالة في الدنيا والآخرة، وبين منزلة العبد المقرب، حتى لا تُفهم الوجاهة على أنها مجرد قبول اجتماعي أو منزلة دنيوية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، أوصاف عيسى عليه السلام.؛ العنوان الجزئي: اجتماع الوجاهة والقرب في وصف عيسى.","url":""}]},{"id":"s3-810","number":810,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"ما سر التعبير عن عيسى في الآية بثلاثة ألقاب وأسماء: ﴿الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ﴾، وما الأثر البلاغي لاختلاف هذه التسميات؟","answer":"«المسيح» لقب يدل على المنزلة والوصف، و«عيسى» اسم العلم، و«ابن مريم» كنية. فجمعها يعرّف بالمبشَّر به من جهات متعددة، ويهيئ لذكر خصائصه من غير أن يخلط بين اللقب والاسم والكنية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، التفريق بين «المسيح» و«عيسى» و«ابن مريم».؛ العنوان الجزئي: المسيح لقب، وعيسى اسم، وابن مريم كنية.","url":""}]},{"id":"s3-811","number":811,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"ما سر ورود لقب ﴿الْمَسِيحُ﴾ في بشارة مريم ومقامات تصحيح الاعتقاد، وعدم جعله الاسم الغالب في سياق التكليف بالرسالة؟","answer":"«المسيح» لقب يبرز المنزلة ويكثر في الثناء أو في مناقشة ما قيل في عيسى وتصحيح الاعتقاد فيه. أما سياقات الرسالة وإيتاء البينات فتغلب فيها تسميته باسمه أو نسبه؛ فيختار القرآن من وجوه التعريف ما يخدم غرض المقام.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المسيح وعيسى وابن مريم بحسب المقام.؛ العنوان الجزئي: توزيع ألقاب عيسى على مقامات الثناء والعقيدة والرسالة.","url":""}]},{"id":"s3-812","number":812,"surah":3,"verses":[45],"references":[{"surah":3,"verses":[45]}],"verseLabel":"آل عمران: 45","question":"ما سر وصف عيسى عليه السلام بأنه ﴿وَجِيهًا فِي الدُّنْيَا وَالْآخِرَةِ﴾ بعد التصريح باسمه ونسبه، وما الذي يضيفه قيدَا الزمان إلى البشارة؟","answer":"الوجاهة منزلة قبول ورفعة، وليست مجرد شهرة عابرة. وذكر الدنيا والآخرة يبين امتداد هذه المنزلة: فهو وجيه بين الناس في الدنيا بما آتاه الله من النبوة والآيات، ووجيه في الآخرة بما له من القرب والكرامة. فجاء القيدان لتقرير أن منزلته ثابتة في المرحلتين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، أسماء عيسى وأوصافه في القرآن.؛ العنوان الجزئي: دلالة لقب «المسيح» ووصف عيسى بالوجاهة.","url":""}]},{"id":"s3-813","number":813,"surah":3,"verses":[46],"references":[{"surah":3,"verses":[46]}],"verseLabel":"آل عمران: 46","question":"ما دلالة وصف عيسى بأنه ﴿وَكَهْلًا﴾، وما الفرق بين الكهل والشيخ في هذا السياق؟","answer":"الكهل مرحلة بين الشباب والشيخوخة، ويُطلق غالبًا على من اكتملت قوته ونضجه قبل أن يبلغ سنّ الشيخوخة. لذلك فالوصف لا يعني أنه كان شيخًا، بل يشير إلى استمرار كلامه بالحق في المهد ثم في مرحلة النضج.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «كهلًا».؛ العنوان الجزئي: الفرق بين الكهل والشيخ في وصف عيسى.","url":""}]},{"id":"s3-814","number":814,"surah":3,"verses":[47],"references":[{"surah":3,"verses":[47]}],"verseLabel":"آل عمران: 47","question":"ما سر مجيء اسم الإشارة في ﴿كَذَلِكِ اللَّهُ يَخْلُقُ مَا يَشَاءُ﴾ بالكسر، وما الذي يحدده هذا الكسر في الخطاب؟","answer":"الكاف في «ذلكِ» للمخاطبة، والخطاب هنا لمريم، فجاءت الكاف مكسورة لموافقة المخاطَب المؤنث. فالكسر ليس وصفًا للشيء المشار إليه، بل علامة على جهة الخطاب التي وُجِّه إليها البيان.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «ذلكِ» في خطاب مريم.؛ العنوان الجزئي: كسر الكاف في «ذلكِ» للمخاطبة المؤنثة.","url":""}]},{"id":"s3-815","number":815,"surah":3,"verses":[49],"references":[{"surah":3,"verses":[49]}],"verseLabel":"آل عمران: 49","question":"كيف يفهم التعبير عن عيسى بقوله: ﴿أَنِّي أَخْلُقُ لَكُم﴾، مع اختصاص الله بالخلق ابتداءً؟","answer":"للخلق استعمالان: خلق ابتداءً من غير مثال سابق، وهذا مختص بالله، وخلق بمعنى التقدير والتشكيل والصنع من مواد خلقها الله، وهذا يصح أن ينسب إلى الإنسان. فعيسى يصنع هيئة الطير من الطين، أما إيجادها حيّةً فبإذن الله، فانتفى توهم الاستقلال في الخلق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، معنى الخلق في «أحسن الخالقين» والاستشهاد بآية عيسى.؛ العنوان الجزئي: الفرق بين خلق الإيجاد وخلق التقدير.","url":""}]},{"id":"s3-816","number":816,"surah":3,"verses":[52],"references":[{"surah":3,"verses":[52]}],"verseLabel":"آل عمران: 52","question":"ما وجه اختلاف ختم جواب الحواريين بين ﴿وَاشْهَدْ بِأَنَّا مُسْلِمُونَ﴾ في آل عمران، و﴿وَاشْهَدْ بِأَنَّنَا مُسْلِمُونَ﴾ في المائدة؟","answer":"سياق آل عمران سياق استجابة عاجلة لنصرة عيسى بعد ظهور الكفر، فجاء التعبير أخف وأسرع. أما المائدة فسياق تعداد النعم والإقرار بها، فناسب زيادة التوكيد في ﴿بِأَنَّنَا﴾. فالاختلاف يخدم اختلاف المقام، ولا يدل على اختلاف أصل إسلام الحواريين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، جواب الحواريين في آل عمران والمائدة.؛ العنوان الجزئي: الفرق بين «بأنا مسلمون» و«بأننا مسلمون».","url":""}]},{"id":"s3-817","number":817,"surah":3,"verses":[59],"references":[{"surah":3,"verses":[59]}],"verseLabel":"آل عمران: 59","question":"ما سر التعبير عن خلق عيسى بقوله: ﴿إِنَّ مَثَلَ عِيسَى عِندَ اللَّهِ كَمَثَلِ آدَمَ﴾، مع أن عيسى وُلد من أم، وآدم لم يولد من أب ولا أم؟","answer":"المقصود إبطال دعوى أن الولادة الخارقة تستلزم الألوهية أو البنوة. فإذا كان آدم قد خُلق من تراب من غير أب ولا أم، فخلق عيسى من أم من غير أب ليس أعجب من ذلك. ووجه الشبه هو الخلق بقدرة الله، لا تماثل التفاصيل بين القصتين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الحجج العقلية في قصة عيسى.؛ العنوان الجزئي: المماثلة بين خلق عيسى وخلق آدم.","url":""}]},{"id":"s3-818","number":818,"surah":3,"verses":[59,65,66],"references":[{"surah":3,"verses":[59,65,66]}],"verseLabel":"آل عمران: 59، 65، 66","question":"كيف يتدرج الاحتجاج من قياس خلق عيسى بخلق آدم إلى إبطال المجادلة في إبراهيم بغير علم؟","answer":"قدمت السورة دليلًا عقليًا محسوس البنية: من خلق آدم بلا أب ولا أم لا يعجز عن خلق عيسى بلا أب. ثم كشفت التناقض التاريخي في نسبة إبراهيم إلى شريعة نزلت بعده، وختمت بذم الجدال فيما لا علم لهم به؛ فتدرجت من إقامة البرهان إلى كشف فساد دعوى الخصم ومنهجه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الحجج والبراهين وسيلة للتثبيت.؛ العنوان الجزئي: بناء الحجة ثم تقويض دعوى المجادل.","url":""}]},{"id":"s3-819","number":819,"surah":3,"verses":[64,84],"references":[{"surah":3,"verses":[64,84]}],"verseLabel":"آل عمران: 64، 84","question":"ما وجه التكامل بين الدعوة إلى ﴿كَلِمَةٍ سَوَاءٍ﴾ وإعلان الإيمان بجميع الأنبياء من غير تفريق؟","answer":"تبدأ الآية 64 من أصل مشترك هو توحيد العبادة ورفض اتخاذ البشر أربابًا، ثم تبين الآية 84 سعة الموقف الإسلامي من سلسلة الوحي كلها. فالحوار لا يبنى على محو المشترك ولا على تنازل عقدي، بل على توحيد خالص وإنصاف لجميع الرسل.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، إيجاد نقاط الاتفاق في حوار أهل الكتاب.؛ العنوان الجزئي: التوحيد ووحدة الرسالات أساسًا للحوار.","url":""}]},{"id":"s3-820","number":820,"surah":3,"verses":[70,71,75],"references":[{"surah":3,"verses":[70,71,75]}],"verseLabel":"آل عمران: 70، 71، 75","question":"كيف يتصاعد العتاب من كفر أهل الكتاب بالآيات ولبس الحق إلى كشف أثر ذلك في الأمانة بالآية 75؟","answer":"بدأت المواجهة بكشف الخلل العلمي: كفر مع شهادة، ولبس مع معرفة. ثم أظهرت أثر الانحراف في السلوك حين سوّغ بعضهم أكل حقوق «الأميين» والكذب على الله. فالسياق يبين أن تحريف المعرفة لا يبقى فكرة، بل ينتهي إلى فساد في المعاملة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تحذير أهل الكتاب من التكذيب والكتمان.؛ العنوان الجزئي: من كتمان الحق إلى فساد السلوك.","url":""}]},{"id":"s3-821","number":821,"surah":3,"verses":[72],"references":[{"surah":3,"verses":[72]}],"verseLabel":"آل عمران: 72","question":"ما سر تحديد الإيمان المصطنع بقولهم: ﴿وَجْهَ النَّهَارِ﴾، ثم الكفر في ﴿آخِرَهُ﴾؟","answer":"جعلوا أول النهار ميدانًا لإظهار الإيمان وآخره ميدانًا لإظهار الكفر ليوقعوا الشك في نفوس المؤمنين، كأن التراجع وقع بعد اختبار قصير. فالتحديد الزمني يصور الخطة بوصفها تمثيلية مقصودة، لا تحولًا حقيقيًا في الاعتقاد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، خطة الإيمان في وجه النهار والكفر في آخره.؛ العنوان الجزئي: التوقيت المقصود في فتنة أهل الكتاب.","url":""}]},{"id":"s3-822","number":822,"surah":3,"verses":[75,199],"references":[{"surah":3,"verses":[75,199]}],"verseLabel":"آل عمران: 75، 199","question":"ما سر توكيد وجود المؤمنين من أهل الكتاب بـ﴿إِنَّ﴾ واللام، مع عدم هذا التوكيد في وصف من يؤدي الأمانة في الآية 75؟","answer":"أداء الأمانة موجود في الناس بكثرة، ومن أهل الكتاب من يؤديها بلا استغراب كبير. أما انتقال المرء عن معتقده السابق وإيمانه بالوحي الجديد خاشعًا لله فحالة أندر؛ لذلك قُوِّي الخبر بما يزيل استبعاد السامع ويثبت وقوعه.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، تفاوت التوكيد بين الأمانة والإيمان.؛ العنوان الجزئي: زيادة التوكيد بقدر ندرة الخبر.","url":""}]},{"id":"s3-823","number":823,"surah":3,"verses":[92],"references":[{"surah":3,"verses":[92]}],"verseLabel":"آل عمران: 92","question":"ما سر التعبير بـ﴿لَن تَنَالُوا الْبِرَّ حَتَّى تُنفِقُوا مِمَّا تُحِبُّونَ﴾، وما الذي يضيفه «مما تحبون»؟","answer":"«لن تنالوا البر» يصور البر منزلة يسعى الإنسان إلى بلوغها، لا مجرد عمل جزئي. ثم اشترط الإنفاق من المحبوب ليظهر صدق البذل؛ فالإنفاق مما لا يحتاجه المرء أسهل، أما إخراج المحبوب فيكشف تغلب الإيمان على شح النفس. ولذلك ارتبطت الآية بمعنى كمال الخير وشموله.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الإنفاق من المحبوب ونيل البر.؛ العنوان الجزئي: معنى «البر» وضمير «تحبون» في آية 92.","url":""}]},{"id":"s3-824","number":824,"surah":3,"verses":[101],"references":[{"surah":3,"verses":[101]}],"verseLabel":"آل عمران: 101","question":"ما دلالة الاستفهام في قوله تعالى: ﴿وَكَيْفَ تَكْفُرُونَ﴾ بعد ذكر تلاوة الآيات ووجود الرسول؟","answer":"الاستفهام إنكاري تعجبي، لأن أسباب الثبات حاضرة: آيات الله تُتلى، والرسول بين المؤمنين. فالكفر بعد هذه النعم ليس مجرد خطأ في الاستدلال، بل انقلاب عن مقتضى البيان والصحبة النبوية. ثم جاء الاعتصام بالله علاجًا عمليًا لهذا الانقلاب.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، وسائل الثبات في سياق آل عمران.؛ العنوان الجزئي: الاستفهام الإنكاري في «وكيف تكفرون».","url":""}]},{"id":"s3-825","number":825,"surah":3,"verses":[104],"references":[{"surah":3,"verses":[104]}],"verseLabel":"آل عمران: 104","question":"ما دلالة افتتاح الأمر بقوله تعالى: ﴿وَلْتَكُن مِّنكُمْ أُمَّةٌ﴾ بعد الأمر بالاعتصام والنهي عن التفرق؟","answer":"الاعتصام يحفظ وحدة الجماعة، ثم يأتي الأمر بوجود أمة تدعو إلى الخير لتحفظ هذه الوحدة من الداخل بالفعل الإيجابي. فليست الجماعة المطلوبة مجرد تجمع ساكن، بل جماعة تقوم بالدعوة والأمر بالمعروف والنهي عن المنكر؛ وبذلك يتحول الاجتماع إلى رسالة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الدعوة إلى الخير وسيلة للثبات.؛ العنوان الجزئي: الصلة بين الاعتصام والدعوة إلى الخير.","url":""}]},{"id":"s3-826","number":826,"surah":3,"verses":[109],"references":[{"surah":3,"verses":[109]}],"verseLabel":"آل عمران: 109","question":"ما دلالة تقديم ﴿لِلَّهِ﴾ في قوله: ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾ عقب الحديث عن تبييض الوجوه وتسـويدها؟","answer":"التقديم يقرر اختصاص الملك الحقيقي بالله، فيأتي الجزاء السابق صادرًا عن المالك الذي لا يخرج شيء عن سلطانه. فليس اختلاف المصائر حكمًا منفصلًا عن ملكه، بل هو تصرف العدل في ملكه، ولذلك أعقبه برجوع الأمور كلها إليه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تفصيل ملك السماوات والأرض.؛ العنوان الجزئي: اختصاص الملك بالله في ختام مقطع الجزاء.","url":""}]},{"id":"s3-827","number":827,"surah":3,"verses":[109],"references":[{"surah":3,"verses":[109]}],"verseLabel":"آل عمران: 109","question":"ما سر الانتقال من ملك الموجودات في ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾ إلى رجوع الشؤون في ﴿وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ﴾؟","answer":"صدر الآية يقرر أن الذوات كلها ملك لله، وخاتمتها تقرر أن العواقب والتدبير والقضاء ترجع إليه كذلك. فاجتمع ملك الموجودات ومرجع الأمور، ليكتمل معنى السلطان الإلهي ولا يتوهم أن شيئًا من الخلق أو التدبير خارج عنه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ملك السماوات والأرض ومرجع الأمور.؛ العنوان الجزئي: الجمع بين الملك والمرجع.","url":""}]},{"id":"s3-828","number":828,"surah":3,"verses":[110],"references":[{"surah":3,"verses":[110]}],"verseLabel":"آل عمران: 110","question":"ما سر تقييد خيرية الأمة بقوله: ﴿أُخْرِجَتْ لِلنَّاسِ﴾، لا بمجرد قوله «كنتم خير أمة»؟","answer":"القيد ينقل الخيرية من امتياز مغلق إلى رسالة نافعة للناس؛ فالأمة أُظهرت لتقوم بوظيفة الأمر بالمعروف والنهي عن المنكر والإيمان بالله. ومن ثم فخيريتها مرتبطة بأداء ما أُخرجت له، لا بالاسم أو الانتساب وحدهما.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، معنى إخراج الأمة للناس.؛ العنوان الجزئي: الخيرية بوصفها وظيفة ورسالة.","url":""}]},{"id":"s3-829","number":829,"surah":3,"verses":[111],"references":[{"surah":3,"verses":[111]}],"verseLabel":"آل عمران: 111","question":"ما وجه المقابلة بين ﴿لَن يَضُرُّوكُمْ إِلَّا أَذًى﴾ في الآية 111، و﴿لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْئًا﴾ في الآية 120؟","answer":"في الآية 111 ذُكر ما قد يصدر منهم من أذى محسوس أو كلامي، مع نفي بلوغه درجة الضرر. وفي الآية 120 عُلّق انتفاء أثر الكيد على الصبر والتقوى؛ فصار الكيد كله عديم الأثر، وجاء التعبير بـ«شيئًا» لتأكيد استئصال النفع منه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الأذى والضرر وكيد أهل الكتاب.؛ العنوان الجزئي: تفاوت التعبير بحسب مقام الأذى ومقام الكيد.","url":""}]},{"id":"s3-830","number":830,"surah":3,"verses":[111,120],"references":[{"surah":3,"verses":[111,120]}],"verseLabel":"آل عمران: 111، 120","question":"ما الدلالة البيانية لاختلاف القراءة في ﴿لَا يَضُرُّكُمْ﴾، مع قوله ﴿لَن يَضُرُّوكُمْ إِلَّا أَذًى﴾؟","answer":"القراءة بالفتح أخف في النطق والدلالة، فتشير إلى أن الضرر لا يقع حقيقة، أما الضم فأثقل، فيوحي ببقاء أذى أو أثر لا يبلغ حد الضرر المستقر. ولذلك جاء سياق الصبر والتقوى مناسبًا لاحتمال بقاء شيء من الأذى مع انتفاء الضرر الحقيقي.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف القراءة في «لا يضرّكم» ودلالة الثقل والخفة.؛ العنوان الجزئي: دلالة اختلاف القراءة في «يضرّكم».","url":""}]},{"id":"s3-831","number":831,"surah":3,"verses":[120,121],"references":[{"surah":3,"verses":[120,121]}],"verseLabel":"آل عمران: 120، 121","question":"ما دلالة الانتقال من مواجهة كيد أهل الكتاب في الآية 120 إلى مشهد ترتيب الصفوف في أُحد في الآية 121؟","answer":"بهذا الانتقال تنتقل السورة من الثبات أمام الأفكار والخصوم من الخارج إلى الثبات العملي داخل الصف المؤمن. فختمت المواجهة الفكرية بالصبر والتقوى، ثم شرعت في اختبار الطاعة والانضباط، ليظهر أن الثبات بناء متكامل لا موقف ذهني فحسب.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، انقسام السورة إلى الثبات الخارجي والداخلي.؛ العنوان الجزئي: الانتقال من الثبات الفكري إلى الثبات العملي.","url":""}]},{"id":"s3-832","number":832,"surah":3,"verses":[121,152],"references":[{"surah":3,"verses":[121,152]}],"verseLabel":"آل عمران: 121، 152","question":"ما سر بدء قصة أُحد بذكر ترتيب المؤمنين للقتال، ثم تأخير العتاب الصريح على الفشل والتنازع إلى الآية 152؟","answer":"بُني السياق على التثبيت قبل العتاب: ذكّرهم الله بولايته ونصره في بدر وبإمداد الملائكة، ثم واجههم بسبب الخلل بعد رفع معنوياتهم. فكان العتاب مربيًا لا محطمًا، يحفظ الانتماء ويكشف الخطأ في الوقت نفسه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تسلسل معالجة غزوة أُحد.؛ العنوان الجزئي: تقديم التثبيت على العتاب.","url":""}]},{"id":"s3-833","number":833,"surah":3,"verses":[130,152],"references":[{"surah":3,"verses":[130,152]}],"verseLabel":"آل عمران: 130، 152","question":"ما وجه إدخال النهي عن الربا في أثناء الحديث عن أُحد قبل العودة إلى بيان أسباب الهزيمة؟","answer":"لم يأت النهي مقطوعًا عن سياق المعركة؛ فالربا من الشهوات التي تفسد المجتمع وتثير التنازع، والسورة تكشف أن الهزيمة تبدأ من خلل الطاعة والقيم قبل أن تظهر في الميدان. لذلك عالجت أسباب الضعف الداخلي ثم عادت إلى تفاصيل أُحد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، صلة آية الربا بأسباب الهزيمة والثبات.؛ العنوان الجزئي: الربا عائقًا من عوائق الثبات.","url":""}]},{"id":"s3-834","number":834,"surah":3,"verses":[132,159],"references":[{"surah":3,"verses":[132,159]}],"verseLabel":"آل عمران: 132، 159","question":"ما وجه الصلة بين الأمر بـ﴿أَطِيعُوا اللَّهَ وَالرَّسُولَ﴾، ثم الأمر للنبي ﷺ بالعفو والاستغفار والمشاورة بعد خطأ أُحد؟","answer":"الطاعة تحفظ الجماعة من التنازع، لكن وقوع المخالفة لا يعني هدمها؛ لذلك جاء العلاج النبوي بالعفو والاستغفار والشورى. فجمع السياق بين حزم المرجعية ورحمة القيادة، وهما معًا من أسباب بقاء الصف وثباته.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المعالجة المتدرجة لأحداث أُحد، وقاعدة التعبير في طاعة الله والرسول.؛ العنوان الجزئي: الطاعة ورحمة القيادة في بناء الصف.","url":""}]},{"id":"s3-835","number":835,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما دلالة قوله ﴿مِنْ رَبِّكُمْ﴾ بعد «مغفرة»، وما الذي يضيفه هذا القيد إلى الرجاء؟","answer":"ذكر الربوبية يقرّب معنى العناية والرحمة والتربية؛ فالمغفرة مطلوبة من رب يتولى عباده ويرعاهم. ولهذا كان التعبير أوقع في الترغيب من قول مختصر لا يبرز جهة المنعم والمغفر.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، وصل المغفرة بقوله «من ربكم».؛ العنوان الجزئي: مناسبة ذكر الربوبية في مقام المغفرة.","url":""}]},{"id":"s3-836","number":836,"surah":3,"verses":[133],"references":[{"surah":3,"verses":[133]}],"verseLabel":"آل عمران: 133","question":"ما سر اختيار ﴿وَسَارِعُوا﴾، لا «وأسرعوا»؟","answer":"صيغة «سارعوا» أبلغ في طلب المبادرة والمبالغة في الإسراع، وتصور جماعة تتنافس في التوجه إلى المغفرة. أما «أسرعوا» فكانت تدل على مجرد السرعة دون هذا الإيحاء بالمبادرة والمسابقة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، وسارعوا وصيغة المبالغة في طلب الإسراع.؛ العنوان الجزئي: المبالغة في «سارعوا».","url":""}]},{"id":"s3-837","number":837,"surah":3,"verses":[134],"references":[{"surah":3,"verses":[134]}],"verseLabel":"آل عمران: 134","question":"ما سر التعبير بـ﴿يُنْفِقُونَ فِي السَّرَّاءِ وَالضَّرَّاءِ﴾، وما الذي يضيفه ذكر الحالين؟","answer":"ذكر السراء والضراء يخرج الإنفاق من كونه سلوكًا مرتبطًا بالرخاء إلى كونه خلقًا ثابتًا في الشدة واليسر. فالمتقون لا ينتظرون فائض المال، بل يثبتون على البذل حتى حين تكون الحاجة والمشقة حاضرتين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الإنفاق في السراء والضراء.؛ العنوان الجزئي: ثبات الإنفاق في حالتي اليسر والعسر.","url":""}]},{"id":"s3-838","number":838,"surah":3,"verses":[145],"references":[{"surah":3,"verses":[145]}],"verseLabel":"آل عمران: 145","question":"ما الذي يكشفه المضارع في ﴿مَن يُرِدْ ثَوَابَ الْآخِرَةِ﴾ عن طبيعة إرادة الثواب؟","answer":"المضارع يلائم الإرادة المتجددة؛ فالأعمال تتكرر، ومع كل عمل تتجدد نية الثواب. أما قوله في الإسراء ﴿وَمَنْ أَرَادَ الْآخِرَةَ﴾ فالمقصود به الوجهة الكبرى الواحدة التي اختارها الإنسان، فجاء الماضي أنسب لحسم الاختيار.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الماضي والمضارع في إرادة الآخرة وثوابها.؛ العنوان الجزئي: تجدد إرادة الثواب ووحدة إرادة الآخرة.","url":""}]},{"id":"s3-839","number":839,"surah":3,"verses":[145,144],"references":[{"surah":3,"verses":[145,144]}],"verseLabel":"آل عمران: 145، 144","question":"ما سر وصف أصحاب الثبات بالشكر في ختام الآيتين، مع أن المقام مقام قتال وصبر؟","answer":"الثبات بعد شائعة موت الرسول ﷺ اعتراف عملي بأن الرسالة نعمة لا تتوقف على حياة فرد، ولو كان الرسول نفسه. ومن يثبت ولا ينقلب فقد حفظ النعمة وأدى حقها، فكان وصف الشاكرين أعمق من وصف الصابرين وحده.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اتساق «سيجزي» و«سنجزي الشاكرين».؛ العنوان الجزئي: الثبات صورة من صور شكر نعمة الرسالة.","url":""}]},{"id":"s3-840","number":840,"surah":3,"verses":[147],"references":[{"surah":3,"verses":[147]}],"verseLabel":"آل عمران: 147","question":"ما الأثر البلاغي لاختلاف القراءتين في ﴿مَا كَانَ قَوْلُهُمْ﴾ و﴿مَا كَانَ قَوْلَهُمْ﴾؟","answer":"قراءة الرفع تفيد أن هذا الدعاء هو القول الذي لم يقولوا غيره في ذلك الموقف. وقراءة النصب تفيد أن هذا القول لم يصدر إلا عنهم، فالأولى تمدح مضمون الدعاء، والثانية تمدح قائليه؛ وباجتماع القراءتين يتكامل مدح المقال وأهله.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المعنى البلاغي لاختلاف القراءتين في «قولهم».؛ العنوان الجزئي: تكامل المعنى بين رفع «قولهم» ونصبه.","url":""}]},{"id":"s3-841","number":841,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما دلالة ختام مشهد المخالفة بقوله: ﴿وَلَقَدْ عَفَا عَنْكُمْ﴾، مع ذكر الفشل والتنازع والعصيان قبلها؟","answer":"يوازن السياق بين كشف الخطأ وفتح باب الرحمة؛ فلم يحجب العفوَ وقوعُ المخالفة، بل جاء بعد بيانها ليمنع اليأس ويقرر أن العتاب القرآني إصلاح لا مجرد إدانة. ثم يذكر فضل الله على المؤمنين ليؤكد أن النجاة فضل ورحمة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، العفو بعد بيان أسباب الهزيمة.؛ العنوان الجزئي: مجيء العفو بعد العتاب.","url":""}]},{"id":"s3-842","number":842,"surah":3,"verses":[152],"references":[{"surah":3,"verses":[152]}],"verseLabel":"آل عمران: 152","question":"ما دلالة مجيء ﴿ثُمَّ صَرَفَكُمْ عَنْهُمْ لِيَبْتَلِيَكُمْ﴾ بعد الفشل والتنازع والعصيان؟","answer":"«ثم» ترتب التحول في المشهد بعد أن ظهرت أسباب الخلل من جانبهم، فجاء الصرف عن العدو نتيجةً تربوية للابتلاء لا مجرد هزيمة مفاجئة. وبذلك يربط السياق بين السلوك الداخلي والنتيجة الخارجية في المعركة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، تسلسل أحداث أحد والابتلاء.؛ العنوان الجزئي: ترتيب الفشل والصرف والابتلاء.","url":""}]},{"id":"s3-843","number":843,"surah":3,"verses":[152,154],"references":[{"surah":3,"verses":[152,154]}],"verseLabel":"آل عمران: 152، 154","question":"كيف يتدرج علاج أُحد من ﴿وَلَقَدْ عَفَا عَنْكُمْ﴾ إلى ﴿أَمَنَةً نُّعَاسًا﴾ ثم إلى تمحيص القلوب؟","answer":"بدأ العلاج بإزالة اليأس بإعلان العفو، ثم أعاد إلى الطائفة المؤمنة سكينتها بنعاس الأمن، ثم كشف ما في النفوس ومحص القلوب. فالخطاب لا يكتفي بتسجيل الخطأ، بل ينقل الجماعة من الذنب إلى الطمأنينة ثم إلى التربية الداخلية.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، التثبيت والعتاب في تسلسل أُحد، وآية 154.؛ العنوان الجزئي: مراحل إعادة بناء الصف بعد الهزيمة.","url":""}]},{"id":"s3-844","number":844,"surah":3,"verses":[153],"references":[{"surah":3,"verses":[153]}],"verseLabel":"آل عمران: 153","question":"ما دلالة رسم ﴿لِكَيْلَا﴾ موصولة في آل عمران، مقابل ﴿كَيْ لَا﴾ مفصولة في الحشر؟","answer":"يربط الدكتور السامرائي بين الوصل في آل عمران واتصال الغمين: غم الهزيمة وغم فوات الغنائم. أما الحشر فالسياق في تفريق المال حتى لا يكون دولة بين الأغنياء، فناسبه الفصل في الرسم، مع التنبيه إلى أن الرسم ليس قاعدة مطردة مستقلة عن السياق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، لكيلا الوصل والفصل بحسب المعنى.؛ العنوان الجزئي: مناسبة رسم «لكيلا» لاتصال الغم أو انفصال المال.","url":""}]},{"id":"s3-845","number":845,"surah":3,"verses":[154],"references":[{"surah":3,"verses":[154]}],"verseLabel":"آل عمران: 154","question":"ما دلالة الجمع بين ﴿مَا فِي صُدُورِكُمْ﴾ و﴿مَا فِي قُلُوبِكُمْ﴾ في آية واحدة؟","answer":"الصدور وعاء لما يختلج ويُخفى، فناسبها فعل الابتلاء الذي يكشف، والقلوب محل الاعتقاد والنية، فناسبها التمحيص الذي ينقي. وبذلك لم يكن التعبيران تكرارًا، بل وزع كل لفظ على المرحلة التي تلائمه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، برنامج لمسات بيانية — آية 154.؛ العنوان الجزئي: ملاءمة الصدور للابتلاء والقلوب للتمحيص.","url":""}]},{"id":"s3-846","number":846,"surah":3,"verses":[155,165],"references":[{"surah":3,"verses":[155,165]}],"verseLabel":"آل عمران: 155، 165","question":"ما وجه التكامل بين ﴿بِبَعْضِ مَا كَسَبُوا﴾ و﴿قُلْ هُوَ مِنْ عِندِ أَنْفُسِكُمْ﴾ في تفسير مصيبة أُحد؟","answer":"الأولى تكشف المدخل الباطني الذي استغله الشيطان، والثانية تحمل الجماعة مسؤولية النتيجة التي ترتبت على الاختيار والمخالفة. فاجتمع تحليل السبب النفسي مع تقرير المسؤولية العملية، حتى لا تُنسب الهزيمة إلى القدر على وجه يعطل المحاسبة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، عوائق الثبات في الآيتين 155 و165.؛ العنوان الجزئي: من زلة النفس إلى مسؤولية النتيجة.","url":""}]},{"id":"s3-847","number":847,"surah":3,"verses":[156],"references":[{"surah":3,"verses":[156]}],"verseLabel":"آل عمران: 156","question":"ما دلالة تسمية من خالفوا المجاهدين ﴿لِإِخْوَانِهِمْ﴾، مع اختلاف موقفهم عن موقف المؤمنين؟","answer":"الأخوة هنا أخوة نسب وقوم، لا أخوة إيمان؛ فكانوا من بني قومهم وإن خالفوا المجاهدين في الاعتقاد والموقف. وهذا يزيد أثر قولهم سوءًا، لأن القريب الذي يثبط عن الجهاد يلبس نصيحته ثوب الشفقة وهو يزرع الحسرة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الأخوة النسبية في آية 156.؛ العنوان الجزئي: الأخوة النسبية لا الأخوة الإيمانية.","url":""}]},{"id":"s3-848","number":848,"surah":3,"verses":[156,158],"references":[{"surah":3,"verses":[156,158]}],"verseLabel":"آل عمران: 156، 158","question":"ما وجه تخصيص سياق آل عمران بالموت في الغربة والجهاد، مقابل الموت على الفراش في سورة المؤمنون؟","answer":"آيات آل عمران تعالج وهم الذين ظنوا أن البقاء في البيوت يمنع الموت، فجاءت في سياق السفر والغزو والشهادة. أما المؤمنون فسياقها في إنكار البعث بعد الموت، فناسب ذكر الموت الذي يتصوره الناس على الفراش، فجاء كل سياق بما يثير شبهته ويجيب عنها.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف سياق الموت بين آل عمران والمؤمنون.؛ العنوان الجزئي: الموت في الغربة والموت على الفراش.","url":""}]},{"id":"s3-849","number":849,"surah":3,"verses":[157,158],"references":[{"surah":3,"verses":[157,158]}],"verseLabel":"آل عمران: 157، 158","question":"ما الأثر البلاغي لاختلاف حركة الميم في ﴿مُتُّمْ﴾ بآل عمران، و﴿مِتُّمْ﴾ في سورة المؤمنون؟","answer":"الضمة أثقل الحركات، فجاءت في سياق الموت المرتبط بالغربة والغزو والشهادة، وهو أشد على النفس من الموت على الفراش بين الأهل الذي يتحدث عنه سياق المؤمنون. فاختيار الحركة يوافق ثقل المشهد وشدته، لا مجرد اختلاف لهجي.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ثقل الضمة ومناسبة سياق الموت.؛ العنوان الجزئي: مناسبة حركة الميم لشدة السياق.","url":""}]},{"id":"s3-850","number":850,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"ما الفرق البلاغي بين ﴿إِن يَنصُرْكُمُ اللَّهُ﴾ و﴿إِن يَخْذُلْكُمْ﴾، وما الذي يضيفه لفظ الخذلان؟","answer":"النصر هو إعانة المؤمنين وتأييدهم، أما الخذلان فترك النصرة ورفع المعونة عنهم. فالمقابلة لا تتحدث عن هزيمة مجردة، بل ترد الأمر كله إلى جهة النصرة: إن تولى الله عباده فلا غالب لهم، وإن ترك نصرتهم فلا ناصر بعده.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين الخذلان والنصرة.؛ العنوان الجزئي: الخذلان ترك النصرة.","url":""}]},{"id":"s3-851","number":851,"surah":3,"verses":[160],"references":[{"surah":3,"verses":[160]}],"verseLabel":"آل عمران: 160","question":"ما سر مجيء الشرطين في الآية متقابلين: ﴿إِن يَنصُرْكُمُ اللَّهُ﴾ و﴿إِن يَخْذُلْكُمْ﴾؟","answer":"جمع الشرطان طرفي حال المؤمن في الصراع: نصر يزيل كل غلبة، وترك للنصرة لا يملك معه أحد أن ينقذ. وبذلك ينتقل السياق من تقرير القدرة الإلهية إلى بناء التوكل العملي على هذا التقرير.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، المقابلة بين النصر والخذلان.؛ العنوان الجزئي: المقابلة بين النصر والخذلان.","url":""}]},{"id":"s3-852","number":852,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما سر اختلاف التعبير بين ﴿وَمَأْوَاهُ جَهَنَّمُ﴾ في آل عمران، و﴿مَأْوَاكُمُ النَّارُ هِيَ مَوْلَاكُمْ﴾ في سورة الحديد؟","answer":"آية آل عمران تتحدث عن الكافرين وهم في الدنيا، فناسبها الإخبار بأن جهنم مأواهم ومصيرهم. أما آية الحديد فجاءت في مشهد الآخرة بعد أن صار العذاب حاضرًا قريبًا منهم، فقيل: ﴿هِيَ مَوْلَاكُمْ﴾؛ أي هي التي تليهم وتحيط بهم، لا مجرد مأوى مستقبل.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «مأواه جهنم» و«هي مولاكم».؛ العنوان الجزئي: اختلاف «المأوى» و«المولى» باختلاف مقام الدنيا والآخرة.","url":""}]},{"id":"s3-853","number":853,"surah":3,"verses":[162],"references":[{"surah":3,"verses":[162]}],"verseLabel":"آل عمران: 162","question":"ما سر قوله في آل عمران: ﴿وَمَأْوَاهُ جَهَنَّمُ﴾، وفي الحديد: ﴿مَأْوَاكُمُ النَّارُ هِيَ مَوْلَاكُمْ﴾؟","answer":"آية آل عمران تتحدث عن فرد صيغ في صورة «من» فاتسق معها ضمير المفرد ومأواه، أما الحديد فخطاب لجماعة المنافقين والكافرين فناسبه الجمع. وزادت آية الحديد ﴿هِيَ مَوْلَاكُمْ﴾ لأن المقام مقام مواجهة مباشرة وقطع لما كانوا يرجونه من نصير.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف ختام آيتي آل عمران والحديد.؛ العنوان الجزئي: الإفراد والجمع وزيادة «هي مولاكم».","url":""}]},{"id":"s3-854","number":854,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما دلالة تقديم ﴿وَيُزَكِّيهِمْ﴾ على ﴿وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ﴾ في آل عمران، مع عكس الترتيب في دعاء إبراهيم؟","answer":"دعاء إبراهيم يصف ما يرجوه من بعثة الرسول، فذكر التعليم ثم التزكية. أما في مقام بيان بعثة الرسول واقعًا، فقدّمت التزكية؛ لأن القلب إذا لم يتهذب ولم يتهيأ لم ينتفع بالكتاب والحكمة على وجههما. فاختلاف الترتيب تابع لاختلاف مقام الدعاء عن مقام تحقق النعمة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف ترتيب التزكية والتعليم.؛ العنوان الجزئي: التقديم والتأخير بين التزكية والتعليم.","url":""}]},{"id":"s3-855","number":855,"surah":3,"verses":[164],"references":[{"surah":3,"verses":[164]}],"verseLabel":"آل عمران: 164","question":"ما سر افتتاح الآية بقوله: ﴿لَقَدْ مَنَّ اللَّهُ﴾، بينما افتتحت آية الجمعة بقوله: ﴿هُوَ الَّذِي بَعَثَ﴾؟","answer":"«لقد منّ» يصرّح بالنعمة ويستحضر أثرها في المؤمنين، ولذلك ناسب مقام التذكير بفضل الرسالة عليهم. أما «هو الذي بعث» فجاء في مقام التعريف بفاعل البعث وإثبات قدرته، فناسبه ضمير الفصل والإخبار عن فعل الله دون التركيز على تعداد المنن.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف مقام الامتنان عن مقام الإخبار بالبعثة.؛ العنوان الجزئي: «لقد منّ» و«هو الذي بعث» بحسب المقام.","url":""}]},{"id":"s3-856","number":856,"surah":3,"verses":[168],"references":[{"surah":3,"verses":[168]}],"verseLabel":"آل عمران: 168","question":"ما سر اختيار الفعل ﴿فَادْرَؤُوا﴾ في قوله تعالى: ﴿فَادْرَؤُوا عَنْ أَنفُسِكُمُ الْمَوْتَ﴾ بدل «فاحموا أنفسكم»؟","answer":"الدرء هو الدفع، وفيه تصوير للموت خطرًا مباغتًا قويًا لا يملك الإنسان مقاومته متى جاء. أما الحماية فتناسب خطرًا منظورًا يستطيع المرء أن يراه ويتخذ له وقاية؛ لذلك جاء اللفظ موافقًا لمفاجأة الموت واستحالة دفعه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «فادرؤوا» في مواجهة الموت.؛ العنوان الجزئي: الدرء والدفع في تصوير مفاجأة الموت.","url":""}]},{"id":"s3-857","number":857,"surah":3,"verses":[169,171],"references":[{"surah":3,"verses":[169,171]}],"verseLabel":"آل عمران: 169، 171","question":"ما سر انتقال وصف الشهداء من النهي عن حسبانهم أمواتًا إلى أفعال الحياة: ﴿يُرْزَقُونَ﴾ و﴿فَرِحِينَ﴾ و﴿يَسْتَبْشِرُونَ﴾؟","answer":"لم يكتف النص بنفي الموت عنهم، بل ملأ صورة حياتهم بالحركة والرزق والفرح والبشارة. وبهذا تتحول الحقيقة الغيبية إلى مشهد حي يثبت المؤمنين، فلا تبدو الشهادة فقدًا مجردًا بل انتقالًا إلى كرامة متجددة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، وصف الشهداء في سياق تثبيت السورة، ودلالة «من خلفهم».؛ العنوان الجزئي: بناء صورة الحياة بعد نفي الموت.","url":""}]},{"id":"s3-858","number":858,"surah":3,"verses":[170],"references":[{"surah":3,"verses":[170]}],"verseLabel":"آل عمران: 170","question":"ما سر جمع بشارة الشهداء لإخوانهم بين ﴿أَلَّا خَوْفٌ عَلَيْهِمْ﴾ و﴿وَلَا هُمْ يَحْزَنُونَ﴾؟","answer":"الخوف يتجه إلى ما يُستقبل، والحزن يتعلق بما فات؛ فجمعت البشارة الأمن من المستقبل والسلامة من أسى الماضي. وبذلك أحاطت الطمأنينة بزمني النفس كليهما، وهو أبلغ في تثبيت من بقي في طريق الجهاد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، استبشار الشهداء بمن خلفهم.؛ العنوان الجزئي: نفي الخوف والحزن عن اللاحقين.","url":""}]},{"id":"s3-859","number":859,"surah":3,"verses":[173],"references":[{"surah":3,"verses":[173]}],"verseLabel":"آل عمران: 173","question":"ما وجه زيادة الإيمان بعد سماع خبر الخطر في قوله تعالى: ﴿فَزَادَهُمْ إِيمَانًا﴾؟","answer":"الخوف كشف مقدار اعتمادهم على الله، فلم يتحول الخبر عندهم إلى هلع، بل إلى يقين بقدرته وثقة بوعده. لذلك قابلوا التهديد بقولهم: ﴿حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ﴾، فصار ما أراده المخوِّفون سببًا في تقوية الإيمان بدل إضعافه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الخوف المتوقع وأثره في زيادة الإيمان.؛ العنوان الجزئي: انقلاب التخويف إلى يقين وتوكل.","url":""}]},{"id":"s3-860","number":860,"surah":3,"verses":[174],"references":[{"surah":3,"verses":[174]}],"verseLabel":"آل عمران: 174","question":"ما سر الجمع بين ﴿بِنِعْمَةٍ مِّنَ اللَّهِ وَفَضْلٍ﴾، مع أن المؤمنين لم يذكروا حصول غنيمة أو مكسب مادي؟","answer":"النعمة هنا سلامتهم من السوء، والفضل عناية الله التي ثبّتتهم وأبطل بها كيد عدوهم، ثم أضاف إليهما اتباع رضوانه. فليس الفضل مقصورًا على زيادة المال؛ قد يكون أعظم الفضل أن ينجو المؤمن ويحفظ دينه ويعود ثابت القلب.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، النعمة والفضل في نجاة المؤمنين.؛ العنوان الجزئي: شمول النعمة والفضل للنجاة والهداية.","url":""}]},{"id":"s3-861","number":861,"surah":3,"verses":[176,178],"references":[{"surah":3,"verses":[176,178]}],"verseLabel":"آل عمران: 176، 178","question":"ما وجه اختلاف خواتيم الآيات بين ﴿عَذَابٌ عَظِيمٌ﴾ و﴿عَذَابٌ أَلِيمٌ﴾ و﴿عَذَابٌ مُّهِينٌ﴾؟","answer":"الذين يسارعون في الكفر ويُحرمون حظ الآخرة ناسبهم وصف العذاب بالعظيم لشدة ما ينتظرهم. والذين اشتروا الكفر بالإيمان خاسرون، فناسب الخسران وصف العذاب بالأليم. أما من أُمهل حتى يزداد إثمًا، فجزاء فعله عذاب مهين يفضح ما ظنه خيرًا لنفسه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف «عظيم» و«أليم» و«مهين».؛ العنوان الجزئي: مناسبة وصف العذاب لحال كل فريق.","url":""}]},{"id":"s3-862","number":862,"surah":3,"verses":[181],"references":[{"surah":3,"verses":[181]}],"verseLabel":"آل عمران: 181","question":"ما سر زيادة اللام في ﴿لَقَدْ سَمِعَ اللَّهُ﴾ عند قولهم: ﴿إِنَّ اللَّهَ فَقِيرٌ﴾، مقابل ﴿قَدْ سَمِعَ اللَّهُ﴾ في شكوى المجادِلة؟","answer":"قولهم في حق الله افتراء بالغ الجسارة، وتلاه وعيد بالكتابة والعذاب؛ فناسبه توكيد السماع بلام القسم و«قد». أما شكوى المرأة فمقام رحمة وإجابة لا مقام إنكار لقول شنيع، فجاء التحقيق بـ«قد» من غير اللام.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «لقد سمع» و«قد سمع».؛ العنوان الجزئي: زيادة التوكيد بقدر فظاعة المقول.","url":""}]},{"id":"s3-863","number":863,"surah":3,"verses":[182],"references":[{"surah":3,"verses":[182]}],"verseLabel":"آل عمران: 182","question":"ما سر استعمال ﴿بِمَا قَدَّمَتْ أَيْدِيكُمْ﴾ في آل عمران والأنفال، واستعمال ﴿بِمَا كَسَبَتْ أَيْدِي النَّاسِ﴾ في مواضع أخرى؟","answer":"التقديم يلحظ ما يقدمه الإنسان لآخرته من عمل، ولا يلزم أن يكون في سياق الكسب والاستحواذ. أما «الكسب» فيناسب جمع الشيء والاستحواذ عليه، ولذلك جاء في سياقات تتعلق بما اكتسبه الناس من فساد أو سوء تصرف. فاختيار اللفظ تابع لطبيعة العمل وسياقه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «قدمت أيديكم» و«كسبت أيدي الناس».؛ العنوان الجزئي: التقديم للآخرة والكسب في سياق الاستحواذ.","url":""}]},{"id":"s3-864","number":864,"surah":3,"verses":[183],"references":[{"surah":3,"verses":[183]}],"verseLabel":"آل عمران: 183","question":"ما دلالة جمعهم بين طلب ﴿قُرْبَانٍ تَأْكُلُهُ النَّارُ﴾، ثم تذكيرهم بأن الرسل جاءوا ﴿بِالْبَيِّنَاتِ وَبِالَّذِي قُلْتُمْ﴾؟","answer":"أعاد الرد عليهم علامتهم المقترحة نفسها، فلم يكتف بذكر البينات العامة؛ لقد جاء رسل سابقون بالدلائل وبالقربان الذي اشترطوه، ومع ذلك قتلوهم. فالتعبير يسقط عذرهم من داخله ويكشف أن المشكلة ليست نقص الآية بل رفض الحق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، آية القربان وصياغة الحجة.؛ العنوان الجزئي: إلزام المعترضين بشرطهم السابق.","url":""}]},{"id":"s3-865","number":865,"surah":3,"verses":[183],"references":[{"surah":3,"verses":[183]}],"verseLabel":"آل عمران: 183","question":"ما سر تأنيث الفعل في ﴿تَأْكُلُهُ النَّارُ﴾، ثم تذكير الفعل في قوله: ﴿جَاءَكُمْ رُسُلٌ﴾؟","answer":"جاء كل فعل على مقتضى فاعله: النار مؤنثة لفظًا فأنث فعلها، والرسل جمع تكسير للعقلاء يغلب معه اعتبار معنى الجماعة المذكرة في هذا السياق. وليس الاختلاف شكليًا؛ فقد حافظ التعبير على الصورة الحية للنار الآكلة وعلى استقلال الرسل بالفعل والحجة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، التذكير والتأنيث في آية القربان.؛ العنوان الجزئي: ملاءمة الفعل لفاعله في مشهد الحجة.","url":""}]},{"id":"s3-866","number":866,"surah":3,"verses":[185],"references":[{"surah":3,"verses":[185]}],"verseLabel":"آل عمران: 185","question":"ما وجه الصلة بين ﴿فَمَن زُحْزِحَ عَنِ النَّارِ﴾ في آل عمران، و﴿سَيُجَنَّبُهَا الْأَتْقَى﴾ في سورة الليل؟","answer":"التعبيران يبرزان أن النجاة من النار ليست بقدرة الإنسان المستقلة؛ فالعبد يُزحزح عنها أو يُجنَّبها بفعل الله وتوفيقه. وفي ذلك تصحيح للتصور الذي يجعل التقوى وحدها سببًا مستقلًا للنجاة، مع كونها سببًا شرعيًا لا يستغني عن رحمة الله.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، النجاة من النار بين «زحزح» و«يجنبها».؛ العنوان الجزئي: إسناد النجاة إلى فعل الله تعالى.","url":""}]},{"id":"s3-867","number":867,"surah":3,"verses":[187,188,199],"references":[{"surah":3,"verses":[187,188,199]}],"verseLabel":"آل عمران: 187، 188، 199","question":"كيف تبني الآيات مقابلة متوازنة بين فعل أهل الكتاب وجزائهم؟","answer":"رتبت الصورة على طرفين متقابلين: نبذ الميثاق وشراء الثمن القليل ثم العذاب، في مقابل الإيمان والخشوع ورفض البيع ثم الأجر. هذا التوازي يجعل العاقبة امتدادًا للعمل، ويكشف أن الربح الظاهر في الدنيا هو عين الخسارة إذا كان ثمنه الحق.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، التقابل بين العمل والعاقبة.؛ العنوان الجزئي: التناظر بين طريق البيع وطريق الوفاء.","url":""}]},{"id":"s3-868","number":868,"surah":3,"verses":[187,188,199],"references":[{"surah":3,"verses":[187,188,199]}],"verseLabel":"آل عمران: 187، 188، 199","question":"ما سر عودة الحديث عن أهل الكتاب في الآية 199 بعد ذم من نبذوا الميثاق في الآيتين 187–188؟","answer":"عادت الآية لتمنع تعميم الذم؛ فبعد عرض من كتموا الكتاب وباعوا آيات الله، ذكرت من آمنوا وخشعوا وحفظوا الوحي. وبذلك يقيم السياق ميزانًا عادلًا داخل الجماعة الواحدة، ويجعل الحكم تابعًا للموقف من الحق لا للاسم الموروث.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، مناسبة الآية 199 لما قبلها.؛ العنوان الجزئي: مقابلة الناكثين بالمؤمنين من أهل الكتاب.","url":""}]},{"id":"s3-869","number":869,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"كيف يجمع لفظ ﴿خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ﴾ بين التأمل في فعل الخلق والتأمل في المخلوقات نفسها؟","answer":"«الخلق» مصدر يحتمل معنى الإنشاء والإيجاد، ويستعمل كذلك بمعنى المخلوق. ولذلك تتسع الآية للتفكر في كيفية إبداع السماوات والأرض، وللتفكر في ذواتهما وصفاتهما وما أودع فيهما من عجائب؛ فتجتمع آيات الفعل وآيات المفعول في لفظ واحد.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اتساع معنى «خلق السماوات والأرض».؛ العنوان الجزئي: «الخلق» بين المصدر والمخلوق.","url":""}]},{"id":"s3-870","number":870,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما الذي يضيفه وصف المتفكرين بأنهم ﴿أُولِي الْأَلْبَابِ﴾، لا مجرد «أصحاب عقول»؟","answer":"اللُّب هو خالص العقل وجوهره بعد تنقيته من الهوى وشوائب الوهم؛ فكل لُبّ عقل، وليس كل عقل لُبًّا. وجاء الوصف ليبين أن الانتفاع بآيات الكون يحتاج إلى عقل راجح زكي، لا إلى مجرد قدرة ذهنية قد تقودها الأهواء.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «أولي الألباب».؛ العنوان الجزئي: اللُّب بوصفه العقل الخالص من الشوائب.","url":""}]},{"id":"s3-871","number":871,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما سر إسناد إدراك آيات الخلق إلى ﴿أُولِي الْأَلْبَابِ﴾ خاصة؟","answer":"مشاهد الكون متاحة للجميع، لكن تحويلها إلى دلائل على القدرة والحكمة يحتاج إلى عقل متحرر من الهوى والوهم. لذلك لم تجعل الآية مجرد الرؤية كافية، بل علقت الانتفاع بأصحاب العقول الزكية التي تنفذ من ظاهر المشهد إلى دلالته.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، أولو الألباب والانتفاع بآيات الكون.؛ العنوان الجزئي: العقل الزكي شرط الانتفاع بالآيات.","url":""}]},{"id":"s3-872","number":872,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما سر اختصار مشاهد الآيات في آل عمران، مقابل تفصيلها في آية البقرة 164؟","answer":"آية البقرة جاءت بعد تقرير وحدانية الله، فناسبها استقصاء الأدلة: الفلك والماء وإحياء الأرض والدواب والرياح والسحاب. أما آل عمران فجاءت في مقام إيقاظ أولي الألباب، فاكتفت بأصلين جامعَين: خلق السماوات والأرض واختلاف الليل والنهار، لأن المقصود تنبيه العقل إلى دلالة الخلق لا تعداد مظاهره.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف التفصيل بين آيتي البقرة وآل عمران.؛ العنوان الجزئي: التفصيل والإجمال بحسب سياق التوحيد والتفكر.","url":""}]},{"id":"s3-873","number":873,"surah":3,"verses":[190],"references":[{"surah":3,"verses":[190]}],"verseLabel":"آل عمران: 190","question":"ما سر ختم آية آل عمران بـ﴿لَآيَاتٍ لِّأُولِي الْأَلْبَابِ﴾، وختم آية البقرة بـ﴿لَآيَاتٍ لِّقَوْمٍ يَعْقِلُونَ﴾؟","answer":"آية البقرة تسوق أدلة مفصلة تحتاج إلى تعقل ونظر في انتظامها، فناسبها وصف «يعقلون». أما آية آل عمران فتتجه إلى من تجاوز مجرد إدراك النظام إلى التفكر في غايته والاعتبار به، فناسبها وصف «أولي الألباب»؛ لأن اللب أعمق من مجرد استعمال العقل في الملاحظة.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، اختلاف «أولي الألباب» و«يعقلون».؛ العنوان الجزئي: تفاوت المخاطبين بين التعقل والتفكر.","url":""}]},{"id":"s3-874","number":874,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما المنهج الدعائي الذي يكشفه تقديم الذكر والتنزيه على قوله: ﴿فَقِنَا عَذَابَ النَّارِ﴾؟","answer":"الآية تعلم أن يحسن الداعي تقديم ذكر الله والثناء عليه قبل عرض حاجته، كما سبقت المحامد وعبادة الله طلبَ الهداية في الفاتحة. فالدعاء هنا ثمرة معرفة وتعظيم، لا طلبًا منفصلًا عن حضور القلب مع الله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص32–35، الثناء على الله بين يدي الدعاء.؛ العنوان الجزئي: أدب تقديم الثناء قبل المسألة.","url":""}]},{"id":"s3-875","number":875,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما دلالة إطلاق الذكر في ﴿يَذْكُرُونَ اللَّهَ﴾ من غير تقييده باللسان أو القلب؟","answer":"الإطلاق يشمل ذكر اللسان وذكر القلب؛ فلا ينحصر وصف أولي الألباب في ألفاظ يرددونها، ولا في خواطر باطنة لا تظهر آثارها. إنما يجتمع حضور القلب مع نطق اللسان، فيكون الذكر شاملًا للباطن والظاهر.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص32–35، ذكر الله باللسان والقلب.؛ العنوان الجزئي: شمول الذكر للسان والقلب.","url":""}]},{"id":"s3-876","number":876,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما سر الجمع بين دوام الذكر والتفكر في الخلق في وصف أولي الألباب؟","answer":"الذكر يصل القلب بالخالق، والتفكر يقرأ آثار حكمته في الخلق؛ فإذا اجتمعا سلم النظر من الغفلة وسلم الذكر من الانفصال عن آيات الكون. ولذلك أثمر اجتماعهما تنزيه الله عن العبث، ثم التوجه إليه بالدعاء.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص32–35، الذكر والتفكر ثم التنزيه والدعاء.؛ العنوان الجزئي: تكامل معرفة الخالق والنظر في الخلق.","url":""}]},{"id":"s3-877","number":877,"surah":3,"verses":[191],"references":[{"surah":3,"verses":[191]}],"verseLabel":"آل عمران: 191","question":"ما سر تعقيب ﴿مَا خَلَقْتَ هَذَا بَاطِلًا﴾ مباشرةً بقوله: ﴿سُبْحَانَكَ﴾؟","answer":"لما نفوا العبث عن الخلق أتبعوه بتنزيه الخالق عن كل ما لا يليق به؛ فـ«سبحانك» تقرر أن أفعاله كلها حق وحكمة. وبذلك لا تبقى نتيجة التفكر فكرة عقلية مجردة، بل تتحول إلى تعظيم وتنزيه لله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص32–35، التنزيه عن العبث والباطل.؛ العنوان الجزئي: انتقال التفكر إلى التنزيه.","url":""}]},{"id":"s3-878","number":878,"surah":3,"verses":[191,192],"references":[{"surah":3,"verses":[191,192]}],"verseLabel":"آل عمران: 191، 192","question":"ما سر الانتقال من طلب الوقاية: ﴿فَقِنَا عَذَابَ النَّارِ﴾ إلى تقرير عاقبة من يدخلها: ﴿فَقَدْ أَخْزَيْتَهُ﴾؟","answer":"بدأ الدعاء بطلب النجاة، ثم بيّنوا سبب شدة افتقارهم إليها: دخول النار خزي وفضيحة لا مجرد ألم عابر. فالجملة الثانية تعمق معنى الطلب الأول، وتكشف وعيهم بحقيقة المصير الذي يستعيذون منه.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص35–40، دخول النار خزي وإهانة.؛ العنوان الجزئي: تعليل سؤال الوقاية ببيان حقيقة الخزي.","url":""}]},{"id":"s3-879","number":879,"surah":3,"verses":[191,194],"references":[{"surah":3,"verses":[191,194]}],"verseLabel":"آل عمران: 191، 194","question":"ما أثر استقلال مطالب الدعاء المتتابعة المفتتحة بـ﴿رَبَّنَا﴾ من غير ربطها كلها بحروف العطف؟","answer":"استقلال الجمل يجعل كل مطلب قائمًا بنفسه عظيم الشأن: الوقاية، والمغفرة، والتكفير، وحسن الخاتمة، وإنجاز الوعد، والسلامة من الخزي. فلا تبدو المطالب توابع سريعة لمطلب واحد، بل مناجاة متجددة يتكرر فيها الافتقار.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص47–50، استقلال مطالب الدعاء وعلو شأنها.؛ العنوان الجزئي: تعدد المطالب واستقلال كل مناجاة.","url":""}]},{"id":"s3-880","number":880,"surah":3,"verses":[191,195],"references":[{"surah":3,"verses":[191,195]}],"verseLabel":"آل عمران: 191، 195","question":"ما الذي يكشفه جواب الدعاء عن الصلة بين الإيمان والعمل والثناء قبل المسألة؟","answer":"سبق الدعاء ذكرُ الله والتفكر والثناء، وصرح الداعون بإيمانهم، ثم جاء الجواب: ﴿لَا أُضِيعُ عَمَلَ عَامِلٍ﴾. فدل السياق على أن الاستجابة لم تُعرض بوصفها كلمات مجردة، بل ثمرة إيمان وعمل صالح وتعظيم لله قُدم بين يدي الدعاء.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص50–52، مدار الاستجابة على الإيمان والعمل والثناء.؛ العنوان الجزئي: الدعاء المؤيد بالإيمان والعمل.","url":""}]},{"id":"s3-881","number":881,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"كيف يكون نفي «الناصر» أقوى في الدلالة من نفي «النصير» مع أن «النصير» صيغة مبالغة؟","answer":"إذا نُفي أصل الناصر فقد انتفى النصير القوي من باب أولى؛ لأن نفي القليل يشمل الكثير، أما نفي الكثير فلا يلزم منه نفي القليل. لذلك يكون قولك «ما له من ناصر» أبلغ في استئصال كل قدر من النصرة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص35–40، قوة نفي الناصر والنصير.؛ العنوان الجزئي: نفي أصل النصرة ونفي المبالغة فيها.","url":""}]},{"id":"s3-882","number":882,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"ما الفرق البلاغي بين نفي ﴿أَنصَارٍ﴾ عن الظالمين، ونفي ﴿نَاصِرِينَ﴾ عن الكافرين في السورة نفسها؟","answer":"«الأنصار» تحتمل جمع ناصر وجمع نصير، أما «الناصرون» فهي جمع ناصر. وقد جاء نفي الناصرين في سياقات الكفر الشديد والضلال المستحكم، بينما جاء «أنصار» مع وصف الظلم الذي قد يكون كفرًا وقد يكون دونه؛ فاختير لكل مقام ما يلائمه.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص35–40، الفرق بين «أنصار» و«ناصرين».؛ العنوان الجزئي: تفاوت نفي النصرة بحسب شدة الوصف.","url":""}]},{"id":"s3-883","number":883,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"ما سر استعمال الجمع ﴿أَنصَارٍ﴾ في آل عمران، مقابل المفرد ﴿مِنْ نَصِيرٍ﴾ في سورة الحج؟","answer":"آية آل عمران تتحدث عن الظالمين على امتداد الأزمنة، فناسب كثرتهم وتعدد صور النصرة أن ينفى عنهم «أنصار». أما آية الحج فسياقها في جماعة مخصوصة في زمن الرسول، فناسبها المفرد «نصير». ويتبع اللفظ مقدار العموم والكثرة في السياق.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «أنصار» و«نصير».؛ العنوان الجزئي: المفرد والجمع في نفي النصرة.","url":""}]},{"id":"s3-884","number":884,"surah":3,"verses":[192],"references":[{"surah":3,"verses":[192]}],"verseLabel":"آل عمران: 192","question":"ما سر التعبير عن المدخلين النار بقوله: ﴿لِلظَّالِمِينَ﴾؟","answer":"عُدل عن الضمير إلى وصف الظلم لإظهار علة دخول النار وذم أصحابها، ولتتسع الدلالة فتشمل كل ظالم، لا جماعة بعينها. فالاسم الظاهر هنا يحمل حكمًا أخلاقيًا وسببًا للعقوبة في الوقت نفسه.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، وضع «الظالمين» موضع الضمير.؛ العنوان الجزئي: إظهار الوصف بدل الإضمار للتعليل والذم.","url":""}]},{"id":"s3-885","number":885,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة الفاء في جوابهم: ﴿فَآمَنَّا﴾؟","answer":"الفاء تفيد التعقيب والسببية، فتصور أن الإيمان ترتب على سماع النداء من غير مهلة ولا تردد. وبذلك يمدح التعبير سرعة استجابتهم، لا مجرد وقوع الإيمان منهم في وقت لاحق.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، الفاء في «فآمنا».؛ العنوان الجزئي: تعجيل القبول وتسبب الإيمان عن السماع.","url":""}]},{"id":"s3-886","number":886,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة حذف المفعول الصريح في قوله: ﴿يُنَادِي لِلْإِيمَانِ﴾؟","answer":"حذف من وُجه إليه النداء يفيد العموم، فكأن المنادي يدعو كل من يصل إليه صوته، لا فئة مخصوصة. وفي ذلك توسيع لرسالة الإيمان وإظهار أنها خطاب مفتوح للناس جميعًا.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، حذف مفعول «ينادي» للعموم.؛ العنوان الجزئي: عموم المدعوين إلى الإيمان.","url":""}]},{"id":"s3-887","number":887,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة قولهم: ﴿سَمِعْنَا مُنَادِيًا﴾ مع أن كثيرًا منهم لم يروا الرسول ﷺ؟","answer":"يبرز التعبير أنهم صدقوا الدعوة عن طريق السماع من غير اشتراط رؤية الرسول، وفي ذلك إظهار لصدق إيمانهم وسرعة قبولهم. كما يتسع المنادي للقرآن الباقي الذي يسمعه الناس على مر العصور.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، الإيمان بالسماع من غير رؤية.؛ العنوان الجزئي: فضل الاستجابة للرسالة المسموعة.","url":""}]},{"id":"s3-888","number":888,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما دلالة قولهم: ﴿وَتَوَفَّنَا مَعَ الْأَبْرَارِ﴾ بدل الاكتفاء بطلب الوفاة على الإيمان؟","answer":"لم يطلبوا سلامة الخاتمة منفردين فحسب، بل سألوا أن يكونوا معدودين في جملة الأبرار ومخصوصين بصحبتهم. فـ«مع» تضيف معنى الرفقة والمنزلة المشتركة، وتكشف شوقهم إلى جماعة الصالحين في المصير.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، صحبة الأبرار وحسن الخاتمة.؛ العنوان الجزئي: طلب الرفقة الصالحة في الآخرة.","url":""}]},{"id":"s3-889","number":889,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما سر اختيار ﴿مُنَادِيًا﴾ بدل «داعيًا» في وصف من دعاهم إلى الإيمان؟","answer":"النداء يشعر برفع الصوت والمبالغة في الإسماع، فيصور عناية المنادي بتبليغ الدعوة إلى القريب والبعيد. أما «الداعي» فلا يحمل وحده هذه الصورة القوية في الإبلاغ، فكان «المنادي» أليق بعظمة الرسالة وعمومها.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، إيثار المنادي على الداعي.؛ العنوان الجزئي: قوة الإسماع وعموم التبليغ.","url":""}]},{"id":"s3-890","number":890,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما سر التوكيد في ﴿إِنَّنَا سَمِعْنَا﴾ بآل عمران، مقابل ﴿إِنَّا سَمِعْنَا﴾ على لسان الجن؟","answer":"أُظهرت النون في ﴿إننا﴾ لزيادة التوكيد؛ لأنهم سمعوا مناديًا يرفع النداء، ولأن كلامهم جاء في مقام التضرع والتوسل وطلب المغفرة وحسن الخاتمة. أما الجن فذكروا سماع الكتاب، ولم يقع كلامهم في سلسلة المطالب الدعائية نفسها، فناسب التخفيف.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، «إننا سمعنا» و«إنا سمعنا».؛ العنوان الجزئي: زيادة التوكيد بحسب المسموع ومقام التضرع.","url":""}]},{"id":"s3-891","number":891,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما سر تقديم المغفرة والتكفير على قولهم: ﴿وَتَوَفَّنَا مَعَ الْأَبْرَارِ﴾؟","answer":"طلبوا أولًا أن يلقوا الله وقد غُفرت ذنوبهم وكُفرت سيئاتهم، ثم سألوا حسن الخاتمة؛ فالتطهير يسبق الوفاة في ترتيب الرجاء. وفي ذلك خوف من أن يدركهم الموت قبل إصلاح ما بينهم وبين الله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، تقديم التطهير على طلب حسن الخاتمة.؛ العنوان الجزئي: الموت بعد المغفرة والتكفير.","url":""}]},{"id":"s3-892","number":892,"surah":3,"verses":[193],"references":[{"surah":3,"verses":[193]}],"verseLabel":"آل عمران: 193","question":"ما سر وصل قولهم ﴿فَآمَنَّا﴾ بطلب المغفرة والتكفير؟","answer":"الإيمان هو الباب الذي تُرجى بعده المغفرة والتكفير؛ فالإسلام يجب ما قبله، ومن لم يؤمن لا يكون في مقام هذا الرجاء. لذلك قدموا إعلان الاستجابة، ثم بنوا عليه سؤال محو آثار الذنب والسيئة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص40–47، الإيمان مدعاة إلى المغفرة والتكفير.؛ العنوان الجزئي: بناء طلب المغفرة على تحقق الإيمان.","url":""}]},{"id":"s3-893","number":893,"surah":3,"verses":[193,195],"references":[{"surah":3,"verses":[193,195]}],"verseLabel":"آل عمران: 193، 195","question":"كيف استجمع سياق دعاء أولي الألباب أصول الإيمان قبل وعدهم بعدم إضاعة العمل؟","answer":"صرحوا بالإيمان بالله، وصدقوا الرسل وما جاء على ألسنتهم، ويلزم من ذلك الإيمان بالكتب والملائكة الذين يبلغون الوحي. وذكروا يوم القيامة والميعاد، وما في الكتب من القدر؛ فاجتمعت أصول الإيمان في السياق قبل ذكر العمل والجزاء.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص50–52، استكمال عناصر الإيمان في سياق الدعاء.؛ العنوان الجزئي: اكتمال الإيمان قبل الوعد بالجزاء.","url":""}]},{"id":"s3-894","number":894,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"كيف يجمع الدعاء بين طلب النصر في الدنيا وطلب السلامة من الخزي في الآخرة؟","answer":"إذا شمل الوعد النصر والثواب، صار الدعاء جامعًا لكرامة الدارين: ألا يُخزوا في الدنيا بغلبة العدو، وألا يُخزوا في الآخرة بسوء الحساب. فالثبات عندهم لا ينفصل عن حسن المصير، ولا يقتصر على نتيجة المعركة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص47–50، الجمع بين وعد النصر ووعد الثواب.؛ العنوان الجزئي: نفي خزي الدنيا والآخرة.","url":""}]},{"id":"s3-895","number":895,"surah":3,"verses":[194],"references":[{"surah":3,"verses":[194]}],"verseLabel":"آل عمران: 194","question":"ما دلالة قولهم: ﴿وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ﴾ بعد سؤالهم إنجاز الوعد؟","answer":"طلبوا ألا يفضحهم الله بما صدر منهم من تقصير، بل يستر عليهم يوم ظهور الأعمال. فإيمانهم بالوعد لم يحملهم على الاغترار، وإنما جمعوا الرجاء في فضل الله مع الخوف من ذنوبهم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص47–50، معنى الخزي في دعاء يوم القيامة.؛ العنوان الجزئي: الرجاء في الوعد مع الخوف من الفضيحة.","url":""}]},{"id":"s3-896","number":896,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما الصورة المقابلة بين ﴿أُخْرِجُوا مِن دِيَارِهِمْ﴾ و﴿لَأُدْخِلَنَّهُمْ جَنَّاتٍ﴾؟","answer":"قابل الله إخراجهم القسري من مساكن الدنيا بإدخاله إياهم جنات الآخرة؛ فما فقدوه في سبيله عوضهم عنه دارًا خيرًا. وتمنح المقابلة المظلوم يقينًا بأن الإخراج ليس نهاية القصة، بل وراءه إدخال كريم من الله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، الإخراج من الديار والإدخال إلى الجنات.؛ العنوان الجزئي: الجزاء من جنس الابتلاء على وجه أكرم.","url":""}]},{"id":"s3-897","number":897,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما دلالة العبارة الجامعة ﴿بَعْضُكُم مِّن بَعْضٍ﴾ بعد ذكر الذكر والأنثى؟","answer":"تؤكد العبارة وحدة الأصل الإنساني، وأن الذكر من الأنثى والأنثى من الذكر، فلا فضل في الجزاء بسبب الجنس أو النسب. وجاءت لتقرر شركة النساء مع الرجال في الوعد، وتردّ ما كان في أعراف الناس من احتقار المرأة أو جعل العمل الفاضل مقصورًا على الرجال.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، دلالة «بعضكم من بعض».؛ العنوان الجزئي: وحدة الأصل وشمول الثواب للرجال والنساء.","url":""}]},{"id":"s3-898","number":898,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما دلالة بناء ﴿أُخْرِجُوا﴾ للمجهول، وإسناد ﴿لَأُدْخِلَنَّهُمْ﴾ إلى الله بصيغة المتكلم؟","answer":"طوى التعبير ذكر من أخرجهم لحقارته وعدم العناية به، ثم أبرز فاعل الإدخال وأكده؛ فالمخرجون من البشر عارضون، أما الذي يتولى الجزاء والإدخال فهو رب العزة. وبذلك تنتقل العناية من يد الظلم إلى يد الكرامة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، المبني للمجهول وإسناد الإدخال إلى الله.؛ العنوان الجزئي: إخفاء فاعل الظلم وإظهار فاعل الجزاء.","url":""}]},{"id":"s3-899","number":899,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما دلالة تقديم ﴿لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ﴾ على ﴿وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ﴾؟","answer":"دخول الجنة يكون بعد إزالة ما يحول دونه من السيئات، فقدم التكفير لأنه أسبق في ترتيب الجزاء. وجاء النظم موافقًا لمسار النجاة: تطهير من التبعة أولًا، ثم إدخال إلى دار النعيم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، تقديم التكفير على دخول الجنة.؛ العنوان الجزئي: ترتيب التطهير والنعيم.","url":""}]},{"id":"s3-900","number":900,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سر التوكيد بالنون في ﴿لَأُكَفِّرَنَّ﴾ و﴿لَأُدْخِلَنَّهُمْ﴾، مقابل السين في ﴿سَنُدْخِلُهُمْ جَنَّاتٍ﴾؟","answer":"كلا الأسلوبين يدل على الاستقبال، لكن نون التوكيد الثقيلة تزيد الوعد قوة. وقد جاءت في آل عمران بعد أعمال شاقة من هجرة وإخراج وإيذاء وقتال وقتل، بينما جاءت السين في سياقات عامة للإيمان والعمل الصالح من غير تفصيل تلك المشاق.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، نون التوكيد والسين في وعد الجنة.؛ العنوان الجزئي: قوة الوعد بحسب مشقة العمل.","url":""}]},{"id":"s3-901","number":901,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سر ترتيب الأعمال في قوله تعالى: ﴿هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ وَأُوذُوا ... وَقَاتَلُوا وَقُتِلُوا﴾؟","answer":"تدرجت الأفعال في الشدة: فالهجرة قد تكون اختيارًا، والإخراج أشد لأنه قهري، والإيذاء أشد من مجرد الخروج، ثم القتال، ثم القتل وهو غاية التضحية. فجاء الترتيب مصورًا لتصاعد البذل حتى يبلغ أعلى درجات الفداء.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ترتيب أعمال المهاجرين والمجاهدين.؛ العنوان الجزئي: التدرج من الهجرة إلى القتل.","url":""}]},{"id":"s3-902","number":902,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سر حذف قيد ﴿وَهُوَ مُؤْمِنٌ﴾ في آل عمران، مع التصريح به في قوله بسورة غافر: ﴿وَمَنْ عَمِلَ صَالِحًا... وَهُوَ مُؤْمِنٌ﴾؟","answer":"سياق آل عمران سبق أن أثبت إيمانهم بقولهم: ﴿أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا﴾، ووصفهم بصفات المؤمنين؛ فلم يحتج إلى إعادة القيد. أما آية غافر فذكرت العمل في قاعدة عامة، فاحتيج إلى التصريح بشرط الإيمان.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص50–52، حذف «وهو مؤمن» لسبق إثبات الإيمان.؛ العنوان الجزئي: الاكتفاء بالسياق عن إعادة شرط الإيمان.","url":""}]},{"id":"s3-903","number":903,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما سر مقابلة ﴿دِيَارِهِمْ﴾ التي فقدوها بـ﴿جَنَّاتٍ﴾ يدخلونها؟","answer":"الديار مساكن محدودة في الدنيا أُبعدوا عنها، أما الجنات فدار واسعة باقية أعدها الله لهم. فانتقل التعبير من مفردات الفقد والغربة إلى مفردات الأمن والنعيم، ليظهر عظم العوض الإلهي.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، مقابلة الديار بالجنات.؛ العنوان الجزئي: من فقد الوطن إلى سعة دار الجزاء.","url":""}]},{"id":"s3-904","number":904,"surah":3,"verses":[195],"references":[{"surah":3,"verses":[195]}],"verseLabel":"آل عمران: 195","question":"ما وجه المناسبة بين ثقل الأعمال المذكورة وثقل التوكيد في وعد أصحابها؟","answer":"لما ثقلت تضحياتهم بالهجرة والإخراج والأذى والقتال والقتل، قوبلت بوعد مؤكد بنون التوكيد الثقيلة في التكفير والإدخال. فازدادت قوة الوعد بمقدار ما عرض السياق من شدة الطريق وثقل التكليف.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص53–56، التوكيد مع مشاق الأعمال.؛ العنوان الجزئي: مقابلة مشقة العمل بتوكيد الجزاء.","url":""}]},{"id":"s3-905","number":905,"surah":3,"verses":[195,198],"references":[{"surah":3,"verses":[195,198]}],"verseLabel":"آل عمران: 195، 198","question":"ما الفرق البلاغي بين ﴿لَأُدْخِلَنَّهُمْ جَنَّاتٍ﴾ و﴿لَهُمْ جَنَّاتٌ﴾؟","answer":"الإدخال يثبت بلوغ الجنة، لكنه لا يدل في أصل العبارة على الملك، أما ﴿لَهُمْ جَنَّاتٌ﴾ فتفيد الاختصاص والتمليك. ولما كان وصف المتقين في الآية 198 أعم وأشمل، جاء لهم التعبير الأعلى الدال على أن الجنات صارت لهم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، الفرق بين الإدخال والتمليك في الآيتين 195 و198.؛ العنوان الجزئي: بلوغ الجنة وامتلاكها.","url":""}]},{"id":"s3-906","number":906,"surah":3,"verses":[195,198],"references":[{"surah":3,"verses":[195,198]}],"verseLabel":"آل عمران: 195، 198","question":"ما دلالة كون ﴿الَّذِينَ اتَّقَوْا رَبَّهُمْ﴾ أعم من الذين هاجروا وأُخرجوا وقاتلوا؟","answer":"المهاجرون والمخرجون والمجاهدون طائفة من المتقين، أما التقوى فتشمل فعل المأمورات واجتناب المنهيات وسائر أبواب البر. لذلك جاء وصف المتقين في الآية 198 جامعًا، ودخل فيه أصحاب الأعمال المذكورة في الآية 195 من غير أن يقتصر عليهم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، عموم المتقين وشمولهم أصحاب الهجرة والجهاد.؛ العنوان الجزئي: الخاص داخل في الوصف العام.","url":""}]},{"id":"s3-907","number":907,"surah":3,"verses":[195,198],"references":[{"surah":3,"verses":[195,198]}],"verseLabel":"آل عمران: 195، 198","question":"ما سر التعبير بـ﴿ثَوَابًا مِّنْ عِندِ اللَّهِ﴾ في الآية 195، وبـ﴿نُزُلًا مِّنْ عِندِ اللَّهِ﴾ في الآية 198؟","answer":"«الثواب» جزاء على عمل متميز، فجاء مع الذين هاجروا وأُخرجوا وأوذوا وقاتلوا. أما «النُّزُل» فهو ما يُهيأ للنازل من ضيافة وإقامة، فجاء مع المتقين في مقام أوسع، يصف الجنة ضيافةً مستقرة من عند الله، لا مجرد جزاء على عمل معين.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، الفرق بين «ثوابًا» و«نزلًا».؛ العنوان الجزئي: الثواب للجزاء، والنُّزُل للإقامة والضيافة.","url":""}]},{"id":"s3-908","number":908,"surah":3,"verses":[195,198],"references":[{"surah":3,"verses":[195,198]}],"verseLabel":"آل عمران: 195، 198","question":"ما سر ذكر ﴿خَالِدِينَ فِيهَا﴾ في الآية 198، وعدم ذكرها في الآية 195؟","answer":"المذكورون في الآية 195 فئة من المتقين، أما الآية 198 فتتناول المتقين على وجه أعم وأشمل، فناسب أن يذكر فيها الخلود. كما أن الآية 196 وصفت متاع الكافرين بالقلة والزوال، فجاء ذكر الخلود في الآية 198 مقابلاً لذلك المتاع المؤقت.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، سبب ذكر الخلود في الآية 198 دون الآية 195.؛ العنوان الجزئي: عموم المتقين ومقابلة الخلود بالمتاع القليل.","url":""}]},{"id":"s3-909","number":909,"surah":3,"verses":[195,198,200],"references":[{"surah":3,"verses":[195,198,200]}],"verseLabel":"آل عمران: 195، 198، 200","question":"كيف تلخص أوامر الخاتمة طريق المبتلين وجزاء المتقين في الآيات السابقة؟","answer":"يقابل الصبر الهجرة والإخراج، والمصابرة الأذى، والمرابطة القتال والقتل، ثم تقابل التقوى وصف المتقين أصحاب الجنات. وبذلك لا تأتي الخاتمة منفصلة، بل تختصر رحلة العمل والابتلاء والجزاء في أربعة أوامر جامعة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، مقابلة الخاتمة لما تقدمها.؛ العنوان الجزئي: الخاتمة خلاصة مسار السورة العملي.","url":""}]},{"id":"s3-910","number":910,"surah":3,"verses":[195,200],"references":[{"surah":3,"verses":[195,200]}],"verseLabel":"آل عمران: 195، 200","question":"ما وجه المقابلة بين ﴿اصْبِرُوا﴾ وذكر الذين ﴿هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ﴾؟","answer":"الهجرة والإخراج يقتضيان احتمال فراق الوطن وفقد الأمان، وهما من أشد مواطن الصبر. فجاء الأمر العام بالصبر كأنه يستخلص الخلق اللازم لمواجهة أول درجات الابتلاء المذكورة قبل الخاتمة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، اصبروا في مقابلة الهجرة والإخراج.؛ العنوان الجزئي: الصبر زاد الهجرة وفقد الديار.","url":""}]},{"id":"s3-911","number":911,"surah":3,"verses":[195,200],"references":[{"surah":3,"verses":[195,200]}],"verseLabel":"آل عمران: 195، 200","question":"ما وجه المقابلة بين ﴿رَابِطُوا﴾ وقوله: ﴿وَقَاتَلُوا وَقُتِلُوا﴾؟","answer":"القتال والقتل ذروة المواجهة، والمرابطة هي الاستعداد الدائم الذي يحفظ الثغور ويهيئ لها. فجاءت في الخاتمة بإزاء أشد مراحل البلاء، لتجعل الاستعداد المستمر خلقًا يحمي الجماعة قبل وقوع القتال وأثناءه.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، رابطوا في مقابلة القتال والقتل.؛ العنوان الجزئي: المرابطة سياج المواجهة الكبرى.","url":""}]},{"id":"s3-912","number":912,"surah":3,"verses":[195,200],"references":[{"surah":3,"verses":[195,200]}],"verseLabel":"آل عمران: 195، 200","question":"ما وجه المقابلة بين ﴿صَابِرُوا﴾ وقوله: ﴿وَأُوذُوا فِي سَبِيلِي﴾؟","answer":"الأذى في سبيل الله محاولة لكسر إرادة المؤمن وإرجاعه عن طريقه، والمصابرة هي أن يواجه تلك الإرادة بثبات أطول. فالأمر لا يكتفي بتحمل الألم، بل يطلب مغالبة من يصنعه بالصبر على الحق.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، صابروا في مقابلة الأذى.؛ العنوان الجزئي: مقاومة الأذى بثبات أطول.","url":""}]},{"id":"s3-913","number":913,"surah":3,"verses":[196,197],"references":[{"surah":3,"verses":[196,197]}],"verseLabel":"آل عمران: 196، 197","question":"كيف يحول وصف ﴿مَتَاعٌ قَلِيلٌ﴾ صورة القوة والتمكن في البلاد إلى مشهد عابر؟","answer":"التقلب يوحي بالسعة والقدرة والاستقرار، لكن وصفه بالمتاع القليل ينزع عنه وهم الدوام؛ فهو انتفاع محدود زمانًا وقدرًا. ثم يأتي المأوى الأخير ليبين أن البلاد التي تقلبوا فيها لم تكن إلا محطات انتقال.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص56–57، التقلب متاع محدود والبلاد محطات انتقال.؛ العنوان الجزئي: تقليص المظهر الدنيوي أمام المصير الدائم.","url":""}]},{"id":"s3-914","number":914,"surah":3,"verses":[196,197],"references":[{"surah":3,"verses":[196,197]}],"verseLabel":"آل عمران: 196، 197","question":"ما وجه الصلة بين «التقلب» في البلاد وذكر ﴿مَأْوَاهُمْ﴾ بعده؟","answer":"المتقلب كثير الحركة لا بد له في النهاية من مكان يأوي إليه ويستقر فيه. فجاء «المأوى» بعد «التقلب» ليكشف نهاية حركتهم الواسعة: انتقالاتهم مؤقتة، أما مأواهم الأخير فجهنم.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص56–57، من التقلب إلى المأوى.؛ العنوان الجزئي: نهاية الحركة في مستقر المصير.","url":""}]},{"id":"s3-915","number":915,"surah":3,"verses":[198,200],"references":[{"surah":3,"verses":[198,200]}],"verseLabel":"آل عمران: 198، 200","question":"ما وجه المقابلة بين ﴿وَاتَّقُوا اللَّهَ﴾ وذكر ﴿الَّذِينَ اتَّقَوْا رَبَّهُمْ﴾ قبلها؟","answer":"عرضت الآية 198 عاقبة المتقين، ثم جاءت الخاتمة بالأمر بالطريق الموصل إلى تلك العاقبة. فتحول وصف أهل الجنة إلى تكليف عملي للقارئ: إن أردتم منزلتهم فحققوا تقوى الله.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، الأمر بالتقوى ووصف المتقين.؛ العنوان الجزئي: تحويل وصف أهل الجزاء إلى منهج عمل.","url":""}]},{"id":"s3-916","number":916,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما سر استعمال ﴿أُنزِلَ﴾ في وصف إيمان أهل الكتاب، وما الذي يضيفه البناء للمجهول هنا؟","answer":"المقام يعدد متعلق الإيمان لا كيفية التنزيل ولا زمنه، فبُني الفعل للمجهول لتتجه العناية إلى الوحي المنزل وإلى اجتماع الفريقين عليه. والفاعل معلوم من السياق، فحذفه لا يوقع لبسًا بل يركز الضوء على وحدة المصدر والمضمون.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، أنزل ونزّل، وأُنزل إليك وأُنزل عليك.؛ العنوان الجزئي: توجيه العناية إلى الوحي المنزل.","url":""}]},{"id":"s3-917","number":917,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما سر اقتران رفض ﴿ثَمَنًا قَلِيلًا﴾ بتوكيد سرعة الحساب في ختام الآية؟","answer":"من يبيع الآيات يطلب عاجل الدنيا، أما هؤلاء فتركوا ذلك العاجل وفاءً لله. فجاء توكيد سرعة الحساب وعدًا بألا يفوتهم الخير العاجل؛ يعجل الله لهم من فضله في الدنيا، مع ما ادخر لهم من أجر الآخرة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، تعجيل أجر من ترك الثمن القليل.؛ العنوان الجزئي: مقابلة العاجل المحرم بالعاجل الموهوب.","url":""}]},{"id":"s3-918","number":918,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما سر توكيد سرعة الحساب في آل عمران، وعدم توكيدها في مشهد صاحب السراب في سورة النور؟","answer":"مشهد النور يصور فردًا واحدًا بلغ نهاية سعيه فوجد حسابه، فلا يثير السياق معنى كثرة المحاسَبين. أما آل عمران ففيها أجور جماعة ومراتب استحقاق، فكان المقام أدعى إلى التوكيد بأن كثرة الأعمال وأصحابها لا تبطئ الحساب.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، التوكيد مع الجماعة وتركه مع الفرد.؛ العنوان الجزئي: اختلاف التوكيد باختلاف سعة المشهد.","url":""}]},{"id":"s3-919","number":919,"surah":3,"verses":[199],"references":[{"surah":3,"verses":[199]}],"verseLabel":"آل عمران: 199","question":"ما وجه التناسب بين توكيد سرعة الحساب في آل عمران، وتوكيدها بعد ﴿لِيَجْزِيَ اللَّهُ كُلَّ نَفْسٍ﴾ في إبراهيم؟","answer":"آية إبراهيم صرحت بشمول الجزاء لكل نفس، فناسب التوكيد دفع توهم أن العموم يطيل الحساب. وآية آل عمران وعدت جماعة المؤمنين بأجور متفاوتة يعلم الله مقاديرها؛ فالتوكيد في الموضعين يقرر أن كثرة المستحقين لا تؤخر تمام الجزاء.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص62–67، توكيد سرعة الحساب مع عموم الجزاء.؛ العنوان الجزئي: العموم سبب مناسب لتقوية خبر السرعة.","url":""}]},{"id":"s3-920","number":920,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"كيف تكون المرابطة نوعًا من الصبر، مع إفرادها بأمر مستقل؟","answer":"المرابط يصبر على طول الإقامة والترقب واحتمال الخطر، فهي صبر ممتد ذو وظيفة جماعية. وأُفردت بالذكر لأن دوامها وحراسة الثغور بها يجاوزان الصبر الفردي العام إلى التزام منظم يحمي الأمة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، المرابطة نوع من الصبر.؛ العنوان الجزئي: الصبر المنظم لحماية الجماعة.","url":""}]},{"id":"s3-921","number":921,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما أثر إحاطة الاستعداد العسكري بالتقوى في قوله: ﴿رَابِطُوا وَاتَّقُوا اللَّهَ﴾؟","answer":"المرابطة سبب قوة، لكن التقوى تضبط مقصدها ووسائلها؛ فلا تصبح القوة غاية مستقلة ولا ذريعة لتجاوز أمر الله. فالجمع بينهما يبني يقظة قادرة وضميرًا مراقبًا في آن واحد.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، التقوى عامة في جميع الأحوال.؛ العنوان الجزئي: ضبط القوة بالتقوى.","url":""}]},{"id":"s3-922","number":922,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما الذي تضيفه ﴿صَابِرُوا﴾ إلى الثبات في شدائد الحرب؟","answer":"المصابرة ليست تحمل الشدة منفردًا، بل الثبات أمام عدو يحاول أن يكون أطول نفسًا. فهي تطلب من المؤمن ألا يكون أقل صبرًا من خصمه، وأن يغلب مقاومته بثبات أشد.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، المصابرة في مواجهة الأعداء.؛ العنوان الجزئي: مغالبة الخصم في الصبر.","url":""}]},{"id":"s3-923","number":923,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما سر جعل الفلاح غايةً للصبر والمصابرة والمرابطة والتقوى مجتمعة؟","answer":"كل أمر يعالج جانبًا لا يغني عنه الآخر: ثبات النفس، ومغالبة الخصم، وحراسة الجماعة، ومراقبة الله. لذلك عُلّق الفلاح بالمجموع، حتى لا يظن أن النجاح يتحقق بقوة الميدان من غير صلاح القلب، أو بالتقوى المدعاة من غير أخذ بأسباب الثبات.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، الأوامر المجتمعة وطريق الفلاح.؛ العنوان الجزئي: تكامل أسباب الفلاح.","url":""}]},{"id":"s3-924","number":924,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما سر ختم سورة آل عمران بالأمر بـ﴿اصْبِرُوا وَصَابِرُوا﴾ بعد ما عرضته من محن وتمحيص؟","answer":"جاءت الخاتمة نتيجة عملية لما سبق من قضايا الإيمان والابتلاء والتمييز والنصر؛ فالإيمان لا يكتمل بالمعرفة والجدل، بل يحتاج إلى صبر ومصابرة وثبات. ولذلك ختمت السورة بهذا الأمر الجامع، ليظل المؤمن ثابتًا على الحق في نفسه ومع خصمه، مستحقًا طريق الفلاح.","sources":[{"label":"فاضل السامرائي، موقع تدارس القرآن الكريم، ختام السورة بالأمر بالصبر والمصابرة.؛ العنوان الجزئي: مناسبة خاتمة السورة لمحورها في الثبات والتمحيص.","url":""}]},{"id":"s3-925","number":925,"surah":3,"verses":[200],"references":[{"surah":3,"verses":[200]}],"verseLabel":"آل عمران: 200","question":"ما سعة المعنى التي يحملها الأمر ﴿اصْبِرُوا﴾ قبل ذكر المصابرة والمرابطة؟","answer":"الصبر هنا أصل جامع: صبر على المصيبة، وصبر على الطاعة، وصبر عن المعصية. فبدأت الخاتمة ببناء النفس في جميع أحوالها، قبل الانتقال إلى مواجهة الخصم وحراسة الثغور.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، أنواع الصبر في خاتمة السورة.؛ العنوان الجزئي: شمول الصبر للمصيبة والطاعة والمعصية.","url":""}]},{"id":"s3-926","number":926,"surah":3,"verses":[],"references":[{"surah":3,"verses":[]}],"verseLabel":"آل عمران: غير محدد","question":"ما سر انتقال خطاب التقوى من المؤمنين في ختام آل عمران إلى الناس جميعًا في افتتاح النساء؟","answer":"ختمت آل عمران ببناء جماعة الإيمان على الصبر والتقوى، ثم افتتحت النساء بالأصل الإنساني الجامع وخاطبت الناس كافة. فانتقل الخطاب من تربية الصف المؤمن إلى تذكير البشرية بوحدة المنشأ وربوبية الخالق.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، تناسب خاتمة آل عمران وفاتحة النساء.؛ العنوان الجزئي: من خصوص المؤمنين إلى عموم الناس.","url":""}]},{"id":"s3-927","number":927,"surah":3,"verses":[],"references":[{"surah":3,"verses":[]}],"verseLabel":"آل عمران: غير محدد","question":"ما سر تعاقب اسمي ﴿رَبِّهِمْ﴾ و﴿اللَّهَ﴾ في ختام آل عمران، ثم ورودهما معًا في افتتاح النساء؟","answer":"قالت الخاتمة: ﴿اتَّقَوْا رَبَّهُمْ﴾ ثم ﴿اتَّقُوا اللَّهَ﴾، وافتتحت النساء بـ﴿اتَّقُوا رَبَّكُمُ﴾ ثم ﴿وَاتَّقُوا اللَّهَ﴾. هذا التناسب يصل السورتين: اسم الرب يستحضر الخلق والرعاية، واسم الله يستجمع معاني الألوهية والطاعة.","sources":[{"label":"فاضل السامرائي، «قبسات من البيان القرآني»، ص67–69، ذكر الرب ولفظ الجلالة بين السورتين.؛ العنوان الجزئي: التناسب الاسمي بين الخاتمة والافتتاح.","url":""}]},{"id":"s4-476","number":476,"surah":4,"verses":[1,176],"references":[{"surah":4,"verses":[1,176]}],"verseLabel":"النساء: 1، 176","question":"ما سر التناسب بين فاتحة سورة النساء وخاتمتها؟","answer":"بدأت بخلق الإنسان وبثّ ذريته في الأرض، وانتهت بهلاكه: ﴿إِنِ امْرُؤٌا هَلَكَ لَيْسَ لَهُ وَلَدٌ﴾، فهي صورة لبدء الحياة ونهايتها. وابتدأت بإيتاء اليتامى أموالهم وهم يستقبلون الحياة، واختتمت بتقسيم تركة من ودّع الحياة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص257–258.","url":""}]},{"id":"s4-477","number":477,"surah":4,"verses":[2],"references":[{"surah":4,"verses":[2]}],"verseLabel":"النساء: 2","question":"ما سر التعبير بـ﴿وَلَا تَتَبَدَّلُوا الْخَبِيثَ بِالطَّيِّبِ﴾ بتاءين، مع قوله في الأحزاب: ﴿وَلَا أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَاجٍ﴾ بتاء واحدة؟","answer":"آية الأحزاب حكم مقصور على الرسول ﷺ وحده، فهو منهي عن أن يتبدّل بأزواجه أزواجًا، فحذف من الفعل. أما آية النساء فحكم عام للمسلمين على مر العصور، فجاء بالصيغة الطويلة للحدث الطويل الممتد، وبالصيغة القصيرة للحدث المقصور على شخص واحد.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص11–12.","url":""}]},{"id":"s4-478","number":478,"surah":4,"verses":[69],"references":[{"surah":4,"verses":[69]}],"verseLabel":"النساء: 69","question":"ما سر ترتيب المذكورين في ﴿وَمَن يُطِعِ اللَّهَ وَالرَّسُولَ فَأُولَٰئِكَ مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِم مِّنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ﴾؟","answer":"هو من التقديم بحسب الفضل والشرف، فقدّم اسم الله على الرسول، ثم جعل الصديقين صنفًا بعد الأنبياء، وذكر بعدهم الشهداء، ثم عموم الصالحين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص54. الآيات 71–104","url":""}]},{"id":"s4-479","number":479,"surah":4,"verses":[95],"references":[{"surah":4,"verses":[95]}],"verseLabel":"النساء: 95","question":"ما دلالة النفي بـ«لا» في ﴿لَّا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُولِي الضَّرَرِ وَالْمُجَاهِدُونَ﴾؟","answer":"النفي بـ«لا» هنا لنفي الاستواء في المستقبل، أي في الآخرة، فعدم استواء القاعدين والمجاهدين يظهر أثره يوم الجزاء.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية، ج2، ص96.","url":""}]},{"id":"s4-480","number":480,"surah":4,"verses":[107],"references":[{"surah":4,"verses":[107]}],"verseLabel":"النساء: 107","question":"ما سر ختم الآية بـ﴿أَثِيمًا﴾ والتعبير بـ﴿مَن كَانَ﴾، مع قوله في الحج: ﴿إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ خَوَّانٍ كَفُورٍ﴾؟","answer":"السياق في النساء في الخيانة والآثام، وقد تكرر فيه ذكر الإثم، والخائن أثيم، فناسب الختم بـ«أثيم». وآية الحج حكم عام لعموم المسلمين فجاءت بـ«كل»، أما آية النساء ففي جماعة مخصوصة سرقوا طعامًا ورموا بالسرقة غيرهم، فلم يأت بصيغة العموم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص175–176.","url":""}]},{"id":"s5-772","number":772,"surah":5,"verses":[3],"references":[{"surah":5,"verses":[3]}],"verseLabel":"المائدة: 3","question":"ما دلالة التعبير بلفظ «الفِسْق» في ﴿ذَٰلِكُمْ فِسْقٌ﴾ دون «الفُسوق»؟","answer":"ورد «الفسق» في القرآن في سياق الأطعمة وبخاصة الذبائح، كآية المائدة هذه وآيتي الأنعام 145 و121. أما «الفسوق» فورد للخروج عن طاعة الله عامة، كقوله: ﴿فَلَا رَفَثَ وَلَا فُسُوقَ﴾. فاستعمل الفسوق لما هو أعم، وكأنه لما زاد في المعنى زاد في البناء.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص20.","url":""}]},{"id":"s5-773","number":773,"surah":5,"verses":[6],"references":[{"surah":5,"verses":[6]}],"verseLabel":"المائدة: 6","question":"ما سر عطف ﴿وَأَرْجُلَكُمْ﴾ على الوجوه في الغسل مع الفصل بينهما بالمسح بالرؤوس؟","answer":"هذا العطف صحيح كثير في القرآن وغيره، كعطف ﴿وَحِينَ تُظْهِرُونَ﴾ على ﴿حِينَ تُمْسُونَ﴾ في الروم مع ما بينهما، وكآية الكرسي وآية البر. والغرض منه في آية الوضوء إرادة الترتيب، فيجب أن تكون أعمال الوضوء مرتبة بحسب ما ذكره القرآن الكريم.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص51–53.","url":""}]},{"id":"s5-774","number":774,"surah":5,"verses":[20],"references":[{"surah":5,"verses":[20]}],"verseLabel":"المائدة: 20","question":"ما سر النداء بـ﴿يَا قَوْمِ﴾ في قول موسى في المائدة، وخلوّ آية إبراهيم منه؟","answer":"عدّد عليهم في المائدة نعمًا جسامًا: جعل فيهم أنبياء وجعلهم ملوكًا، والإنسان يحب أن ينتسب إلى قوم ذوي رفعة، بخلاف آية إبراهيم التي ذكّرتهم بأيام ذلّهم. ثم طلب منهم دخول الأرض المقدسة، فناداهم بـ«يا قوم» عطفًا لقلوبهم حين كلّفهم هذا الأمر الشاق. وزاد ذلك حسنًا طولُ القصة في المائدة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص120–121؛ وفاضل السامرائي، على طريق التفسير البياني، ج1، ص211. الآيات 26 – 54","url":""}]},{"id":"s5-775","number":775,"surah":5,"verses":[33],"references":[{"surah":5,"verses":[33]}],"verseLabel":"المائدة: 33","question":"ما سر تقديم «الخزي» على «الدنيا» في ﴿ذَٰلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا﴾، وتأخيره في آيتي البقرة والحج ﴿لَهُمْ فِي الدُّنْيَا خِزْيٌ﴾؟","answer":"الخزي المذكور في آية المائدة أظهر للعيان وأثبت، فهو التقتيل والتصليب وقطع الأيدي والأرجل من خلاف والنفي من الأرض. أما في البقرة فهو خوف مقارن للدخول، والخوف أمر قلبي غير ظاهر، وفي الحج لم يذكر نوع الخزي. فناسب تقديم الخزي الأظهر والأشد في آية المائدة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص15–16.","url":""}]},{"id":"s6-1421","number":1421,"surah":6,"verses":[17],"references":[{"surah":6,"verses":[17]}],"verseLabel":"الأنعام: 17","question":"ما سر ختم ﴿وَإِن يَمْسَسْكَ بِخَيْرٍ فَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ﴾، وفي يونس ﴿وَإِن يُرِدْكَ بِخَيْرٍ فَلَا رَادَّ لِفَضْلِهِ﴾؟","answer":"آية الأنعام في افتراض مسّ الخير، وآية يونس في افتراض إرادته. والإرادة من غير الله قد لا تتحقق لحائل يحول دونها، أما إرادته سبحانه فلا رادّ لها. ولما اتفق الافتراضان في مسّ الضر اتفق الجوابان ﴿فَلَا كَاشِفَ لَهُ إِلَّا هُوَ﴾، ولما اختلفا في الخير اختلف التعقيبان.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص56.","url":""}]},{"id":"s6-1422","number":1422,"surah":6,"verses":[20,21],"references":[{"surah":6,"verses":[20,21]}],"verseLabel":"الأنعام: 20، 21","question":"ما سر الختم بـ﴿إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ﴾ بعد وصفهم بأنهم ﴿خَسِرُوا أَنفُسَهُمْ﴾؟","answer":"لما وصفهم بأنهم خسروا أنفسهم، وهي أثمن شيء، ناسب أن ينفي عنهم الفلاح؛ فمن خسر مالًا قد يأتيه الفلاح من جهة أخرى، أما من خسر نفسه فمن أين يأتيه الفلاح ولم تعد له نفس؟ ولذلك أكّد الكلام بـ«إنّ» وجاء بضمير الشأن للدلالة على عِظَم الخسارة وانتفاء الفلاح.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص217.","url":""}]},{"id":"s6-1423","number":1423,"surah":6,"verses":[47],"references":[{"surah":6,"verses":[47]}],"verseLabel":"الأنعام: 47","question":"ما سر التعبير بـ﴿أَرَأَيْتَكُمْ إِنْ أَتَاكُمْ عَذَابُ اللَّهِ﴾، وفي مريم ﴿أَن يَمَسَّكَ عَذَابٌ مِّنَ الرَّحْمَٰنِ﴾؟","answer":"التحذير في آية الأنعام أشد من أوجه: ف«أرأيتكم» بحرف الخطاب مع الضمير آكد من «أرأيتم»، والإتيان أشد من مجرد المسّ، وأضاف العذاب إلى الله ولم يجعله من «الرحمن». وزاد ﴿بَغْتَةً أَوْ جَهْرَةً﴾، وجعل العذاب مهلكًا مستأصلًا ﴿هَلْ يُهْلَكُ إِلَّا الْقَوْمُ الظَّالِمُونَ﴾. ثم إن اسم «الرحمن» لم يرد في الأنعام، وورد لفظ الجلالة فيها نحو سبع وثمانين مرة، فناسب سمتها التعبيرية.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص44–45.","url":""}]},{"id":"s6-1424","number":1424,"surah":6,"verses":[80],"references":[{"surah":6,"verses":[80]}],"verseLabel":"الأنعام: 80","question":"ما سر مجيء الفعل تامًّا بتاءين في ﴿أَفَلَا تَتَذَكَّرُونَ﴾؟","answer":"الكلام في محاجّة إبراهيم لقومه العريقين في الشرك، وهم محتاجون إلى طول التذكر وإدامة التفكر ليهتدوا إلى التوحيد، كما تأمل إبراهيم في ملكوت السماوات والأرض. فجاء بالفعل كاملًا لم يحذف منه شيئًا، وناسب ذلك أيضًا مقامَ التفصيل والإطالة فيما حُكي عن اهتدائه من الكوكب إلى القمر إلى الشمس.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص17.","url":""}]},{"id":"s6-1425","number":1425,"surah":6,"verses":[90],"references":[{"surah":6,"verses":[90]}],"verseLabel":"الأنعام: 90","question":"ما سر التعبير بـ﴿أَجْرًا … إِنْ هُوَ إِلَّا ذِكْرَىٰ﴾ هنا، وفي يوسف ﴿مِنْ أَجْرٍ إِنْ هُوَ إِلَّا ذِكْرٌ﴾؟","answer":"«الذِّكر» أعم من «الذكرى»، فهو يشمل الحفظ والشرف إلى جانب التذكير، وهذا يناسب ما في قصة يوسف من سعة. وآية الأنعام مفردة في سياقها، أما سياق يوسف فأوسع، فناسبه «مِن» الاستغراقية. ثم إن ﴿مِنْ أَجْرٍ﴾ أكثر حروفًا، فقابل السعةَ بالسعة والإيجازَ بالإيجاز.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص46–47.","url":""}]},{"id":"s6-1426","number":1426,"surah":6,"verses":[102],"references":[{"surah":6,"verses":[102]}],"verseLabel":"الأنعام: 102","question":"ما سر تقديم ﴿لَا إِلَٰهَ إِلَّا هُوَ﴾ على ﴿خَالِقُ كُلِّ شَيْءٍ﴾ هنا، وعكسه في غافر؟","answer":"السياق في الأنعام سياق الإنكار على الشرك والدعوة إلى التوحيد الخالص ونفي الصاحبة والولد، فقد سبقها ﴿وَجَعَلُوا لِلَّهِ شُرَكَاءَ الْجِنَّ﴾ و﴿أَنَّىٰ يَكُونُ لَهُ وَلَدٌ﴾، فقدّم كلمة التوحيد لأنها المناسبة للمقام. ونظيره أنه أخّر ﴿وَخَلَقَ كُلَّ شَيْءٍ﴾ في الآية السابقة بعد نفي الولد والصاحبة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص67.","url":""}]},{"id":"s6-1427","number":1427,"surah":6,"verses":[125],"references":[{"surah":6,"verses":[125]}],"verseLabel":"الأنعام: 125","question":"ما دلالة التشبيه في ﴿يَجْعَلْ صَدْرَهُ ضَيِّقًا حَرَجًا كَأَنَّمَا يَصَّعَّدُ فِي السَّمَاءِ﴾؟","answer":"السماء هنا بمعنى الجوّ العالي، ومن يصعد في الجو يضيق صدره ويحرج لاختلاف الضغط وقلّة الهواء كلما ارتفع. فشبّه ضيق صدر الضال بحال المتصعّد في الجو، وهذا من الإعجاز العلمي فوق ما في التعبير من إعجاز لغوي، إذ لم يكن ذلك معروفًا وقت التنزيل.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص43.","url":""}]},{"id":"s6-1428","number":1428,"surah":6,"verses":[151],"references":[{"surah":6,"verses":[151]}],"verseLabel":"الأنعام: 151","question":"ما دلالة التضعيف في ﴿ذَٰلِكُمْ وَصَّاكُم بِهِ﴾ دون «أوصاكم»؟","answer":"يستعمل القرآن «وصّى» بالتضعيف في الأمور المعنوية وأمور الدين، و«أوصى» في الأمور المادية كالميراث. وما في هذه الآيات من توحيد وبرّ وتحريم للفواحش والقتل من أصول الدين، فناسبه الفعل المضعّف الدال على الاهتمام والتوكيد.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص59.","url":""}]},{"id":"s6-1429","number":1429,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما سر اقتران الوزن بـ«القسط» في ﴿وَأَوْفُوا الْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِ﴾؟","answer":"الغرض من الوزن أن يأخذ كل شخص حصته ونصيبه، وهذا من معاني القسط. ولذلك لم يرد مع الوزن في القرآن إلا لفظ «القسط» ولم يستعمل معه «العدل»، كما في هود والأنبياء والرحمن، بل إن من أسماء الميزان «القسطاس».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص289.","url":""}]},{"id":"s6-1430","number":1430,"surah":6,"verses":[152],"references":[{"surah":6,"verses":[152]}],"verseLabel":"الأنعام: 152","question":"ما سر تقديم الجار والمجرور في ﴿وَبِعَهْدِ اللَّهِ أَوْفُوا﴾، وفي الإسراء ﴿وَأَوْفُوا بِالْعَهْدِ﴾؟","answer":"التقديم في الأنعام للاهتمام والعناية، لأنه أضاف العهد إلى الله فازداد تفخيمًا. وهو عهد مطلق يشمل ما عهده الله إلى عباده وما تعاهد عليه الخلق فيما بينهم، بخلاف آية النحل ﴿وَأَوْفُوا بِعَهْدِ اللَّهِ إِذَا عَاهَدتُّمْ﴾ فهي مقيّدة بما يلتزمه الإنسان باختياره، فقدّم فيها الفعل.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص287.","url":""}]},{"id":"s6-1431","number":1431,"surah":6,"verses":[157],"references":[{"surah":6,"verses":[157]}],"verseLabel":"الأنعام: 157","question":"ما دلالة التعبير بـ«صدف» في ﴿مِمَّن كَذَّبَ بِآيَاتِ اللَّهِ وَصَدَفَ عَنْهَا﴾، وبـ«أعرض» في الكهف والسجدة؟","answer":"الصُّدوف إعراض شديد، مأخوذ من الصَّدَف وهو جانب الجبل الصلب. وفي آية الأنعام اجتمع التكذيب مع الإعراض، وهو أشد من الإعراض وحده، فاختار اللفظ الأشد، ولذلك كان الجزاء أشد أيضًا ﴿سَنَجْزِي الَّذِينَ يَصْدِفُونَ عَنْ آيَاتِنَا سُوءَ الْعَذَابِ﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص51–52.","url":""}]},{"id":"s6-1432","number":1432,"surah":6,"verses":[161],"references":[{"surah":6,"verses":[161]}],"verseLabel":"الأنعام: 161","question":"ما سر الوصف بالمصدر في ﴿دِينًا قِيَمًا مِّلَّةَ إِبْرَاهِيمَ حَنِيفًا﴾، وفي التوبة ﴿ذَٰلِكَ الدِّينُ الْقَيِّمُ﴾؟","answer":"«قِيَم» مصدر، والوصف بالمصدر آكد من الوصف بالصفة «القيّم»، كأن الدين هو الاستقامة نفسها. وهذا يناسب سعة السياق ﴿إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ﴾. وقد أكّد الاستقامة بثلاثة تعبيرات: ﴿صِرَاطٍ مُّسْتَقِيمٍ﴾ و﴿قِيَمًا﴾ و﴿حَنِيفًا﴾، وفي الآية قراءة متواترة «قَيِّمًا».","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص53–55.","url":""}]},{"id":"s7-1667","number":1667,"surah":7,"verses":[18],"references":[{"surah":7,"verses":[18]}],"verseLabel":"الأعراف: 18","question":"ما سر تقديم التابعين في ﴿لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ﴾، وتقديم ملء جهنم في ص؟","answer":"تقدّم في ص قبل القصة الكلام على جهنم وعذابها فقدّم ما يتعلق بها، وفي الأعراف تأخّر ذكرها فأخّره. وفي الأعراف أفاض إبليس فيما سيحتال به لذرية آدم ليتبعوه: القعود لهم على الصراط، وإتيانهم من بين أيديهم ومن خلفهم وعن أيمانهم وعن شمائلهم، فناسب أن يُقدَّم من تبعه.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص69–70.","url":""}]},{"id":"s7-1668","number":1668,"surah":7,"verses":[143],"references":[{"surah":7,"verses":[143]}],"verseLabel":"الأعراف: 143","question":"ما سر ذكر موسى باسمه في ﴿وَلَمَّا جَاءَ مُوسَىٰ لِمِيقَاتِنَا﴾، وذكر النبي ﷺ بوصف العبودية في ﴿أَسْرَىٰ بِعَبْدِهِ﴾؟","answer":"لما ذكر موسى عند المناجاة باسمه كانت عاقبة ذلك أن خرّ صعقًا، ولما ذكر محمدًا ﷺ بصفة العبودية عُرج به إلى السماوات العلى. فلا يحسن أن يُقال: «ولما جاء عبدنا موسى» فينسبه إلى نفسه ثم يصعقه، لأن الإضافة إليه سبحانه تشريف وحفظ.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص205.","url":""}]},{"id":"s7-1669","number":1669,"surah":7,"verses":[167,169],"references":[{"surah":7,"verses":[167,169]}],"verseLabel":"الأعراف: 167، 169","question":"ما سر تأكيد سرعة العقاب باللام في ﴿إِنَّ رَبَّكَ لَسَرِيعُ الْعِقَابِ﴾، مع ترك اللام في ﴿وَالدَّارُ الْآخِرَةُ خَيْرٌ﴾ وهي في الأنعام ﴿وَلَلدَّارُ الْآخِرَةُ﴾؟","answer":"السياق في آيات الأعراف في العقوبات الدنيوية لبني إسرائيل: أخذ الظالمين بعذاب بئيس، ومسخهم قردة، وبعث من يسومهم سوء العذاب. فأكّد سرعة العقاب لأنه عاجلهم في الدنيا، ولم يؤكد الآخرة. أما آيات الأنعام فالكلام فيها على الدار الآخرة نفسها، فأكّدها باللام.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص131–132.","url":""}]},{"id":"s8-299","number":299,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"ما سر التعبير بالحَوْل في قوله: ﴿واعلموا أن الله يحول بين المرء وقلبه﴾؟","answer":"من معاني «الحول» في اللغة الحجز والمنع، ومنها التحوّل والتغيّر. والتعبير هنا يدل على شدة قرب الله من عبده وتمكّنه من قلبه، فهو يحجز بينه وبين قلبه ويصرّفه كيف يشاء، فينبغي للعبد أن يبادر إلى الاستجابة قبل أن يُحال بينه وبين قلبه.","sources":[{"label":"فاضل السامرائي، برنامج «لمسات بيانية»، منقول في صفحة «لمسات ومتشابهات وأسباب النزول لسورة الأنفال»: https://engyfoda.com/blog/?page_id=2290 ؛ وانظر في معنى الحول: فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص21.","url":""}]},{"id":"s8-300","number":300,"surah":8,"verses":[45],"references":[{"surah":8,"verses":[45]}],"verseLabel":"الأنفال: 45","question":"ما دلالة حذف الموصوف في قوله: ﴿واذكروا الله كثيرًا﴾؟","answer":"ذُكر الموصوف في مواضع أخرى مثل ﴿ذكرًا كثيرًا﴾ لأن السياق فيها سياق الذكر نفسه. أما في الأنفال فالسياق في لقاء العدو والثبات في القتال، فحذف الموصوف ولم يؤكد بالمصدر، لأن الموضع ليس للحديث عن الذكر نفسه.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص101–102.","url":""}]},{"id":"s8-301","number":301,"surah":8,"verses":[50],"references":[{"surah":8,"verses":[50]}],"verseLabel":"الأنفال: 50","question":"ما سر تذكير الفعل في قوله: ﴿إذ يتوفى الذين كفروا الملائكة﴾ وتأنيثه في سورة محمد: ﴿فكيف إذا توفتهم الملائكة﴾؟","answer":"يرى السامرائي أن الفعل يُذكّر مع الملائكة حين يكون الموقف أشد، ويؤنث فيما دونه. وآية الأنفال في قتلى بدر من الكفار، وفيها ضرب الوجوه والأدبار وذوق عذاب الحريق، فهو موقف أشد، فذكّر الفعل.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص190.","url":""}]},{"id":"s9-772","number":772,"surah":9,"verses":[35],"references":[{"surah":9,"verses":[35]}],"verseLabel":"التوبة: 35","question":"ما سر الترتيب في قوله: ﴿فتُكوى بها جباههم وجنوبهم وظهورهم﴾؟","answer":"بدأ بالجباه ثم الجنوب ثم الظهور متدرّجًا بحسب الرتبة. وينقل السامرائي قول من قال: إنهم كانوا إذا رأوا الفقير عبسوا، وإذا ضمّهم وإياه مجلس ازورّوا عنه بجنوبهم، ثم ولّوه ظهورهم، فكان العذاب على هذا الترتيب.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص58.","url":""}]},{"id":"s9-773","number":773,"surah":9,"verses":[36],"references":[{"surah":9,"verses":[36]}],"verseLabel":"التوبة: 36","question":"ما الفرق بين ﴿ذلك الدين القيّم﴾ بتشديد الياء هنا، و﴿دينًا قِيَمًا﴾ في الأنعام؟","answer":"«القِيَم» مصدر بمعنى الاستقامة نُعت به مبالغة، و«القيّم» صفة مشبهة بمعنى المستقيم. وسياق الأنعام أعمّ يشمل الحياة والعبادة كلها فوُصف بالمصدر، أما آية التوبة ففي عدة الشهور والأشهر الحرم وحكم القتال فيهن، وهي جزء من ذلك، فوُصف بالصفة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص53–55.","url":""}]},{"id":"s9-774","number":774,"surah":9,"verses":[94],"references":[{"surah":9,"verses":[94]}],"verseLabel":"التوبة: 94","question":"ما دلالة تعدية الإيمان باللام في قوله: ﴿لن نؤمن لكم﴾ وقوله: ﴿ويؤمن للمؤمنين﴾ [61]؟","answer":"الإيمان بالله لا يُعدّى إلا بالباء، نحو ﴿حتى تؤمنوا بالله وحده﴾، فإذا رأيت الإيمان معدّى باللام فاعلم أنه لغير الله. وقد عدّاه القرآن باللام مع الأشخاص غالبًا، بمعنى التصديق لهم فيما يقولون.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص75.","url":""}]},{"id":"s10-287","number":848,"surah":10,"verses":[2,108],"references":[{"surah":10,"verses":[2,108]}],"verseLabel":"يونس: 2، 108","question":"ما وجه التناسب بين مطلع السورة ﴿أكان للناس عجبًا أن أوحينا إلى رجل منهم أن أنذر الناس﴾ وخاتمتها ﴿قل يا أيها الناس قد جاءكم الحق من ربكم﴾؟","answer":"يذكر السامرائي سورة يونس في أمثلة تناسب الفاتحة والخاتمة، فقد بدأت بالوحي إلى الرسول لينذر الناس، وخُتمت بخطاب الناس بأن الحق قد جاءهم من ربهم، فالتقى المبدأ والمنتهى في أمر الرسالة ودعوة الناس.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص258.","url":""}]},{"id":"s10-288","number":849,"surah":10,"verses":[50],"references":[{"surah":10,"verses":[50]}],"verseLabel":"يونس: 50","question":"ما سر ترك كاف الخطاب في قوله: ﴿قل أرأيتم إن أتاكم عذابه بياتًا أو نهارًا﴾، وذكرها في الأنعام: ﴿أرأيتكم﴾؟","answer":"زيادة الكاف تأكيد للخطاب وتنبيه زائد في موقف أشد، وقد تقدّم في الأنعام ذكر الصمم والبكم وأخذ السمع والأبصار، وليس ذلك في يونس، بل تقدّمها ﴿أمّن يملك السمع والأبصار﴾ فحصل التنبيه فاكتفى بخطاب واحد. وينقل في ذلك عن «البرهان» وعن ابن الزبير.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص101–102.","url":""}]},{"id":"s10-289","number":850,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]}],"verseLabel":"يونس: 61","question":"ما سر تقديم الأرض على السماء في قوله: ﴿وما يعزب عن ربك من مثقال ذرة في الأرض ولا في السماء﴾، وعكسه في سبأ؟","answer":"بدأت الآية بشؤون أهل الأرض وأعمالهم: ﴿وما تكون في شأن وما تتلو منه من قرآن ولا تعملون من عمل﴾، فناسب تقديم الأرض. ويستشهد بما في «الكشاف» من أن حق السماء التقديم، لكن ذكر شهادته على شؤون أهل الأرض لاءمه تقديم الأرض.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص262–263.","url":""}]},{"id":"s10-290","number":851,"surah":10,"verses":[90],"references":[{"surah":10,"verses":[90]}],"verseLabel":"يونس: 90","question":"ما الفرق بين ﴿فأتبعهم فرعون وجنوده﴾ بالواو هنا، و﴿فأتبعهم فرعون بجنوده﴾ بالباء في طه؟","answer":"الواو تدل نصًّا على أن فرعون خرج بنفسه مع جنوده، أما الباء فتحتمل أنه أرسل جنوده ولم يذهب معهم. والسياق في يونس يؤكد علوّ فرعون وإسرافه وتصميمه على البطش، ولذلك ذُكر غرقه هو وإيمانه حين أدركه الغرق.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص142–145.","url":""}]},{"id":"s10-291","number":852,"surah":10,"verses":[90],"references":[{"surah":10,"verses":[90]}],"verseLabel":"يونس: 90","question":"ما دلالة التعبير بـ«العَدْو» في قوله: ﴿بغيًا وعَدْوًا﴾؟","answer":"العَدْو أكثر ما يُستعمل في المشي والحركة والأمور العلاجية، واتباع فرعون لبني إسرائيل مشي وحركة. أما «العداوة» فأمر قلبي، و«العدوان» الظلم والإخلال بالمعاملة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص17.","url":""}]},{"id":"s10-292","number":853,"surah":10,"verses":[101],"references":[{"surah":10,"verses":[101]}],"verseLabel":"يونس: 101","question":"ما دلالة رسم الياء في قوله: ﴿وما تغني الآيات والنذر﴾، وحذفها في القمر: ﴿فما تغنِ النذر﴾؟","answer":"يقرر أن رسم المصحف لا يُقاس عليه، لكنه يرى للاختلاف دلالة محتملة: فقد زاد في يونس «الآيات» على «النذر» فزادت دواعي الإغناء، فزاد في الرسم. ولما نقصت الدواعي في القمر نقص من الرسم.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص85–86.","url":""}]},{"id":"s10-293","number":854,"surah":10,"verses":[107],"references":[{"surah":10,"verses":[107]}],"verseLabel":"يونس: 107","question":"ما سر الختم بـ﴿فلا رادّ لفضله﴾ في قوله: ﴿وإن يردك بخير﴾، وبـ﴿فهو على كل شيء قدير﴾ في الأنعام؟","answer":"آية الأنعام في افتراض مسّ الخير: ﴿وإن يمسسك بخير﴾، وآية يونس في افتراض إرادة الخير. والإرادة من غير الله قد لا تتحقق لحائل يحول دونها، أما إرادته سبحانه فلا رادّ لها. ولما اتفق الافتراضان في مسّ الضر اتفق الجواب: ﴿فلا كاشف له إلا هو﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص56.","url":""}]},{"id":"s11-256","number":256,"surah":11,"verses":[13],"references":[{"surah":11,"verses":[13]}],"verseLabel":"هود: 13","question":"ما دلالة قوله: ﴿فأتوا بعشر سور مثله مفتريات﴾، دون «مِن مثله» كما في البقرة؟","answer":"لما قالوا: ﴿افتراه﴾ قيل لهم: ﴿مثله مفتريات﴾، أي افتروا أنتم كما تزعمون أنه افترى. ولا يحسُن هنا «مِن مثله»؛ لأنها تفترض أن له مثلًا موجودًا، وما له مثل لا يكون مفترى. وفي البقرة لم يقولوا «افتراه» فجاء «مِن مثله».","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص8–10.","url":""}]},{"id":"s11-257","number":257,"surah":11,"verses":[35],"references":[{"surah":11,"verses":[35]}],"verseLabel":"هود: 35","question":"ما سر نسبة الإجرام إليهم في قوله: ﴿فعليّ إجرامي وأنا بريء مما تجرمون﴾، وفي سبأ: ﴿ولا نُسأل عما تعملون﴾؟","answer":"في آية هود نسبوا الافتراء إليه: ﴿أم يقولون افتراه﴾، فقال: إن افتريته فعليّ عقوبة إجرامي، وأنا بريء من إجرامكم في نسبة ذلك إليّ، فقابل الإجرام بالإجرام.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص63.","url":""}]},{"id":"s11-258","number":258,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]}],"verseLabel":"هود: 40","question":"ما سر زيادة ﴿ومَن آمن﴾ وترك ﴿منهم﴾ في قوله: ﴿وأهلَك إلا من سبق عليه القول ومن آمن﴾، خلافًا لسورة المؤمنون؟","answer":"القصة في هود مبنية على العموم، وفي المؤمنون على الخصوص: فزاد في هود مَن آمن على الأهل، ونفى العاصم نفيًا عامًّا: ﴿لا عاصم اليوم من أمر الله﴾، وذكر البركات بالجمع عليه وعلى أمم ممن معه. ويبيّن أيضًا أن ﴿أهلَك﴾ اسم بمعنى الأهل، وليس فعلًا ماضيًا.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص88–90.","url":""}]},{"id":"s11-259","number":259,"surah":11,"verses":[54],"references":[{"surah":11,"verses":[54]}],"verseLabel":"هود: 54","question":"ما سر حذف الباء في قول هود: ﴿واشهدوا أني بريء مما تشركون﴾، وذكرها في آل عمران: ﴿اشهدوا بأنّا مسلمون﴾؟","answer":"الذكر أقوى وآكد من الحذف، وما ذكره الرسول ﷺ في آل عمران أكثر مما قاله هود؛ فهناك: ألا نعبد إلا الله، ولا نشرك به شيئًا، ولا يتخذ بعضنا بعضًا أربابًا، فناسب الموضعَ الأكثرَ التعبيرُ الآكد بذكر الباء.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص33–34.","url":""}]},{"id":"s11-260","number":260,"surah":11,"verses":[66],"references":[{"surah":11,"verses":[66]}],"verseLabel":"هود: 66","question":"ما سر التوكيد بـ«إنّ» وضمير الفصل في قوله: ﴿إن ربك هو القوي العزيز﴾، وتركه في الشورى: ﴿وهو القوي العزيز﴾؟","answer":"المقام في هود مقام عقوبة للكافرين ونصر للمؤمنين، أما في الشورى فمقام لطفه بالعباد ورزقه من يشاء، فأكّد القوة والعزة في المقام الذي يقتضيهما. ويلاحظ أن اسمه «القوي» لا يُقرن إلا بـ«العزيز» أو بـ«شديد العقاب».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص25 وص79.","url":""}]},{"id":"s11-261","number":261,"surah":11,"verses":[72],"references":[{"surah":11,"verses":[72]}],"verseLabel":"هود: 72","question":"ما دلالة قول امرأة إبراهيم: ﴿يا ويلتى﴾، دون «يا ويلي»؟","answer":"«الويلة» هي الفضيحة والخزي، فالمعنى: يا للفضيحة، لأنها رأت أن تلد وهي عجوز وبعلها شيخ. ومثله قول المجرمين حين يرون فضائحهم في الكتاب: ﴿يا ويلتنا مال هذا الكتاب﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص131.","url":""}]},{"id":"s11-262","number":262,"surah":11,"verses":[72],"references":[{"surah":11,"verses":[72]}],"verseLabel":"هود: 72","question":"ما سر التوكيد بـ«إنّ» واللام في قولها: ﴿إن هذا لشيء عجيب﴾، وفي ق: ﴿هذا شيء عجيب﴾؟","answer":"تدرّج التعبير بحسب قوة العجب. ففي ق عجبوا من مجيء منذر منهم فلم يؤكد. أما في هود فالعجب أكبر، لأن امرأة عجوزًا عقيمًا بعلها شيخ تلد، فأُكّد بـ«إنّ» واللام. وفي ص بلغ العجب غايته فقال: ﴿لشيء عُجاب﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص36.","url":""}]},{"id":"s11-263","number":263,"surah":11,"verses":[77],"references":[{"surah":11,"verses":[77]}],"verseLabel":"هود: 77","question":"ما سر ترك «أن» بعد «لمّا» في قوله: ﴿ولما جاءت رسلنا لوطًا سيء بهم﴾، وذكرها في العنكبوت: ﴿ولما أن جاءت﴾؟","answer":"أفاض في العنكبوت في ذكر صفات قوم لوط السيئة، وفي دعائه بالنصر، وفي التصريح بالتنجية مرتين، فزاد «أن» مراعاة للتبسط وللدلالة على استطالة الوقت وطول الترقب. وليس ذلك في هود، إذ لم يزد على قوله: ﴿ومن قبل كانوا يعملون السيئات﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص108–109.","url":""}]},{"id":"s11-264","number":264,"surah":11,"verses":[105,108],"references":[{"surah":11,"verses":[105,108]}],"verseLabel":"هود: 105، 108","question":"ما سر تقديم الأشقياء في قوله: ﴿فمنهم شقي وسعيد﴾، وجريان التفصيل على النسق نفسه؟","answer":"السياق في هود في ذكر الأمم الكافرة وما نزل بهم من العقوبات، وعقّب بـ﴿ذلك من أنباء القرى﴾، فقدّم الأشقياء. وجرى التفصيل على نسق الإجمال لأنهم كلهم غائبون، بخلاف آل عمران التي فيها مخاطَب وغائب.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص37–39.","url":""}]},{"id":"s11-265","number":265,"surah":11,"verses":[108],"references":[{"surah":11,"verses":[108]}],"verseLabel":"هود: 108","question":"ما معنى الاستثناء في قوله: ﴿خالدين فيها ما دامت السماوات والأرض إلا ما شاء ربك﴾، وهل يعني خروج أهل الجنة منها؟","answer":"أهل الجنة خالدون فيها أبدًا كما أخبر الله في مواطن عدة. ويذكر السامرائي أقوالًا في الاستثناء: منها أنه مدة الموقف قبل الحساب، أو مدة البرزخ، أو مرورهم على الجسر تحلّةً للقسم، أو فيمن يدخل النار من عصاة المسلمين ثم يخرج.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص65.","url":""}]},{"id":"s12-277","number":277,"surah":12,"verses":[13],"references":[{"surah":12,"verses":[13]}],"verseLabel":"يوسف: 13","question":"ما دلالة التعريف في قول يعقوب: ﴿وأخاف أن يأكله الذئب﴾؟","answer":"«أل» هنا جنسية تشير إلى واحد مما عُرفت حقيقته في الذهن من غير قصد إلى التعيين، فهو لا يقصد ذئبًا بعينه، بل واحدًا من أفراد الجنس مما استقرّ في الذهن معرفته.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص109.","url":""}]},{"id":"s12-278","number":278,"surah":12,"verses":[30],"references":[{"surah":12,"verses":[30]}],"verseLabel":"يوسف: 30","question":"ما سر تذكير الفعل في قوله: ﴿وقال نسوة في المدينة﴾، وتأنيثه في الحجرات: ﴿قالت الأعراب﴾؟","answer":"جرى التعبير على قاعدة العربية في الإتيان بالمؤنث للدلالة على الكثرة بخلاف المذكر، فتذكير الفعل مع «النسوة» يدل على أنهن قلة، وتأنيثه مع «الأعراب» يدل على كثرتهم.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص180.","url":""}]},{"id":"s12-279","number":279,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"ما دلالة قول يوسف لإخوته: ﴿أنا يوسف وهذا أخي﴾، مع أنهم يعرفون أخاهم؟","answer":"أراد أن يخبرهم أنه أخوه وهو يعرفه حقًا كما عرفهم وهم له منكرون، فلم يخدعوه بشخص آخر يزعمون أنه أخوه، كما خدعوا أباهم حين جاؤوا بالبكاء وبالقميص والدم الكذب.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص67–68.","url":""}]},{"id":"s12-280","number":280,"surah":12,"verses":[96],"references":[{"surah":12,"verses":[96]}],"verseLabel":"يوسف: 96","question":"ما سر زيادة «أن» بعد «لمّا» في قوله: ﴿فلمّا أن جاء البشير ألقاه على وجهه﴾؟","answer":"زيدت لمناسبة حالة الانتظار والترقب التي كان فيها يعقوب، فقد كان شديد اللهفة على رؤية ولده يستطيل كل لحظة، ففصل بين «لمّا» ومجيء البشير إشارةً إلى الشعور باستطالة الوقت. ونظيره ﴿ولما أن جاءت رسلنا لوطًا﴾ في العنكبوت.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص109.","url":""}]},{"id":"s12-281","number":281,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما سر ذكر الإخراج من السجن دون البئر في قوله: ﴿وقد أحسن بي إذ أخرجني من السجن﴾؟","answer":"أُخرج من البئر إلى الرقّ والعبودية ثم إلى السجن بتهمة مخلّة بالشرف، فلا منّة في ذلك، أما إخراجه من السجن فكان إلى الإحسان إليه وجعله عزيز مصر، فاختلف الأمران.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص68–69.","url":""}]},{"id":"s12-282","number":282,"surah":12,"verses":[109],"references":[{"surah":12,"verses":[109]}],"verseLabel":"يوسف: 109","question":"ما دلالة العطف بالفاء في قوله: ﴿أفلم يسيروا في الأرض﴾؟","answer":"إذا كان ما بعدها مبنيًا على ما قبلها عُطف بالفاء. وقد قال قبلها: ﴿أفأمنوا أن تأتيهم غاشية من عذاب الله﴾، فالمعنى: ألا يسيرون فينظرون عاقبة من جاءتهم الغواشي من قبلهم؟ فالسياق داعٍ إلى التأمل والاتعاظ المترتب على ما سبق، فاستدعى الفاء.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص125.","url":""}]},{"id":"s13-132","number":132,"surah":13,"verses":[11],"references":[{"surah":13,"verses":[11]}],"verseLabel":"الرعد: 11","question":"ما سر إسناد إرادة السوء إلى لفظ الجلالة دون «الرب» في قوله: ﴿وإذا أراد الله بقوم سوءًا فلا مردّ له﴾؟","answer":"لم يرد في القرآن إسناد إرادة السوء أو الضرّ إلى «الرب»، بل يُسند ذلك إلى الله كما يُسند إليه إرادة الخير والرحمة. أما «الرب» فلا يُسند إليه من الإرادة إلا إرادة الخير والرشد، كقوله: ﴿فأراد ربّك أن يبلغا أشدّهما﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص71 وص275.","url":""}]},{"id":"s13-133","number":133,"surah":13,"verses":[20,22],"references":[{"surah":13,"verses":[20,22]}],"verseLabel":"الرعد: 20، 22","question":"ما سر مجيء بعض صفات أولي الألباب بالمضارع ﴿يوفون، يصلون، يخشون، يدرؤون﴾، وبعضها بالماضي ﴿صبروا، أقاموا، أنفقوا﴾؟","answer":"ما كان مستمرًا ليس له وقت محدد جاء بالمضارع، كالوفاء والصلة والخشية ودرء السيئة. وما كان له وقت محدد جاء بالماضي، كإقامة الصلاة والإنفاق. وجاء الصبر بالماضي لأنه أسبق من الجميع والصفات مترتبة عليه، ولذا لم يرد الصبر صلةً في القرآن إلا بالماضي.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص71–74.","url":""}]},{"id":"s13-134","number":134,"surah":13,"verses":[21],"references":[{"surah":13,"verses":[21]}],"verseLabel":"الرعد: 21","question":"ما دلالة إطلاق الخشية في قوله: ﴿ويخشون ربّهم﴾، وتقييدها في مواضع أخرى بـ﴿بالغيب﴾؟","answer":"الخشية بالغيب جزء من الخشية العامة المطلقة، وكلّ موضع ذُكرت فيه الخشية بالغيب اشتمل على جزء مما ذُكر في آيات الرعد. أما الرعد ففصّلت في الصفات وزادت في الجزاء: عقبى الدار وجنات عدن ودخول الملائكة عليهم من كل باب، فناسبها الخشية المطلقة، فناظر بين المواضع في الإطلاق والتقييد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص37–38.","url":""}]},{"id":"s13-135","number":135,"surah":13,"verses":[24],"references":[{"surah":13,"verses":[24]}],"verseLabel":"الرعد: 24","question":"ما دلالة تنكير السلام في تحية الملائكة: ﴿سلامٌ عليكم بما صبرتم﴾؟","answer":"النكرة أعم وأشمل من المعرفة، ولذلك كانت تحية أهل الجنة «سلام» بالتنكير، يحييهم بها الرحمن والملائكة، ولم ترد تحيتهم بالتعريف. وهو أيضًا ما سلّم به الله على رسله: ﴿سلامٌ على نوح في العالمين﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص151.","url":""}]},{"id":"s13-136","number":136,"surah":13,"verses":[32],"references":[{"surah":13,"verses":[32]}],"verseLabel":"الرعد: 32","question":"ما سر الختم بـ﴿فكيف كان عقاب﴾ هنا، وبـ﴿فكيف كان نكير﴾ في الحج؟","answer":"العقاب أشدّ موقعًا من النكير، لأن الإنكار قد يقع على ما لا عقاب فيه. وقد تقدّم في الرعد ﴿ولقد استُهزئ برسل من قبلك﴾، والاستهزاء زائد على التكذيب، فناسبه العقاب. أما آية الحج فلم يُذكر فيها غير التكذيب. وهذا التوجيه منقول عن «ملاك التأويل».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص232–233.","url":""}]},{"id":"s13-137","number":137,"surah":13,"verses":[40],"references":[{"surah":13,"verses":[40]}],"verseLabel":"الرعد: 40","question":"ما دلالة رسم ﴿وإن ما نرينّك﴾ مفصولة هنا، وموصولة في يونس وغافر ﴿وإمّا نرينّك﴾؟","answer":"هذا من رسم المصحف الذي لا يُقاس عليه، لكن قد يُلتمس له تعليل لا يُقطع بأنه مقصود: الكلام في الرعد على الدنيا والحساب في الآخرة: ﴿فإنما عليك البلاغ وعلينا الحساب﴾، ففُصلت إشارةً إلى الفصل بين الأحداث. أما يونس وغافر ففي سياق الآخرة والرجوع إلى الله، فوُصلت إشارةً إلى اتصال الأحداث.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص83–85.","url":""}]},{"id":"s14-187","number":187,"surah":14,"verses":[27],"references":[{"surah":14,"verses":[27]}],"verseLabel":"إبراهيم: 27","question":"ما دلالة التعبير بالفعل في قوله: ﴿ويُضلّ الله الظالمين﴾، ولم يُوصف سبحانه بـ«المُضِلّ»؟","answer":"أضاف الله الإضلال إلى نفسه بالصورة الفعلية فقط، للدلالة على أنه أمر طارئ يفعله مع من يستحقه مجازاةً، وليس من صفاته ونعوته، فلم يُسنده إليه بالصورة الاسمية. في حين وُصف الشيطان بالاسم: ﴿إنه عدوّ مضلّ مبين﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص31–32.","url":""}]},{"id":"s14-188","number":188,"surah":14,"verses":[31],"references":[{"surah":14,"verses":[31]}],"verseLabel":"إبراهيم: 31","question":"ما سر ختم آية البقرة بـ﴿والكافرون هم الظالمون﴾، والاكتفاء في إبراهيم بذكر اليوم الذي لا بيع فيه ولا خلال؟","answer":"سبق آية البقرة الكلام على الكافرين: ﴿فمنهم من آمن ومنهم من كفر﴾، فناسب ذكرهم وأنهم هم الظالمون. أما آية إبراهيم فسبقها الكلام على جهنم والمصير إلى النار، فناسب الكلام على اليوم الآخر.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص193.","url":""}]},{"id":"s14-189","number":189,"surah":14,"verses":[34],"references":[{"surah":14,"verses":[34]}],"verseLabel":"إبراهيم: 34","question":"ما سر وصف الإنسان بـ«كفّار» هنا، وهو يُوصف في غيرها بـ«كفور»؟","answer":"وُصف الإنسان بـ«الكفور» كثيرًا كأنه مخلوق من هذا الوصف، ولم يُوصف بـ«الكفّار» إلا هنا، لأن الآية في سياق النعم المتعددة المتجددة التي لا تُحصى، فجاء بصيغة «فعّال» الدالة على التجدد والمزاولة وقتًا بعد وقت، أي أنه يكفر النعم بصورة مستمرة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص38–39.","url":""}]},{"id":"s14-190","number":190,"surah":14,"verses":[52],"references":[{"surah":14,"verses":[52]}],"verseLabel":"إبراهيم: 52","question":"ما سر ذكر المبتدأ في قوله: ﴿هذا بلاغ للناس﴾، وحذفه في الأحقاف: ﴿بلاغٌ فهل يُهلك إلا القوم الفاسقون﴾؟","answer":"المقام في الأحقاف مقام إيجاز، إذ سبق البلاغ آيتان فقط. أما في إبراهيم فمقام تفصيل، فالبلاغ يبدأ من قوله: ﴿ولا تحسبنّ الله غافلًا﴾ في إحدى عشرة آية، وفُصّل في آية البلاغ نفسها ما لم يُفصّل في الأحقاف، فناسب ذكر المبتدأ.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص112–113.","url":""}]},{"id":"s15-190","number":190,"surah":15,"verses":[27],"references":[{"surah":15,"verses":[27]}],"verseLabel":"الحجر: 27","question":"ما دلالة قوله: ﴿والجانّ خلقناه من قبل من نار السموم﴾ في تقديم الجن على الإنس في مواضع من القرآن؟","answer":"قد يرتّب القرآن الألفاظ بحسب القدم والأولية في الوجود، كقوله: ﴿وما خلقت الجنّ والإنس إلا ليعبدون﴾، فقدّم الجن لأن خلقهم سابق لخلق الإنس، بدليل آية الحجر هذه: ﴿خلقناه من قبل﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص53.","url":""}]},{"id":"s15-191","number":191,"surah":15,"verses":[28],"references":[{"surah":15,"verses":[28]}],"verseLabel":"الحجر: 28","question":"ما سر قوله: ﴿إني خالق بشرًا من صلصال من حمأ مسنون﴾، وفي ص: ﴿إني خالق بشرًا من طين﴾؟","answer":"القصة في الحجر جاءت بعد قوله: ﴿ولقد خلقنا الإنسان من صلصال من حمأ مسنون﴾، فناسب أن ترد اللفظة في صلب القصة. ومن لطائفه أن «صلصال» مؤلفة من الصاد والألف واللام، وقد تكررت فيها الألف واللام أكثر من الصاد، فوضعها في السورة المبدوءة بـ﴿الر﴾ أنسب.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص310–311.","url":""}]},{"id":"s15-192","number":192,"surah":15,"verses":[31],"references":[{"surah":15,"verses":[31]}],"verseLabel":"الحجر: 31","question":"ما الفرق بين ﴿أبى أن يكون مع الساجدين﴾ هنا، و﴿استكبر وكان من الكافرين﴾ في ص؟","answer":"«أبى» رفض وامتنع، و«استكبر» رأى نفسه خيرًا من غيره، والرفض قد يكون لغير استكبار. وقد بُنيت قصة الحجر على الإباء، وقصة ص على الاستكبار، ولذلك سُئل في ص: ﴿أستكبرت أم كنت من العالين﴾ وأجاب: ﴿أنا خير منه﴾، وليس مثل ذلك في الحجر.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص312–313.","url":""}]},{"id":"s15-193","number":193,"surah":15,"verses":[31],"references":[{"surah":15,"verses":[31]}],"verseLabel":"الحجر: 31","question":"ما سر ذكر السجود في قوله: ﴿أبى أن يكون مع الساجدين﴾، وتركه في ص؟","answer":"جوّ السجود شائع في قصة الحجر وسورتها، فقد ورد السجود في القصة ست مرات، وخُتمت به السورة: ﴿وكن من الساجدين﴾. أما في ص فورد ثلاث مرات، حتى إن داود لمّا تاب قيل فيه: ﴿وخرّ راكعًا﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص314.","url":""}]},{"id":"s15-194","number":194,"surah":15,"verses":[42],"references":[{"surah":15,"verses":[42]}],"verseLabel":"الحجر: 42","question":"ما سر التشديد في قوله: ﴿إلا من اتّبعك من الغاوين﴾، والتخفيف في ص: ﴿وممّن تبِعك منهم أجمعين﴾؟","answer":"جاء بعد القصة في الحجر: ﴿نبّئ عبادي أني أنا الغفور الرحيم﴾، فناسب أن يخفّف على عباده فلا يدخل النار إلا من بالغ في اتباع إبليس. ولم يرد مثل ذلك في ص فكان التحذير أشد. ثم إن قصة الحجر جاءت بعد ذكر نعم الله على البشر، وفي ص بعد ذكر العقوبات.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص317.","url":""}]},{"id":"s15-195","number":195,"surah":15,"verses":[52],"references":[{"surah":15,"verses":[52]}],"verseLabel":"الحجر: 52","question":"ما سر ترك ردّ إبراهيم التحية في قوله: ﴿إذ دخلوا عليه فقالوا سلامًا﴾، وذكره في الذاريات: ﴿قال سلامٌ﴾؟","answer":"وُصف الضيف في الذاريات بأنهم ﴿المكرَمين﴾، وردّ التحية من الإكرام، فذُكر، وردّها بخير منها بالجملة الاسمية الدالة على الثبوت. أما في الحجر فلم يصفهم بالإكرام ولم يذكر أنه ردّ عليهم.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص84.","url":""}]},{"id":"s15-196","number":196,"surah":15,"verses":[52,53],"references":[{"surah":15,"verses":[52,53]}],"verseLabel":"الحجر: 52، 53","question":"ما دلالة الجملة الاسمية في قوله: ﴿إنا منكم وجِلون﴾ و﴿إنا نبشّرك﴾، والفعلية في الذاريات: ﴿فأوجس منهم خيفة﴾ و﴿وبشّروه﴾؟","answer":"الوجل في الحجر أكبر؛ فقد واجههم به بجملة اسمية مؤكدة بـ«إنّ»، وبالصفة المشبهة «وجِلون» الدالة على شدة الخوف، وبصيغة الجمع لأهل البيت. فلما واجههم بالاسمية واجهوه بالبشرى اسميةً. أما في الذاريات فجاء الخوف فعليًّا غير مؤكد بصيغة الغيبة، فجاءت البشرى فعلية بصيغة الغيبة أيضًا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص86–87.","url":""}]},{"id":"s16-241","number":241,"surah":16,"verses":[14],"references":[{"surah":16,"verses":[14]}],"verseLabel":"النحل: 14","question":"ما سر تقديم «مواخر» على «فيه» في قوله: ﴿وَتَرَى الْفُلْكَ مَوَاخِرَ فِيهِ﴾، وقد قُدِّم الجار في فاطر: ﴿فِيهِ مَوَاخِرَ﴾؟","answer":"سياق النحل في وسائط النقل؛ فقد ذكر الأنعام تحمل الأثقال، والخيل والبغال والحمير للركوب، ثم ذكر الفلك وهي واسطة نقل أيضًا، فقدّم «مواخر» لأنها صفة الفلك في جريانها، وهذا ما يناسب سياق الحمل والانتقال. أما سياق فاطر فليس في وسائط النقل، فلم يقتضِ هذا التقديم.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص69.","url":""}]},{"id":"s16-242","number":242,"surah":16,"verses":[34],"references":[{"surah":16,"verses":[34]}],"verseLabel":"النحل: 34","question":"ما سر قوله: ﴿فَأَصَابَهُمْ سَيِّئَاتُ مَا عَمِلُوا﴾، وفي الزمر: ﴿سَيِّئَاتُ مَا كَسَبُوا﴾؟","answer":"وقعت آية النحل بين ألفاظ العمل، كقولهم: ﴿مَا كُنَّا نَعْمَلُ مِن سُوءٍ﴾ والرد: ﴿بِمَا كُنتُمْ تَعْمَلُونَ﴾، ووقعت آية الزمر بين ألفاظ الكسب. ويقوّي ذلك أن لفظ الكسب لم يرد في النحل البتة، وتكرر في الزمر خمس مرات، فوُضعت كل لفظة في موطنها. والتوجيه الأول منقول عن غيره.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص242–243.","url":""}]},{"id":"s16-243","number":243,"surah":16,"verses":[35],"references":[{"surah":16,"verses":[35]}],"verseLabel":"النحل: 35","question":"ما سر قوله في النحل: ﴿لَوْ شَاءَ اللَّهُ مَا عَبَدْنَا مِن دُونِهِ مِن شَيْءٍ نَّحْنُ وَلَا آبَاؤُنَا﴾، وفي الأنعام: ﴿مَا أَشْرَكْنَا وَلَا آبَاؤُنَا﴾؟","answer":"سياق النحل في الرد على الشرك في العبادة والنعي على المعبودات الباطلة، وقد بدأت بقوله: ﴿سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ﴾، فذكر العبادة من دونه صراحة، وزاد «نحن» و«من دونه» توفيةً للمعنى وتوكيدًا. أما سياق الأنعام ففي التحريم والافتراء في الحرث والأنعام، فاكتفى بنفي الإشراك.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص265–269.","url":""}]},{"id":"s16-244","number":244,"surah":16,"verses":[64],"references":[{"surah":16,"verses":[64]}],"verseLabel":"النحل: 64","question":"ما سر ذكر «الهدى والرحمة» في الآية 64، و«الهدى والبشرى» في الآية 102، وجمع الثلاثة في الآية 89 من السورة نفسها؟","answer":"في الآية 64 ذكر غرضًا واحدًا من أغراض إنزال الكتاب، وهو تبيين ما اختلفوا فيه، فذكر الهدى والرحمة. وفي الآية 102 تقدّمها شيء من البشرى للصابرين والعاملين، فذكر الهدى والبشرى. أما الآية 89 فوصفت الكتاب بأنه ﴿تِبْيَانًا لِّكُلِّ شَيْءٍ﴾ فجمعت الأوصاف كلها.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص107–108.","url":""}]},{"id":"s16-245","number":245,"surah":16,"verses":[65],"references":[{"surah":16,"verses":[65]}],"verseLabel":"النحل: 65","question":"ما سر الإفراد في قوله: ﴿إِنَّ فِي ذَلِكَ لَآيَةً لِّقَوْمٍ يَسْمَعُونَ﴾، والجمع في الروم: ﴿لَآيَاتٍ﴾ مع أن المشهد واحد؟","answer":"زاد في الروم ذكر البرق خوفًا وطمعًا فزادت الآيات. ثم إنه قال في النحل: ﴿أَنزَلَ... فَأَحْيَا﴾ بالماضي، وقال في الروم: ﴿يُرِيكُمُ... وَيُنَزِّلُ... فَيُحْيِي﴾ بالمضارع، فتكرر التنزيل والإحياء والرؤية فصارت آيات لا آية واحدة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص78–79.","url":""}]},{"id":"s16-246","number":246,"surah":16,"verses":[66],"references":[{"surah":16,"verses":[66]}],"verseLabel":"النحل: 66","question":"ما سر تذكير الضمير في قوله: ﴿نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ﴾، وتأنيثه في المؤمنون: ﴿مِّمَّا فِي بُطُونِهَا﴾؟","answer":"الكلام في النحل على إسقاء اللبن، واللبن لا يخرج من جميع الأنعام بل من قسم من إناثها، فجاء بضمير المذكر الدال على القلة. أما المؤمنون فعلى منافع الأنعام عامة: ﴿وَلَكُمْ فِيهَا مَنَافِعُ كَثِيرَةٌ﴾، وهي تعم ذكورها وإناثها، فجاء بضمير المؤنث الدال على الكثرة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص179–180.","url":""}]},{"id":"s16-247","number":247,"surah":16,"verses":[72],"references":[{"surah":16,"verses":[72]}],"verseLabel":"النحل: 72","question":"ما دلالة ذكر الضمير «هم» في قوله: ﴿وَبِنِعْمَتِ اللَّهِ هُمْ يَكْفُرُونَ﴾، وحذفه في العنكبوت: ﴿وَبِنِعْمَةِ اللَّهِ يَكْفُرُونَ﴾؟","answer":"في إسناد الفعل إلى الضمير المتقدم توكيد وتخصيص. وآية النحل في سياق النعم العامة المفصّلة، حتى تُسمّى السورة سورة النعم، فناسب زيادة الإنكار على من يكفر بعد كل تلك النعم. أما العنكبوت ففي قريش خاصة وجوّها الفتن والمحن. ولفظ النعمة ورد في النحل تسع مرات وفي العنكبوت مرة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص95–97.","url":""}]},{"id":"s16-248","number":248,"surah":16,"verses":[80],"references":[{"surah":16,"verses":[80]}],"verseLabel":"النحل: 80","question":"ما دلالة لفظ «الإقامة» في قوله: ﴿يَوْمَ ظَعْنِكُمْ وَيَوْمَ إِقَامَتِكُمْ﴾، دون «الإقام»؟","answer":"خصّ القرآن «الإقام» بإقام الصلاة، كقوله: ﴿وَإِقَامَ الصَّلَاةِ﴾، واستعمل «الإقامة» لما يقابل الظعن والسفر، فجاءت هنا في مقابلة الظعن.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص20.","url":""}]},{"id":"s16-249","number":249,"surah":16,"verses":[120,122],"references":[{"surah":16,"verses":[120,122]}],"verseLabel":"النحل: 120، 122","question":"ما سر قوله في إبراهيم: ﴿وَآتَيْنَاهُ فِي الدُّنْيَا حَسَنَةً﴾، وفي العنكبوت: ﴿وَآتَيْنَاهُ أَجْرَهُ فِي الدُّنْيَا﴾؟","answer":"ما ورد في النحل هو كل ما ورد من خبر إبراهيم فيها، وقد وصفه بصفاته ولم يذكر له عملًا مع قومه، فلم يذكر الأجر لأن الأجر جزاء العمل. أما العنكبوت فذكرت دعوته قومه وصبره حتى قالوا: ﴿اقْتُلُوهُ أَوْ حَرِّقُوهُ﴾، فجزاه ربه وآتاه أجره.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص79–80.","url":""}]},{"id":"s17-235","number":235,"surah":17,"verses":[9],"references":[{"surah":17,"verses":[9]}],"verseLabel":"الإسراء: 9","question":"ما سر الإشارة بـ«هذا» الدالة على القريب في قوله: ﴿إِنَّ هَٰذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ﴾، وبـ«ذلك» في البقرة: ﴿ذَٰلِكَ الْكِتَابُ﴾؟","answer":"أشار في البقرة بـ«ذلك» ليدل على علوّ الكتاب وبُعده عن الريب وأنه بعيد المنال عن أن يُؤتى بمثله. أما في الإسراء فالكلام في هداية الناس ومعرفتهم به وبأحكامه، فانبغى أن يكون قريبًا منهم.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص7.","url":""}]},{"id":"s17-236","number":236,"surah":17,"verses":[28],"references":[{"surah":17,"verses":[28]}],"verseLabel":"الإسراء: 28","question":"ما دلالة التعبير بالإعراض في قوله: ﴿وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ابْتِغَاءَ رَحْمَةٍ مِّن رَّبِّكَ﴾ دون التولّي؟","answer":"الإعراض أخفّ من التولّي، فالتولّي فيه إدبار، ولو لم يكن معه إدبار فهو أشد من الإعراض. ولما كان المعرَض عنهم ذوي القربى والمساكين وابن السبيل جاء باللفظ الأخفّ، وأتبعه بقوله: ﴿فَقُل لَّهُمْ قَوْلًا مَّيْسُورًا﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص247.","url":""}]},{"id":"s17-237","number":237,"surah":17,"verses":[33],"references":[{"surah":17,"verses":[33]}],"verseLabel":"الإسراء: 33","question":"ما سر زيادة قوله: ﴿فَلَا يُسْرِف فِّي الْقَتْلِ﴾ في الإسراء، والاقتصار في الأنعام على النهي عن قتل النفس؟","answer":"النهي عن الإسراف في القتل متناسق مع النهي عن التبذير في الأموال الذي سبقه في السورة، ثم إن هذا التبسّط ملائم لسياق التفصيل في الإسراء، كما أن الإيجاز ملائم لسياق الأنعام.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص285.","url":""}]},{"id":"s17-238","number":238,"surah":17,"verses":[34],"references":[{"surah":17,"verses":[34]}],"verseLabel":"الإسراء: 34","question":"ما سر تقديم الفعل في قوله: ﴿وَأَوْفُوا بِالْعَهْدِ﴾، وتقديم الجار والمجرور في الأنعام: ﴿وَبِعَهْدِ اللَّهِ أَوْفُوا﴾؟","answer":"التقديم في الأنعام للاهتمام والعناية، لأنه أضاف العهد إلى الله فازداد تفخيمًا وكان أدعى إلى تقديمه. ولم يُضف العهد في آية الإسراء إلى الله.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص287.","url":""}]},{"id":"s17-239","number":239,"surah":17,"verses":[34,35],"references":[{"surah":17,"verses":[34,35]}],"verseLabel":"الإسراء: 34، 35","question":"ما سر تقديم الوفاء بالعهد على إيفاء الكيل في الإسراء، وعكسه في الأنعام؟","answer":"مرّ في الأنعام ذكر المفتقرين: ﴿مِّنْ إِمْلَاقٍ﴾، والفقراء أدعى إلى التطفيف لحاجتهم إلى المال، فقدّم الكيل والميزان. ومرّ في الإسراء ذكر الموسرين، فقدّم العهد، فوُضع كل تعبير في مكانه الأليق به.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص286.","url":""}]},{"id":"s17-240","number":240,"surah":17,"verses":[35],"references":[{"surah":17,"verses":[35]}],"verseLabel":"الإسراء: 35","question":"ما فائدة التقييد في قوله: ﴿وَأَوْفُوا الْكَيْلَ إِذَا كِلْتُمْ﴾؟","answer":"هذه الزيادة متناسبة مع سياق التفصيل في الإسراء، ومعناها: أوفوا وقت الكيل نفسه ولا تؤخّروا شيئًا من الحق بأن يُكال بنقصان ثم يُوفى بعد. وهذا التوجيه منقول عن «البحر المحيط».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص286.","url":""}]},{"id":"s17-241","number":241,"surah":17,"verses":[49],"references":[{"surah":17,"verses":[49]}],"verseLabel":"الإسراء: 49","question":"ما سر قولهم في الإسراء: ﴿أَئِذَا كُنَّا عِظَامًا وَرُفَاتًا﴾، وفي المؤمنون وغيرها: ﴿أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا﴾؟","answer":"الرفات هو الفتات والحطام، فإذا بلي صار ترابًا، فالتراب والعظام أدلّ على البلى وبعثهما أغرب في عقول المنكرين. ولم يُذكر في الإسراء من إنكارهم غير هاتين الآيتين، أما حيث ذُكر التراب والعظام فقد اشتدّ العجب والاستبعاد، كإضافتهم الآباء الأولين.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص117–118.","url":""}]},{"id":"s17-242","number":242,"surah":17,"verses":[62],"references":[{"surah":17,"verses":[62]}],"verseLabel":"الإسراء: 62","question":"ما سر حذف الياء في قوله: ﴿لَئِنْ أَخَّرْتَنِ إِلَىٰ يَوْمِ الْقِيَامَةِ﴾، وإثباتها في المنافقون: ﴿لَوْلَا أَخَّرْتَنِي﴾؟","answer":"تردّد فعل التأخير مرتين في سورة المنافقون، وذُكر مرة واحدة في الإسراء، فزاد الياء في موطن الزيادة وحذفها في موطن الاجتزاء بالكسرة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص88.","url":""}]},{"id":"s17-243","number":243,"surah":17,"verses":[83],"references":[{"surah":17,"verses":[83]}],"verseLabel":"الإسراء: 83","question":"ما سر إسناد الإنعام إلى الله وترك إسناد الشر إليه في قوله: ﴿وَإِذَا أَنْعَمْنَا عَلَى الْإِنسَانِ أَعْرَضَ... وَإِذَا مَسَّهُ الشَّرُّ كَانَ يَئُوسًا﴾؟","answer":"القرآن يُسند الفعل إلى الله في مقام الخير والتفضل، ولا يذكر نفسه في الشر والسوء تنزيهًا له عن إرادة السوء، ففي النعمة أظهر نفسه فقال: «أنعمنا»، وفي الشر قال: «مسّه الشر» ولم يقل: «مسسناه بالشر».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص320.","url":""}]},{"id":"s17-244","number":244,"surah":17,"verses":[93],"references":[{"surah":17,"verses":[93]}],"verseLabel":"الإسراء: 93","question":"ما دلالة تعدية الإيمان باللام في قولهم: ﴿وَلَن نُّؤْمِنَ لِرُقِيِّكَ﴾؟","answer":"الإيمان بالله لا يُعدّى إلا بالباء، فإذا عُدّي باللام فهو لغير الله ومعناه التصديق، وأكثر ما يكون مع الأشخاص كقوله: ﴿لَن نُّؤْمِنَ لَكَ﴾. وجاء هنا مع غير الشخص وهو نادر، أي لن نصدّق برقيّك.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص75.","url":""}]},{"id":"s18-246","number":246,"surah":18,"verses":[2],"references":[{"surah":18,"verses":[2]}],"verseLabel":"الكهف: 2","question":"ما سر التعبير بـ«لَدُن» في قوله: ﴿لِّيُنذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ﴾، وهي تأتي في مواطن اللين والرحمة؟","answer":"هذا هو الموطن الوحيد الذي اقترن فيه البأس والشدة بـ«لدن»، وهو مع ذلك في سياق الرحمة؛ فالكلام على القرآن الذي أُنزل مُنذرًا ومبشرًا: ﴿وَيُبَشِّرَ الْمُؤْمِنِينَ﴾، وهو خير ورحمة في الإنذار والتبشير جميعًا.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج2، ص218.","url":""}]},{"id":"s18-247","number":247,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما سر التعبير بالماضي في قوله: ﴿إِذَا طَلَعَت تَّزَاوَرُ عَن كَهْفِهِمْ... وَإِذَا غَرَبَت تَّقْرِضُهُمْ﴾؟","answer":"الطلوع والغروب يقعان جملةً واحدة فعبّر عنهما بالماضي، بخلاف قوله: ﴿وَاللَّيْلِ إِذَا يَسْرِ﴾ فالمضارع هناك يفيد الاستمرار والتطاول. وجاء بـ«إذا» لأنها للمقطوع بوقوعه، والطلوع والغروب لا بدّ من وقوعهما.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص62، ص72.","url":""}]},{"id":"s18-248","number":248,"surah":18,"verses":[22],"references":[{"surah":18,"verses":[22]}],"verseLabel":"الكهف: 22","question":"ما سر الواو في قوله: ﴿وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْ﴾ دون الجملتين الأوليين؟","answer":"هي الواو الداخلة على الجملة الواقعة صفةً للنكرة، وفائدتها تأكيد لصوق الصفة بالموصوف وأن اتصافه بها ثابت مستقر، فآذنت بأن القائلين «سبعة وثامنهم كلبهم» قالوه عن ثبات علم لا رجمًا بالظن كغيرهم. وهذا التوجيه منقول عن «الكشاف»، والجمهور يعدّونها واو الحال.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج2، ص299.","url":""}]},{"id":"s18-249","number":249,"surah":18,"verses":[23],"references":[{"surah":18,"verses":[23]}],"verseLabel":"الكهف: 23","question":"ما دلالة صيغة اسم الفاعل في قوله: ﴿وَلَا تَقُولَنَّ لِشَيْءٍ إِنِّي فَاعِلٌ ذَٰلِكَ غَدًا﴾، وقد جاء في غيرها: ﴿فَعَّالٌ لِّمَا يُرِيدُ﴾؟","answer":"ورد «فاعل» مرة واحدة في القرآن في هذه الآية، فجاء باسم الفاعل للشيء الواحد: ﴿لِشَيْءٍ﴾. وجاء بصيغة المبالغة «فعّال» في موضعيها للتكثير، لأن ﴿مَا يُرِيدُ﴾ يشمل عموم ما يريد.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص37.","url":""}]},{"id":"s18-250","number":250,"surah":18,"verses":[43],"references":[{"surah":18,"verses":[43]}],"verseLabel":"الكهف: 43","question":"ما سر قوله: ﴿وَلَمْ تَكُن لَّهُ فِئَةٌ... وَمَا كَانَ مُنتَصِرًا﴾، وفي قارون: ﴿فَمَا كَانَ لَهُ مِن فِئَةٍ... وَمَا كَانَ مِنَ الْمُنتَصِرِينَ﴾؟","answer":"في الكهف هَلَكت الجنتان ونجا صاحبهما، وفي القصص خُسف بقارون وداره، فالعقوبة هناك أشد. فجاء في القصص بـ«ما كان» وهي آكد من «لم تكن»، وبـ«مِن» الاستغراقية المؤكدة. ولما كان الحوار في الكهف بين شخصين والمنتصر واحد قال: «منتصرًا»، ولما كان المنتصرون في القصص قوم موسى قال: «من المنتصرين».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص140–142.","url":""}]},{"id":"s18-251","number":251,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما سر ذكر التذكير والإعراض في الكهف: ﴿ذُكِّرَ... فَأَعْرَضَ﴾، والتكذيب والصدوف في الأنعام: ﴿كَذَّبَ بِآيَاتِ اللَّهِ وَصَدَفَ عَنْهَا﴾؟","answer":"الصدوف إعراض شديد، وقد جمع في الأنعام التكذيب والإعراض الشديد، وأتبعه بجزاء أشدّ: ﴿سَنَجْزِي الَّذِينَ يَصْدِفُونَ... سُوءَ الْعَذَابِ﴾. أما في الكهف فذكر التذكير والإعراض ولم يذكر التكذيب، فكان ما في الأنعام أشدّ.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص51–52.","url":""}]},{"id":"s19-155","number":155,"surah":19,"verses":[3,4],"references":[{"surah":19,"verses":[3,4]}],"verseLabel":"مريم: 3، 4","question":"ما سر ذكر فعل القول بعد النداء في قوله: ﴿إِذْ نَادَىٰ رَبَّهُ نِدَاءً خَفِيًّا قَالَ رَبِّ﴾، والاكتفاء بالنداء في الأنبياء: ﴿إِذْ نَادَىٰ رَبَّهُ رَبِّ لَا تَذَرْنِي فَرْدًا﴾؟","answer":"تبسّط زكريا في مريم وفصّل؛ فذكر وهن عظمه واشتعال رأسه شيبًا، وأن امرأته عاقر، وخوفه الموالي من بعده، وطلب أن يكون الوليّ رضيًّا، فاقتضى ذلك التوكيد والإلحاح فذكر فعل القول. وأوجز في الأنبياء فاكتفى بالنداء، وكما تبسّط زكريا في مريم تبسّط الرب في الجواب، ولما أوجز هناك أوجز.","sources":[{"label":"فاضل السامرائي، الجملة العربية تأليفها وأقسامها، ص215–216.","url":""}]},{"id":"s19-156","number":156,"surah":19,"verses":[10],"references":[{"surah":19,"verses":[10]}],"verseLabel":"مريم: 10","question":"ما سر قوله في مريم: ﴿أَلَّا تُكَلِّمَ النَّاسَ ثَلَاثَ لَيَالٍ سَوِيًّا﴾، وفي آل عمران: ﴿ثَلَاثَةَ أَيَّامٍ﴾؟","answer":"حسُن ذكر الليل في مريم لأن النداء فيها خفيّ، والليل أنسب للإخفاء والنهار للإظهار. وذكر فيها شيخوخته ووهن عظمه وبلوغه من الكبر عتيًّا، والضعف أشبه بالليل وسكونه، وذكر طلبه وارثًا يرثه بعد موته، والموت ليل طويل. ولم يذكر شيئًا من ذلك في آل عمران فذكر الأيام.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص115–117.","url":""}]},{"id":"s19-157","number":157,"surah":19,"verses":[18],"references":[{"surah":19,"verses":[18]}],"verseLabel":"مريم: 18","question":"ما سر استعاذة مريم بالرحمن في قولها: ﴿إِنِّي أَعُوذُ بِالرَّحْمَٰنِ مِنكَ﴾، وقول موسى: ﴿أَعُوذُ بِاللَّهِ أَنْ أَكُونَ مِنَ الْجَاهِلِينَ﴾؟","answer":"استعاذت بالرحمن ليرحمها ويقيها السوء، وذلك مناسب لجوّ الرحمة الذي يشيع في السورة. أما سياق البقرة فسياق عقوبة ومسخ وتنكيل، ولا تناسب الرحمةُ ذاك، فقال: «أعوذ بالله».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص253.","url":""}]},{"id":"s19-158","number":158,"surah":19,"verses":[26],"references":[{"surah":19,"verses":[26]}],"verseLabel":"مريم: 26","question":"ما دلالة لفظ «الصوم» في قولها: ﴿إِنِّي نَذَرْتُ لِلرَّحْمَٰنِ صَوْمًا﴾؟","answer":"خصّ القرآن كلمة «الصوم» بمعنى الصمت، ولم يرد بمعنى العبادة المعروفة إلا «الصيام»، ولذا قالت بعده: ﴿فَلَنْ أُكَلِّمَ الْيَوْمَ إِنسِيًّا﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص72.","url":""}]},{"id":"s19-159","number":159,"surah":19,"verses":[29],"references":[{"surah":19,"verses":[29]}],"verseLabel":"مريم: 29","question":"ما دلالة «المَهْد» في قوله: ﴿كَيْفَ نُكَلِّمُ مَن كَانَ فِي الْمَهْدِ صَبِيًّا﴾ مقابل «المِهَاد»؟","answer":"المَهْد مهد الصبي، وهو الموضع الذي يُهيّأ له ويُوطّأ لينام فيه، أما المِهاد فهو الفراش الواسع، كقوله: ﴿أَلَمْ نَجْعَلِ الْأَرْضَ مِهَادًا﴾، والمهاد أجمع من المهد.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص62.","url":""}]},{"id":"s19-160","number":160,"surah":19,"verses":[31],"references":[{"surah":19,"verses":[31]}],"verseLabel":"مريم: 31","question":"ما سر قوله: ﴿وَأَوْصَانِي بِالصَّلَاةِ وَالزَّكَاةِ﴾ بـ«أوصى» دون «وصّى»؟","answer":"«وصّى» بالتشديد تأتي في القرآن في الدين والأمور المعنوية، و«أوصى» في الأمور المادية كالمواريث. ولم ترد «أوصى» في أمر معنوي إلا في هذا الموطن، لأن الصلاة اقترنت بالزكاة، والزكاة أمر مادي يتعلق بالأموال.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص14.","url":""}]},{"id":"s19-161","number":161,"surah":19,"verses":[65],"references":[{"surah":19,"verses":[65]}],"verseLabel":"مريم: 65","question":"ما دلالة «اصطبر» دون «اصبر» في قوله: ﴿فَاعْبُدْهُ وَاصْطَبِرْ لِعِبَادَتِهِ﴾؟","answer":"أمره بالاصطبار لا بمجرّد الصبر ليدلّ على ثِقل العبادة وأنها تحتاج إلى اصطبار، فالفعل أثقل من الترك، والأمر بالعبادة أمر بفعل دائم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص178.","url":""}]},{"id":"s19-162","number":162,"surah":19,"verses":[85],"references":[{"surah":19,"verses":[85]}],"verseLabel":"مريم: 85","question":"ما سر قوله: ﴿يَوْمَ نَحْشُرُ الْمُتَّقِينَ إِلَى الرَّحْمَٰنِ وَفْدًا﴾، وفي الزمر: ﴿وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا﴾؟","answer":"الحشر الجمع، والوفد لا بدّ أن يكتمل أفراده، فهم يُجمعون قبل أن يُذهب بهم إلى الرحمن لتكريمهم. أما في الزمر فالسوق جماعات لم تكتمل بعد، حتى إذا اكتملوا جُمعوا وذُهب بهم إلى الرحمن وفدًا.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص81.","url":""}]},{"id":"s20-204","number":204,"surah":20,"verses":[40],"references":[{"surah":20,"verses":[40]}],"verseLabel":"طه: 40","question":"ما سر قوله: ﴿هَلْ أَدُلُّكُمْ عَلَىٰ مَن يَكْفُلُهُ﴾، وفي القصص: ﴿عَلَىٰ أَهْلِ بَيْتٍ يَكْفُلُونَهُ لَكُمْ﴾؟","answer":"ذكر في القصص امرأة فرعون وهي أهل بيته، وذكر ﴿آلُ فِرْعَوْنَ﴾ وأصل «آل» أهل، فناسب أن تدلّ أهلَ بيت فرعون على أهل بيت، وليس في طه شيء من ذلك. ثم إن القصة هنا أوجز، فناسب الإيجازَ الإيجاز. ولفظ «أهل» في القصص أكثر، و«مَن» في طه أكثر.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص122–124.","url":""}]},{"id":"s20-205","number":205,"surah":20,"verses":[78],"references":[{"surah":20,"verses":[78]}],"verseLabel":"طه: 78","question":"ما سر الباء في قوله: ﴿فَأَتْبَعَهُمْ فِرْعَوْنُ بِجُنُودِهِ﴾، والواو في يونس: ﴿فَأَتْبَعَهُمْ فِرْعَوْنُ وَجُنُودُهُ﴾؟","answer":"الواو تدل نصًّا على أن فرعون كان مع جنوده متّبعًا لموسى وقومه، والباء تحتمل ذلك وتحتمل أنه أرسل جنوده ولم يخرج معهم. وسياق يونس يذكر بطش فرعون وبغيه وغرقه وحده، وسياق طه يذكر غرق الجند: ﴿فَغَشِيَهُم﴾، ثم قال: ﴿وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ﴾ فكان موجِّهًا لهم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص143–145.","url":""}]},{"id":"s20-206","number":206,"surah":20,"verses":[94],"references":[{"surah":20,"verses":[94]}],"verseLabel":"طه: 94","question":"ما سر ذكر حرف النداء في قوله: ﴿قَالَ يَا ابْنَ أُمَّ لَا تَأْخُذْ بِلِحْيَتِي﴾، وحذفه في الأعراف: ﴿قَالَ ابْنَ أُمَّ﴾؟","answer":"سياق الأعراف سياق إيجاز وعجلة، فقد أخذ موسى برأس أخيه يجره إليه، فأراد هارون الإسراع في البيان فحذف «يا». أما سياق طه فسياق تبسّط وسؤال وأخذ ورد ولوم، فجاء بـ«يا» متودّدًا يحاول كسر حدة غضبه.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص323–324.","url":""}]},{"id":"s20-207","number":207,"surah":20,"verses":[110],"references":[{"surah":20,"verses":[110]}],"verseLabel":"طه: 110","question":"ما سر نفي الإحاطة بذاته في قوله: ﴿وَلَا يُحِيطُونَ بِهِ عِلْمًا﴾، ونفيها بعلمه في آية الكرسي: ﴿وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ﴾؟","answer":"آية طه جاءت بعد ذكر العجل الذي اتخذه بنو إسرائيل إلهًا، وقد أحاطوا به علمًا لأنهم صنعوه بأيديهم من الذهب، أما الله فلا يُحاط به علمًا، فنفى الإحاطة بذاته. وآية الكرسي في سياق العلم، فنفى الإحاطة بشيء من علمه.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص199.","url":""}]},{"id":"s21-157","number":157,"surah":21,"verses":[4],"references":[{"surah":21,"verses":[4]}],"verseLabel":"الأنبياء: 4","question":"ما سر التعبير بـ﴿يَعْلَمُ الْقَوْلَ﴾، وما دلالة إفراد ﴿السَّمَاءِ﴾ هنا وجمعها في سورة الفرقان؟","answer":"«القول» أعم من «السر» لأنه يشمل السر والجهر، فناسبه لفظ «السماء» الذي هو أعم من «السماوات». أما في الفرقان فجاء ﴿يَعْلَمُ السِّرَّ فِي السَّمَاوَاتِ﴾، فناسب الأخصُّ الأخصَّ. كما أن سياق الأنبياء ذكر النجوى وما قالوه فيها، فكان ذكر «القول» أنسب وأبلغ في إحاطة العلم بما أسروا وما أعلنوا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 21–23، مبحث «يعلم القول في السماء والأرض»؛ وانظر: فاضل السامرائي، التعبير القرآني، ص 52–53، مبحث «مناسبة العموم والخصوص في التعبير».","url":""}]},{"id":"s21-158","number":158,"surah":21,"verses":[30],"references":[{"surah":21,"verses":[30]}],"verseLabel":"الأنبياء: 30","question":"ما سر الإخبار بالمصدر ﴿رَتْقًا﴾ بدل «مرتوقتين»؟","answer":"المصدر يصح أن يخبر به عن المفرد والمثنى والجمع، لكنه هنا يحقق أيضًا المبالغة؛ فكأن السماوات والأرض كانتا عين الرتق وشدة الالتئام، لا مجرد شيئين موصوفين به. ثم قابل هذا التماسك بالفعل ﴿فَفَتَقْنَاهُمَا﴾ الذي يصور الفصل بعد الالتحام.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 76–78، مبحث «كانتا رتقًا ففتقناهما».","url":""}]},{"id":"s21-159","number":159,"surah":21,"verses":[36],"references":[{"surah":21,"verses":[36]}],"verseLabel":"الأنبياء: 36","question":"ما سر نفي فعلهم بـ﴿إِنْ﴾ في قوله: ﴿إِنْ يَتَّخِذُونَكَ إِلَّا هُزُوًا﴾، والتعبير بالمصدر ﴿هُزُوًا﴾؟","answer":"النفي بـ«إن» يلائم هذا الموضع ويقصر شأنهم عند رؤيته على اتخاذه موضع استهزاء. وجاء ﴿هُزُوًا﴾ مصدرًا بمعنى اسم المفعول للمبالغة، فكأنهم جعلوه نفس الهزء، مع أن المفارقة أنهم يعيبون ذكر آلهتهم وهم بذكر الرحمن كافرون.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 90–94، مبحث «وإذا رآك الذين كفروا».","url":""}]},{"id":"s21-160","number":160,"surah":21,"verses":[39],"references":[{"surah":21,"verses":[39]}],"verseLabel":"الأنبياء: 39","question":"ما سر حذف جواب ﴿لَوْ﴾ في قوله تعالى: ﴿لَوْ يَعْلَمُ الَّذِينَ كَفَرُوا﴾؟","answer":"حُذف الجواب للتهويل؛ لأن العبارة المحددة لا تستوعب فظاعة ما سيعلمونه، فتُترك النفس تتخيل من الهول ما لا يبلغه التصريح. وصار ﴿حِينَ﴾ مفعولًا للعلم: لو يعلمون ذلك الوقت الذي لا يستطيعون فيه دفع النار عن وجوههم ولا ظهورهم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 97–101، مبحث «لو يعلم الذين كفروا».","url":""}]},{"id":"s21-161","number":161,"surah":21,"verses":[40],"references":[{"surah":21,"verses":[40]}],"verseLabel":"الأنبياء: 40","question":"ما الفرق بين قوله: ﴿فَلَا يَسْتَطِيعُونَ رَدَّهَا﴾ وبين أن يقال: «فلا يردونها»؟","answer":"«لا يردونها» قد تحتمل وجود القدرة مع ترك الفعل، أما ﴿فَلَا يَسْتَطِيعُونَ﴾ فتنفي أصل القدرة على الرد. وجاءت ﴿بَغْتَةً﴾ مصدرًا للمبالغة، ثم ربطت الفاء المباغتة بالبهت مباشرة، فصورت سرعة الغلبة وانقطاع المهلة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 101–102، مبحث «بل تأتيهم بغتة فتبهتهم».","url":""}]},{"id":"s21-162","number":162,"surah":21,"verses":[45],"references":[{"surah":21,"verses":[45]}],"verseLabel":"الأنبياء: 45","question":"ما أثر العدول عن وصفهم بعدم الاستجابة إلى تصويرهم بالصم؟","answer":"لم يقل إنهم لا يستجيبون للإنذار، بل جعلهم بمنزلة الصم الذين لا يسمعون الدعاء أصلًا؛ فانتقل من تقرير موقف إلى صورة محسوسة تكشف شدة إغلاقهم لوسائل الهداية. وخص السمع لأن الإنذار خطاب يُسمع، لكنهم عطّلوا أثره في نفوسهم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 111–113، مبحث «ولا يسمع الصم الدعاء».","url":""}]},{"id":"s21-163","number":163,"surah":21,"verses":[60,61],"references":[{"surah":21,"verses":[60,61]}],"verseLabel":"الأنبياء: 60، 61","question":"ما سر معاملتهم الأصنام معاملة العقلاء في قولهم: ﴿فَتًى يَذْكُرُهُمْ﴾؟","answer":"قالوا ﴿يَذْكُرُهُمْ﴾ بضمير العقلاء، لا «يذكرها»، لأن اعتقادهم الفاسد رفع الأصنام في أذهانهم إلى منزلة ذوات عاقلة. فكشف الضمير نفسه خلل تصورهم قبل أن تكشفه حجة إبراهيم، ثم جاء ﴿عَلَى أَعْيُنِ النَّاسِ﴾ لتصوير الإحضار العلني المشهود.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 149–150، مبحث «سمعنا فتى يذكرهم».","url":""}]},{"id":"s21-164","number":164,"surah":21,"verses":[68],"references":[{"surah":21,"verses":[68]}],"verseLabel":"الأنبياء: 68","question":"ما دلالة التشديد في ﴿حَرِّقُوهُ﴾، ولم اختير في الأنبياء دون التخيير المذكور في العنكبوت؟","answer":"صيغة التفعيل تدل على التكثير والمبالغة، فليست مجرد إيقاع النار بل إحراقًا شديدًا متتابعًا. وفي الأنبياء استقر رأيهم على أشد العقوبتين نصرة لآلهتهم، أما العنكبوت فحكى مرحلة اقتراح القتل أو التحريق قبل استقرارهم على التنفيذ.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 154–156، مبحث «قالوا حرقوه».","url":""}]},{"id":"s21-165","number":165,"surah":21,"verses":[73],"references":[{"surah":21,"verses":[73]}],"verseLabel":"الأنبياء: 73","question":"ما سر تكرار الفعل والضمير في ﴿وَجَعَلْنَاهُمْ أَئِمَّةً﴾ بدل عطف «أئمة» على ما قبله؟","answer":"التكرار يرفع احتمال أن يكون الأئمة جماعة أخرى غير المذكورين؛ فقد أعاد الفعل ومفعوله ليقرر أن الأنبياء أنفسهم هم الذين جعلهم أئمة. وبذلك تتحدد مرجعية الهداية فيهم، ثم قيدها بقوله ﴿بِأَمْرِنَا﴾ حتى لا تُفهم إمامتهم مستقلة عن وحي الله.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 162–165، مبحث «وجعلناهم أئمة».","url":""}]},{"id":"s21-166","number":166,"surah":21,"verses":[74,75],"references":[{"surah":21,"verses":[74,75]}],"verseLabel":"الأنبياء: 74، 75","question":"ما سر استعمال ﴿نَجَّيْنَاهُ﴾ في سورة الأنبياء، واستعمال ﴿أَنْجَيْنَاهُ﴾ في الأعراف والنمل في قصة لوط نفسها؟","answer":"يراعي الاستعمال القرآني فرقًا دقيقًا بين الصيغتين؛ فـ«نجّى» تستعمل حيث يكون في النجاة تلبث وتمهل، أما «أنجى» فتدل على سرعة التخليص من الشدة. عرض موضع الأنبياء النجاة إجمالًا فقال ﴿نَجَّيْنَاهُ﴾، بينما صورت الأعراف والنمل خطر الإخراج واقتراب العقوبة، فناسبهما ﴿أَنْجَيْنَاهُ﴾ الأسرع دلالة.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص 70–77، مبحث «فعّل وأفعل بمعنى: نجّى وأنجى».","url":""}]},{"id":"s21-167","number":167,"surah":21,"verses":[79],"references":[{"surah":21,"verses":[79]}],"verseLabel":"الأنبياء: 79","question":"ما سر تقديم الجبال على الطير، واختيار الفعل ﴿يُسَبِّحْنَ﴾ بدل اسم الفاعل؟","answer":"قُدمت الجبال لأن تسخير الجماد وتسبيحه أعجب وأدل على القدرة من تسبيح الطير وهو حيوان. واختير الفعل المضارع ﴿يُسَبِّحْنَ﴾ ليدل على تجدد التسبيح حالًا بعد حال، بخلاف «مسبحات» الذي يغلب عليه ثبوت الوصف.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 180–181، مبحث «وسخرنا مع داود الجبال يسبحن والطير».","url":""}]},{"id":"s21-168","number":168,"surah":21,"verses":[80],"references":[{"surah":21,"verses":[80]}],"verseLabel":"الأنبياء: 80","question":"ما سر طلب الشكر في الأنبياء: ﴿فَهَلْ أَنْتُمْ شَاكِرُونَ﴾، وطلب العمل الصالح في سبأ بعد ذكر الدروع؟","answer":"في الأنبياء صرّح بأن اللبوس صُنع ﴿لَكُمْ﴾ ليحصن الناس، فناسب أن يطالبهم بالشكر على النعمة. أما في سبأ فوصف الدروع بالسابغات، أي الكاملات الوافيات، فناسب الأمر بالعمل الصالح، وهو أعم من الشكر؛ فجاء كل ختام على قدر ما أبرز السياق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 181–183، مبحث «وعلمناه صنعة لبوس لكم».","url":""}]},{"id":"s21-169","number":169,"surah":21,"verses":[82],"references":[{"surah":21,"verses":[82]}],"verseLabel":"الأنبياء: 82","question":"ما سر جمع الفعل في ﴿مَنْ يَغُوصُونَ لَهُ﴾، وإفراده في قوله بسورة سبأ: ﴿مَنْ يَعْمَلُ بَيْنَ يَدَيْهِ﴾؟","answer":"حمل فعل الأنبياء على معنى «مَن» الجمعي لأن السياق ذكر طائفتين أو عملين: الغوص والعمل دونه، فناسبه الجمع. أما سبأ فذكر أصل العمل وإن تنوعت صوره، فحمل الفعل على لفظ «مَن» المفرد؛ فجاء كل عدد ملائمًا لسعة المذكور في سياقه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 188–190، مبحث «ومن الشياطين من يغوصون له».","url":""}]},{"id":"s21-170","number":170,"surah":21,"verses":[83,84],"references":[{"surah":21,"verses":[83,84]}],"verseLabel":"الأنبياء: 83، 84","question":"ما سر مجيء قصة أيوب المبتلى الصابر بعد سليمان الغني الشاكر؟","answer":"جمع الترتيب صورتَي الابتلاء: نعمة واسعة تقتضي الشكر، وضر شديد يقتضي الصبر. فسليمان نموذج الغني الشاكر، وأيوب نموذج المبتلى الصابر؛ وباجتماعهما يكتمل ميزان العبودية في السراء والضراء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 191–195، مبحث «وأيوب إذ نادى ربه».","url":""}]},{"id":"s21-171","number":171,"surah":21,"verses":[85,86],"references":[{"surah":21,"verses":[85,86]}],"verseLabel":"الأنبياء: 85، 86","question":"ما سر ذكر إسماعيل وإدريس وذي الكفل عقب قصة أيوب؟","answer":"الرابط البلاغي هو الصبر؛ فقد ختم وصف أيوب في موضع آخر بأنه صابر، ثم جمع هؤلاء بقوله ﴿كُلٌّ مِنَ الصَّابِرِينَ﴾. فالترتيب ليس جمع أسماء متفرقة، بل انتقال من نموذج مفصل للصبر إلى طائفة يشملها الوصف نفسه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 196، مبحث «كل من الصابرين».","url":""}]},{"id":"s21-172","number":172,"surah":21,"verses":[87],"references":[{"surah":21,"verses":[87]}],"verseLabel":"الأنبياء: 87","question":"ما دلالة ﴿مُغَاضِبًا﴾، وما المعنى الدقيق لقوله: ﴿لَنْ نَقْدِرَ عَلَيْهِ﴾؟","answer":"«مغاضب» من المفاعلة، أي غاضب قومه بسبب إصرارهم، وليس المعنى أنه غضب من ربه. و﴿نَقْدِرَ عَلَيْهِ﴾ تعني نضيّق عليه، لا نعجز عنه؛ فظن أن المجال متسع له في الانتقال إلى قوم آخرين، ثم أدرك أن خروجه كان قبل الإذن.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 197–198، مبحث «وذا النون إذ ذهب مغاضبًا».","url":""}]},{"id":"s21-173","number":173,"surah":21,"verses":[91],"references":[{"surah":21,"verses":[91]}],"verseLabel":"الأنبياء: 91","question":"ما سر قوله هنا: ﴿فَنَفَخْنَا فِيهَا﴾، وقوله في التحريم: ﴿فَنَفَخْنَا فِيهِ﴾؟","answer":"الضمير في الأنبياء يعود إلى مريم المذكورة بالموصول ﴿الَّتِي أَحْصَنَتْ﴾، فالمقام يبرز شخصها وابنها آية للعالمين. وفي التحريم يعود الضمير إلى الفرج المذكور صراحة، فاختار كل موضع مرجعًا يناسب بناء الجملة وغرض السياق، من غير تعارض في المعنى.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 213–216، مبحث «فنفخنا فيها من روحنا».","url":""}]},{"id":"s21-174","number":174,"surah":21,"verses":[104],"references":[{"surah":21,"verses":[104]}],"verseLabel":"الأنبياء: 104","question":"ما سر التعبير بالماضي واسم الفاعل معًا في قوله: ﴿إِنَّا كُنَّا فَاعِلِينَ﴾ عن أمر سيقع مستقبلًا؟","answer":"نُزِّل المستقبل منزلة الماضي في التحقق، فجاء ﴿كُنَّا﴾ كأن الفعل قد وقع وانقضى. ثم جيء باسم الفاعل ﴿فَاعِلِينَ﴾ لما فيه من الثبوت، وأكدت الجملة بـ«إن»؛ فتضافرت ثلاثة أساليب لتقرير أن إعادة الخلق وعد محقق لا مجال للشك فيه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 243–247، مبحث «يوم نطوي السماء».","url":""}]},{"id":"s21-175","number":175,"surah":21,"verses":[107],"references":[{"surah":21,"verses":[107]}],"verseLabel":"الأنبياء: 107","question":"ما سر جعل الرسول ﷺ نفسه ﴿رَحْمَةً لِلْعَالَمِينَ﴾، لا مجرد صاحب رحمة؟","answer":"الإخبار بالمصدر أبلغ؛ فكأنه عين الرحمة التي أُرسلت إلى العالمين، لا شخص اتصف بجزء منها. واختيار «الرحمة» دون «الرأفة» يحقق العموم؛ فالرأفة تختص غالبًا بدفع المكروه، أما الرحمة فتشمل دفع الضر وجلب الخير والهداية.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 249–251، مبحث «وما أرسلناك إلا رحمة للعالمين».","url":""}]},{"id":"s21-176","number":176,"surah":21,"verses":[108],"references":[{"surah":21,"verses":[108]}],"verseLabel":"الأنبياء: 108","question":"ما سر اجتماع أداتي الحصر في قوله: ﴿إِنَّمَا يُوحَى إِلَيَّ أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾؟","answer":"الأولى تقصر الوحي في هذا المقام على المقصد الأصلي للرسالة، والثانية تقصر الألوهية على إله واحد؛ فاجتمع قصر الحكم على الشيء وقصر الشيء على الحكم. ويحتمل أن تكون «ما» الأولى موصولة: إن الذي يوحى إلي هو وحدانية إلهكم، وفي الاحتمالين توكيد لمركزية التوحيد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 251–256، مبحث «قل إنما يوحى إلي أنما إلهكم إله واحد».","url":""}]},{"id":"s21-177","number":177,"surah":21,"verses":[112],"references":[{"surah":21,"verses":[112]}],"verseLabel":"الأنبياء: 112","question":"كيف ردَّت خاتمة سورة الأنبياء على مطلعها، حتى بدا آخرها كأنه تمام المشهد الأول؟","answer":"افتتحت السورة باقتراب الحساب وبغفلة المعرضين، ثم عادت في أواخرها إلى اقتراب الوعد واعترافهم: ﴿قَدْ كُنَّا فِي غَفْلَةٍ﴾، وختمت بطلب الحكم الحق. فتحول الإنذار الأول إلى مشهد واقع في الخاتمة، واتصل أول السورة بآخرها اتصال السبب بالنتيجة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، الجزء الرابع، ص 262–266، مبحث «قال رب احكم بالحق».","url":""}]},{"id":"s22-137","number":137,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما دلالة زيادة ﴿مِنْ﴾ في قوله: ﴿مِنْ بَعْدِ عِلْمٍ﴾، وحذفها في نظيرتها من سورة النحل: ﴿بَعْدَ عِلْمٍ﴾؟","answer":"تفيد ﴿مِنْ﴾ ابتداء الغاية، فتُصوّر بدء التحول من العلم إلى عدمه واتصاله به من غير فاصل معتبر. وجاء هذا التفصيل في سورة الحج موافقًا لتفصيل أطوار الخلق قبل العبارة، بينما جاء التعبير في النحل على الإجمال، فناسبه حذف ﴿مِنْ﴾.","sources":[{"label":"فاضل السامرائي، لمسات بيانية، ج1، ص840، مبحث «﴿من بعد علم﴾ و﴿بعد علم﴾».","url":""}]},{"id":"s22-138","number":138,"surah":22,"verses":[5],"references":[{"surah":22,"verses":[5]}],"verseLabel":"الحج: 5","question":"ما سر إفراد ﴿طِفْلًا﴾ مع أن الخطاب لجماعة في قوله: ﴿ثُمَّ نُخْرِجُكُمْ طِفْلًا﴾؟","answer":"بُني الكلام على خلق جنس الإنسان لا على تعداد أفراده؛ فجاءت مراحل الخلق مفردة: نطفة، ثم علقة، ثم مضغة، فناسبها ﴿طِفْلًا﴾ الدالة على الجنس. أما حيث يكون الحكم متعلقًا بالأفراد وأحوال كل واحد منهم، فيأتي الجمع مثل ﴿وَإِذَا بَلَغَ الْأَطْفَالُ مِنْكُمُ الْحُلُمَ﴾.","sources":[{"label":"فاضل السامرائي، «ما سر مجيء كلمة طفل مفردة؟»، عنوان فرعي: «خلق الجنس لا خلق الأفراد».","url":""}]},{"id":"s22-139","number":139,"surah":22,"verses":[17],"references":[{"surah":22,"verses":[17]}],"verseLabel":"الحج: 17","question":"ما سر اختيار ﴿يَفْصِلُ بَيْنَهُمْ﴾ بدل التعبير بالحكم بينهم؟","answer":"الفصل أبلغ هنا من مجرد الحكم؛ لأن المذكورين طوائف متباينة المصائر، والفصل يقتضي تمييز بعضها من بعض وإبعاد فريق عن فريق. أما الحكم فقد يقع بين أفراد ملة واحدة مع بقائهم في جهة واحدة؛ فاختير ﴿يفصل﴾ لمشهد القيامة الذي تنتهي فيه الطوائف إلى مصائر متباعدة.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين الحكم والفصل في القرآن الكريم؟»، عنوان فرعي: «﴿إن الله يفصل بينهم يوم القيامة﴾».","url":""}]},{"id":"s22-140","number":140,"surah":22,"verses":[19,20],"references":[{"surah":22,"verses":[19,20]}],"verseLabel":"الحج: 19، 20","question":"ما دلالة دخول ﴿مِنْ﴾ في قوله: ﴿يُصَبُّ مِنْ فَوْقِ رُءُوسِهِمُ الْحَمِيمُ﴾؟","answer":"﴿مِنْ﴾ تفيد ابتداء الغاية، فجعلت ابتداء الصب من النقطة الملاصقة لفوق رؤوسهم، وكأن الحميم يباشرهم بلا فاصل. أما لفظ ﴿فوق﴾ وحده فيحتمل القرب والبعد؛ ولذلك زادت ﴿مِنْ﴾ صورة العذاب شدة ومباشرة، ووافقت ما بعده من صهر البطون والجلود.","sources":[{"label":"فاضل السامرائي، «الفرق بين ﴿يصب من فوق رؤوسهم﴾ و﴿صبوا فوق رأسه﴾»، عنوان فرعي: «من لابتداء الغاية وزيادة العذاب».","url":""}]},{"id":"s22-141","number":141,"surah":22,"verses":[24],"references":[{"surah":22,"verses":[24]}],"verseLabel":"الحج: 24","question":"ما سر بناء الفعل للمجهول في ﴿وَهُدُوا إِلَى الطَّيِّبِ مِنَ الْقَوْلِ﴾، بدل ﴿اهتدوا﴾ أو التصريح بالفاعل؟","answer":"السياق في دخول الجنة؛ فهم يُدخلون ويُحلَّون ثم يُرشَدون إلى مواطن يسمعون فيها القول الطيب وإلى طريق الجنة. لذلك عبّر بـ﴿هُدُوا﴾ ليدل على أن الهداية واقعة عليهم من خارجهم، تتولاها الملائكة بأمر الله، لا على مجرد اهتداء نشأ من أنفسهم كما يفيده ﴿اهتدوا﴾.","sources":[{"label":"فاضل السامرائي، «لِمَ قال ﴿هُدوا﴾ ولم يقل اهتدوا أو هداهم الله؟»، عنوان فرعي: «الهداية إلى منازل الجنة».","url":""}]},{"id":"s22-142","number":142,"surah":22,"verses":[27],"references":[{"surah":22,"verses":[27]}],"verseLabel":"الحج: 27","question":"ما دلالة قوله لإبراهيم: ﴿يَأْتُوكَ﴾، لا التعبير بالإتيان إلى البيت؟","answer":"الخطاب موجَّه إلى إبراهيم عليه السلام: ﴿وَأَذِّنْ فِي النَّاسِ بِالْحَجِّ يَأْتُوكَ﴾، فناسب ضمير الخطاب لحظة التكليف الأولى. والتعبير يربط استجابة الحجيج عبر الأجيال بنداء إبراهيم نفسه، فيجعل وفودهم كأنه جواب متجدد لذلك النداء القديم.","sources":[{"label":"فاضل السامرائي، «﴿يأتوك رجالًا وعلى كل ضامر﴾»، عنوان فرعي: «الخطاب لإبراهيم: يأتوك لا يأتوه».","url":""}]},{"id":"s22-143","number":143,"surah":22,"verses":[27],"references":[{"surah":22,"verses":[27]}],"verseLabel":"الحج: 27","question":"ما سر الاقتصار على المشاة والضوامر في قوله: ﴿يَأْتُوكَ رِجَالًا وَعَلَى كُلِّ ضَامِرٍ﴾؟","answer":"الآية تحكي وسائل المجيء المعهودة زمن خطاب إبراهيم عليه السلام، فكان الناس يأتون مشاة أو ركبانًا على الإبل. وليست الآية تعدادًا استباقيًا لكل وسيلة ستظهر، بل تصوير لاستجابة المخاطَبين الأولين بما عرفوه؛ ولذلك جاء التعبير صادقًا على مقامه من غير تكلّف لإقحام وسائل الأزمنة اللاحقة.","sources":[{"label":"فاضل السامرائي، «لماذا لم تُذكر وسائل النقل الأخرى؟»، عنوان فرعي: «مراعاة زمن خطاب إبراهيم».","url":""}]},{"id":"s22-144","number":144,"surah":22,"verses":[27],"references":[{"surah":22,"verses":[27]}],"verseLabel":"الحج: 27","question":"ما سر وصف الراحلة بـ﴿ضَامِرٍ﴾ في مشهد الوفود إلى الحج؟","answer":"الضامر هو الذي هزل من طول السفر ومشقته، فاختارت الآية الصفة التي تحمل أثر الطريق على جسد الراحلة. ولم تقل مجرد بعير أو راحلة؛ لأن المقام يريد أن يُري القارئ بُعد الشقة وقوة الشوق اللذين أنهكا المركوب حتى بلغ البيت.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص130، مبحث «ضامر وفج عميق».","url":""}]},{"id":"s22-145","number":145,"surah":22,"verses":[46],"references":[{"surah":22,"verses":[46]}],"verseLabel":"الحج: 46","question":"ما سر تقييد القلوب بقوله: ﴿الْقُلُوبُ الَّتِي فِي الصُّدُورِ﴾ مع أن موضع القلب معلوم؟","answer":"ليس المقصود مجرد المعرفة الذهنية؛ فالإنسان قد يفهم الحجة ثم لا يتحرك بموجبها. القلب هنا مناط اليقظة والدافع إلى العمل بما عُقل، ولذلك نُصّ على القلوب التي في الصدور لإبراز أن العمى الحقيقي أصاب مركز الاستجابة الداخلية، لا أبصار الوجوه التي ترى الآثار ولا تعتبر.","sources":[{"label":"فاضل السامرائي، «﴿ولكن تعمى القلوب التي في الصدور﴾: بين القلب والعقل»، عنوان فرعي: «العقل يدرك والقلب يدفع إلى العمل».","url":""}]},{"id":"s22-146","number":146,"surah":22,"verses":[46],"references":[{"surah":22,"verses":[46]}],"verseLabel":"الحج: 46","question":"ما سر مجيء ﴿أَفَلَمْ يَسِيرُوا﴾ بالفاء، في حين يأتي في مواضع أخرى ﴿أَوَلَمْ يَسِيرُوا﴾ بالواو؟","answer":"الفاء تدل هنا على أن ما قبلها يفضي إلى ما بعدها؛ فقد ذُكرت القرى الهالكة والبئر المعطلة والقصر المشيد، فكان ذلك سببًا مباشرًا يدعوهم إلى السير والاعتبار، فقيل ﴿أفلم﴾. أما الواو فتجيء حين يكون ما قبلها خبرًا مجموعًا إلى ما بعده من غير هذه السببية المباشرة.","sources":[{"label":"فاضل السامرائي، «لمسات بيانية 182: الفرق بين أولم يسيروا وأفلم يسيروا»، عنوان فرعي: «الفاء للسببية ومناسبة ما قبلها لما بعدها».","url":""}]},{"id":"s22-147","number":147,"surah":22,"verses":[72],"references":[{"surah":22,"verses":[72]}],"verseLabel":"الحج: 72","question":"ما سر اختيار الهمزة في ﴿قُلْ أَفَأُنَبِّئُكُمْ بِشَرٍّ مِنْ ذَلِكُمُ﴾، واختيار ﴿هَلْ﴾ في نظيرتها من سورة المائدة؟","answer":"﴿هل﴾ أقوى في الاستفهام وأشد توكيدًا من الهمزة، بدليل اختصاصها بمصاحبة ﴿مِنْ﴾ الاستغراقية في نحو ﴿هل من خالق﴾. وسياق المائدة أشد؛ فقد وصف اتخاذ الدين والصلاة هزوًا ولعبًا، والفسق، واللعن والمسخ وعبادة الطاغوت، فناسبه الاستفهام الأقوى. أما سياق الحج فذكر أنهم يكادون يسطون ولم يقع منهم الفعل، فناسبته الهمزة.","sources":[{"label":"فاضل السامرائي، «الفرق بين ﴿هل أنبئكم بشر من ذلك﴾ و﴿أفأنبئكم بشر من ذلكم﴾»، عنوان فرعي: «هل أقوى من الهمزة ومناسبة كل منهما لسياقها».","url":""}]},{"id":"s22-148","number":148,"surah":22,"verses":[73],"references":[{"surah":22,"verses":[73]}],"verseLabel":"الحج: 73","question":"ما دلالة اختيار ﴿لَا يَسْتَنْقِذُوهُ مِنْهُ﴾ بدل قول أقصر مثل: لا يأخذوه منه؟","answer":"الاستنقاذ ليس مجرد الأخذ، بل تخليص الشيء ممن استولى عليه بقوة؛ وصيغة الاستفعال توحي بمحاولة وبذل جهد. فجاءت الكلمة لتبلغ غاية التهكم بعجز المعبودات: لا تخلق ذبابًا ولو اجتمعت، بل إذا سلبها الذباب شيئًا حاولت استرداده فلم تستطع؛ فصار الضعف واقعًا في الخلق والدفع والاسترجاع جميعًا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص66، مبحث «دلالة يستنقذوه في سورة الحج».","url":""}]},{"id":"s22-149","number":149,"surah":22,"verses":[77,78],"references":[{"surah":22,"verses":[77,78]}],"verseLabel":"الحج: 77، 78","question":"ما سر أن تختم سورة الحج بقوله: ﴿لَعَلَّكُمْ تُفْلِحُونَ﴾ وبالصلاة والزكاة، ثم تفتتح السورة التالية بـ﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ﴾؟","answer":"ختمت سورة الحج بأسباب الفلاح: الركوع والسجود والعبادة وفعل الخير، ثم أكدت إقامة الصلاة وإيتاء الزكاة. وجاء مطلع المؤمنون جوابًا محققًا لذلك الرجاء: ﴿قَدْ أَفْلَحَ الْمُؤْمِنُونَ﴾، ثم أعاد الصلاة والزكاة ضمن صفاتهم؛ فكأن خاتمة الحج تضع طريق الفلاح، ومطلع المؤمنون يعلن تحقق الفلاح لمن سلكه.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص2، مبحث «التناسب بين خاتمة سورة الحج ومفتتح سورة المؤمنون».","url":""}]},{"id":"s23-181","number":181,"surah":23,"verses":[1,117],"references":[{"surah":23,"verses":[1,117]}],"verseLabel":"المؤمنون: 1، 117","question":"ما سر إحاطة السورة بالفلاح: ﴿قد أفلح المؤمنون﴾ في مطلعها و﴿إنه لا يفلح الكافرون﴾ قرب ختامها؟","answer":"المطلع يثبت الفلاح للمؤمنين ويعقبه بصفاتهم العملية، والخاتمة تنفيه عن الكافرين بعد عرض دلائل التوحيد ومصائر المكذبين. فالسورة مبنية على مفاصلة واضحة بين طريقين ونتيجتين، وجاء وسطها مؤكدًا للمعنى نفسه: ﴿فأولئك هم المفلحون﴾. وهكذا يجمع التناسب بين البداية والوسط والنهاية محور السورة كله.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص5، مبحث: التناسب بين مفتتح سورة المؤمنون وخاتمتها، وسورة المؤمنون – فقرة: المناسبة بين بداية السورة ونهايتها. .","url":""}]},{"id":"s23-182","number":182,"surah":23,"verses":[2],"references":[{"surah":23,"verses":[2]}],"verseLabel":"المؤمنون: 2","question":"ما سر اختيار ﴿خاشعون﴾ في سورة المؤمنون، في حين جاء ﴿دائمون﴾ في سورة المعارج؟","answer":"الخشوع أوسع وأعلى من مجرد الدوام؛ فهو روح الصلاة، ويجمع عمل القلب والجوارح من التدبر والخضوع والسكون وغض البصر وترك الالتفات. والخاشع مستغرق في صلاته ملازم لها حتى يتمها، فدخل الدوام في الخشوع وزاد عليه. ولأن صفات المؤمنين هنا أعلى، اختير لهم الوصف الأكمل.","sources":[{"label":"فاضل السامرائي، «مقارنة بين صفات المؤمنين في سورتي المؤمنون والمعارج»، فقرة: خاشعون ودائمون.","url":""}]},{"id":"s23-183","number":183,"surah":23,"verses":[2,9],"references":[{"surah":23,"verses":[2,9]}],"verseLabel":"المؤمنون: 2، 9","question":"ما سر وصف المؤمنين بصيغ الأسماء: ﴿خاشعون﴾ و﴿معرضون﴾ و﴿فاعلون﴾ و﴿حافظون﴾ و﴿راعون﴾، بدل التعبير عنهم بالأفعال؟","answer":"صيغ أسماء الفاعلين تجعل هذه الخصال صفات راسخة ملازمة للمؤمنين، لا أفعالًا عارضة تقع مرة وتنقطع أخرى. فالجملة الاسمية أقوى في إفادة الثبوت والدوام من نحو: يخشعون أو يعرضون أو يحفظون. وبذلك يرسم المطلع شخصية المؤمن المستقرة على الطاعة، لا صاحب المواقف المؤقتة.","sources":[{"label":"فاضل السامرائي، سورة المؤمنون – بوابة إسلاميات، فقرة: دلالة صيغة اسم الفاعل في صفات المؤمنين.","url":""}]},{"id":"s23-184","number":184,"surah":23,"verses":[3],"references":[{"surah":23,"verses":[3]}],"verseLabel":"المؤمنون: 3","question":"ما سر التعبير بـ﴿عن اللغو معرضون﴾ بدل الاكتفاء بقول يفيد أنهم لا يلغون؟","answer":"عدم فعل اللغو لا يمنع صاحبه من الميل إليه أو حضور مجالسه والاستمتاع بسماعه، أما الإعراض فيصور تباعدًا كاملًا عنه: فعلًا وسماعًا وحضورًا وتسببًا. وجاءت العبارة اسمية لتفيد الثبات، وقُدِّم ﴿عن اللغو﴾ لإبراز شدة تنزههم عنه؛ فهم في ناحية واللغو في ناحية أخرى.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص10، مبحث: بلاغة «عن اللغو معرضون».","url":""}]},{"id":"s23-185","number":185,"surah":23,"verses":[9],"references":[{"surah":23,"verses":[9]}],"verseLabel":"المؤمنون: 9","question":"ما دلالة جمع ﴿صلواتهم﴾ في سورة المؤمنون، وإفراد ﴿صلاتهم﴾ في سورة المعارج؟","answer":"الجمع أعم وأشمل؛ إذ يتناول الصلوات المتعددة من فرائض ونوافل، فتكون المحافظة عليها أعلى وأوسع من المحافظة على الصلاة بصيغة الإفراد. وهذا يلائم علو الصفات المذكورة في سورة المؤمنون وكمالها، ولذلك جاء جزاؤهم أعلى كذلك: وراثة الفردوس والخلود فيه.","sources":[{"label":"فاضل السامرائي، «مقارنة بين صفات المؤمنين في سورتي المؤمنون والمعارج»، فقرة: صلواتهم وصلاتهم.","url":""}]},{"id":"s23-186","number":186,"surah":23,"verses":[10,11],"references":[{"surah":23,"verses":[10,11]}],"verseLabel":"المؤمنون: 10، 11","question":"ما سر الوعد بالفردوس والخلود في سورة المؤمنون، والاكتفاء بـ﴿جنات مكرمون﴾ في سورة المعارج؟","answer":"صفات المؤمنين هنا أكمل وأعلى: إيمان عام، وخشوع، وإعراض عن اللغو، وزكاة شاملة، ومحافظة على الصلوات بصيغة الجمع. فلما علت الصفات علا الجزاء، فخصهم بالفردوس وصرح بخلودهم فيه. أما سياق المعارج فذكر صفات دون هذه في العموم والكمال، فجاء الجزاء مناسبًا لها.","sources":[{"label":"فاضل السامرائي، «مقارنة بين صفات المؤمنين في سورتي المؤمنون والمعارج»، فقرة: الفردوس وجنات مكرمون.","url":""}]},{"id":"s23-187","number":187,"surah":23,"verses":[21],"references":[{"surah":23,"verses":[21]}],"verseLabel":"المؤمنون: 21","question":"ما سر عود الضمير مؤنثًا مجموعًا في ﴿مما في بطونها﴾، وعوده مذكرًا مفردًا في نظيرتها من سورة النحل: ﴿مما في بطونه﴾؟","answer":"سياق المؤمنون يعدد منافع الأنعام على سعتها: السقي والمنافع الكثيرة والأكل والحمل، فيشمل أنواعًا وأعدادًا أكثر، ذكورًا وإناثًا، فناسب ضمير الجمع المؤنث العائد إلى الأنعام. أما آية النحل فالمقام فيها على اللبن، وهو مما يختص بالإناث وفي أوقات مخصوصة، فكان مدلولها أضيق فناسبه الإفراد.","sources":[{"label":"فاضل السامرائي، مقطع باحث المباشر: «الفرق بين نسقيكم مما في بطونها ونسقيكم مما في بطونه».","url":""}]},{"id":"s23-188","number":188,"surah":23,"verses":[31,44],"references":[{"surah":23,"verses":[31,44]}],"verseLabel":"المؤمنون: 31، 44","question":"ما دلالة التناسب بين ﴿قرنًا﴾ و﴿رسولًا﴾، ثم بين ﴿قرونًا﴾ و﴿رسلنا﴾؟","answer":"حين ذكر قرنًا واحدًا قال: ﴿فأرسلنا فيهم رسولًا﴾، فطابق الواحدُ الواحدَ. ثم لما اتسع الحديث إلى ﴿قرونًا آخرين﴾ قال: ﴿ثم أرسلنا رسلنا تترى﴾، فطابق الجمعُ الجمعَ. وهذا التناسق العددي يصور تعاقب الأمم وتعاقب رسلها، وتؤكده ﴿تترى﴾ بمعنى متتابعين بعضهم إثر بعض.","sources":[{"label":"فاضل السامرائي، «قرنًا آخرين وقرونًا آخرين»، فقرة: مطابقة القرن للرسول والقرون للرسل.","url":""}]},{"id":"s23-189","number":189,"surah":23,"verses":[37],"references":[{"surah":23,"verses":[37]}],"verseLabel":"المؤمنون: 37","question":"ما سر تفصيل مقالة المنكرين هنا بقولهم ﴿نموت ونحيا﴾، وحذف هذا التفصيل في نظيرتها من سورة الأنعام؟","answer":"هذا من مراعاة مقامي الإيجاز والتفصيل. ففي سورة المؤمنون نقل السياق محاجة القوم ومقولاتهم مفصلة، فبسط إنكارهم للحياة الآخرة بقوله ﴿نموت ونحيا﴾. أما في الأنعام فجاء القول منقولًا بإيجاز في سياق الحديث عن موقفهم من البعث، فاقتصر على ﴿إن هي إلا حياتنا الدنيا وما نحن بمبعوثين﴾.","sources":[{"label":"فاضل السامرائي، «إن هي إلا حياتنا الدنيا نموت ونحيا»، الآية 37 من سورة المؤمنون.","url":""}]},{"id":"s23-190","number":190,"surah":23,"verses":[52],"references":[{"surah":23,"verses":[52]}],"verseLabel":"المؤمنون: 52","question":"ما سر مجيء ﴿فاتقون﴾ في سورة المؤمنون، في مقابل ﴿فاعبدون﴾ في سورة الأنبياء؟","answer":"سورة الأنبياء أبرزت عبودية الأنبياء وإخلاصهم، وتكرر فيها ذكر العبادة، فناسبها ﴿فاعبدون﴾. أما سورة المؤمنون فجاء الأمر بالتقوى بعد الأمر بالعبادة والعمل الصالح، ثم أعقبه التحذير من التفرق: ﴿فتقطعوا أمرهم بينهم زبرًا﴾. فكانت التقوى أنسب بسياق حفظ وحدة الدين واجتناب أسباب التفرق.","sources":[{"label":"فاضل السامرائي، «وأنا ربكم فاعبدون – وأنا ربكم فاتقون».","url":""}]},{"id":"s23-191","number":191,"surah":23,"verses":[60],"references":[{"surah":23,"verses":[60]}],"verseLabel":"المؤمنون: 60","question":"ما دقة اختيار ﴿وجلة﴾ لوصف قلوب المؤمنين وهم يقدمون الطاعات؟","answer":"الوجل ليس مجرد خوف عام، بل اضطراب باطني يختص بالقلب ويبلغ أثره الجسد كالقشعريرة. ولذلك لم يسند الوجل في الاستعمال القرآني إلى جارحة أخرى، وإنما إلى القلب أو إلى الشخص من جهة قلبه. فالصورة تجمع العمل الصالح مع قلب شديد المراقبة، يخشى الرجوع إلى الله وألا يقبل منه.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين الخشية والخوف والوجل؟»، فقرة: ﴿وقلوبهم وجلة﴾.","url":""}]},{"id":"s23-192","number":192,"surah":23,"verses":[84,89],"references":[{"surah":23,"verses":[84,89]}],"verseLabel":"المؤمنون: 84، 89","question":"ما سر الجواب بـ﴿لله﴾ في محاجة سورة المؤمنون، وبـ﴿الله﴾ في نظيرتها من سورة الرعد؟","answer":"سياق المؤمنون قائم على الملكية: ﴿لمن الأرض ومن فيها﴾ و﴿من بيده ملكوت كل شيء﴾، فجاء الجواب بلام الملك: ﴿لله﴾. أما آية الرعد فالمقام فيها تعريف الذات الإلهية وتقرير التوحيد: ﴿قل من رب السماوات والأرض﴾، فجاء الجواب بالاسم مباشرة: ﴿قل الله﴾. فكل جواب صيغ على مقتضى السؤال وسياقه.","sources":[{"label":"فاضل السامرائي، مقطع باحث المباشر: «قل لمن الأرض ومن فيها… لماذا لله وليس الله؟».","url":""}]},{"id":"s23-193","number":193,"surah":23,"verses":[99],"references":[{"surah":23,"verses":[99]}],"verseLabel":"المؤمنون: 99","question":"ما دلالة التعبير بـ﴿جاء أحدهم الموت﴾، لا بما يفيد مجرد حضور الموت؟","answer":"المجيء يتضمن القرب الشديد وتحقق الوقوع، ويستعمل حين يكون الكلام على الموت نفسه وأحوال الإنسان عند مفارقة الروح. أما الحضور فيرد غالبًا في مقام الوصايا والأحكام، حيث يكون الموت قريبًا شاهدًا ولم تنفذ المفارقة بعد. وهنا طلب الرجوع دليل على أن الإنسان خرج من الدنيا، فناسب ﴿جاء﴾.","sources":[{"label":"فاضل السامرائي، تفسير الآية 99 من سورة المؤمنون، فقرة: الفرق بين «جاء الموت» و«حضر الموت».","url":""}]},{"id":"s23-194","number":194,"surah":23,"verses":[100],"references":[{"surah":23,"verses":[100]}],"verseLabel":"المؤمنون: 100","question":"ما سر تسمية قوله الطويل ﴿رب ارجعون لعلي أعمل صالحًا فيما تركت﴾ بـ﴿كلمة﴾؟","answer":"أطلقت الكلمة وأريد بها الكلام كله، وهو مجاز مرسل يطلق فيه الجزء ويراد به الكل. وفي هذا الاختزال تهوين لأمنيته المتأخرة: فما قاله، على طوله وحرارته، لا يتجاوز لفظًا يردده ولا يغير المصير. فجاءت ﴿كلمة﴾ لتسقط عنه قيمة الفعل والجدوى بعد انقضاء زمن العمل.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين الكلم والكلام؟»، فقرة: ﴿إنها كلمة هو قائلها﴾.","url":""}]},{"id":"s24-171","number":171,"surah":24,"verses":[7,9],"references":[{"surah":24,"verses":[7,9]}],"verseLabel":"النور: 7، 9","question":"ما سر اختيار اللعنة في يمين الزوج، واختيار الغضب في يمين الزوجة؟","answer":"اللعنة هي الطرد والإبعاد من رحمة الله، وهي ملائمة للزوج إن كان كاذبًا؛ لأنه بقذفه الكاذب يعرّض زوجته للعقوبة والفضيحة. أما الزوجة، فإن كانت كاذبة، فقد قارفت الفاحشة ثم دفعت الحد عن نفسها بالأيمان؛ فناسب حالها الغضب. فاختلاف اللفظين تابع لاختلاف الجناية المترتبة على كذب كل واحد منهما.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين اللعنة والغضب؟» – برنامج لمسات بيانية، سورة النور، الآيتان 7 و9.","url":""}]},{"id":"s24-172","number":172,"surah":24,"verses":[52],"references":[{"surah":24,"verses":[52]}],"verseLabel":"النور: 52","question":"ما السر الصوتي واللغوي في قراءة حفص: ﴿وَيَتَّقْهِ﴾ بسكون القاف؟","answer":"القياس المشهور بعد حذف حرف العلة أن تُحرّك القاف بالكسر: «ويتّقِه»، لكن تسكين القاف لغة لبعض العرب في المعتل المحذوف الآخر، فيعاملونه معاملة المجزوم الصحيح. وقد جاءت قراءة حفص على هذه اللغة، وفي السكون تخفيف للنطق. والهاء مفعول به، أي: يتقي الله.","sources":[{"label":"فاضل السامرائي، «ما اللمسة البيانية في كلمة ويتقه بتسكين القاف؟» – سورة النور، الآية 52.","url":""}]},{"id":"s24-173","number":173,"surah":24,"verses":[58,59],"references":[{"surah":24,"verses":[58,59]}],"verseLabel":"النور: 58، 59","question":"ما سر التعريف في ﴿يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ﴾، ثم الإضافة في ﴿يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ﴾؟","answer":"الآية الأولى تعالج استئذان من لم يبلغوا الحلم في أوقات مخصوصة ذات علامات ظاهرة، فجاء ﴿الْآيَاتِ﴾. أما الثانية فتنقل من بلغ الحلم إلى حكم البالغين العام في الاستئذان، وهو حكم إلهي لازم كاستئذان الذين من قبلهم، فجاءت الإضافة المشرفة والمؤكدة للنسبة: ﴿آيَاتِهِ﴾. فاختلاف الخاتمتين يتبع انتقال المخاطَب من طور الصغر إلى التكليف الكامل.","sources":[{"label":"فاضل السامرائي، «اللمسة البيانية في الآيات وآياته» – سورة النور، الآيتان 58 و59.","url":""}]},{"id":"s24-174","number":174,"surah":24,"verses":[64],"references":[{"surah":24,"verses":[64]}],"verseLabel":"النور: 64","question":"هل تفيد ﴿قَدْ﴾ التقليل في قوله: ﴿قَدْ يَعْلَمُ مَا أَنْتُمْ عَلَيْهِ﴾؟ وما سر دخولها على علم الله؟","answer":"«قد» مع المضارع لا تنحصر في التقليل؛ فمن معانيها التحقيق والتكثير أيضًا، ويعين السياق المراد. وعلم الله متحقق محيط، فلا يمكن حملها هنا على قلة العلم أو تردده؛ بل تفيد تحقيقه وتقريره في مقام التحذير والمحاسبة. ثم يؤكد ختام السورة هذا الإحاطة بقوله: ﴿وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ﴾.","sources":[{"label":"فاضل السامرائي، «لماذا جاء العلم بعد قد؟» – سورة النور، الآية 64.","url":""}]},{"id":"s25-169","number":169,"surah":25,"verses":[13],"references":[{"surah":25,"verses":[13]}],"verseLabel":"الفرقان: 13","question":"ما أثر وصف مكان النار بأنه ﴿مَكَانًا ضَيِّقًا﴾، لا «ضائقًا»؟","answer":"«ضيّق» صفة مشبهة تدل على الثبوت والدوام، فكأن الضيق طبيعة مستقرة في المكان لا حالة عارضة تمر به. أما «ضائق» فاسم فاعل يغلب عليه معنى حدوث الصفة وتجددها. وجمع الضيق الثابت مع قوله ﴿مُقَرَّنِينَ﴾ يضاعف صورة الحبس والاختناق حتى يدعوا هنالك ثبورًا.","sources":[{"label":"فاضل السامرائي، «اللمسة البيانية في ضائق وضيق وضيّق» – سورة الفرقان، الآية 13.","url":""}]},{"id":"s25-170","number":170,"surah":25,"verses":[32],"references":[{"surah":25,"verses":[32]}],"verseLabel":"الفرقان: 32","question":"كيف اجتمع ﴿نُزِّلَ﴾ مع قولهم: ﴿جُمْلَةً وَاحِدَةً﴾ مع أن «نزّل» تُربط غالبًا بالتدريج؟","answer":"التفريق بين «نزّل» للتدرج و«أنزل» للنزول جملة ليس قاعدة مطردة في كل موضع. فالآية نفسها حكت طلبهم النزول جملة بلفظ ﴿نُزِّلَ﴾، مما يدل على أن السياق قد يجعل إحدى الصيغتين تقوم مقام الأخرى. ويظهر الفرق بوضوح أكبر حين تجتمع الصيغتان في سياق واحد وتقوم قرينة على التمييز.","sources":[{"label":"فاضل السامرائي، «نُزِّل تعني التفريق؛ فكيف تناسب جملة واحدة؟» – سورة الفرقان، الآية 32.","url":""}]},{"id":"s25-171","number":171,"surah":25,"verses":[45],"references":[{"surah":25,"verses":[45]}],"verseLabel":"الفرقان: 45","question":"ما دلالة التركيب العجيب: ﴿أَلَمْ تَرَ إِلَى رَبِّكَ كَيْفَ مَدَّ الظِّلَّ﴾؟","answer":"«ألم تر إلى» و«ألم تر كيف» لا يراد بهما هنا مجرد الرؤية البصرية، بل التعجيب والتنبيه إلى علم يبلغ من الوضوح منزلة المشاهدة. فالمعنى: ألم ينته علمك إلى هذا الصنع البديع، وتأملت كيف مدّ ربك الظل؟ واجتماع التركيبين يضاعف استدعاء النظر العقلي في الظاهرة ودلالتها على القدرة.","sources":[{"label":"فاضل السامرائي، «ما دلالة تركيبة ألم تر؟» – سورة الفرقان، الآية 45.","url":""}]},{"id":"s25-172","number":172,"surah":25,"verses":[61],"references":[{"surah":25,"verses":[61]}],"verseLabel":"الفرقان: 61","question":"ما سر تكرار ﴿تَبَارَكَ الَّذِي﴾ قرب ختام السورة بعد افتتاحها به؟","answer":"افتتحت السورة بتنزيل الفرقان وملك السماوات والأرض، ثم عاد التعبير إلى مشاهد من ذلك الملك: البروج والسراج والقمر المنير. ويقابل البناء أيضًا بين المكذبين في أول السورة و﴿عِبَادُ الرَّحْمَنِ﴾ في آخرها. فتكرار ﴿تَبَارَكَ﴾ يعقد صلة بنائية بين أول السورة وآخرها، وبين الوحي والكون، وبين موقفين من الرحمن.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص39، «التناسب بين أول سورة الفرقان وأواخرها».","url":""}]},{"id":"s25-173","number":173,"surah":25,"verses":[63],"references":[{"surah":25,"verses":[63]}],"verseLabel":"الفرقان: 63","question":"ما الفرق الدقيق بين ﴿هَوْنًا﴾ بفتح الهاء و«هُون» بضمها؟","answer":"الهَون بالفتح هو الوقار والتؤدة والرفق، وهو الذي يناسب مشي عباد الرحمن من غير كبر ولا طيش. أما الهُون بالضم فهو الذل والعار، كما في قوله: ﴿أَيُمْسِكُهُ عَلَى هُونٍ﴾. فمشيهم متواضع كريم، وليس مشي مذلة وانكسار.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين هونًا وهُون؟» – سورة الفرقان، الآية 63.","url":""}]},{"id":"s25-174","number":174,"surah":25,"verses":[70,71],"references":[{"surah":25,"verses":[70,71]}],"verseLabel":"الفرقان: 70، 71","question":"ما سر ختم آية تبديل السيئات بقوله: ﴿وَكَانَ اللَّهُ غَفُورًا رَحِيمًا﴾، ثم ختم الآية التالية بقوله: ﴿فَإِنَّهُ يَتُوبُ إِلَى اللَّهِ مَتَابًا﴾؟","answer":"الآية الأولى تتحدث عن فعل الله في التائبين: يبدل سيئاتهم حسنات، فناسبها وصفه بالمغفرة والرحمة؛ إذ لا يفعل هذا الفضل إلا الغفور الرحيم. أما الثانية فمحورها صفة التائب نفسه وصدق رجوعه، فجاء الختام مصورًا إقباله إلى الله توبةً عظيمة خالصة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص85–86، مبحث «اختلاف ختام آيتي التوبة في سورة الفرقان»، النسخة المصورة.","url":""}]},{"id":"s25-175","number":175,"surah":25,"verses":[74],"references":[{"surah":25,"verses":[74]}],"verseLabel":"الفرقان: 74","question":"ما دلالة ﴿مِنْ﴾ في دعائهم: ﴿هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ﴾؟","answer":"﴿مِنْ﴾ لابتداء الغاية، لا لمجرد التبعيض؛ أي: اجعل قرة أعيننا آتية من جهة أزواجنا وذرياتنا. فهؤلاء أقرب الناس إلى الإنسان، ومن جهتهم قد يأتي السرور أو الهم. والدعاء يطلب أن يكون منبع السكينة في أقرب دوائر الحياة.","sources":[{"label":"فاضل السامرائي، «ربنا هب لنا من أزواجنا وذرياتنا قرة أعين» – مقطع مباشر، سورة الفرقان، الآية 74.","url":""}]},{"id":"s26-201","number":201,"surah":26,"verses":[2,192,212],"references":[{"surah":26,"verses":[2,192,212]}],"verseLabel":"الشعراء: 2، 192، 212","question":"ما سر عودة ختام السورة إلى الحديث عن تنزيل القرآن بعد افتتاحها بـ﴿تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ﴾؟","answer":"افتتحت السورة بإثبات أن هذه آيات الكتاب المبين، ثم عاد ختامها فبيّن مصدر هذا الكتاب وواسطة نزوله ولغته: ﴿وَإِنَّهُ لَتَنْزِيلُ رَبِّ الْعَالَمِينَ ۝ نَزَلَ بِهِ الرُّوحُ الْأَمِينُ... بِلِسَانٍ عَرَبِيٍّ مُبِينٍ﴾. ثم نفى أن تكون الشياطين قد تنزلت به. فكأن الخاتمة تفصيل للخبر الذي أُجمل في المطلع، وبذلك يلتئم أول السورة وآخرها.","sources":[{"label":"فاضل السامرائي، «تناسب فواتح سورة الشعراء مع خواتيمها» – صفحة نصية مستقلة يظهر فيها نص المادة.","url":""}]},{"id":"s26-202","number":202,"surah":26,"verses":[49],"references":[{"surah":26,"verses":[49]}],"verseLabel":"الشعراء: 49","question":"ما سر زيادة اللام في وعيد فرعون: ﴿فَلَسَوْفَ تَعْلَمُونَ﴾، مع قوله في الأعراف: ﴿فَسَوْفَ تَعْلَمُونَ﴾؟","answer":"اللام الداخلة على «سوف» زادت الوعيد توكيدًا؛ لأن انقلاب السحرة إلى الإيمان كان في الشعراء أشد مساسًا بعزة فرعون وسلطانه. وسياق السورة كله أقوى محاجة وتحديًا، فجاء تهديده مشحونًا بأداة توكيد زائدة. فزيادة المبنى هنا تقابل زيادة الانفعال وشدة المقام.","sources":[{"label":"فاضل السامرائي، «قصة موسى بين سورتي الأعراف والشعراء» – مقطع مباشر على منصة باحث، مبحث فلسوف تعلمون.","url":""}]},{"id":"s26-203","number":203,"surah":26,"verses":[52],"references":[{"surah":26,"verses":[52]}],"verseLabel":"الشعراء: 52","question":"ما سر حذف ﴿لَيْلًا﴾ من ﴿أَنْ أَسْرِ بِعِبَادِي﴾ هنا، وذكرها في سورة الدخان؟","answer":"السُّرى هو السير ليلًا، لكن تنكير الظرف في «أسر بعبادي ليلًا» يحدد ليلة الأمر القريبة، أي: أسرِ بهم هذه الليلة. وسياق الدخان يصور التنفيذ العاجل: اخرج الآن واترك البحر، فهم جند مغرقون. أما الشعراء فتفصل ما وقع بعد الأمر من إرسال فرعون الحاشرين واستنفار المدن، فلم يحتج المقام إلى هذا التحديد الزمني المؤكد.","sources":[{"label":"فاضل السامرائي، «فأسر بعبادي بين سورتي الدخان والشعراء» – مقطع مباشر.","url":""}]},{"id":"s26-204","number":204,"surah":26,"verses":[56],"references":[{"surah":26,"verses":[56]}],"verseLabel":"الشعراء: 56","question":"ما دلالة الجمع في قول فرعون: ﴿وَإِنَّا لَجَمِيعٌ حَاذِرُونَ﴾، ولم لم يكتف بوصف الجماعة بأنها «حاذر»؟","answer":"أرسل فرعون جماعات متعددة في المدائن لحشد الناس، لكن الحذر المطلوب لم يكن صفة كتلة واحدة فحسب؛ بل أراد أن يكون كل فرد من مجموعهم متيقظًا. لذلك جاء الخبر جمعًا: ﴿حَاذِرُونَ﴾، فوزع الحذر على الأفراد جميعًا. وفي ذلك كشف لحجم الخوف المختبئ وراء استصغار بني إسرائيل ووصفهم بالشرذمة القليلة.","sources":[{"label":"فاضل السامرائي، «قصة موسى بين سورتي الأعراف والشعراء» – مقطع مباشر على منصة باحث، مبحث وإنا لجميع حاذرون.","url":""}]},{"id":"s26-205","number":205,"surah":26,"verses":[70],"references":[{"surah":26,"verses":[70]}],"verseLabel":"الشعراء: 70","question":"ما سر السؤال الهادئ بـ﴿مَا تَعْبُدُونَ﴾ هنا، والسؤال الأقوى بـ﴿مَاذَا تَعْبُدُونَ﴾ في الصافات؟","answer":"«ماذا» أطول مبنى وأقوى في الاستفهام من «ما». وفي الشعراء كان إبراهيم في مقام حجاج هادئ وسؤال وجواب؛ سألهم ﴿مَا تَعْبُدُونَ﴾، فأجابوا، ثم تابع مناقشتهم في السمع والنفع والضر. أما الصافات فالموقف موقف هجوم وتقريع يعقبه تحطيم الأصنام، فجاءت الصيغة الأقوى: ﴿مَاذَا تَعْبُدُونَ﴾.","sources":[{"label":"فاضل السامرائي، «ماذا تعبدون وما تعبدون في خطاب إبراهيم» – مقطع مباشر، سورة الشعراء، الآية 70.","url":""}]},{"id":"s26-206","number":206,"surah":26,"verses":[177],"references":[{"surah":26,"verses":[177]}],"verseLabel":"الشعراء: 177","question":"ما سر حذف وصف الأخوة في ﴿إِذْ قَالَ لَهُمْ شُعَيْبٌ﴾، مع قوله عن بقية الأنبياء: ﴿أَخُوهُمْ﴾؟","answer":"أُرسل شعيب إلى مدين وإلى أصحاب الأيكة؛ وهو من مدين، ولذلك قيل عند ذكرهم: ﴿أَخَاهُمْ شُعَيْبًا﴾. أما أصحاب الأيكة فلم يكن شعيب واحدًا منهم ولا من نسبهم، فلم يقل القرآن «أخوهم». فإثبات الأخوة وحذفها تابع للحقيقة التاريخية والنسبية، لا لمجرد تنويع العبارة.","sources":[{"label":"فاضل السامرائي، «لماذا لم يرد وصف أخوهم مع شعيب في سورة الشعراء؟» – مقطع مباشر.","url":""}]},{"id":"s26-207","number":207,"surah":26,"verses":[221,222],"references":[{"surah":26,"verses":[221,222]}],"verseLabel":"الشعراء: 221، 222","question":"كيف استُعمل فعل ﴿تَنَزَّلُ﴾ للشياطين كما استُعمل للملائكة والمطر؟","answer":"أصل التنزل هو المجيء من جهة العلو، ولا يختص بذات النازل ولا يدل وحده على شرفه. كانت الشياطين تسترق شيئًا من السمع في السماء ثم تنزل به إلى الكهنة، ولذلك قيل: ﴿تَنَزَّلُ عَلَى كُلِّ أَفَّاكٍ أَثِيمٍ﴾. فاشتراك اللفظ سببه جهة الحركة، أما قيمة المنزل ومضمونه فتحددها بقية العبارة.","sources":[{"label":"فاضل السامرائي، «كيف تنزل الشياطين؟» – سورة الشعراء، الآيتان 221 و222.","url":""}]},{"id":"s27-161","number":161,"surah":27,"verses":[8],"references":[{"surah":27,"verses":[8]}],"verseLabel":"النمل: 8","question":"ما دلالة ﴿فَلَمَّا جَاءَهَا﴾ في النمل، مقابل ﴿فَلَمَّا أَتَاهَا﴾ في القصص؟","answer":"المجيء يستعمل غالبًا لما هو أشق وأصعب، وأن الإتيان أخف وفيه معنى السهولة. فجاء ﴿جَاءَهَا﴾ في النمل منسجمًا مع جو القوة ومع المهمة العظيمة التي سيتلقاها موسى، بينما جاء ﴿أَتَاهَا﴾ في القصص مع جو الخوف والتيسير. واختيار الفعل جزء من شبكة الألفاظ التي تميز كل سياق.","sources":[{"label":"فاضل السامرائي، «قصة موسى بين سورتي النمل والقصص (1)» – مقطع مباشر، مبحث جاءها وأتاها.","url":""}]},{"id":"s27-162","number":162,"surah":27,"verses":[10],"references":[{"surah":27,"verses":[10]}],"verseLabel":"النمل: 10","question":"ما سر الاكتفاء بـ﴿يَا مُوسَى لَا تَخَفْ﴾ هنا، وزيادة ﴿أَقْبِلْ﴾ في سورة القصص؟","answer":"صُوِّر موسى في النمل في مقام قوة وتكريم، فلم يحتج السياق إلا إلى نفي الخوف عنه وبيان أن المرسلين لا يخافون لدى ربهم. أما قصة القصص فيغلب عليها الخوف منذ بدايتها، فجاء الأمر ﴿أَقْبِلْ﴾ لإعادته بعد إدباره، ثم طمأنه بقوله: ﴿إِنَّكَ مِنَ الْآمِنِينَ﴾. فالزيادة هناك معالجة لجو نفسي فصّلته السورة.","sources":[{"label":"فاضل السامرائي، «قصة موسى بين سورتي النمل والقصص (1)» – مقطع مباشر، مبحث لا تخف وأقبل ولا تخف.","url":""}]},{"id":"s27-163","number":163,"surah":27,"verses":[12],"references":[{"surah":27,"verses":[12]}],"verseLabel":"النمل: 12","question":"ما سر اختيار ﴿وَأَدْخِلْ يَدَكَ فِي جَيْبِكَ﴾ في النمل، واختيار ﴿اسْلُكْ يَدَكَ﴾ في القصص؟","answer":"«السلوك» يستعمل في دخول الشيء وفي سلوك الطرق، وقصة القصص مليئة بحركة موسى في الطرق من مصر إلى مدين ثم عودته، فناسبها ﴿اسْلُكْ﴾. أما قصة النمل فلم تُفصّل تلك المسالك، وتردد فيها فعل الدخول، فناسبها ﴿أَدْخِلْ﴾. كما أن السلوك أيسر، فوضع في السياق الذي يغلب عليه الخوف والتخفيف.","sources":[{"label":"فاضل السامرائي، «الفرق بين اسلك يدك وأدخل يدك في أمر الله لموسى» – مقطع مباشر.","url":""}]},{"id":"s27-164","number":164,"surah":27,"verses":[18],"references":[{"surah":27,"verses":[18]}],"verseLabel":"النمل: 18","question":"كيف جمعت نملةٌ في جملة واحدة أكثر من عشرة ألوان من البلاغة؟","answer":"جمعت قولها النداء والتنبيه والتسمية والأمر والنهي والتحذير والتخصيص والتعميم والتوكيد والمبالغة والاعتذار. فنادت بـ﴿يَا أَيُّهَا النَّمْلُ﴾ لتبلغ المنشغل والبعيد، وأمرت كل نملة بدخول مسكنها، وحذرت بالنون الثقيلة، ثم نسبت الحطم إلى عدم الشعور أدبًا مع سليمان وجنوده. فبلاغة الكلام في إحكام هذه المعاني الكثيرة داخل عبارة قصيرة طبيعية.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص88–89، مبحث «الأوجه البلاغية في قول النملة»، النسخة المصورة.","url":""}]},{"id":"s27-165","number":165,"surah":27,"verses":[22],"references":[{"surah":27,"verses":[22]}],"verseLabel":"النمل: 22","question":"ما سر ارتقاء كلام الهدهد من «الخبر» إلى ﴿بِنَبَإٍ يَقِينٍ﴾؟","answer":"النبأ في الاستعمال العربي أهم من الخبر وأعظم، ولا يقال عادة إلا لما له شأن وفائدة ظاهرة. ولم يكتف الهدهد بلفظ النبأ، بل وصفه باليقين؛ لأن ما جاء به يتصل بمملكة كاملة وقوم يسجدون للشمس، ويترتب عليه موقف دعوي وسياسي. فاختيار اللفظين معًا يبين ثقل المعلومة وقوة توثيقها.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين النبأ والخبر؟» – ومن شواهده النمل، الآية 22.","url":""}]},{"id":"s27-166","number":166,"surah":27,"verses":[58],"references":[{"surah":27,"verses":[58]}],"verseLabel":"النمل: 58","question":"ما سر التعبير بـ﴿مَطَرًا﴾ في مقام العقوبة، واستعمال «الغيث» في مقام الرحمة؟","answer":"«المطر» لا يرد في القرآن إلا في سياق الانتقام والعذاب، كما في إهلاك قوم لوط: ﴿فَسَاءَ مَطَرُ الْمُنْذَرِينَ﴾. أما «الغيث» فيرد في الخير والرحمة والإغاثة بعد القنوط. فاختيار كل اسم يحمل معه طبيعة الأثر الذي ينزل بالناس، وإن اشتركا في أصل الماء النازل من السماء.","sources":[{"label":"فاضل السامرائي، «الفرق بين المطر والغيث في الاستعمال القرآني» – سورة النمل، الآية 58.","url":""}]},{"id":"s27-167","number":167,"surah":27,"verses":[60,64],"references":[{"surah":27,"verses":[60,64]}],"verseLabel":"النمل: 60، 64","question":"ما سر تغيّر خواتيم براهين التوحيد الخمسة من ﴿قَوْمٌ يَعْدِلُونَ﴾ إلى ﴿لَا يَعْلَمُونَ﴾ و﴿مَا تَذَكَّرُونَ﴾ ثم التنزيه وطلب البرهان؟","answer":"خُتمت آية الخلق والإنبات بـ﴿يَعْدِلُونَ﴾ لأنهم يعلمون أن الله الخالق ثم ينحرفون عن الحق، وخُتمت دقائق الأرض والبحرين بنفي العلم لخفاء حكمها عن أكثرهم. وفي كشف الضر ناسب التذكّر لأنهم ينسون لجوءهم إلى الله، ثم جاء تنزيه الله بعد كشف صفاتهم، وخُتمت السلسلة بطلب البرهان بعد إلزامهم الحجج كلها.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص90–92، مبحث «اختلاف خواتيم الآيات الستين إلى الرابعة والستين من سورة النمل»، النسخة المصورة.","url":""}]},{"id":"s27-168","number":168,"surah":27,"verses":[67,68],"references":[{"surah":27,"verses":[67,68]}],"verseLabel":"النمل: 67، 68","question":"ما دلالة تقديم اسم الإشارة في ﴿لَقَدْ وُعِدْنَا هَذَا نَحْنُ وَآبَاؤُنَا﴾، وتأخيره في سورة المؤمنون: ﴿وُعِدْنَا نَحْنُ وَآبَاؤُنَا هَذَا﴾؟","answer":"في النمل كان موضع الإنكار هو الشيء الموعود نفسه، أي الإخراج والبعث بعد أن يصيروا ترابًا؛ لذلك قُدِّم ﴿هَذَا﴾ للعناية به. أما في المؤمنون فسبق الكلام عن موتهم وكونهم ترابًا وعظامًا، فجرى التركيب على نسق الفاعلين أولًا: نحن وآباؤنا، ثم أُخّر المفعول به على الأصل. فالتقديم في النمل أبرز محور إنكارهم.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج1، ص111، «الفرق بين: وعدنا هذا نحن وآباؤنا، ووعدنا نحن وآباؤنا هذا».","url":""}]},{"id":"s27-169","number":169,"surah":27,"verses":[81],"references":[{"surah":27,"verses":[81]}],"verseLabel":"النمل: 81","question":"ما دلالة إثبات الياء في ﴿وَمَا أَنْتَ بِهَادِي الْعُمْيِ﴾ في النمل، وحذفها في ﴿بِهَادِ الْعُمْيِ﴾ في الروم؟","answer":"مع التنبيه إلى أن رسم المصحف لا يقاس عليه، فالمناسبة البيانية أن لفظ الهداية أكثر دورانًا في النمل، وفيها ذُكر المهتدون ووُصف القرآن بأنه هدى ورحمة. أما سياق الروم في ذلك الموضع فليس مبنيًا على الهداية. فناسب زيادة حضور معنى الهداية في النمل إثبات الياء في مبنى الكلمة.","sources":[{"label":"فاضل السامرائي، «إثبات الياء في بهادي العمي وحذفها في بهاد العمي» – سورة النمل، الآية 81.","url":""}]},{"id":"s27-170","number":170,"surah":27,"verses":[88],"references":[{"surah":27,"verses":[88]}],"verseLabel":"النمل: 88","question":"ما دلالة تقديم الخبرة في ﴿إِنَّهُ خَبِيرٌ بِمَا تَفْعَلُونَ﴾، بدل «بما تفعلون خبير»؟","answer":"التعبير إذا كان الحديث فيه عن الله أو عن علمه أو عن الأمور القلبية تُقدَّم الخبرة: ﴿خَبِيرٌ بِمَا تَفْعَلُونَ﴾. أما إذا انصبّ الكلام على الإنسان وعمله فقد يُقدَّم العمل: «بما تعملون خبير». وهنا سبق الحديث عن صنع الله وإتقانه، فكان محور السياق هو الله وقدرته، فناسب تقديم ﴿خَبِيرٌ﴾.","sources":[{"label":"فاضل السامرائي، «الفرق بين خبير بما تعملون وبما تعملون خبير» – ومن شواهده النمل، الآية 88.","url":""}]},{"id":"s27-171","number":171,"surah":27,"verses":[88],"references":[{"surah":27,"verses":[88]}],"verseLabel":"النمل: 88","question":"ما سر وصف حركة الجبال بـ﴿صُنْعَ اللَّهِ﴾، ثم التعبير عن أفعال الناس بـ﴿بِمَا تَفْعَلُونَ﴾؟","answer":"«الفعل» أعم الألفاظ؛ فقد يصدر بقصد أو بغير قصد، ومن الإنسان وغيره. و«العمل» أخص منه لأنه يغلب فيما يقع بقصد، أما «الصنع» فأخص وأدق، وفيه معنى الإجادة والإحكام. لذلك سميت حركة الجبال المذهلة ﴿صُنْعَ اللَّهِ﴾ وأُتبعت بقوله ﴿أَتْقَنَ كُلَّ شَيْءٍ﴾، بينما عبّر عن عموم ما يصدر من المكلفين بالفعل.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين يفعلون ويعملون ويصنعون؟» – ومن شواهده النمل، الآية 88.","url":""}]},{"id":"s27-172","number":172,"surah":27,"verses":[90],"references":[{"surah":27,"verses":[90]}],"verseLabel":"النمل: 90","question":"ما دلالة اختصاص وعيد ﴿هَلْ تُجْزَوْنَ إِلَّا مَا كُنْتُمْ تَعْمَلُونَ﴾ بسياق المسيئين دون المؤمنين؟","answer":"لا يأتي هذا الأسلوب في القرآن خطابًا للمؤمنين؛ لأن الثواب الإلهي للمؤمن لا يقتصر على مقدار عمله، بل يتجاوزه بالفضل والمضاعفة. أما المسيء فيقال له إنه لا يجزى إلا ما عمل، تحقيقًا للعدل ونفيًا للزيادة في العقوبة. لذلك جاءت العبارة بعد ﴿وَمَنْ جَاءَ بِالسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِي النَّارِ﴾.","sources":[{"label":"فاضل السامرائي، «دلالة: لا تجزون إلا ما كنتم تعملون، واختصاصها بالمسيئين» – ومن شواهده النمل، الآية 90.","url":""}]},{"id":"s29-120","number":120,"surah":29,"verses":[3,11],"references":[{"surah":29,"verses":[3,11]}],"verseLabel":"العنكبوت: 3، 11","question":"ما سر التعبير بالفعل في ﴿الَّذِينَ صَدَقُوا﴾ و﴿الَّذِينَ آمَنُوا﴾، وباسم الفاعل في ﴿الْكَاذِبِينَ﴾ و﴿الْمُنَافِقِينَ﴾؟","answer":"الفعل يصوّر أمرًا متجددًا وقع منهم ويُختبر ثباته؛ فهؤلاء حديثو عهد بالإيمان والابتلاء يكشف صدقهم. أما اسم الفاعل فيوحي بالثبوت والدوام، فجاء للكذب والنفاق اللذين استقرا في أصحابهما وصارا وصفًا ملازمًا لهم.","sources":[{"label":"فاضل السامرائي، دلالة استعمال الفعل واسم الفاعل في ﴿الذين صدقوا﴾ و﴿الكاذبين﴾، عنوان الوقفة الجزئي: «دلالة استخدام صيغة اسم الفاعل في كلمة الكاذبين والمنافقين في سورة العنكبوت».","url":""}]},{"id":"s29-121","number":121,"surah":29,"verses":[8],"references":[{"surah":29,"verses":[8]}],"verseLabel":"العنكبوت: 8","question":"ما الفرق بين ﴿وَإِنْ جَاهَدَاكَ لِتُشْرِكَ بِي﴾ هنا، و﴿عَلَى أَنْ تُشْرِكَ بِي﴾ في سورة لقمان؟","answer":"اللام في ﴿لِتُشْرِكَ﴾ تبين الغرض من المجاهدة: بذلا جهدهما لكي يقع الشرك. أما ﴿عَلَى أَنْ﴾ فتفيد معنى الاشتراط والاستعلاء، فهي أشد؛ كأنهما يجعلان الشرك شرطًا لا يتنازلان عنه. لذلك اتسع خطاب لقمان مع شدة الموقف إلى الأمر بمصاحبتهما في الدنيا معروفًا.","sources":[{"label":"فاضل السامرائي، الفرق بين ﴿لتشرك بي﴾ و﴿على أن تشرك بي﴾، نقلاً عن موقع تدارس القرآن الكريم.","url":""}]},{"id":"s29-122","number":122,"surah":29,"verses":[15],"references":[{"surah":29,"verses":[15]}],"verseLabel":"العنكبوت: 15","question":"ما دلالة تسميتها ﴿السَّفِينَةِ﴾ هنا، وتسميتها في مواضع أخرى ﴿الْفُلْكِ﴾ أو ﴿ذَاتِ أَلْوَاحٍ وَدُسُرٍ﴾؟","answer":"تستعمل السفينة عندما تُعيَّن ويُذكر أصحابها، كما هنا: ﴿وَأَصْحَابَ السَّفِينَةِ﴾، وكما في سفينة المساكين في الكهف. أما الفلك فأعم، و﴿ذَاتِ أَلْوَاحٍ وَدُسُرٍ﴾ تصف مادة صناعتها وبنيتها؛ فكل اسم يبرز جانبًا يقتضيه المقام.","sources":[{"label":"فاضل السامرائي، الفرق بين السفينة والفلك وذات ألواح ودسر، عنوان الوقفة: «مرة فلك ومرة جارية ومرة ذات ألواح ودسر ومرة سفينة».","url":""}]},{"id":"s29-123","number":123,"surah":29,"verses":[16,27],"references":[{"surah":29,"verses":[16,27]}],"verseLabel":"العنكبوت: 16، 27","question":"ما سر اقتصار قصة إبراهيم هنا على موقفه من قومه دون بقية مواقف حياته؟","answer":"القصة القرآنية ليست سردًا تاريخيًا جامعًا، وإنما يُختار منها الملمح الذي يخدم مقصد السورة. فسورة العنكبوت تبرز دعوة إبراهيم قومه، وثباته أمام فتنتهم، وإنجاءه من النار؛ لأن ذلك ينسجم مع محور الابتلاء والثبات، بينما تعرض سور أخرى موقفه من أبيه أو ذريته أو الملائكة.","sources":[{"label":"فاضل السامرائي، تجزئة القصص القرآني – قصة إبراهيم عليه السلام، منصة باحث.","url":""}]},{"id":"s29-124","number":124,"surah":29,"verses":[24],"references":[{"surah":29,"verses":[24]}],"verseLabel":"العنكبوت: 24","question":"ما دلالة جمع الآيات في قوله: ﴿إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يُؤْمِنُونَ﴾ مع أن المذكور قريبًا إنجاء إبراهيم من النار؟","answer":"الإشارة لا تنحصر في لحظة النجاة، بل تشمل ما عرضه السياق: عجز الأصنام عن الدفاع عن نفسها، وبقاء إبراهيم سالمًا، وعجز قومه عن قتله، وتحول النار عن طبيعتها، وما سبق من دلائل البدء والإعادة. فكانت في القصة والسياق آيات متعددة لا آية واحدة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في قصة إبراهيم – ﴿إن في ذلك لآيات﴾، منصة باحث.","url":""}]},{"id":"s29-125","number":125,"surah":29,"verses":[26],"references":[{"surah":29,"verses":[26]}],"verseLabel":"العنكبوت: 26","question":"ما الفرق بين ﴿فَآمَنَ لَهُ لُوطٌ﴾ و«آمن به»؟","answer":"آمن له أي صدّقه واستجاب لدعوته، وتستعمل اللام مع الشخص المبلِّغ؛ كما في ﴿وَمَا أَنْتَ بِمُؤْمِنٍ لَنَا﴾. أما الباء فتتصل بما يعتقد ويُؤمن به، فتقال في الإيمان بالله والوحي والعقيدة؛ فلو قيل «آمن به» لتحول المعنى من الاستجابة لإبراهيم إلى اتخاذه متعلقًا للإيمان.","sources":[{"label":"فاضل السامرائي، دلالة ﴿فآمن له لوط﴾، نقلاً عن موقع تدارس القرآن الكريم.","url":""}]},{"id":"s29-126","number":126,"surah":29,"verses":[27],"references":[{"surah":29,"verses":[27]}],"verseLabel":"العنكبوت: 27","question":"ما سر قوله هنا: ﴿وَآتَيْنَاهُ أَجْرَهُ فِي الدُّنْيَا﴾، وقوله في النحل: ﴿وَآتَيْنَاهُ فِي الدُّنْيَا حَسَنَةً﴾؟","answer":"فصلت العنكبوت عمل إبراهيم وجهاده في الدعوة ومواجهة قومه حتى أرادوا قتله أو إحراقه، والأجر جزاء العمل، فناسب ﴿أَجْرَهُ﴾. أما النحل فذكرت صفاته من القنوت والحنيفية والشكر من غير تفصيل ذلك العمل والمواجهة، فناسبها التعبير العام ﴿حَسَنَةً﴾.","sources":[{"label":"فاضل السامرائي، الفرق بين ﴿وآتيناه أجره في الدنيا﴾ و﴿وآتيناه في الدنيا حسنة﴾، منصة باحث.","url":""}]},{"id":"s29-127","number":127,"surah":29,"verses":[33],"references":[{"surah":29,"verses":[33]}],"verseLabel":"العنكبوت: 33","question":"ما سر زيادة ﴿أَنْ﴾ في قوله: ﴿وَلَمَّا أَنْ جَاءَتْ رُسُلُنَا لُوطًا﴾؟","answer":"تفصل ﴿أَنْ﴾ بين ﴿لَمَّا﴾ والفعل، فتشعر بامتداد الانتظار واستطالة الزمن في نفس لوط. فقد بلغ ضيقه بقومه مبلغًا شديدًا، واستعجلوا العذاب، ودعا عليهم؛ فكأن مجيء الرسل تأخر في شعوره، فناسب التعبيرَ حرفٌ يزيد المبنى ويمد الإيقاع.","sources":[{"label":"فاضل السامرائي، دلالة ﴿أن﴾ في قوله: ﴿ولما أن جاءت رسلنا لوطًا﴾، نقلاً عن موقع تدارس القرآن الكريم.","url":""}]},{"id":"s29-128","number":128,"surah":29,"verses":[38,40],"references":[{"surah":29,"verses":[38,40]}],"verseLabel":"العنكبوت: 38، 40","question":"ما سر اختصار قصة موسى هنا في إشارات قليلة مع تفصيلها في سور أخرى؟","answer":"المقام ليس مقام سرد قصة موسى، وإنما مقام جمع نماذج المكذبين وعقوباتهم. لذلك ذُكر مجيء موسى بالبينات واستكبار قارون وفرعون وهامان، ثم أدرج مصيرهم ضمن سلسلة الحاصب والصيحة والخسف والإغراق؛ فالمقصود وحدة العاقبة لا تفصيل أحداث الرسالة.","sources":[{"label":"فاضل السامرائي، لماذا اختُصرت قصة موسى في سورة العنكبوت؟، عنوان الوقفة: «ذكر الله قصة موسى في آيتين».","url":""}]},{"id":"s29-129","number":129,"surah":29,"verses":[41],"references":[{"surah":29,"verses":[41]}],"verseLabel":"العنكبوت: 41","question":"ما سر تأنيث الفعل في قوله: ﴿كَمَثَلِ الْعَنْكَبُوتِ اتَّخَذَتْ بَيْتًا﴾؟","answer":"لفظ العنكبوت يجوز فيه التذكير والتأنيث في العربية، لكن الفعل جاء مؤنثًا لأن أنثى العنكبوت هي التي تتولى بناء البيت. فوافق التأنيث الحقيقة التي يقوم عليها المثل، إلى جانب جوازه اللغوي، وزاد الصورة دقة.","sources":[{"label":"فاضل السامرائي، سر قوله ﴿العنكبوت اتخذت بيتًا﴾، عنوان الوقفة: «هل العنكبوت مذكر؟ ولماذا اتخذت بتاء التأنيث؟».","url":""}]},{"id":"s29-130","number":130,"surah":29,"verses":[56],"references":[{"surah":29,"verses":[56]}],"verseLabel":"العنكبوت: 56","question":"ما دلالة إثبات الياء في ﴿يَا عِبَادِيَ الَّذِينَ آمَنُوا﴾، وحذفها في ﴿قُلْ يَا عِبَادِ الَّذِينَ آمَنُوا﴾ بالزمر؟","answer":"إثبات الياء في ﴿عِبَادِيَ﴾ يناسب الكثرة والسعة؛ فخطاب العنكبوت متعلق بعموم المؤمنين، وتلاه ﴿كُلُّ نَفْسٍ﴾، كما ناسبت سعةُ العباد سعةَ الأرض. أما خطاب الزمر فانتقل إلى المتقين والصابرين، وهم طائفة أقل، فناسب الحذف والإيجاز.","sources":[{"label":"فاضل السامرائي، الفرق بين ﴿عبادي﴾ في العنكبوت و﴿عبادِ﴾ في الزمر، نقلاً عن موقع تدارس القرآن الكريم.","url":""}]},{"id":"s29-131","number":131,"surah":29,"verses":[56],"references":[{"surah":29,"verses":[56]}],"verseLabel":"العنكبوت: 56","question":"ما سر مجيء النداء مباشرة: ﴿يَا عِبَادِيَ﴾، ومجيئه في الزمر مسبوقًا بـ﴿قُلْ﴾؟","answer":"سياق العنكبوت مبني على حضور ضمير المتكلم وإظهار العناية المباشرة: ﴿بِي﴾، ﴿إِلَيَّ﴾، ﴿أَرْضِي﴾، ﴿فَإِيَّايَ﴾، ﴿إِلَيْنَا﴾؛ فناسبه النداء بلا واسطة. أما الزمر فبنيت على التبليغ وتكرر فيها الأمر ﴿قُلْ﴾، فجيء بالنداء في إطار هذا النسق.","sources":[{"label":"فاضل السامرائي، سر ذكر ﴿قل﴾ في الزمر وحذفها في العنكبوت، نقلاً عن موقع تدارس القرآن الكريم.","url":""}]},{"id":"s29-132","number":132,"surah":29,"verses":[62],"references":[{"surah":29,"verses":[62]}],"verseLabel":"العنكبوت: 62","question":"ما دلالة زيادة ﴿لَهُ﴾ في قوله: ﴿وَيَقْدِرُ لَهُ﴾، وحذفها في مواضع أخرى؟","answer":"مع ﴿لَهُ﴾ يعود البسط والتضييق إلى الشخص نفسه؛ فقد يوسع الله عليه زمنًا ثم يضيق عليه زمنًا آخر. أما قوله: ﴿يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ﴾ من غير ﴿له﴾ فيحتمل بسطه لبعض العباد وتضييقه على آخرين؛ فزيادة الجار تحدد جهة التضييق.","sources":[{"label":"فاضل السامرائي، دلالة ﴿ويقدر﴾ و﴿ويقدر له﴾، نقلاً عن موقع تدارس القرآن الكريم.","url":""}]},{"id":"s29-133","number":133,"surah":29,"verses":[66],"references":[{"surah":29,"verses":[66]}],"verseLabel":"العنكبوت: 66","question":"ما سر قوله: ﴿وَلِيَتَمَتَّعُوا﴾ بلام الغيبة، مقابل ﴿فَتَمَتَّعُوا﴾ في النحل والروم؟","answer":"سياق العنكبوت حافظ على ضمير الغائب من أوله: ﴿سَأَلْتَهُمْ﴾ و﴿لَيَقُولُنَّ﴾ و﴿رَكِبُوا﴾ و﴿نَجَّاهُمْ﴾ و﴿هُمْ يُشْرِكُونَ﴾، فاستمر النسق: ﴿وَلِيَتَمَتَّعُوا﴾. أما النحل والروم فجمع سياقهما بين الخطاب والغيبة، فناسب الانتقال إلى الأمر ﴿فَتَمَتَّعُوا﴾ على أسلوب الالتفات، وهو أوقع في التهديد المباشر.","sources":[{"label":"فاضل السامرائي، ﴿فتمتعوا﴾ و﴿وليتمتعوا﴾، منصة باحث.","url":""}]},{"id":"s29-134","number":134,"surah":29,"verses":[69],"references":[{"surah":29,"verses":[69]}],"verseLabel":"العنكبوت: 69","question":"ما سر اتصال خاتمة العنكبوت: ﴿وَالَّذِينَ جَاهَدُوا فِينَا﴾ بفواتح سورة الروم التي بشرت بالنصر؟","answer":"ختمت العنكبوت بالمجاهدة والهداية والمعية الإلهية للمحسنين، ثم افتتحت الروم بوعد الغلبة وفرح المؤمنين بنصر الله. فعاقبة المجاهدة النصر، والمعية تثمر التأييد؛ وبذلك تتصل خاتمة السورة المكلفة بالصبر والعمل ببداية السورة التالية المبشرة بالنتيجة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج١، ص٢، مبحث «تناسب خواتيم العنكبوت مع فواتح الروم»؛ النص المباشر.","url":""}]},{"id":"s30-94","number":94,"surah":30,"verses":[2,5],"references":[{"surah":30,"verses":[2,5]}],"verseLabel":"الروم: 2، 5","question":"ما سر اتصال البشارة بالنصر في أول سورة الروم بالمجاهدة في خاتمة سورة العنكبوت؟","answer":"خُتمت العنكبوت بالمجاهدة والهداية ومعية الله للمحسنين، ثم افتتحت الروم بوعد الغلبة وفرح المؤمنين بنصر الله. فالبداية تعرض ثمرة ما قررته الخاتمة السابقة: المجاهدة يعقبها النصر، والمعية الإلهية تثمر التأييد والفرح للمؤمنين.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج١، ص٢، مبحث «تناسب خواتيم العنكبوت مع فواتح الروم»؛ النص المباشر.","url":""}]},{"id":"s30-95","number":95,"surah":30,"verses":[5],"references":[{"surah":30,"verses":[5]}],"verseLabel":"الروم: 5","question":"ما سر ختم آيات الحرب والنصر بقوله: ﴿وَهُوَ الْعَزِيزُ الرَّحِيمُ﴾؟","answer":"العزة تناسب قهر الجبابرة وتبديل الغلبة بالهزيمة، والرحمة تناسب إنقاذ المؤمنين ونصرهم وإدخال الفرح عليهم. فالفاصلة تنظر إلى طرفي الحدث معًا: عزةٌ على المهزومين المتجبرين، ورحمةٌ بالمؤمنين المنصورين.","sources":[{"label":"فاضل السامرائي، سر الجمع بين ﴿العزيز الرحيم﴾ في سياق الحرب والنصر، موقع تدارس القرآن الكريم.","url":""}]},{"id":"s30-96","number":96,"surah":30,"verses":[17,18],"references":[{"surah":30,"verses":[17,18]}],"verseLabel":"الروم: 17، 18","question":"ما سر مجيء ﴿وَعَشِيًّا وَحِينَ تُظْهِرُونَ﴾ بعد الجملة الفاصلة: ﴿وَلَهُ الْحَمْدُ فِي السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"ليس ﴿عشيًّا﴾ معطوفًا على الأرض، وإنما يعود العطف إلى أوقات التسبيح في الآية السابقة: حين تمسون، وحين تصبحون، وعشيًّا، وحين تظهرون. وبين أجزاء هذا النسق جاءت جملة مستقلة معطوفة هي ﴿وَلَهُ الْحَمْدُ﴾، فجمع التركيب بين إحاطة التسبيح بالأوقات وإحاطة الحمد بالأمكنة.","sources":[{"label":"فاضل السامرائي، العطف في قوله: ﴿وعشيًّا وحين تظهرون﴾، عنوان الوقفة الجزئي: «من الأمثلة على العطف في القرآن قوله تعالى في سورة الروم».","url":""}]},{"id":"s30-97","number":97,"surah":30,"verses":[24],"references":[{"surah":30,"verses":[24]}],"verseLabel":"الروم: 24","question":"ما سر جمع الآيات في ﴿إِنَّ فِي ذَلِكَ لَآيَاتٍ﴾، وإفرادها في نظيرها من سورة النحل: ﴿لَآيَةً﴾؟","answer":"زادت آية الروم مشهد البرق بما فيه من خوف وطمع، وجاء إنزال الماء وإحياء الأرض فيها بالمضارع الدال على التجدد والتكرر. أما آية النحل فذكرت إنزال الماء والإحياء بالماضي في صورة مشهد واحد؛ فتعددت جهات الدلالة وتجددت في الروم فناسب الجمع.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج٢، ص٧٨، مبحث «إفراد الآية في النحل وجمعها في الروم»؛ النص المباشر.","url":""}]},{"id":"s30-98","number":98,"surah":30,"verses":[27],"references":[{"surah":30,"verses":[27]}],"verseLabel":"الروم: 27","question":"كيف يُفهم قوله: ﴿وَهُوَ أَهْوَنُ عَلَيْهِ﴾ مع أن الخلق كله هيّن على الله؟","answer":"التعبير يحاجّ المنكرين بما تقرره عقولهم ومقاييسهم؛ فهم يعدّون إعادة الشيء بعد إنشائه أيسر من إيجاده أول مرة. فإذا أقروا بالابتداء لم يبق لهم وجه لاستبعاد البعث، وليس في الآية إثبات تعب أو تفاوت قدرة في حق الله تعالى.","sources":[{"label":"فاضل السامرائي، الجمع بين ﴿وما مسنا من لغوب﴾ و﴿وهو أهون عليه﴾، منصة باحث.","url":""}]},{"id":"s30-99","number":99,"surah":30,"verses":[34],"references":[{"surah":30,"verses":[34]}],"verseLabel":"الروم: 34","question":"ما سر الالتفات من الغيبة في ﴿لِيَكْفُرُوا﴾ إلى الخطاب في ﴿فَتَمَتَّعُوا﴾؟","answer":"تنقل السياق قبلها بين الخطاب والغيبة: ﴿ضَرَبَ لَكُمْ﴾ و﴿فَأَقِمْ وَجْهَكَ﴾، ثم ﴿دَعَوْا رَبَّهُمْ﴾ و﴿فَرِيقٌ مِنْهُمْ﴾؛ فناسب أن يتحول من حكاية فعلهم إلى مواجهتهم بالتهديد: ﴿فَتَمَتَّعُوا﴾. والالتفات يجعل الوعيد أشد حضورًا من الاستمرار في الحديث عنهم بضمير الغائب.","sources":[{"label":"فاضل السامرائي، الالتفات في ﴿ليكفروا بما آتيناهم فتمتعوا﴾، موقع تدارس القرآن الكريم.","url":""}]},{"id":"s30-100","number":100,"surah":30,"verses":[36],"references":[{"surah":30,"verses":[36]}],"verseLabel":"الروم: 36","question":"ما دلالة مجيء الرحمة مع ﴿إِذَا﴾، والسيئة مع ﴿إِنْ﴾ في قوله: ﴿وَإِذَا أَذَقْنَا النَّاسَ رَحْمَةً... وَإِنْ تُصِبْهُمْ سَيِّئَةٌ﴾؟","answer":"﴿إذا﴾ تستعمل لما يكثر وقوعه أو يقوى تحققه، و﴿إن﴾ لما هو أقل وقوعًا أو محتمل. فجاءت الرحمة مع ﴿إذا﴾ للدلالة على سعتها وكثرة غمرها للناس، وجاءت السيئة مع ﴿إن﴾ لأنها عارضة ولأن ما يعفو الله عنه أكثر؛ وفي ذلك تغليب للرحمة على العقوبة.","sources":[{"label":"فاضل السامرائي، الفرق بين ﴿إذا﴾ مع الرحمة و﴿إن﴾ مع السيئة، نقلاً عن موقع تدارس القرآن الكريم.","url":""}]},{"id":"s30-101","number":101,"surah":30,"verses":[36,41],"references":[{"surah":30,"verses":[36,41]}],"verseLabel":"الروم: 36، 41","question":"ما سر قوله: ﴿بِمَا قَدَّمَتْ أَيْدِيهِمْ﴾ في الآية ٣٦، وقوله: ﴿بِمَا كَسَبَتْ أَيْدِي النَّاسِ﴾ في الآية ٤١؟","answer":"التقديم هو ما يرسله الإنسان أمامه من عمل، أما الكسب ففيه معنى الجمع والتحصيل والاستحواذ. آية ٣٦ سبقتها أحوال الضر والرحمة والشرك من غير حديث عن كسب مالي، فناسب ﴿قَدَّمَتْ﴾؛ أما آية ٤١ فسبقها الربا والزكاة وكسب الأموال، فناسبها ﴿كَسَبَتْ﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج١، ص١٦٨–١٦٩، مبحث «الفرق بين ما قدمت أيديكم وما كسبت أيديكم»؛ النص المباشر.","url":""}]},{"id":"s30-102","number":102,"surah":30,"verses":[42],"references":[{"surah":30,"verses":[42]}],"verseLabel":"الروم: 42","question":"ما سر قوله: ﴿عَاقِبَةُ الَّذِينَ مِنْ قَبْلُ﴾ بحذف المضاف إليه، وقوله في مواضع أخرى: ﴿مِنْ قَبْلِهِمْ﴾؟","answer":"﴿من قبلهم﴾ تتصل بأقوام مخصوصين عرفهم المخاطبون في أسفارهم ورأوا آثارهم. أما آية الروم فهي أمر بالسير والنظر على العموم، لا في الطرق والأقوام المعهودين وحدهم؛ فحُذف المضاف إليه لتعم العبرة كل من تقدم، ويتسع السير والنظر والزمن.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج٢، ص٦٩، مبحث «الفرق بين ﴿من قبلهم﴾ و﴿من قبلُ﴾»؛ النص المباشر.","url":""}]},{"id":"s30-103","number":103,"surah":30,"verses":[46,48],"references":[{"surah":30,"verses":[46,48]}],"verseLabel":"الروم: 46، 48","question":"ما سر توسط الحديث عن الرسل ونصر المؤمنين بين آيتين تتحدثان عن إرسال الرياح؟","answer":"بدأت الآيات بنعمة الرياح عامة ودعت إلى الشكر، فجاء ذكر الرسل تحذيرًا لمن يكفر بالنعمة، وتذكيرًا بمصير المجرمين ونصر المؤمنين. ثم عادت إلى تفصيل الرياح والمطر وموقف الناس منهما؛ فليس الانتقال انقطاعًا، بل هو وصل بين النعمة ومسؤولية شكرها وعاقبة الجحود بها.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في آيات إرسال الرياح في سورة الروم، منصة باحث.","url":""}]},{"id":"s30-104","number":104,"surah":30,"verses":[46,51],"references":[{"surah":30,"verses":[46,51]}],"verseLabel":"الروم: 46، 51","question":"ما دلالة جمع ﴿الرِّيَاحَ﴾ في آية البشارة، وإفراد ﴿رِيحًا﴾ في آية اصفرار الزرع؟","answer":"جاءت الرياح مجموعة حين حملت البشارة والرحمة وجريان الفلك وابتغاء الفضل، وجاءت الريح مفردة حين صارت سببًا في إفساد الزرع واصفراره. وبذلك قابل السياق بين الرحمة والعقوبة، والاستبشار والإبلاس، والشكر والكفر، فاختار لكل جهة لفظها المناسب.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في آيات إرسال الرياح في سورة الروم، منصة باحث، المقطع الجزئي المتعلق بالمقابلة بين «الرياح» و«الريح».","url":""}]},{"id":"s30-105","number":105,"surah":30,"verses":[49],"references":[{"surah":30,"verses":[49]}],"verseLabel":"الروم: 49","question":"ما سر تكرار ﴿مِنْ قَبْلُ﴾ في قوله: ﴿مِنْ قَبْلِ أَنْ يُنَزَّلَ عَلَيْهِمْ مِنْ قَبْلِهِ لَمُبْلِسِينَ﴾؟","answer":"ليست العبارتان لزمن واحد؛ فالأولى متعلقة بنزول المطر: كانوا قبل أن ينزل عليهم في يأس، والثانية متعلقة بالاستبشار المذكور قبلها: كانوا من قبل هذا الفرح مبلسين. فجمع التعبير بين زمن الحرمان وزمن الحالة النفسية التي انقلبت سريعًا من اليأس إلى البشر.","sources":[{"label":"فاضل السامرائي، سر تكرار ﴿من قبل﴾ في الآية، منصة باحث.","url":""}]},{"id":"s30-106","number":106,"surah":30,"verses":[53],"references":[{"surah":30,"verses":[53]}],"verseLabel":"الروم: 53","question":"ما سر حذف الياء في ﴿وَمَا أَنْتَ بِهَادِ الْعُمْيِ﴾، وإثباتها في نظيرتها من سورة النمل: ﴿بِهَادِي الْعُمْيِ﴾؟","answer":"كثر ذكر الهداية في سورة النمل، وذُكر فيها المؤمنون المهتدون والحق المبين، فناسب زيادة مبنى الكلمة بإثبات الياء. أما سياق الروم القريب فمحوره المطر والرياح والأرض، وقلّ فيه ذكر الهداية، فناسب الحذف قلةَ السمة التعبيرية في السورة.","sources":[{"label":"فاضل السامرائي، سر إثبات الياء في ﴿بهادي﴾ بالنمل وحذفها في الروم، موقع تدارس القرآن الكريم.","url":""}]},{"id":"s30-107","number":107,"surah":30,"verses":[58,60],"references":[{"surah":30,"verses":[58,60]}],"verseLabel":"الروم: 58، 60","question":"ما سر اتصال ختام الروم بفاتحة لقمان في الحديث عن القرآن والعلم واليقين؟","answer":"ختمت الروم بذكر أمثال القرآن، وبالذين لا يعلمون ولا يوقنون؛ ثم افتتحت لقمان بآيات الكتاب الحكيم، ووصفت أهل الهدى بأنهم بالآخرة يوقنون، وعرضت نموذج من يضل بغير علم. فقابلت الفاتحةُ التالية أوصافَ المعرضين في الخاتمة بأوصاف المحسنين الموقنين.","sources":[{"label":"فاضل السامرائي، تناسب خواتيم الروم مع فواتح لقمان، نقلاً عن موقع تدارس القرآن الكريم.","url":""}]},{"id":"s30-108","number":108,"surah":30,"verses":[60],"references":[{"surah":30,"verses":[60]}],"verseLabel":"الروم: 60","question":"ما سر إحاطة السورة بوعد الله؛ في أولها ﴿وَعْدَ اللَّهِ لَا يُخْلِفُ اللَّهُ وَعْدَهُ﴾ وفي آخرها ﴿إِنَّ وَعْدَ اللَّهِ حَقٌّ﴾؟","answer":"افتتحت السورة بوعد محدد بانقلاب هزيمة الروم إلى غلبة وفرح المؤمنين بالنصر، ثم ختمت بأمر النبي بالصبر على وعد الله الحق. فالبداية تقدم البرهان التاريخي على صدق الوعد، والخاتمة تحول هذا البرهان إلى زاد للصبر والثبات أمام المكذبين.","sources":[{"label":"فاضل السامرائي، تناسب فاتحة سورة الروم مع خاتمتها، نقلاً عن موقع تدارس القرآن الكريم.","url":""}]},{"id":"s31-51","number":51,"surah":31,"verses":[1,3],"references":[{"surah":31,"verses":[1,3]}],"verseLabel":"لقمان: 1، 3","question":"ما سر افتتاح السورة بالأحرف المقطعة ثم وصف القرآن بأنه ﴿الْكِتَابِ الْحَكِيمِ﴾؟","answer":"الأحرف المقطعة تلفت السامع إلى ما سيأتي بعدها؛ لأنها ليست مألوفة في مطالع كلام العرب. وهي كذلك تومئ إلى التحدي: فهذا الكتاب المعجز مؤلف من جنس الحروف التي تتكون منها لغتهم، ومع ذلك عجزوا عن الإتيان بمثله؛ فجاء بعدها وصف الكتاب بالحكمة مناسبًا لهذا المقام.","sources":[{"label":"فاضل السامرائي، الأحرف المقطعة في مطلع سورة لقمان، منصة باحث.","url":""}]},{"id":"s31-52","number":52,"surah":31,"verses":[6],"references":[{"surah":31,"verses":[6]}],"verseLabel":"لقمان: 6","question":"ما سر إثبات اللام في ﴿لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ﴾ وحذفها من ﴿وَيَتَّخِذَهَا هُزُوًا﴾؟","answer":"الغرض الأقوى من شراء لهو الحديث هو الإضلال عن سبيل الله، فصرح معه بلام التعليل توكيدًا لمكانته في القصد. أما اتخاذ الآيات هزوًا فتابع لذلك ودونه في رتبة الغرض، فحذفت اللام؛ لأن تكرار الحرف يقوي المعطوف ويسويه بما قبله في التأكيد.","sources":[{"label":"فاضل السامرائي، اللمسات البيانية في الآية ٦ من سورة لقمان، المبحث الجزئي: «حذف اللام من ويتخذها هزوًا».","url":""}]},{"id":"s31-53","number":53,"surah":31,"verses":[7],"references":[{"surah":31,"verses":[7]}],"verseLabel":"لقمان: 7","question":"ما سر زيادة قوله: ﴿كَأَنَّ فِي أُذُنَيْهِ وَقْرًا﴾ في لقمان وحذفه من نظيرها في الجاثية؟","answer":"في الجاثية صرّح بأنه يسمع الآيات: ﴿يَسْمَعُ آيَاتِ اللَّهِ تُتْلَى عَلَيْهِ﴾، فلا يناسب بعد إثبات السماع أن يجعل في أذنيه وقرًا. أما في لقمان فذُكرت التلاوة من غير تصريح بسماعه، فناسب تصويره كأن في أذنيه ثقلًا يمنع وصول الآيات إليه.","sources":[{"label":"فاضل السامرائي، سر زيادة ﴿كأن في أذنيه وقرًا﴾، المبحث الجزئي للآية ٧.","url":""}]},{"id":"s31-54","number":54,"surah":31,"verses":[12],"references":[{"surah":31,"verses":[12]}],"verseLabel":"لقمان: 12","question":"ما دلالة المضارع في ﴿وَمَنْ يَشْكُرْ﴾ والماضي في ﴿وَمَنْ كَفَرَ﴾؟","answer":"النعم متجددة، ولذلك ينبغي أن يتجدد الشكر ويتكرر، فجيء به مضارعًا. أما الكفر فالمطلوب قطعه وعدم تكراره، ويكفي وقوعه مرة في الاعتقاد، فجاء بالفعل الماضي؛ فبنية الفعل تلائم ما ينبغي دوامه وما ينبغي انقطاعه.","sources":[{"label":"فاضل السامرائي، المضارع في الشكر والماضي في الكفر، المبحث الجزئي للآية ١٢.","url":""}]},{"id":"s31-55","number":55,"surah":31,"verses":[12],"references":[{"surah":31,"verses":[12]}],"verseLabel":"لقمان: 12","question":"ما سر الجمع بين ﴿غَنِيٌّ حَمِيدٌ﴾ في خاتمة آية الشكر؟","answer":"الغنى يقرر أن شكر العبد لا يزيد في ملك الله، وأن كفره لا ينقص منه شيئًا. و﴿حميد﴾ أبلغ من «محمود»، فهي تدل على استحقاق الحمد وكثرته ودوامه؛ فهو غني عن شكر الخلق، محمود في ذاته ونِعمه سواء شكروا أم كفروا.","sources":[{"label":"فاضل السامرائي، دلالة الجمع بين غني وحميد، المبحث الجزئي للآية ١٢.","url":""}]},{"id":"s31-56","number":56,"surah":31,"verses":[13],"references":[{"surah":31,"verses":[13]}],"verseLabel":"لقمان: 13","question":"ما أثر النداء المصغر ﴿يَا بُنَيَّ﴾ قبل النهي عن الشرك؟","answer":"التصغير مع الإضافة إلى ياء المتكلم يحمل معنى التحبيب والشفقة والقرب، فيفتح قلب الابن قبل توجيه النهي الأعظم إليه. وبدأ بالتوحيد لأنه أصل الأعمال وأعم من العبادة وأيسر تعليمًا للصغير، ثم علل النهي بأن الشرك ظلم عظيم ليقنع العقل ولا يكتفي بالأمر المجرد.","sources":[{"label":"فاضل السامرائي، نظرات بيانية في وصية لقمان لابنه، موقع تدارس القرآن الكريم.","url":""}]},{"id":"s31-57","number":57,"surah":31,"verses":[13],"references":[{"surah":31,"verses":[13]}],"verseLabel":"لقمان: 13","question":"ما سر قوله: ﴿وَهُوَ يَعِظُهُ﴾ بدل «واعظًا له»؟","answer":"الجملة تحتمل الحالية، فتفيد أنه اختار لابنه حالًا ووقتًا مناسبين للوعظ، وتحتمل الاستئناف، فتفيد أن تعاهد ابنه بالنصح كان من عادته. أما اسم الحال «واعظًا» فيؤدي معنى واحدًا؛ فجاءت الجملة لتجمع حسن اختيار اللحظة ودوام الرعاية.","sources":[{"label":"فاضل السامرائي، دلالة قوله ﴿وهو يعظه﴾، مبحث «وصية لقمان لابنه».","url":""}]},{"id":"s31-58","number":58,"surah":31,"verses":[14,15],"references":[{"surah":31,"verses":[14,15]}],"verseLabel":"لقمان: 14، 15","question":"ما سر مجيء وصية الله بالوالدين في أثناء كلام لقمان قبل أن يتم وصيته؟","answer":"تولى الله الوصية بالوالدين لعظم منزلتهما، حتى لا يتوهم الابن أن الأب يطلب منفعة لنفسه حين يأمره بحقه. ووُضعت الوصية عقب النهي عن الشرك مباشرة؛ لأن حق الوالدين يأتي في القرآن بعد حق الله، ثم عاد السياق إلى كلام لقمان بقوله: ﴿يَا بُنَيَّ﴾.","sources":[{"label":"فاضل السامرائي، سر المداخلة في وصية لقمان، منصة باحث.","url":""}]},{"id":"s31-59","number":59,"surah":31,"verses":[16],"references":[{"surah":31,"verses":[16]}],"verseLabel":"لقمان: 16","question":"ما سر حذف النون في ﴿إِنْ تَكُ مِثْقَالَ حَبَّةٍ﴾ وإثباتها في ﴿فَتَكُنْ فِي صَخْرَةٍ﴾؟","answer":"عند قوله ﴿إِنْ تَكُ مِثْقَالَ حَبَّةٍ﴾ لم يذكر للحبة مكانًا، فناسب خفة اللفظ بحذف النون. وحين أثبت لها مكانًا مستقرًّا في صخرة أو السماوات أو الأرض أثبت النون في ﴿فَتَكُنْ﴾؛ فوافق اكتمال المبنى اكتمال صورة الاستقرار المكاني.","sources":[{"label":"فاضل السامرائي، الفرق بين ﴿تك﴾ و﴿تكن﴾ في الآية ١٦، المبحث الجزئي للآية ١٦.","url":""}]},{"id":"s31-60","number":60,"surah":31,"verses":[17],"references":[{"surah":31,"verses":[17]}],"verseLabel":"لقمان: 17","question":"ما سر قوله: ﴿إِنَّ ذَلِكَ مِنْ عَزْمِ الْأُمُورِ﴾، وزيادة اللام في الشورى: ﴿لَمِنْ عَزْمِ الْأُمُورِ﴾؟","answer":"المطلوب في لقمان هو الصبر على ما يصيب الإنسان، وهو شاق. أما في الشورى فاجتمع الصبر مع المغفرة، وهو أشق على النفس وأعلى مرتبة؛ فاحتاج المقام إلى توكيد زائد بلام التوكيد: ﴿لَمِنْ عَزْمِ الْأُمُورِ﴾.","sources":[{"label":"فاضل السامرائي، لمسات بيانية لسور القرآن الكريم، ج١، ص٢٩، مبحث «من عزم الأمور ولمن عزم الأمور»؛ النص المباشر.","url":""}]},{"id":"s31-61","number":61,"surah":31,"verses":[19],"references":[{"surah":31,"verses":[19]}],"verseLabel":"لقمان: 19","question":"ما دلالة دخول ﴿مِنْ﴾ في قوله: ﴿وَاغْضُضْ مِنْ صَوْتِكَ﴾؟","answer":"﴿من﴾ للتبعيض؛ فالمطلوب خفض مقدار من الصوت حتى لا يؤذي بارتفاعه، لا إسقاطه كله حتى يصير همسًا لا يسمع. وهكذا قابل الاعتدال في الصوت الاعتدال في المشي: ﴿وَاقْصِدْ فِي مَشْيِكَ﴾.","sources":[{"label":"فاضل السامرائي، دلالة ﴿من﴾ في قوله ﴿واغضض من صوتك﴾، المبحث الجزئي للآية ١٩.","url":""}]},{"id":"s31-62","number":62,"surah":31,"verses":[20],"references":[{"surah":31,"verses":[20]}],"verseLabel":"لقمان: 20","question":"ما سر جمع الكثرة ﴿نِعَمَهُ﴾ بدل جمع القلة «أنعمه»؟","answer":"﴿أنعُم﴾ جمع قلة، أما ﴿نِعَم﴾ فجمع كثرة. والمقام في إسباغ النعم الظاهرة والباطنة التي لا تحصى، فاختير جمع الكثرة واتصل بفعل ﴿أَسْبَغَ﴾ الدال على الإفاضة والشمول؛ إذ لا يستطيع الإنسان استقصاءها فضلًا عن شكرها جميعًا.","sources":[{"label":"فاضل السامرائي، الفرق بين أنعُم ونِعَم، المبحث الجزئي للآية ٢٠.","url":""}]},{"id":"s31-63","number":63,"surah":31,"verses":[22],"references":[{"surah":31,"verses":[22]}],"verseLabel":"لقمان: 22","question":"ما دلالة تعدية ﴿يُسْلِمْ وَجْهَهُ﴾ بـ﴿إِلَى اللَّهِ﴾ لا باللام؟","answer":"الإسلام لله يدل على الإخلاص والانقياد، أما الإسلام إلى الله فيتضمن دفع الأمر إليه وتفويضه والتوكل عليه. وهذا أنسب بما بعده: ﴿فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَى﴾؛ فمن فوض أمره إلى الله في الشدائد استمسك بما يعصمه.","sources":[{"label":"فاضل السامرائي، الفرق بين أسلم لله وأسلم إلى الله، المبحث الجزئي للآية ٢٢.","url":""}]},{"id":"s31-64","number":64,"surah":31,"verses":[23],"references":[{"surah":31,"verses":[23]}],"verseLabel":"لقمان: 23","question":"ما لطف التعبير في قوله: ﴿فَلَا يَحْزُنْكَ كُفْرُهُ﴾؟","answer":"لم يجعل النبي فاعل الحزن كما في «لا تحزن»، بل جعل الكفر فاعلًا منهيًّا عن إحزانه، كأنه ذات تريد أن تنال منه فيقال لها: لا تحزنيه. وفي ذلك رقة وإشفاق على الرسول، كما أن الفاء جعلت ﴿من﴾ شرطية تفيد عموم كل كافر، لا شخصًا بعينه.","sources":[{"label":"فاضل السامرائي، دلالة قوله ﴿فلا يحزنك كفره﴾، المبحث الجزئي للآية ٢٣.","url":""}]},{"id":"s31-65","number":65,"surah":31,"verses":[24],"references":[{"surah":31,"verses":[24]}],"verseLabel":"لقمان: 24","question":"ما سر حذف الموصوف في ﴿نُمَتِّعُهُمْ قَلِيلًا﴾؟","answer":"يحتمل ﴿قليلًا﴾ أن تكون تمتيعًا قليلًا، وأن تكون زمنًا قليلًا. ولو ذُكر الموصوف لتحدد أحد المعنيين، أما حذفه فجمع قلة المتاع وقصر مدته معًا في لفظ واحد؛ وهذا من اتساع المعنى بالحذف.","sources":[{"label":"فاضل السامرائي، التوسع في معنى ﴿نمتعهم قليلًا﴾، المبحث الجزئي للآية ٢٤.","url":""}]},{"id":"s31-66","number":66,"surah":31,"verses":[28],"references":[{"surah":31,"verses":[28]}],"verseLabel":"لقمان: 28","question":"ما سر ختم آية الخلق والبعث بقوله: ﴿إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ﴾ لا بوصف القدرة؟","answer":"الخالق والباعث لا بد أن يسمع أقوال خلقه ويبصر أعمالهم ليحاسبهم عليها، و﴿بصير﴾ تتسع للبصر والبصيرة فتشمل المرئي وما تضمره النفوس. أما القدرة فهي مفهومة من الخلق والبعث، فجاءت الفاصلة بمعنى جديد يجمع الإحاطة بأقوال العباد وأعمالهم وخفاياهم.","sources":[{"label":"فاضل السامرائي، سر ختم الآية بـ﴿سميع بصير﴾، منصة باحث.","url":""}]},{"id":"s31-67","number":67,"surah":31,"verses":[31,32],"references":[{"surah":31,"verses":[31,32]}],"verseLabel":"لقمان: 31، 32","question":"ما سر وصف الناجي من الموج بأنه ﴿مُقْتَصِدٌ﴾، ووصف الناجين في العنكبوت بأنهم يشركون؟","answer":"صورت لقمان هولًا عظيمًا: موجًا كالظلل يوقظ الفطرة ويجعلهم يخلصون الدعاء، فبقي أثر الهزة بعد النجاة وخفّ غلو بعضهم، فكان منهم مقتصد. أما العنكبوت فذكرت مجرد ركوب الفلك من غير تصوير ذلك الهول، وجاء سياقها في المشركين، فناسب التصريح بعودهم إلى الشرك.","sources":[{"label":"فاضل السامرائي، الفرق بين ﴿فمنهم مقتصد﴾ و﴿إذا هم يشركون﴾، المبحث الجزئي للآية ٣٢.","url":""}]},{"id":"s31-68","number":68,"surah":31,"verses":[33],"references":[{"surah":31,"verses":[33]}],"verseLabel":"لقمان: 33","question":"ما سر تقديم الحياة الدنيا على الغَرور وتوكيد الفعلين بالنون في ﴿فَلَا تَغُرَّنَّكُمُ... وَلَا يَغُرَّنَّكُمْ﴾؟","answer":"الدنيا هي مبتغى الإنسان الأول، والشيطان إنما يغره غالبًا من جهتها، لذلك قُدِّمت. وأكد النهي بنون التوكيد لأن وقوع التغرير شديد متكرر، فجاء التحذير بقوة تناسب قوة الفتنة؛ كما جعل الدنيا والغَرور فاعلين كأنهما ينصبان للإنسان الشراك.","sources":[{"label":"فاضل السامرائي، اللمسات البيانية في قوله ﴿فلا تغرنكم الحياة الدنيا﴾، المبحث الجزئي للآية ٣٣.","url":""}]},{"id":"s31-69","number":69,"surah":31,"verses":[34],"references":[{"surah":31,"verses":[34]}],"verseLabel":"لقمان: 34","question":"ما سر العدول من العلم إلى الفعل في قوله: ﴿وَيُنَزِّلُ الْغَيْثَ﴾؟","answer":"لم يقل «ويعلم نزول الغيث»؛ لأن الذي يمس حياة العباد ومعاشهم هو إنزاله فعلًا، لا مجرد العلم بموعده. فانتقل التعبير من اختصاص الله بعلم الساعة إلى نعمته وقدرته في تنزيل الغيث، واختار الجانب الألصق بحاجة الناس.","sources":[{"label":"فاضل السامرائي، دلالة العطف في آية مفاتح الغيب، المبحث الجزئي للآية ٣٤.","url":""}]},{"id":"s31-70","number":70,"surah":31,"verses":[34],"references":[{"surah":31,"verses":[34]}],"verseLabel":"لقمان: 34","question":"ما سر تحديد مكان الموت في ﴿بِأَيِّ أَرْضٍ تَمُوتُ﴾ دون تحديد زمنه؟","answer":"سبقت الآيةَ مشاهدُ الانتقال في الفلك والبحر، وغشيان الموج، ثم النجاة إلى البر؛ فغلب على السياق الانتقال من مكان إلى مكان. لذلك ناسب أن تختم السورة بجهل النفس بالمكان الذي تنتهي إليه: أفي بحر تموت أم في أرض، مع بقاء الأجل كله في علم الله.","sources":[{"label":"فاضل السامرائي، سر تحديد المكان دون الزمان في خاتمة لقمان، المبحث الجزئي للآية ٣٤.","url":""}]},{"id":"s32-40","number":40,"surah":32,"verses":[4,5],"references":[{"surah":32,"verses":[4,5]}],"verseLabel":"السجدة: 4، 5","question":"ما سر زيادة التاء في ﴿أَفَلَا تَتَذَكَّرُونَ﴾، وحذفها من ﴿أَفَلَا تَذَكَّرُونَ﴾ في سورة يونس؟","answer":"زيادة المبنى تناسب زيادة المعنى والتفصيل. فقد فصّلت السجدة بذكر ﴿وَمَا بَيْنَهُمَا﴾، وزادت الولي على الشفيع، وبسطت تدبير الأمر من السماء إلى الأرض وعروجه في يوم مقداره ألف سنة؛ فناسب التفصيلَ الفعلُ الأطول ﴿تتذكرون﴾. أما يونس فأوجزت، فناسبها ﴿تذكرون﴾ الأخف.","sources":[{"label":"فاضل السامرائي، استخدام ﴿تذكرون﴾ و﴿تتذكرون﴾، منصة باحث، المقطع الخاص بسورتي السجدة ويونس.","url":""}]},{"id":"s32-41","number":41,"surah":32,"verses":[13],"references":[{"surah":32,"verses":[13]}],"verseLabel":"السجدة: 13","question":"ما دلالة اختيار ﴿الْجِنَّةِ وَالنَّاسِ﴾ بدل «الجن والإنس»؟","answer":"يقابل الاستعمال القرآني بين ﴿الجن﴾ و﴿الإنس﴾ حين يراد أصل الجنسيْن، ويقابل بين ﴿الجِنّة﴾ و﴿الناس﴾ حين يراد الجماعات والأفراد من الجنسين. ولما كان المقام في ملء جهنم بمن استحقها من هؤلاء وهؤلاء، ناسب التعبير بالمجموعتين: ﴿الجنة والناس﴾.","sources":[{"label":"فاضل السامرائي، الفرق بين الجن والجِنّة ودلالة البدء بهما، المبحث الجزئي للآية ١٣.","url":""}]},{"id":"s32-42","number":42,"surah":32,"verses":[20],"references":[{"surah":32,"verses":[20]}],"verseLabel":"السجدة: 20","question":"ما سر وصف عذاب النار بـ﴿الَّذِي﴾ في السجدة، ووصفه بـ﴿الَّتِي﴾ في موضع آخر؟","answer":"يعود ﴿الذي﴾ في السجدة إلى العذاب: ﴿عَذَابَ النَّارِ الَّذِي كُنْتُمْ بِهِ تُكَذِّبُونَ﴾؛ لأن السياق بعده مستمر في العذاب الأدنى والأكبر، ولأن الفاسق قد يقر بالنار ثم يستبعد عذابه. أما ﴿التي﴾ فتعود إلى النار نفسها في سياق الكافرين المنكرين لها؛ فحدد اسم الموصول جهة التكذيب في كل مقام.","sources":[{"label":"فاضل السامرائي، الفرق بين ﴿عذاب النار التي﴾ و﴿عذاب النار الذي﴾، منصة باحث.","url":""}]},{"id":"s32-43","number":43,"surah":32,"verses":[22],"references":[{"surah":32,"verses":[22]}],"verseLabel":"السجدة: 22","question":"ما سر التراخي بـ﴿ثُمَّ﴾ في ﴿ثُمَّ أَعْرَضَ عَنْهَا﴾، والتعقيب بالفاء في نظيرها من سورة الكهف؟","answer":"الفاء تفيد سرعة الإعراض عقب التذكير، وقد ذكرت آية الكهف دواعي هذه السرعة: نسيان ما قدمت اليدان، والأكنة على القلوب، والوقر في الآذان، وعدم الاهتداء أبدًا. أما السجدة فلم تذكر تلك الدواعي المعجلة، فجاءت ﴿ثم﴾ الدالة على المهلة؛ فكلا الحرفين يرسم سرعة الإعراض التي يقتضيها سياقه.","sources":[{"label":"فاضل السامرائي، الفرق بين ﴿فأعرض عنها﴾ و﴿ثم أعرض عنها﴾، المبحث الجزئي للآية ٢٢.","url":""}]},{"id":"s32-44","number":44,"surah":32,"verses":[25],"references":[{"surah":32,"verses":[25]}],"verseLabel":"السجدة: 25","question":"ما دلالة ضمير الفصل في قوله: ﴿إِنَّ رَبَّكَ هُوَ يَفْصِلُ بَيْنَهُمْ﴾؟","answer":"ضمير الفصل ﴿هو﴾ يفيد التوكيد والقصر في الغالب، فيقرر أن الفصل الحاسم بين المختلفين لله وحده. وزيد هذا التوكيد في السجدة لأن الخلاف بين أمم وملل متعددة، بخلاف الجاثية التي تناولت اختلاف جماعة من بني إسرائيل داخل ملة واحدة فقالت: ﴿إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ﴾ من غير ﴿هو﴾.","sources":[{"label":"فاضل السامرائي، دلالة ضمير الفصل في ﴿إن ربك هو يفصل بينهم﴾، المبحث الجزئي للآية ٢٥.","url":""}]},{"id":"s32-45","number":45,"surah":32,"verses":[25],"references":[{"surah":32,"verses":[25]}],"verseLabel":"السجدة: 25","question":"ما سر التعبير بـ﴿يَفْصِلُ بَيْنَهُمْ﴾ في السجدة، وبـ﴿يَقْضِي بَيْنَهُمْ﴾ في الجاثية؟","answer":"القضاء حكم، أما الفصل فهو حكم يزيد عليه إبعاد المتخاصمين وجعل حاجز بينهم. ولما كان الاختلاف في الجاثية داخل ملة واحدة قيل ﴿يقضي﴾، أما السجدة فتتحدث عن ملل وطوائف مختلفة ينتهي بعضها إلى الجنة وبعضها إلى النار؛ فناسبها ﴿يفصل﴾ الأشد دلالة.","sources":[{"label":"فاضل السامرائي، الفرق بين ﴿يفصل﴾ و﴿يقضي﴾، المبحث الجزئي للآية ٢٥.","url":""}]},{"id":"s32-46","number":46,"surah":32,"verses":[26,27],"references":[{"surah":32,"verses":[26,27]}],"verseLabel":"السجدة: 26، 27","question":"ما سر ختم خبر القرون بـ﴿أَفَلَا يَسْمَعُونَ﴾، ومشهد إنبات الأرض بـ﴿أَفَلَا يُبْصِرُونَ﴾؟","answer":"هلاك القرون الماضية غائب عن المخاطبين، وإنما يصل إليهم خبره بالسماع، فختمت آيته بـ﴿أفلا يسمعون﴾. أما سوق الماء إلى الأرض الجرز وإخراج الزرع فمشهد متكرر يقع تحت أبصارهم، فختم بـ﴿أفلا يبصرون﴾؛ فجاءت كل فاصلة من جنس الطريق الذي تدرك به الآية.","sources":[{"label":"فاضل السامرائي، دلالة اختلاف الفاصلتين ﴿أفلا يسمعون﴾ و﴿أفلا يبصرون﴾، المبحث الجزئي للآيتين ٢٦–٢٧.","url":""}]},{"id":"s33-103","number":103,"surah":33,"verses":[1,70],"references":[{"surah":33,"verses":[1,70]}],"verseLabel":"الأحزاب: 1، 70","question":"ما سر افتتاح السورة بأمر النبي ﷺ بالتقوى، ثم ختامها بأمر المؤمنين جميعًا بها؟","answer":"يبدأ البناء البياني بالقدوة الأولى؛ فيُوجَّه الأمر إلى النبي ﷺ، ثم يتسع في الخاتمة ليشمل المؤمنين. فكأن تقوى الرسول في المطلع نموذج عملي، ثم يأتي التعميم في الختام ليحمّل الأمة كلها مسؤولية الاقتداء والامتثال.","sources":[{"label":"فاضل السامرائي، تناسب فواتح الأحزاب مع خواتيمها، مبحث «تناسب فواتح الأحزاب مع خواتيمها».","url":""}]},{"id":"s33-104","number":104,"surah":33,"verses":[4],"references":[{"surah":33,"verses":[4]}],"verseLabel":"الأحزاب: 4","question":"ما سر رسم ﴿السبيل﴾ بلا ألف في أول السورة، وورودها ﴿السبيلا﴾ بألف في مشهد النار؟","answer":"جاءت ﴿السبيل﴾ في الآية الرابعة في سياق تقرير حكم هادئ مستقر، فلم يحتج المقام إلى امتداد صوتي. أما ﴿السبيلا﴾ في مشهد أهل النار فجاءت بألف الإطلاق؛ لتناسب امتداد صراخهم وندامتهم وتفجعهم، فكأن الصوت نفسه يطول مع الحسرة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ج1، ص539، مبحث «ألف الإطلاق في الرسولا والسبيلا»؛ النص المباشر.","url":""}]},{"id":"s33-105","number":105,"surah":33,"verses":[26],"references":[{"surah":33,"verses":[26]}],"verseLabel":"الأحزاب: 26","question":"ما دلالة تقديم ﴿فريقًا﴾ في القتل وتأخيره في الأسر: ﴿فريقًا تقتلون وتأسرون فريقًا﴾؟","answer":"قُدِّم الفريق في القتل لأن المقتولين جماعة محددة وقع عليها القتل، فكان إبرازها أنسب. وأُخِّر في الأسر لأن الأسر أوسع امتدادًا وأكثر عددًا، فجيء بالفعل أولًا ليشمل ما تتابع من الأسر، ثم ذُكر الفريق في موضعه الذي يلائم سعة الحدث.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص147–148، مبحث «تقديم فريقًا وتأخيرها»؛ النص المباشر.","url":""}]},{"id":"s33-106","number":106,"surah":33,"verses":[26],"references":[{"surah":33,"verses":[26]}],"verseLabel":"الأحزاب: 26","question":"ما سر الانتقال من الأفعال الماضية ﴿أنزل، قذف﴾ إلى المضارعين ﴿تقتلون وتأسرون﴾؟","answer":"الماضي يحكي ما تمّ من إنزال أهل الكتاب وقذف الرعب في قلوبهم، أما المضارع فيستحضر مشهد القتل والأسر كأنه يقع أمام السامع. وبذلك ينتقل التعبير من الإخبار عن مقدمات انتهت إلى تصوير حيّ لنتائجها المتتابعة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص147–148، مبحث «الماضي والمضارع في آية بني قريظة»؛ النص المباشر.","url":""}]},{"id":"s33-107","number":107,"surah":33,"verses":[28],"references":[{"surah":33,"verses":[28]}],"verseLabel":"الأحزاب: 28","question":"ما سر النداء بوصف النبوة في قوله: ﴿يا أيها النبي قل لأزواجك﴾؟","answer":"المقام متعلق ببيت النبوة وبأزواج النبي ﷺ وما يترتب على منزلتهن من حكم وتخيير وأدب، فكان وصف ﴿النبي﴾ ألصق بالسياق من وصف الرسالة. فالنبوة هنا ليست مجرد نداء، بل أساس الخصوصية التي بُني عليها الحكم.","sources":[{"label":"فاضل السامرائي، سورة الأحزاب – الآية 28: النبي والرسول، عنوان المادة الجزئي «الفرق بين استعمال النبي والرسول».","url":""}]},{"id":"s33-108","number":108,"surah":33,"verses":[35],"references":[{"surah":33,"verses":[35]}],"verseLabel":"الأحزاب: 35","question":"ما دلالة افتتاح صفات المؤمنين بالإسلام وختمها بذكر الله كثيرًا؟","answer":"بدأ بالإسلام لأنه الأصل الظاهر الذي تُبنى عليه سائر الأعمال، ثم جاء الإيمان الباطن وما يتفرع عنه من الطاعة والصدق والصبر. وختم بالذكر لأنه يصاحب الأعمال كلها ويغذيها؛ فصار الذكر خاتمة جامعة لما قبله، كما أن الإسلام مدخل جامع إليه.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: الأحزاب 35 – ترتيب الصفات، مبحث «ترتيب المسلمين والمؤمنين والقانتين… والذاكرين».","url":""}]},{"id":"s33-109","number":109,"surah":33,"verses":[35],"references":[{"surah":33,"verses":[35]}],"verseLabel":"الأحزاب: 35","question":"ما سر التصريح بالمؤمنات مع أن جمع المذكر قد يشمل النساء؟","answer":"التصريح يرفع كل توهم بأن ما سبق من أحكام وفضائل يختص بالرجال، ويقرر المساواة في أصل التكليف والجزاء. وهو ملائم لسياق السورة الذي أفرد نساء النبي بخطاب خاص؛ فبيّن هنا أن أبواب المغفرة والأجر العظيم مفتوحة للرجال والنساء بهذه الصفات.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: الأحزاب 35 – ذكر الرجال والنساء، مبحث «المسلمين والمسلمات والمؤمنين والمؤمنات».","url":""}]},{"id":"s33-110","number":110,"surah":33,"verses":[37],"references":[{"surah":33,"verses":[37]}],"verseLabel":"الأحزاب: 37","question":"ما دلالة قوله: ﴿وتخشى الناس والله أحق أن تخشاه﴾ في سياق إبطال التبنّي؟","answer":"الخشية هنا متصلة بما سيقوله الناس عند زواج النبي ﷺ بمطلقة من كانوا يدعونه ابنًا له، لا بخوف يقدح في تبليغ الرسالة. فالمشهد يكشف ثقل العرف الاجتماعي، ثم يحسمه التشريع عمليًا ليبطل آثار التبنّي الجاهلي.","sources":[{"label":"فاضل السامرائي، قصة زيد وإلغاء التبنّي في الإسلام، مقطع مباشر.","url":""}]},{"id":"s33-111","number":111,"surah":33,"verses":[37,50],"references":[{"surah":33,"verses":[37,50]}],"verseLabel":"الأحزاب: 37، 50","question":"ما سر فصل ﴿لكي لا﴾ في الآية 37 ووصل ﴿لكيلا﴾ في الآية 50؟","answer":"الفصل في ﴿لكي لا يكون على المؤمنين حرج﴾ يُبقي «لا» ظاهرة مستقلة ويبرز نفي الحرج، وهو مقصد تشريعي عام أُجري الفعل من أجله. أما الوصل في ﴿لكيلا يكون عليك حرج﴾ فجاء في حكم خاص بالنبي ﷺ، فناسب اندماج الأداة وتماسك العبارة خصوصية المقام.","sources":[{"label":"فاضل السامرائي، سورة الأحزاب – الآيتان 37 و50: لكي لا ولكيلا، عنوان المادة الجزئي «ما الفرق بين لكي لا ولكيلا؟».","url":""}]},{"id":"s33-112","number":112,"surah":33,"verses":[47],"references":[{"surah":33,"verses":[47]}],"verseLabel":"الأحزاب: 47","question":"ما أثر دخول الباء في قوله: ﴿وبشر المؤمنين بأن لهم من الله فضلًا كبيرًا﴾؟","answer":"الباء تقوي تعلق البشارة بمضمونها وتؤكده، وجاءت في سياق بُسطت فيه أوصاف المؤمنين وأعمالهم وجزاؤهم. فناسب زيادة التفصيل في السياق زيادةُ التوكيد في المبنى، بخلاف مواضع يوجز فيها الخبر فتأتي العبارة من غير الباء.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ج1، ص533، مبحث «دخول الباء في بأن لهم»؛ النص المباشر.","url":""}]},{"id":"s33-113","number":113,"surah":33,"verses":[50],"references":[{"surah":33,"verses":[50]}],"verseLabel":"الأحزاب: 50","question":"ما دقة إفراد العم والخال وجمع العمات والخالات في قوله: ﴿بنات عمك وبنات عماتك وبنات خالك وبنات خالاتك﴾؟","answer":"الإفراد هنا للجنس، فـ﴿عمك﴾ و﴿خالك﴾ يشملان الواحد والمتعدد، وليس المراد حصر القرابة في عم أو خال واحد. واختلاف الإفراد والجمع يحقق تنوعًا في النظم من غير إخلال بالاستغراق، فالمراد جميع بنات هذه الجهات من القرابة.","sources":[{"label":"فاضل السامرائي، سورة الأحزاب – الآية 50: إفراد العم والخال وجمع العمات والخالات، عنوان المادة الجزئي «لماذا أفرد العم والخال وجمع العمات والخالات؟».","url":""}]},{"id":"s33-114","number":114,"surah":33,"verses":[52],"references":[{"surah":33,"verses":[52]}],"verseLabel":"الأحزاب: 52","question":"ما دلالة قوله: ﴿لا يحل لك النساء من بعد ولا أن تبدل بهن﴾ من غير تاء في «تبدل»؟","answer":"﴿تبدّل﴾ بالتخفيف تتعدى مباشرة إلى الشيء المراد استبداله، وهي أوفق بإيجاز الحكم وحسمه. أما ﴿تتبدل﴾ ففيها تاء زائدة في المبنى، وقد تأتي في سياقات يبرز فيها التدرج أو التكلف؛ فاختير الأخف هنا لمباشرة النهي ووضوحه.","sources":[{"label":"فاضل السامرائي، سورة الأحزاب – الآية 52: تبدل وتتبدل، عنوان المادة الجزئي «ما الفرق بين تبدل وتتبدل؟».","url":""}]},{"id":"s33-115","number":115,"surah":33,"verses":[55],"references":[{"surah":33,"verses":[55]}],"verseLabel":"الأحزاب: 55","question":"ما سر التعبير بـ﴿أبناء إخوانهن وأبناء أخواتهن﴾ هنا، وبـ﴿بني إخوانهن وبني أخواتهن﴾ في سورة النور؟","answer":"﴿بني﴾ أوسع في العدد من ﴿أبناء﴾. آية النور خطاب لعموم المؤمنات، فناسبها اللفظ الدال على الكثرة، أما آية الأحزاب فخطابها خاص بنساء النبي ﷺ وهن أقل عددًا، فناسبها جمع القلة ﴿أبناء﴾.","sources":[{"label":"فاضل السامرائي، سورة الأحزاب – الآية 55: الفرق بين بني وأبناء، عنوان المادة الجزئي «الفرق بين بني وأبناء في آيتي النور والأحزاب».","url":""}]},{"id":"s33-116","number":116,"surah":33,"verses":[59],"references":[{"surah":33,"verses":[59]}],"verseLabel":"الأحزاب: 59","question":"ما دلالة الفعل ﴿يدنين﴾ في قوله: ﴿يدنين عليهن من جلابيبهن﴾؟","answer":"الإدناء هو التقريب والإرخاء، فيصوّر حركة مقصودة تُقرّب بها المرأة جلبابها عليها وتسدله بما يحقق الستر. واختيار ﴿يدنين﴾ أدق من مجرد ذكر اللباس؛ لأنه لا يصف الثوب وحده، بل يصف هيئة استعماله وطريقة إحاطته بالجسد.","sources":[{"label":"فاضل السامرائي، سورة الأحزاب – الآية 59: دلالة يدنين والجلباب، عنوان المادة الجزئي «معنى يدنين عليهن من جلابيبهن».","url":""}]},{"id":"s33-117","number":117,"surah":33,"verses":[59],"references":[{"surah":33,"verses":[59]}],"verseLabel":"الأحزاب: 59","question":"ما سر قوله: ﴿ونساء المؤمنين﴾ بعد ﴿لأزواجك وبناتك﴾، وعدم قوله «أزواج المؤمنين وبناتهم»؟","answer":"﴿نساء المؤمنين﴾ أعم؛ فهي تشمل الزوجات والبنات وسائر المؤمنات، فلا يقف الحكم عند علاقتين أسريتين محددتين. أما ذكر أزواج النبي وبناته أولًا فلبيان البدء ببيته ﷺ، ثم تعميم الحكم على نساء المؤمنين جميعًا.","sources":[{"label":"فاضل السامرائي، سورة الأحزاب – الآية 59: نساء المؤمنين، عنوان المادة الجزئي «لماذا قال نساء المؤمنين؟».","url":""}]},{"id":"s33-118","number":118,"surah":33,"verses":[66,67],"references":[{"surah":33,"verses":[66,67]}],"verseLabel":"الأحزاب: 66، 67","question":"ما سر ألف الإطلاق في ﴿أطعنا الله وأطعنا الرسولا﴾ و﴿فأضلونا السبيلا﴾؟","answer":"المشهد مشهد تقلب وجوه في النار وصراخ واعتراف وندامة؛ فجاءت الألف لتطلق الصوت وتمده في ﴿الرسولا﴾ و﴿السبيلا﴾. وهذا الامتداد الصوتي يلائم طول الحسرة وشدة التفجع، بخلاف الموضع الهادئ في أول السورة: ﴿وهو يهدي السبيل﴾.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ج1، ص539، مبحث «ألف الإطلاق في الرسولا والسبيلا»؛ النص المباشر.","url":""}]},{"id":"s33-119","number":119,"surah":33,"verses":[72],"references":[{"surah":33,"verses":[72]}],"verseLabel":"الأحزاب: 72","question":"ما دلالة إسناد حمل الأمانة إلى ﴿الإنسان﴾ دون الجن مع دخولهم في التكليف؟","answer":"ذُكر الإنسان لأنه محور الخطاب القرآني في هذا الموضع، ولأنه الجنس الظاهر الذي تتجلى فيه مسؤولية الاختيار وما يتبعها من طاعة أو ظلم وجهل. ولا يفيد ذلك نفي التكليف عن الجن؛ إنما هو تخصيص بالذكر للمقصود الأول بالسياق، لا حصرٌ للمكلَّفين.","sources":[{"label":"فاضل السامرائي، سورة الأحزاب – الآية 72: حمل الإنسان الأمانة، عنوان المادة الجزئي «لماذا قال وحملها الإنسان ولم يذكر الجن؟».","url":""}]},{"id":"s34-89","number":89,"surah":34,"verses":[2],"references":[{"surah":34,"verses":[2]}],"verseLabel":"سبأ: 2","question":"ما سر حذف ﴿وهو معكم أينما كنتم﴾ هنا، مع ورودها بعد التعبير نفسه في سورة الحديد؟","answer":"سياق الحديد سياق خلق وعمل ومراقبة، وتحيط بالآية عبارات العلم والبصر؛ فناسبه ذكر المعية والمراقبة. أما سياق سبأ فمبني على الآخرة وطيّ صفحة العمل والجزاء، وخُتم بالرحمة والمغفرة؛ فكان حذف عبارة المراقبة أوفق بجو السورة وبختام ﴿الرحيم الغفور﴾.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 2 – اختلاف ختام آيتي سبأ والحديد، مبحث «عدم ذكر وهو معكم أينما كنتم في سبأ».","url":""}]},{"id":"s34-90","number":90,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"ما دلالة الضمير في ﴿لا يعزب عنه﴾ بدل الاسم الظاهر الوارد في يونس: ﴿عن ربك﴾؟","answer":"سبق الضميرَ في سبأ ذكرُ الرب وعالم الغيب: ﴿قل بلى وربي لتأتينكم عالم الغيب﴾، فصار مرجعه حاضرًا، وكان الإضمار أوفق وأبعد عن التكرار. أما في يونس فلم يسبق في السياق القريب اسم يعود عليه الضمير، فاقتضى البيان إظهار ﴿ربك﴾.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 3 – الفروق بينها وبين يونس 61، مبحث «عنه وعن ربك».","url":""}]},{"id":"s34-91","number":91,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"ما دلالة جمع ﴿السماوات﴾ هنا، وإفراد ﴿السماء﴾ في آية يونس المشابهة؟","answer":"قد تدل ﴿السماء﴾ بالإفراد على كل ما علا، فتكون أوسع من السماوات المعدودة؛ لذلك ناسبت سياق يونس القائم على استغراق العلم وإحاطته. أما في سبأ فالمقام متعلق بالساعة لا بتفصيل الاستغراق، فجاءت ﴿السماوات﴾ بحسب ما يقتضيه ذلك السياق.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 3 – الفروق بينها وبين يونس 61، مبحث «السماء والسماوات».","url":""}]},{"id":"s34-92","number":92,"surah":34,"verses":[3],"references":[{"surah":34,"verses":[3]}],"verseLabel":"سبأ: 3","question":"ما سر قوله: ﴿لا يعزب عنه﴾ في سبأ، وقوله: ﴿وما يعزب عن ربك﴾ في يونس؟","answer":"آية يونس تتحدث عن أحوال واقعة: ﴿وما تكون في شأن وما تتلو منه من قرآن﴾، فناسب نفي الحال بـ﴿ما﴾. أما آية سبأ فجواب عن إنكار الساعة الآتية في المستقبل، فناسبها ﴿لا﴾ التي يكثر استعمالها في نفي المستقبل، واتسق النفي مع قولهم: ﴿لا تأتينا الساعة﴾.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 3 – الفروق بينها وبين يونس 61، مبحث «ما يعزب ولا يعزب».","url":""}]},{"id":"s34-93","number":93,"surah":34,"verses":[12],"references":[{"surah":34,"verses":[12]}],"verseLabel":"سبأ: 12","question":"ما سر إفراد الريح في قوله: ﴿ولسليمان الريح﴾ مع أن جمعها يرد غالبًا في مواطن الرحمة؟","answer":"الغالب أن تفرد الريح في سياق الشدة وتجمع في سياق الخير، لكن ريح سليمان لم تُخصّص بوجه واحد؛ فقد سُخرت له يتصرف بها حيث شاء، في الخير أو في غيره. لذلك جاء لفظ الجنس المفرد ﴿الريح﴾ عامًا غير مقيد بوظيفة واحدة.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 12 – دلالة إفراد الريح، مبحث «الريح والرياح».","url":""}]},{"id":"s34-94","number":94,"surah":34,"verses":[14],"references":[{"surah":34,"verses":[14]}],"verseLabel":"سبأ: 14","question":"ما الدقة البيانية في اختيار ﴿منسأته﴾ بدل «عصاه» في قصة سليمان؟","answer":"المنسأة عصا عظيمة يُزجر بها البعير ليساق، ومادتها تدل أيضًا على التأخير. وقد جمعت في القصة المعنيين: ظلت تسوق الجن إلى العمل لظنهم أن سليمان حي، وأخرت انكشاف موته وامتد بها حكمه إلى أن سقطت؛ فكانت أدق من لفظ العصا العام.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص196–197، مبحث «المنسأة والعصا في قصتي سليمان وموسى»؛ النص المباشر.","url":""}]},{"id":"s34-95","number":95,"surah":34,"verses":[33],"references":[{"surah":34,"verses":[33]}],"verseLabel":"سبأ: 33","question":"ما دقة التعبير بـ﴿الندامة﴾ هنا، وبـ﴿الحسرة﴾ في مواضع أخرى؟","answer":"الندامة جنس التأسف على ما فات، أما الحسرة فهي أشد الندم حتى يبلغ بصاحبه الانقطاع والعجز عن التدارك. فاختيار كل لفظ يراعي درجة الشعور في سياقه؛ والحسرة أغلظ وأقسى من مجرد الندامة.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: سبأ 33 – الفرق بين الندامة والحسرة، مبحث «الحسرة أشد الندم».","url":""}]},{"id":"s34-96","number":96,"surah":34,"verses":[33],"references":[{"surah":34,"verses":[33]}],"verseLabel":"سبأ: 33","question":"ما سر اختصاص الوعيد بقوله: ﴿هل يجزون إلا ما كانوا يعملون﴾ وعدم وروده بهذا الأسلوب في خطاب المؤمنين؟","answer":"السيئة تجازى بمثلها، فيناسبها حصر الجزاء في العمل، أما الحسنة فتضاعف ويزاد صاحبها من الفضل؛ لذلك يقال في المؤمنين: ﴿أحسن ما عملوا﴾ و﴿ويزيدهم من فضله﴾. ولو خوطب المؤمن بهذا التركيب لأوهم أن جزاءه لا يتجاوز مقدار عمله.","sources":[{"label":"فاضل السامرائي، هل يجزون إلا ما كانوا يعملون – خصوصية الاستعمال القرآني، مبحث «عدم ورودها في خطاب المؤمنين».","url":""}]},{"id":"s34-97","number":97,"surah":34,"verses":[53],"references":[{"surah":34,"verses":[53]}],"verseLabel":"سبأ: 53","question":"ما الصورة البيانية المدهشة في قوله: ﴿ويقذفون بالغيب من مكان بعيد﴾؟","answer":"يصور أقوالهم في الله والرسالة والبعث برامٍ يقذف هدفًا لا يعرف موضعه، ومن مسافة لا تبلغها رميته؛ فهو لا يعلم ماذا يرمي ولا أين يرمي. هكذا كانت أحكامهم على الغيب ظنونًا جزافية: شاعر أو ساحر، ولا بعث ولا جنة ولا نار، بلا علم ولا دليل.","sources":[{"label":"فاضل السامرائي، سبأ 53: ويقذفون بالغيب من مكان بعيد، عنوان المادة الجزئي «ما معنى هذه الآية؟».","url":""}]},{"id":"s35-62","number":62,"surah":35,"verses":[2,45],"references":[{"surah":35,"verses":[2,45]}],"verseLabel":"فاطر: 2، 45","question":"ما السر في أن تُفتتح السورة برحمة لا يستطيع أحد إمساكها، ثم تُختتم بتأخير العقوبة عن الناس؟","answer":"يكشف ختام السورة صورة عملية للرحمة المذكورة في أولها؛ فلو عوجل الناس بجميع ما كسبوا لم تبق دابة، لكن العقوبة أُخّرت. ودخول لو يفيد امتناع المؤاخذة العامة لوجود رحمة الله، فكأن خاتمة السورة برهان على قوله: ﴿مَا يَفْتَحِ اللَّهُ لِلنَّاسِ مِنْ رَحْمَةٍ فَلَا مُمْسِكَ لَهَا﴾.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «تناسب فواتح سورة فاطر مع خواتيمها»، الفقرة الخاصة بالآيتين 2 و45.","url":""}]},{"id":"s35-63","number":63,"surah":35,"verses":[4,44],"references":[{"surah":35,"verses":[4,44]}],"verseLabel":"فاطر: 4، 44","question":"كيف يحوّل ختام السورة تسلية الرسول في قوله ﴿فَقَدْ كُذِّبَتْ رُسُلٌ مِنْ قَبْلِكَ﴾ إلى حجة مخيفة للمكذبين؟","answer":"أجمل مطلع السورة سنّة التكذيب التي لقيها الرسل، ثم جاء قرب الختام ما يكشف عاقبة المكذبين: ﴿فَيَنْظُرُوا كَيْفَ كَانَ عَاقِبَةُ الَّذِينَ مِنْ قَبْلِهِمْ﴾. فالعلاقة إكمال وبيان: من سار في طريق الأمم المكذبة فليتأمل نهايتها، مهما بلغت قوته.","sources":[{"label":"فاضل السامرائي، تدارس القرآن الكريم: «تناسب فواتح سورة فاطر مع خواتيمها»، الفقرة الخاصة بالآيتين 4 و44.","url":""}]},{"id":"s35-64","number":64,"surah":35,"verses":[9],"references":[{"surah":35,"verses":[9]}],"verseLabel":"فاطر: 9","question":"ما سر الانتقال من الماضي ﴿أَرْسَلَ﴾ إلى المضارع ﴿فَتُثِيرُ﴾، ثم العودة إلى الماضي ﴿فَسُقْنَاهُ﴾؟","answer":"الأحداث كلها واقعة في نسق واحد، لكن إثارة الرياح للسحاب هي موطن الحركة والمشهد الحي؛ فجيء لها بالمضارع ليستحضر السامع السحاب وهو يتكوّن ويتحرك أمامه. ثم عاد التعبير إلى الماضي في ﴿فَسُقْنَاهُ﴾ بعد اكتمال الصورة المتحركة، وهذا من حكاية الحال.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «دلالة اختلاف صيغة الأفعال بين الماضي والمضارع»، مبحث الآية 9.","url":""}]},{"id":"s35-65","number":65,"surah":35,"verses":[10],"references":[{"surah":35,"verses":[10]}],"verseLabel":"فاطر: 10","question":"كيف جمع رفعُ ﴿الْعَمَلُ الصَّالِحُ﴾ بين معنيين لا يؤديهما النصب؟","answer":"رفعُ ﴿العملُ الصالحُ﴾ يفتح احتمالين صحيحين: أن العمل الصالح يرفع الكلم الطيب، وأن الله يرفع العمل الصالح؛ لأن ضمير ﴿يرفعه﴾ يحتمل عوده على الكلم، ويحتمل أن يكون الفاعل المستتر عائدًا إلى الله. أما نصب «العملَ الصالحَ» فيحصر المعنى في أن الله يرفعه، فضاعت سعة الدلالة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص57، مبحث «التوسع في المعنى في قوله: ﴿والعمل الصالح يرفعه﴾»؛ وانظر المقطع المباشر: باحث: «إليه يصعد الكلم الطيب والعمل الصالح يرفعه».","url":""}]},{"id":"s35-66","number":66,"surah":35,"verses":[12],"references":[{"surah":35,"verses":[12]}],"verseLabel":"فاطر: 12","question":"ما دلالة تقديم ﴿فِيهِ﴾ في فاطر: ﴿وَتَرَى الْفُلْكَ فِيهِ مَوَاخِرَ﴾، وتأخيرها في النحل: ﴿وَتَرَى الْفُلْكَ مَوَاخِرَ فِيهِ﴾؟","answer":"سياق فاطر منصبّ على البحرين وخصائصهما، فقدم ضمير البحر ﴿فيه﴾ ليبقى محور الكلام متصلًا بما قبله. أما سياق النحل فسبق فيه تعداد وسائل النقل من الأنعام والخيل والبغال والحمير، فقدم وصف السفن ﴿مواخر﴾ وألصقه بها؛ لأن موطن العناية هناك وسيلة النقل.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «دلالة التقديم والتأخير في وترى الفلك»، مبحث الآية 12.","url":""}]},{"id":"s35-67","number":67,"surah":35,"verses":[25],"references":[{"surah":35,"verses":[25]}],"verseLabel":"فاطر: 25","question":"ما دلالة مجيء التكذيب مضارعًا في ﴿وَإِنْ يُكَذِّبُوكَ﴾، مع وروده ماضيًا في آل عمران: ﴿فَإِنْ كَذَّبُوكَ﴾؟","answer":"المضارع في فعل الشرط يصور التكذيب أمرًا متجددًا مستمرًا، وهو الملائم لمقام فاطر الذي يعرض سنّة المكذبين عبر الزمن. أما الماضي في آل عمران فمتصل بحادثة تاريخية معينة سبق ذكرها، فناسبه الدلالة على وقوع الحدث، لا على استمراره وتجدد صورته.","sources":[{"label":"فاضل السامرائي، لمسات بيانية، ج1، ص536، مبحث «مقام التوكيد في سورة فاطر»؛ النص المباشر في المكتبة القرآنية.","url":""}]},{"id":"s35-68","number":68,"surah":35,"verses":[28],"references":[{"surah":35,"verses":[28]}],"verseLabel":"فاطر: 28","question":"كيف يمنع ضبطُ كلمتي ﴿اللَّهَ﴾ و﴿الْعُلَمَاءُ﴾ انقلابَ المعنى، وما سر القصر بـ﴿إِنَّمَا﴾؟","answer":"لفظ الجلالة منصوب مفعول به، و﴿العلماءُ﴾ فاعل مؤخر مرفوع؛ فالعلماء هم الذين يخشون الله. و﴿إنما﴾ تقصر الخشية الحقة عليهم؛ لأن معرفتهم بقدرة الله وعظمته تجعل خشيتهم أتم من خشية الجاهل، فكلما رسخ العلم بالله عظمت الخشية منه.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «المعنى الإعرابي لقوله إنما يخشى الله من عباده العلماء»، مبحث الآية 28.","url":""}]},{"id":"s35-69","number":69,"surah":35,"verses":[29],"references":[{"surah":35,"verses":[29]}],"verseLabel":"فاطر: 29","question":"ما دلالة ترتيب الأفعال: ﴿يَتْلُونَ﴾ ثم ﴿أَقَامُوا﴾ ثم ﴿أَنْفَقُوا﴾، والعدول من المضارع إلى الماضي؟","answer":"رُتبت الأعمال بحسب الكثرة والاستمرار: تلاوة الكتاب أوسع؛ فهي في الصلاة وخارجها، ثم الصلاة في أوقاتها، ثم الإنفاق وهو أقل تكرارًا. لذلك بدأ بالمضارع الدال على التجدد في ﴿يتلون﴾، وجاء بالماضي في العملين ذوي الأوقات المحددة، مع بقاء الماضي بعد الموصول صالحًا للدلالة على التحقق والاستقبال.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «دلالة استخدام الفعل الماضي والمضارع»، مبحث الآية 29.","url":""}]},{"id":"s35-70","number":70,"surah":35,"verses":[35],"references":[{"surah":35,"verses":[35]}],"verseLabel":"فاطر: 35","question":"ما دقة الجمع بين نفي ﴿نَصَبٌ﴾ ونفي ﴿لُغُوبٌ﴾، ولماذا تقدم النصب؟","answer":"النَّصَب هو التعب والإعياء، واللُّغوب هو الفتور الذي يعقب التعب؛ فرتبهما التعبير من السبب إلى أثره. وقيل أيضًا: النصب تعب البدن واللغوب تعب النفس، فيكون الجمع نفيًا لكل تعب ظاهر وباطن، لا مجرد نفي نوع واحد من المشقة.","sources":[{"label":"فاضل السامرائي، باحث: «معنى النصب واللغوب»، مقطع مباشر من سلسلة سورة فاطر.","url":""}]},{"id":"s35-71","number":71,"surah":35,"verses":[43],"references":[{"surah":35,"verses":[43]}],"verseLabel":"فاطر: 43","question":"ما سر تكرار الجملة مع تغيير كلمة واحدة: ﴿فَلَنْ تَجِدَ لِسُنَّتِ اللَّهِ تَبْدِيلًا وَلَنْ تَجِدَ لِسُنَّتِ اللَّهِ تَحْوِيلًا﴾؟","answer":"ليس التكرار توكيدًا لفظيًا محضًا؛ فـالتبديل نفي أن تُغيّر العقوبة المستحقة إلى شيء آخر أو إلى إكرام، والتحويل نفي أن تُصرف العقوبة عن أهلها إلى قوم آخرين. فسنّة الجزاء لا تتغير في ماهيتها، ولا تنتقل عن مستحقها.","sources":[{"label":"فاضل السامرائي، بوابة إسلاميات: سورة فاطر، «الحكمة من تكرار التركيب: تبديلًا وتحويلًا»، مبحث الآية 43.","url":""}]},{"id":"s35-72","number":72,"surah":35,"verses":[44],"references":[{"surah":35,"verses":[44]}],"verseLabel":"فاطر: 44","question":"ما الدلالة الخفية للواو في ﴿وَكَانُوا أَشَدَّ مِنْهُمْ قُوَّةً﴾؟","answer":"الواو واو الحال، فالمعنى: لينظروا كيف كانت عاقبة السابقين مع أنهم كانوا أشد منهم قوة. وبذلك لا تضيف الآية خبرًا تاريخيًا فحسب، بل تجعل شدة قوتهم حالًا يزيد العبرة رهبة: القوة التي اغتروا بها لم تمنع عنهم العاقبة.","sources":[{"label":"فاضل السامرائي، باحث: «الواو في الآية: وكانوا أشد منهم قوة»، مقطع مباشر من سلسلة سورة فاطر.","url":""}]},{"id":"s35-73","number":73,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"ما سر التعبير بـ﴿بِمَا كَسَبُوا﴾ في فاطر، وبـ﴿بِظُلْمِهِمْ﴾ في آية النحل المشابهة؟","answer":"سياق النحل سبقه وأد البنات، وهو ظلم صريح لا يكون إلا شرًا، فناسبه ﴿بظلمهم﴾. أما فاطر فسياقها في أعمال الأمم، فجاءت بلفظ الكسب الذي يقع في الخير والشر، وإن كان المراد هنا كسب السوء. ثم إن الظلم مصدر مطلق عن الزمن، أما ﴿كسبوا﴾ ففعل ماضٍ مقيد، ولكل منهما ما يلائم سياقه.","sources":[{"label":"فاضل السامرائي، باحث: مقارنة خاتمتي النحل وفاطر، من الدقيقة 1:38 إلى 7:31.","url":""}]},{"id":"s35-74","number":74,"surah":35,"verses":[45],"references":[{"surah":35,"verses":[45]}],"verseLabel":"فاطر: 45","question":"ما سر ختم آية فاطر بـ﴿فَإِنَّ اللَّهَ كَانَ بِعِبَادِهِ بَصِيرًا﴾، وختم نظيرتها في النحل بضبط الأجل: ﴿لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ﴾؟","answer":"سياق فاطر قبل الآية يدور على علم الله وقدرته وصفاته: علم الغيب، والإحاطة بالصدور، وإمساك السماوات والأرض، وعدم إعجاز شيء له؛ فناسبه الختام بصفة البصر المحيط بالعباد. أما سياق النحل فمحوره الناس وأفعالهم وصفاتهم، فناسبه أن يختم بما يقع عليهم عند مجيء أجلهم.","sources":[{"label":"فاضل السامرائي، باحث: مقارنة خاتمتي النحل وفاطر، من الدقيقة 9:42 إلى 13:23.","url":""}]},{"id":"s36-69","number":69,"surah":36,"verses":[2],"references":[{"surah":36,"verses":[2]}],"verseLabel":"يس: 2","question":"ما الأسرار التي جمعها وصف القرآن بأنه ﴿الْحَكِيمِ﴾ في كلمة واحدة؟","answer":"جمع الوصف إحكام القرآن وخلوه من التناقض والباطل، واتصافه بالحكمة ونطقه بها، وكونه حاكمًا مهيمنًا على الأحكام والكتب. فالكلمة لا تؤدي معنى واحدًا، بل تجمع المحكم، وذا الحكمة، والحاكم المهيمن في بناء موجز بالغ.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص6-8، مبحث: «والقرآن الحكيم».","url":""}]},{"id":"s36-70","number":70,"surah":36,"verses":[8],"references":[{"surah":36,"verses":[8]}],"verseLabel":"يس: 8","question":"ما دلالة تقديم ﴿فِي أَعْنَاقِهِمْ﴾ على ﴿أَغْلَالًا﴾ في هذا المشهد المهيب؟","answer":"مدار السياق على هؤلاء المعاندين لا على وصف الأغلال، فَقُدِّم ما يتصل بهم. وترسم الآية هيئة من بلغ الغل ذقنه فارتفع رأسه وتعذر عليه أن يطأطئه أو يبصر طريقه؛ وهي صورة حسية لعجزه عن رؤية صراط الهدى والانقياد له.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص31-33، مبحث: «إنا جعلنا في أعناقهم أغلالًا».","url":""}]},{"id":"s36-71","number":71,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"ما الفرق البياني بين ﴿مَا قَدَّمُوا﴾ و﴿آثَارَهُمْ﴾؟","answer":"﴿ما قدموا﴾ هو ما باشره الإنسان من خير أو شر في حياته، أما ﴿آثارهم﴾ فهي النتائج الممتدة بعده: علم نافع أو سنة حسنة، أو بدعة وضلالة وضرر باقٍ. فالإحصاء لا يقف عند الفعل، بل يتبعه إلى ما ولّده في الناس والزمن.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص55-58، مبحث: «ونكتب ما قدموا وآثارهم».","url":""}]},{"id":"s36-72","number":72,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"ما دلالة تقديم إحياء الموتى على كتابة الأعمال؟","answer":"البعث هو الغاية التي من أجلها تظهر قيمة كتابة الأعمال ويقع الحساب، فناسب أن يتقدم. وهو أيضًا فعل لا يقدر عليه إلا الله، بخلاف الكتابة التي قد توكل إلى الملائكة؛ فتقدم الفعل الأعظم والأخص بالله، ووافق ذلك المحور العام للسورة.","sources":[{"label":"فاضل السامرائي، «تقديم إحياء الموتى على الكتابة» – مقطع مباشر، عنوان المبحث الجزئي: «تقديم إحياء الموتى على الكتاب».","url":""}]},{"id":"s36-73","number":73,"surah":36,"verses":[12],"references":[{"surah":36,"verses":[12]}],"verseLabel":"يس: 12","question":"ما دلالة توكيد إحياء الموتى بقوله: ﴿إِنَّا نَحْنُ نُحْيِي الْمَوْتَى﴾؟","answer":"جاءت ﴿إنَّ﴾ للتوكيد، وجاء ضمير الفصل ﴿نحن﴾ لزيادة التوكيد والقصر؛ فإحياء الموتى لا يملكه إلا الله. وهذا هو المحور الذي يشيع في السورة من أولها إلى آخرها، لذلك جاء تقريره حاسمًا لا يحتمل شركة ولا ترددًا.","sources":[{"label":"فاضل السامرائي، «إنا نحن نحيي الموتى» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة إنا نحن».","url":""}]},{"id":"s36-74","number":74,"surah":36,"verses":[13],"references":[{"surah":36,"verses":[13]}],"verseLabel":"يس: 13","question":"ما سر التعبير بـ﴿إِذْ جَاءَهَا الْمُرْسَلُونَ﴾ بدل الإخبار عن مجيئهم إلى أهلها؟","answer":"﴿جاءها﴾ يدل على أنهم قصدوا القوم في مقرهم وبلغوا الدعوة إلى ديارهم، وفيه تصوير لجدهم في البلاغ وما تحملوه من مشقة. والمجيء أقوى من مطلق الإتيان في هذا السياق، لأنه يلائم ما صاحبه من أذى وتهديد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص67-70، مبحث: «إذ جاءها المرسلون».","url":""}]},{"id":"s36-75","number":75,"surah":36,"verses":[14],"references":[{"surah":36,"verses":[14]}],"verseLabel":"يس: 14","question":"ما دلالة التوكيد في قول الرسل: ﴿إِنَّا إِلَيْكُمْ مُرْسَلُونَ﴾؟","answer":"جاء التوكيد بعد تكذيب القوم للرسولين، فالمقام انتقل من مجرد البلاغ إلى مقابلة الإنكار. كما قُدِّم ﴿إليكم﴾ لإبراز أن الرسالة موجهة إليهم خاصة وأن الحجة قد قامت عليهم.","sources":[{"label":"فاضل السامرائي، «التوكيد في إنا إليكم لمرسلون» – مقطع مباشر، عنوان المبحث الجزئي: «التوكيد في إن إليكم لمرسلون».","url":""}]},{"id":"s36-76","number":76,"surah":36,"verses":[16],"references":[{"surah":36,"verses":[16]}],"verseLabel":"يس: 16","question":"ما دلالة قولهم: ﴿رَبُّنَا يَعْلَمُ إِنَّا إِلَيْكُمْ لَمُرْسَلُونَ﴾؟","answer":"﴿ربنا يعلم﴾ تجري مجرى القسم؛ لذلك جاء جوابها مؤكدًا بإن واللام. واختيار ﴿ربنا﴾ يلائم مقام الرسالة، لأن الرب هو المربي والهادي، فكأنهم يستشهدون بمن تولى تربيتهم وإرسالهم لهداية الخلق.","sources":[{"label":"فاضل السامرائي، «ربنا يعلم إنا إليكم لمرسلون» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة ربنا يعلم».","url":""}]},{"id":"s36-77","number":77,"surah":36,"verses":[18],"references":[{"surah":36,"verses":[18]}],"verseLabel":"يس: 18","question":"ما أثر تكرار لام القسم ونون التوكيد في ﴿لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُمْ﴾؟","answer":"تكرار اللام والنون مع الفعلين يدل على أنهم عازمون على إنفاذ التهديدين معًا، لا على أحدهما فحسب. وزيادة ﴿مِنَّا﴾ تعيّن مصدر العذاب، أي إنهم سيتولونه بأنفسهم، فتشتد نبرة الوعيد والعدوان.","sources":[{"label":"فاضل السامرائي، «لنرجمنكم وليمسنكم منا عذاب أليم» – مقطع مباشر، عنوان المبحث الجزئي: «توكيد التهديد».","url":""}]},{"id":"s36-78","number":78,"surah":36,"verses":[23],"references":[{"surah":36,"verses":[23]}],"verseLabel":"يس: 23","question":"ما سر الجمع بين اسم ﴿الرَّحْمَنُ﴾ وذكر الضر في قوله: ﴿إِنْ يُرِدْنِ الرَّحْمَنُ بِضُرٍّ﴾؟","answer":"المقام مقام طلب الرحمة والنجاة من الضر الذي هدده به قومه، فناسب ذكر الرحمن. وفيه معنى أبلغ: إذا أراد الرحمن نفسه ضرًّا لحكمة، عجزت الآلهة كلها عن دفعه؛ فكيف يُرجى منها نفع أو شفاعة؟","sources":[{"label":"فاضل السامرائي، «إن يردن الرحمن بضر» – مقطع مباشر، عنوان المبحث الجزئي: «اقتران الرحمن بالضر».","url":""}]},{"id":"s36-79","number":79,"surah":36,"verses":[27],"references":[{"surah":36,"verses":[27]}],"verseLabel":"يس: 27","question":"ما دلالة قوله: ﴿مِنَ الْمُكْرَمِينَ﴾ بدل الاكتفاء بوصفه مكرمًا؟","answer":"التعبير يدخله في زمرة المكرمين من الأنبياء والصالحين، فلا يثبت له الإكرام منفردًا فحسب، بل يثبت له الصحبة والانضمام إلى أهل الكرامة. وفي ذلك أنس له ورفع لمقامه بعد ما لقيه من قومه.","sources":[{"label":"فاضل السامرائي، «وجعلني من المكرمين» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة من المكرمين».","url":""}]},{"id":"s36-80","number":80,"surah":36,"verses":[27],"references":[{"surah":36,"verses":[27]}],"verseLabel":"يس: 27","question":"ما سعة المعنى في قوله: ﴿بِمَا غَفَرَ لِي رَبِّي﴾؟","answer":"تحتمل ﴿ما﴾ المصدرية، فيكون المعنى: بمغفرة ربي لي، وتحتمل الموصولية، أي بالسبب أو العمل الذي غفر لي به. وتركها من غير تعيين يجمع المغفرة نفسها وسببها، فيتسع المعنى ولا ينحصر في وجه واحد.","sources":[{"label":"فاضل السامرائي، «بما غفر لي ربي» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة ما في بما غفر لي».","url":""}]},{"id":"s36-81","number":81,"surah":36,"verses":[28],"references":[{"surah":36,"verses":[28]}],"verseLabel":"يس: 28","question":"ما دلالة تكرار ﴿مِنْ﴾ في قوله: ﴿مِنْ بَعْدِهِ مِنْ جُنْدٍ مِنَ السَّمَاءِ﴾؟","answer":"لكل واحدة وظيفة: الأولى تقرر سرعة العقوبة بعده، والثانية تستغرق جنس الجند فتنفي أن يكون قد نزل جندي واحد أو أكثر، والثالثة تبين جهة الجند. وفي هذا تحقير لشأن القوم؛ فما احتاج إهلاكهم إلى جيش سماوي، بل كفتهم صيحة واحدة.","sources":[{"label":"فاضل السامرائي، «وما أنزلنا على قومه من بعده من جند» – مقطع مباشر، عنوان المبحث الجزئي: «دلالات من المتكررة».","url":""}]},{"id":"s36-82","number":82,"surah":36,"verses":[33],"references":[{"surah":36,"verses":[33]}],"verseLabel":"يس: 33","question":"ما سر تقديم ﴿آيَةٌ﴾ في قوله: ﴿وَآيَةٌ لَهُمُ الْأَرْضُ الْمَيْتَةُ﴾؟","answer":"السياق في تعداد الآيات، فكان تقديم الآية أنسب من تقديم المخاطبين. كما أن قول ﴿لهم آية﴾ قد يوهم اختصاص الآية بهم، بينما إحياء الأرض آية عامة للخلق، وإن سيقت هنا حجة لهؤلاء خاصة.","sources":[{"label":"فاضل السامرائي، «وآية لهم الأرض الميتة» – مقطع مباشر، عنوان المبحث الجزئي: «تقديم آية».","url":""}]},{"id":"s36-83","number":83,"surah":36,"verses":[35],"references":[{"surah":36,"verses":[35]}],"verseLabel":"يس: 35","question":"ما سر اختلاف الترتيب بين ﴿فَمِنْهُ يَأْكُلُونَ﴾ و﴿لِيَأْكُلُوا مِنْ ثَمَرِهِ﴾؟","answer":"الحب قوت مستمر يعتمد عليه، فَقُدِّم ﴿منه﴾ للاهتمام بهذا الأصل الغذائي. أما الثمر فموسمي وليس كل الطعام، فلم يقدم الجار والمجرور كيلا يوهم الحصر أو المبالغة في الاعتماد عليه، فجاء كل ترتيب ملائمًا لطبيعة المذكور.","sources":[{"label":"فاضل السامرائي، «الآيتان 34 و35 من سورة يس» – مقطع مباشر، عنوان المبحث الجزئي: «منه يأكلون ومن ثمره».","url":""}]},{"id":"s36-84","number":84,"surah":36,"verses":[37],"references":[{"surah":36,"verses":[37]}],"verseLabel":"يس: 37","question":"ما دلالة قوله: ﴿فَإِذَا هُمْ مُظْلِمُونَ﴾ بدل وصف الأرض بالظلام؟","answer":"نقل التعبير أثر الظاهرة إلى الإنسان؛ فهم الذين يدخلون في الظلام وتتبدل حياتهم به، فتظهر النعمة في تعاقب الضياء والإظلام عليهم. و﴿إذا﴾ ترسم مفاجأة التحول وسرعته، فلا يملكون رد الليل إذا أقبل.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص176-181، مبحث: «فإذا هم مظلمون».","url":""}]},{"id":"s36-85","number":85,"surah":36,"verses":[40],"references":[{"surah":36,"verses":[40]}],"verseLabel":"يس: 40","question":"ما دلالة جمع الفعل في قوله: ﴿وَكُلٌّ فِي فَلَكٍ يَسْبَحُونَ﴾؟","answer":"الجمع يصور الأجرام كلها وهي تتحرك في وقت واحد، كلٌّ في فلكه، في نظام متناسق. واستعمال جمع العقلاء يشخصها كأنها سابحون منضبطون يعرف كل منهم مساره، فيبعث المشهد معنى الحركة الحية والأمان الكوني.","sources":[{"label":"فاضل السامرائي، «لا الشمس ينبغي لها أن تدرك القمر» – مقطع مباشر، عنوان المبحث الجزئي: «كل في فلك يسبحون».","url":""}]},{"id":"s36-86","number":86,"surah":36,"verses":[43],"references":[{"surah":36,"verses":[43]}],"verseLabel":"يس: 43","question":"ما سعة المعنى في قوله: ﴿فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنْقَذُونَ﴾؟","answer":"﴿صريخ﴾ تحتمل المغيث، والمستغيث، والصراخ نفسه؛ فينتفي من ينقذهم، ومن يستغيث لهم، بل حتى قدرتهم على الصراخ. ثم جاء ﴿ولا هم ينقذون﴾ لينفي كل وسيلة نجاة أخرى، ولو لم تكن بواسطة مغيث.","sources":[{"label":"فاضل السامرائي، «معنى الصريخ» – مقطع مباشر، عنوان المبحث الجزئي: «معنى الصريخ».","url":""}]},{"id":"s36-87","number":87,"surah":36,"verses":[50],"references":[{"surah":36,"verses":[50]}],"verseLabel":"يس: 50","question":"ما سر اختلاف ترتيب الكلمات بين ﴿فَلَا يَسْتَطِيعُونَ تَوْصِيَةً﴾ و﴿وَلَا إِلَى أَهْلِهِمْ يَرْجِعُونَ﴾؟","answer":"تقديم الفعل في الأولى ينفي القدرة على أية توصية أصلًا؛ ولو قدمت التوصية لأمكن أن يفهم أنهم يعجزون عنها ويقدرون على غيرها. أما تقديم ﴿إلى أهلهم﴾ في الثانية فيخص نفي الرجوع إلى الأهل، مع الإيحاء برجوع محتوم إلى جهة أخرى هي موقف الحساب.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص238-241، مبحث: «فلا يستطيعون توصية ولا إلى أهلهم يرجعون».","url":""}]},{"id":"s36-88","number":88,"surah":36,"verses":[53],"references":[{"surah":36,"verses":[53]}],"verseLabel":"يس: 53","question":"ما دلالة ﴿جَمِيعٌ لَدَيْنَا مُحْضَرُونَ﴾ بدل التعبير بأنهم مجموعون عند الله؟","answer":"﴿جميع﴾ على وزن فعيل بمعنى مجموع، وهي تلائم مشهدًا وقع وصار حاضرًا، لا خبرًا مستقبليًا فحسب. و﴿لدينا﴾ أخص من «عندنا» في الحضور والقرب، وتقديمها يفيد أنهم محضرون لدى الله وحده لا لدى غيره.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص260-262، مبحث: «فإذا هم جميع لدينا محضرون».","url":""}]},{"id":"s36-89","number":89,"surah":36,"verses":[54],"references":[{"surah":36,"verses":[54]}],"verseLabel":"يس: 54","question":"ما سعة نفي الظلم في قوله: ﴿لَا تُظْلَمُ نَفْسٌ شَيْئًا﴾؟","answer":"تنكير ﴿نفس﴾ يعم كل نفس، و﴿شيئًا﴾ تحتمل المفعول المطلق، أي لا تظلم شيئًا من الظلم ولو قليلًا، وتحتمل المفعول به، أي لا تنقص شيئًا من حقوقها. فجمع التعبير نفي جنس الظلم ونفيه في أي حق أو جزاء.","sources":[{"label":"فاضل السامرائي، «فاليوم لا تظلم نفس شيئًا» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة نفس وشيئًا».","url":""}]},{"id":"s36-90","number":90,"surah":36,"verses":[60],"references":[{"surah":36,"verses":[60]}],"verseLabel":"يس: 60","question":"ما دلالة ندائهم بـ﴿يَا بَنِي آدَمَ﴾ عند التحذير من عبادة الشيطان؟","answer":"هذا النداء يوقظ فيهم قصة أبيهم آدم مع إبليس، فيجعل عصيانهم امتدادًا لعداوة قديمة معلومة. ويستعمل التعبير في القرآن في مقام التذكير بقصة آدم والشيطان أو في مقام التكريم، وهنا جاء ليقيم الحجة عليهم من تاريخ أبيهم.","sources":[{"label":"فاضل السامرائي، «ألم أعهد إليكم يا بني آدم» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة يا بني آدم».","url":""}]},{"id":"s36-91","number":91,"surah":36,"verses":[62],"references":[{"surah":36,"verses":[62]}],"verseLabel":"يس: 62","question":"ما أثر قوله: ﴿جِبِلًّا كَثِيرًا﴾ في تصوير كثرة من أضلهم الشيطان؟","answer":"﴿جبلًّا﴾ تدل في ذاتها على الخلق الكثير، ثم جاء وصفها بـ﴿كثيرًا﴾ فصار المعنى كثرة فوق كثرة، أو كثرة كاثرة متراكمة. فليس المراد جمعًا كبيرًا فحسب، بل أجيال وجموع هائلة استجابوا للشيطان.","sources":[{"label":"فاضل السامرائي، «ولقد أضل منكم جبلًّا كثيرًا» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة جبلًّا كثيرًا».","url":""}]},{"id":"s36-92","number":92,"surah":36,"verses":[63],"references":[{"surah":36,"verses":[63]}],"verseLabel":"يس: 63","question":"ما أثر اسم الإشارة القريب في قوله: ﴿هَذِهِ جَهَنَّمُ الَّتِي كُنْتُمْ تُوعَدُونَ﴾؟","answer":"ينقل التعبير المكذبين إلى مشهد الآخرة كأنهم واقفون على شفير جهنم يرونها رأي العين؛ لذلك قيل ﴿هذه﴾ لا «تلك». ثم جاء ﴿توعدون﴾ جوابًا ساخرًا مرعبًا عن سؤالهم المتكرر: متى هذا الوعد؟ فها هو حاضر أمامهم.","sources":[{"label":"فاضل السامرائي، «هذه جهنم التي كنتم توعدون» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة هذه وتوعدون».","url":""}]},{"id":"s36-93","number":93,"surah":36,"verses":[64],"references":[{"surah":36,"verses":[64]}],"verseLabel":"يس: 64","question":"ما سر التعبير بـ﴿كُنْتُمْ تَكْفُرُونَ﴾ بدل صيغة ماضية موجزة؟","answer":"التركيب يدل على الاستمرار في الكفر في الزمن الماضي، لا على وقوعه مرة عابرة. وهو يقابل ﴿كنتم توعدون﴾: كان الوعد يتكرر وكانوا يقابلونه بالكفر المتكرر؛ كما أن إطلاق الكفر يتسع لكفر العقيدة وكفران النعمة.","sources":[{"label":"فاضل السامرائي، «اصلوها اليوم بما كنتم تكفرون» – مقطع مباشر، عنوان المبحث الجزئي: «كنتم تكفرون».","url":""}]},{"id":"s36-94","number":94,"surah":36,"verses":[67],"references":[{"surah":36,"verses":[67]}],"verseLabel":"يس: 67","question":"ما دلالة تقديم المضي على الرجوع في قوله: ﴿فَمَا اسْتَطَاعُوا مُضِيًّا وَلَا يَرْجِعُونَ﴾؟","answer":"المضي إلى الأمام أصعب لأنه ذهاب إلى طريق أو غاية قد لا يعرفها المرء، أما الرجوع فعادة إلى طريق مألوف ومحل إقامة. فبدأ بالأصعب ثم نفى عنهم الأيسر أيضًا، ليبلغ تصوير العجز غايته: لا تقدم ولا عودة ولا حركة.","sources":[{"label":"فاضل السامرائي، «ولو نشاء لمسخناهم على مكانتهم» – مقطع مباشر، عنوان المبحث الجزئي: «تقديم المضي على الرجوع».","url":""}]},{"id":"s36-95","number":95,"surah":36,"verses":[69],"references":[{"surah":36,"verses":[69]}],"verseLabel":"يس: 69","question":"ما سر مجيء نفي الشعر بعد مشهد كلام الأيدي وشهادة الأرجل؟","answer":"قد يتوهم المكذب أن مشاهد الختم على الأفواه ونطق الجوارح من خيال الشعراء وتصويرهم، فجاء النفي ليقرر أنها حقائق لا خيالات شعرية. فالآية ترد تهمة الشعر، وتثبت في الوقت نفسه صدق المشاهد العجيبة التي سبقتها.","sources":[{"label":"فاضل السامرائي، «وما علمناه الشعر وما ينبغي له» – مقطع مباشر، عنوان المبحث الجزئي: «ارتباط نفي الشعر بما قبله».","url":""}]},{"id":"s36-96","number":96,"surah":36,"verses":[71],"references":[{"surah":36,"verses":[71]}],"verseLabel":"يس: 71","question":"ما دلالة اختيار ﴿خَلَقْنَا لَهُمْ﴾ في الحديث عن الأنعام؟","answer":"«خلقنا لهم» أقوى في الامتنان من مجرد جعل الأنعام لهم، لأنه يرجع بالنعمة إلى أصل إيجادها مخصوصة لمنافعهم. وقد فصّل السياق تمام النعمة بالخلق والتمليك والتذليل والمنافع والمشارب، فناسبه اللفظ الأدعى إلى الشكر.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص336-342، مبحث: «خلقنا لهم مما عملت أيدينا أنعامًا».","url":""}]},{"id":"s36-97","number":97,"surah":36,"verses":[71,72],"references":[{"surah":36,"verses":[71,72]}],"verseLabel":"يس: 71، 72","question":"ما سر تدرج النعمة من خلق الأنعام إلى تمليكها ثم تذليلها؟","answer":"لا تتم منفعة الأنعام بمجرد وجودها؛ فذكر أولًا خلقها لهم، ثم كونهم مالكين لها، ثم انقيادها للصغير والكبير. ولو كانت نافرة متوحشة لتعذر ركوبها وحلبها والانتفاع بها، فجمع التدرج أصل النعمة وتمامها.","sources":[{"label":"فاضل السامرائي، «وذللناها لهم» – مقطع مباشر، عنوان المبحث الجزئي: «الخلق والتمليك والتذليل».","url":""}]},{"id":"s36-98","number":98,"surah":36,"verses":[73],"references":[{"surah":36,"verses":[73]}],"verseLabel":"يس: 73","question":"ما سعة التعبير بكلمة ﴿مَشَارِبُ﴾ بدل الاكتفاء بذكر الشراب؟","answer":"المشارب تشمل ما يُشرب من الأنعام كاللبن، وتشمل ما يُتخذ من جلودها أو أجزائها أوعيةً وآلات للشرب. ولو قيل «شراب» لانحصر المعنى في السائل المشروب، فجاء الجمع ليوسع دائرة المنافع.","sources":[{"label":"فاضل السامرائي، «ولهم فيها منافع ومشارب» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة مشارب».","url":""}]},{"id":"s36-99","number":99,"surah":36,"verses":[76],"references":[{"surah":36,"verses":[76]}],"verseLabel":"يس: 76","question":"ما اللطف البياني في قوله: ﴿فَلَا يَحْزُنْكَ قَوْلُهُمْ﴾؟","answer":"لم يأت النهي بصيغة مباشرة للرسول عن الحزن، بل جُعل قولهم هو الفاعل المنهي عن إحزانه؛ فكأن العناية الإلهية تخاطب أقوالهم: لا تحزنوا رسولي. وفي ذلك تكريم بالغ وتسلية ورعاية للنبي ﷺ.","sources":[{"label":"فاضل السامرائي، «فلا يحزنك قولهم» – مقطع مباشر، عنوان المبحث الجزئي: «دلالة فلا يحزنك قولهم».","url":""}]},{"id":"s36-100","number":100,"surah":36,"verses":[77],"references":[{"surah":36,"verses":[77]}],"verseLabel":"يس: 77","question":"ما المفارقة المدهشة بين ﴿مِنْ نُطْفَةٍ﴾ و﴿خَصِيمٌ مُبِينٌ﴾؟","answer":"تنقل الآية الإنسان فجأة من أصله الضعيف المهين إلى حالته قادرًا على البيان والخصام، فتقيم دليل القدرة من جهة، وتفضح جحوده من جهة أخرى. فالذي أنعم عليه بالعقل واللسان جعل هذه النعمة أداة لمخاصمة خالقه وإنكار البعث.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص365-370، مبحث: «فإذا هو خصيم مبين».","url":""}]},{"id":"s36-101","number":101,"surah":36,"verses":[79],"references":[{"surah":36,"verses":[79]}],"verseLabel":"يس: 79","question":"ما سر ختم جواب البعث بقوله: ﴿وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ﴾؟","answer":"إعادة الأجساد تقتضي علمًا شاملًا بكل ذرة تفرقت من كل مخلوق وأين استقرت، فجاء ﴿عليم﴾ مطلق الدلالة مناسبًا لهذا الشمول. أما ﴿علّام﴾ فاختص في الاستعمال القرآني بالغيوب، بينما المقام هنا علم الخلق كله وتفاصيله.","sources":[{"label":"فاضل السامرائي، «وهو بكل خلق عليم» – مقطع مباشر، عنوان المبحث الجزئي: «عليم وعلام».","url":""}]},{"id":"s36-102","number":102,"surah":36,"verses":[83],"references":[{"surah":36,"verses":[83]}],"verseLabel":"يس: 83","question":"ما جمال الارتباط بين مطلع السورة وخاتمتها في ﴿وَإِلَيْهِ تُرْجَعُونَ﴾؟","answer":"بدأت السورة بإرسال الرسول: ﴿إِنَّكَ لَمِنَ الْمُرْسَلِينَ﴾، وانتهت برجوع الخلق إلى من أرسله. فجمع البناء رحلة التكليف كلها: إرسال من الله، وبلاغ في الدنيا، ثم رجوع إليه للحساب؛ ولذلك قُدِّم ﴿إليه﴾ لقصر الرجوع عليه وحده.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص377-381، مبحث: «ارتباط خاتمة يس بمطلعها».","url":""}]},{"id":"s37-101","number":101,"surah":37,"verses":[4,5,180,182],"references":[{"surah":37,"verses":[4,5,180,182]}],"verseLabel":"الصافات: 4، 5، 180، 182","question":"كيف عادت خاتمة السورة إلى مطلعها في تناسق بياني محكم؟","answer":"افتتحت السورة بتوحيد الربوبية: ﴿إِنَّ إِلَهَكُمْ لَوَاحِدٌ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا﴾، وختمت بتنزيه هذا الرب وحمده بوصفه ﴿رَبِّ الْعَالَمِينَ﴾. فالمطلع ذكر مُلكه للسموات والأرض، والخاتمة جمعت عوالمها كلها تحت ربوبيته وحمده، فالتقى أول السورة بآخرها.","sources":[{"label":"فاضل السامرائي، «تناسب فاتحة سورة الصافات مع خاتمتها»، مادة إلكترونية مباشرة من بحث «تناسب فواتح سور القرآن الكريم مع خواتيمها».","url":""}]},{"id":"s37-102","number":102,"surah":37,"verses":[8],"references":[{"surah":37,"verses":[8]}],"verseLabel":"الصافات: 8","question":"ما سر التعبير المشدد ﴿لَا يَسَّمَّعُونَ﴾ بدل صيغة «لا يتسمعون»؟","answer":"أصل الصيغة «يتسمعون»، ثم أُبدلت التاء وأُدغمت، فاجتمع في اللفظ تشديدان يدلان على قوة الحدث ومبالغتهم في طلب السماع. وهم يريدون بلوغ أقصى التسمع في أقصر وقت قبل أن تدركهم الشهب، فجاء اللفظ المكثف مصورًا شدة المحاولة وسرعتها.","sources":[{"label":"فاضل السامرائي، «ما اللمسة البيانية في يسَّمَّعون؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-103","number":103,"surah":37,"verses":[22],"references":[{"surah":37,"verses":[22]}],"verseLabel":"الصافات: 22","question":"ما سر التعبير بـ﴿أَزْوَاجَهُمْ﴾؟ وهل المراد زوجاتهم؟","answer":"المراد أشباه الظالمين ونظراؤهم في العمل، فيُحشر أصحاب الذنب الواحد بعضهم مع بعض. فالزوج في أصل الاستعمال هو القرين المماثل أو المقابل، ولذلك اتسع اللفظ هنا ليصوّر جمع كل طائفة مع من يشاكلها، لا جمع الرجال مع زوجاتهم فحسب.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص131، مبحث «الفرق بين الزوج والبعل».","url":""}]},{"id":"s37-104","number":104,"surah":37,"verses":[31],"references":[{"surah":37,"verses":[31]}],"verseLabel":"الصافات: 31","question":"ما الدلالة المخيفة في قولهم: ﴿فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَا﴾؟","answer":"«حق القول» و«حقت الكلمة» يردان في الاستعمال القرآني عند ثبوت العذاب ووجوبه على من استحقه. فالعبارة ليست مجرد تحقق خبر، بل إقرار بأن الوعيد السابق قد صار نافذًا فيهم، وأن كلمة ملء جهنم قد استقرت عليهم فلا مهرب منها.","sources":[{"label":"فاضل السامرائي، «ما معنى حق القول؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-105","number":105,"surah":37,"verses":[42],"references":[{"surah":37,"verses":[42]}],"verseLabel":"الصافات: 42","question":"ما دلالة اختيار جمع ﴿فَوَاكِهُ﴾ هنا، واختيار اسم الجنس ﴿فَاكِهَةٍ﴾ للسابقين في سورة الواقعة؟","answer":"«فاكهة» اسم جنس يشمل الواحد والمثنى والجمع، والنوع الواحد والأنواع المتعددة، ولذلك هو أعم من «فواكه». ولما كان نعيم السابقين أعلى قيل في الواقعة: ﴿وَفَاكِهَةٍ مِمَّا يَتَخَيَّرُونَ﴾، أما هنا فجاء الجمع «فواكه» بما يلائم الدرجة المذكورة في السياق.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين فاكهة وفواكه؟»، منصة باحث.","url":""}]},{"id":"s37-106","number":106,"surah":37,"verses":[45,47],"references":[{"surah":37,"verses":[45,47]}],"verseLabel":"الصافات: 45، 47","question":"ما سر بناء ﴿يُطَافُ عَلَيْهِمْ﴾ للمفعول، ومناسبته لقوله: ﴿يُنزَفُونَ﴾؟","answer":"جاء الطواف هنا مبنيًا لما لم يسم فاعله، وكذلك جاء «يُنزفون» على البناء نفسه، فانسجم بناء الفعلين في هذا المشهد. أما في سورة الواقعة فقيل: ﴿يَطُوفُ عَلَيْهِمْ وِلْدَانٌ﴾ مع قراءة «يَنزِفون» بالبناء للمعلوم؛ فانتظم كل سياق على نسقه التعبيري الخاص.","sources":[{"label":"فاضل السامرائي، «الفرق بين نعيم الصافات ونعيم السابقين في الواقعة»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-107","number":107,"surah":37,"verses":[47],"references":[{"surah":37,"verses":[47]}],"verseLabel":"الصافات: 47","question":"كيف جمع التعبير ﴿لَا فِيهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنزَفُونَ﴾ بين سلامة الشراب وسلامة شاربه؟","answer":"نفى أولًا «الغول» عن الخمر نفسها، فلا تغتال العقل ولا تفسد البدن، ثم نفى «الإنزاف» عن الشارب، فلا يسكر ولا ينفد شرابه. فالأول وصف لسلامة المشروب، والثاني وصف لسلامة من يشربه ودوام متعته، فتم نفي آفات خمر الدنيا من الجانبين.","sources":[{"label":"فاضل السامرائي، «الفرق بين: لا يصدعون عنها ولا ينزفون، ولا فيها غول ولا هم عنها ينزفون»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-108","number":108,"surah":37,"verses":[65],"references":[{"surah":37,"verses":[65]}],"verseLabel":"الصافات: 65","question":"كيف يصنع تشبيه ﴿طَلْعُهَا كَأَنَّهُ رُءُوسُ الشَّيَاطِينِ﴾ صورة مرعبة مع أن الطرفين غائبان عن الحس؟","answer":"هذا تشبيه تخييلي يطلق الذهن في أقبح صورة يستطيع تصورها؛ فالناس لم يروا طلع الزقوم ولا رؤوس الشياطين، لكن صورة الشيطان مستقرة في الخيال رمزًا لأقصى القبح. وبدل أن يحد التشبيه هيئة واحدة، يترك لكل نفس أن تستحضر أفظع ما تتخيله من منظر.","sources":[{"label":"فاضل السامرائي، «ما الحكمة من تشبيه طلع الزقوم برؤوس الشياطين؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-109","number":109,"surah":37,"verses":[75,76],"references":[{"surah":37,"verses":[75,76]}],"verseLabel":"الصافات: 75، 76","question":"ما سر الواو في ﴿وَنَجَّيْنَاهُ وَأَهْلَهُ﴾، والفاء في نظيرها بسورة الأنبياء: ﴿فَنَجَّيْنَاهُ﴾؟","answer":"مقام الأنبياء أشد؛ فقد ذُكر تكذيب القوم ووصفهم بالسوء، ونصرة نوح عليهم ثم إغراقهم أجمعين، فناسبت الفاء سرعة الإجابة والنجاة في ذلك الكرب. أما الصافات فلم يذكر فيها القوم ولا شدة المواجهة بتلك التفاصيل، فجاءت الواو لمطلق الجمع من غير دلالة التعقيب السريع.","sources":[{"label":"فاضل السامرائي، «المقارنة بين: فاستجبنا له فنجيناه وأهله، ونجيناه وأهله»، منصة باحث.","url":""}]},{"id":"s37-110","number":110,"surah":37,"verses":[79],"references":[{"surah":37,"verses":[79]}],"verseLabel":"الصافات: 79","question":"ما سر تنكير ﴿سَلَامٌ﴾ في تحية نوح وسائر المرسلين؟","answer":"الأصل في النكرة العموم والشمول، فـ«سلام» أوسع من «السلام» المعرّف الذي قد يدل على سلام معين. ولهذا جاءت تحية الله في القرآن بالتنكير لتشمل كل جنس السلام ولا تدع منه شيئًا، سواء في سلامه على رسله أو في تحية أهل الجنة.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين سلام والسلام؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-111","number":111,"surah":37,"verses":[86],"references":[{"surah":37,"verses":[86]}],"verseLabel":"الصافات: 86","question":"كيف وسّع نصب ﴿إِفْكًا﴾ دائرة التوبيخ في قوله: ﴿أَئِفْكًا آلِهَةً دُونَ اللَّهِ تُرِيدُونَ﴾؟","answer":"يحتمل «إفكًا» أن يكون مفعولًا به، أي: أتريدون إفكًا، وتكون «آلهة» بدلًا منه؛ ويحتمل الحالية، أي: أتريدون آلهة حال كونكم آفكين؛ ويحتمل المفعول لأجله. هذا الاتساع النحوي يجمع توبيخهم على إرادة الباطل، وعلى اتخاذ الآلهة، وعلى حالهم في الافتراء.","sources":[{"label":"فاضل السامرائي، «أئفكًا آلهة دون الله تريدون: إعراب أئفكًا»، منصة باحث.","url":""}]},{"id":"s37-112","number":112,"surah":37,"verses":[98],"references":[{"surah":37,"verses":[98]}],"verseLabel":"الصافات: 98","question":"ما دلالة الفاء في ﴿فَأَرَادُوا بِهِ كَيْدًا﴾، والواو في نظيرها بسورة الأنبياء: ﴿وَأَرَادُوا بِهِ كَيْدًا﴾؟","answer":"في الصافات سبقت الآيةَ دعوتُهم المباشرة: ﴿ابْنُوا لَهُ بُنْيَانًا فَأَلْقُوهُ فِي الْجَحِيمِ﴾، فجاءت الفاء لتفيد ترتب إرادة الكيد وتعقيبها على هذا القرار قبل التنفيذ. أما في الأنبياء فذُكرت إرادة الكيد بعد وقوع الإلقاء وجعل النار بردًا وسلامًا، فلم يناسبها التعقيب بالفاء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص157-161، مبحث «قصة إبراهيم بين الأنبياء والصافات».","url":""}]},{"id":"s37-113","number":113,"surah":37,"verses":[101],"references":[{"surah":37,"verses":[101]}],"verseLabel":"الصافات: 101","question":"ما سر وصف إسماعيل بـ﴿حَلِيمٍ﴾، ووصف إسحاق في مواضع أخرى بـ﴿عَلِيمٍ﴾؟","answer":"الحلم يظهر في مخالطة الناس وضبط النفس، وقد أبرز السياق علاقة إسماعيل بأبيه وقبوله أمر الذبح وصبره، كما عُرف بصدق الوعد ومشاركة أبيه في بناء البيت. أما سياق إسحاق فأبرز العلم والنبوة من غير عرض لمخالطة مماثلة؛ فالصفة المختارة هي الأبرز في المقام، ولا تنفي سائر الكمالات.","sources":[{"label":"فاضل السامرائي، «الغلامان الحليم والعليم»، منصة باحث.","url":""}]},{"id":"s37-114","number":114,"surah":37,"verses":[102],"references":[{"surah":37,"verses":[102]}],"verseLabel":"الصافات: 102","question":"ما سر المضارع في ﴿إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ﴾ مع أن الرؤيا وقعت؟","answer":"المضارع يستحضر الرؤيا الماضية ويجعل صورتها حاضرة أمام السامع لشدة أهميتها، وهو ما يسمى حكاية الحال. ويُذكر كذلك أن الرؤيا تكررت، فناسبها ما يفيد التجدد؛ فصار المشهد حيًّا مستمرًا لا خبرًا ماضيًا بعيدًا.","sources":[{"label":"فاضل السامرائي، «دلالة صيغة المضارع في: إني أرى في المنام»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-115","number":115,"surah":37,"verses":[116],"references":[{"surah":37,"verses":[116]}],"verseLabel":"الصافات: 116","question":"ما سر قوله: ﴿فَكَانُوا هُمُ الْغَالِبِينَ﴾ بعد قوله: ﴿وَنَصَرْنَاهُمْ﴾، مع أن مواضع أخرى عبرت بـ«جعلناهم»؟","answer":"سبق الفعلَ هنا التصريحُ بأن الله نجاهم ونصرهم، فدل السياق على أن غلبتهم ثمرة لذلك النصر: نصرهم فكانوا هم الغالبين. أما في قصة إبراهيم فقيل: ﴿فَجَعَلْنَاهُمُ الْأَسْفَلِينَ﴾ لأن قلب حال الكائدين وإسقاطهم هو جعل إلهي مباشر أبرزته الآية.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص157-161، مبحث «جعلناهم الأسفلين وفكانوا هم الغالبين».","url":""}]},{"id":"s37-116","number":116,"surah":37,"verses":[130],"references":[{"surah":37,"verses":[130]}],"verseLabel":"الصافات: 130","question":"ما سر التعبير بـ﴿إِلْ يَاسِينَ﴾ بدل «إلياس»؟","answer":"الأسماء الأعجمية تتصرف فيها العرب بصور متعددة، مثل «سيناء» و«سينين»، وقد يكون للنبي أكثر من اسم مستعمل في قومه، فيقال إلياس وإل ياسين. وتوجد قراءة «آل ياسين» التي تجعل السلام على أهله وأتباعه؛ فتعدد القراءة والاستعمال يفتح المعنى ولا يخل به.","sources":[{"label":"فاضل السامرائي، «لم قيل: سلام على إل ياسين؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s37-117","number":117,"surah":37,"verses":[133,148],"references":[{"surah":37,"verses":[133,148]}],"verseLabel":"الصافات: 133، 148","question":"ما سر تأخير السلام على لوط ويونس وعدم إفرادهما بقول: «سلام على...» عقب قصتيهما؟","answer":"ذُكرت في قصة يونس مؤاخذة ترك الأولى بألفاظ ﴿أَبَقَ﴾ و﴿مُلِيمٌ﴾، فلا يناسب أن يعقب ذلك مباشرة بالسلام الخاص. وفي قصة لوط انتقل الكلام سريعًا إلى أهله وقومه وآثارهم، ولم تُعرض دعوته كما عُرضت دعوة غيره؛ ثم شملهما السلام العام في خاتمة السورة: ﴿وَسَلَامٌ عَلَى الْمُرْسَلِينَ﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص126، مبحث «السلام على الرسل في سورة الصافات».","url":""}]},{"id":"s37-118","number":118,"surah":37,"verses":[139,148],"references":[{"surah":37,"verses":[139,148]}],"verseLabel":"الصافات: 139، 148","question":"ما سر تفصيل قصة يونس في الصافات أكثر من سائر مواضعها؟","answer":"اختص هذا الموضع بسلسلة المشاهد كاملة: إباقه إلى الفلك، والمساهمة، والتقام الحوت، والنبذ بالعراء، وإنبات اليقطين، ثم إرساله إلى قومه وذكر عددهم وإيمانهم. أما المواضع الأخرى فتنتقي جانب الدعاء أو العتاب بحسب مقصد السياق؛ فالتفصيل هنا مقصود لإبراز الرحلة من الشدة إلى النجاة ثم الرسالة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص197-198، مبحث «قصة يونس في الصافات».","url":""}]},{"id":"s37-119","number":119,"surah":37,"verses":[159,180],"references":[{"surah":37,"verses":[159,180]}],"verseLabel":"الصافات: 159، 180","question":"ما سر قوله أولًا: ﴿سُبْحَانَ اللَّهِ عَمَّا يَصِفُونَ﴾، ثم قوله في الخاتمة: ﴿سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ﴾؟","answer":"جاء التنزيه الأول بعد دعوى واحدة هي اتخاذ الولد، فكفى فيها ﴿سُبْحَانَ اللَّهِ﴾. أما الخاتمة فجاءت بعد الوعد القطعي بنصر المرسلين وغلبة جند الله وتهديد المكذبين بالعذاب؛ فناسب مقام القوة والنصر إضافة ﴿رَبِّ الْعِزَّةِ﴾، إذ العزة هي الصفة المحورية في السياق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص58-61، مبحث «تنوع صيغ التسبيح عما يصفون».","url":""}]},{"id":"s37-120","number":120,"surah":37,"verses":[171],"references":[{"surah":37,"verses":[171]}],"verseLabel":"الصافات: 171","question":"ما دلالة اللام في ﴿سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا الْمُرْسَلِينَ﴾، ومقابلتها بـ«سبق عليه القول»؟","answer":"إذا عُدي السبق باللام كان فيما ينفع ويُبشّر، كما هنا في كلمة النصر للمرسلين؛ وإذا عُدي بـ«على» جاء في الوعيد والعقوبة، نحو «سبق عليه القول». فاختيار الحرف يرسم اتجاه الكلمة: اللام إيصال خير إلى أصحابها، و«على» استعلاء حكم العذاب عليهم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج3، ص155-156، مبحث «سبق له وسبق عليه».","url":""}]},{"id":"s37-121","number":121,"surah":37,"verses":[175,179],"references":[{"surah":37,"verses":[175,179]}],"verseLabel":"الصافات: 175، 179","question":"ما سر ذكر المفعول في ﴿وَأَبْصِرْهُمْ﴾ أولًا، ثم حذفه في ﴿وَأَبْصِرْ﴾؟","answer":"الرؤية الأولى متجهة إلى قوم معينين وما نزل بهم يوم بدر من قتل وأسر وهزيمة، فذُكر الضمير لتعيينهم: ﴿أَبْصِرْهُمْ﴾. أما الثانية فاتصلت بفتح مكة وما امتد من أثره هداية ورحمة وفتحًا عامًا لجزيرة العرب، فأُطلق الفعل بحذف المفعول ليتسع مجال الإبصار ولا ينحصر في جماعة بعينها.","sources":[{"label":"فاضل السامرائي، أسرار البيان في التعبير القرآني، مبحث «الذكر والحذف: وأبصرهم وأبصر»، نص الكتاب الإلكتروني المباشر.","url":""}]},{"id":"s37-122","number":122,"surah":37,"verses":[180],"references":[{"surah":37,"verses":[180]}],"verseLabel":"الصافات: 180","question":"ما أثر وصف الله في الخاتمة بأنه ﴿رَبِّ الْعِزَّةِ﴾؟","answer":"سبقت الخاتمةَ كلمات النصر والغلبة: ﴿إِنَّهُمْ لَهُمُ الْمَنْصُورُونَ﴾ و﴿إِنَّ جُنْدَنَا لَهُمُ الْغَالِبُونَ﴾، ثم جاء الوعيد بنزول العذاب. فاختير «رب العزة» ليقرر أن العزة كلها ملكه وتحت ربوبيته، وأن النصر والغلبة أثران من آثارها، وتنزه صاحبها عما يصفه به المشركون.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص58-61، مبحث «سبحان ربك رب العزة عما يصفون».","url":""}]},{"id":"s38-95","number":95,"surah":38,"verses":[5],"references":[{"surah":38,"verses":[5]}],"verseLabel":"ص: 5","question":"ما دلالة وصف توحيد الآلهة بأنه ﴿لَشَيْءٌ عُجَابٌ﴾، مع توكيد الجملة باللام؟","answer":"تعددت عند المشركين دواعي العجب؛ عجبوا من مجيء منذر منهم، ثم اشتد عجبهم من دعوته إلى إله واحد وهم عريقون في الشرك. فناسب تراكم العجب توكيد الجملة باللام، واختيار «عُجاب» الدالة على المبالغة، لا مجرد «عجيب».","sources":[{"label":"فاضل السامرائي، «الفرق بين عُجاب وعَجَبًا»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-96","number":96,"surah":38,"verses":[9],"references":[{"surah":38,"verses":[9]}],"verseLabel":"ص: 9","question":"ما سر تقييد الخزائن بالرحمة في ﴿خَزَائِنُ رَحْمَةِ رَبِّكَ﴾، وإتباعها بالاسمين ﴿الْعَزِيزِ الْوَهَّابِ﴾؟","answer":"لما قُيّدت الخزائن بخزائن الرحمة ناسبها «الوهاب»؛ فالرحمة هبة، ولا يهب إلا من يملك. وناسبها «العزيز» لأن التصرف في تلك الخزائن لا يكون إلا لصاحب العزة والغلبة، فجاء الاسمان متممين لمعنى الرحمة والملك والهبة.","sources":[{"label":"فاضل السامرائي، «الفرق بين خزائن رحمة ربك وخزائن ربك»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-97","number":97,"surah":38,"verses":[17],"references":[{"surah":38,"verses":[17]}],"verseLabel":"ص: 17","question":"ما دلالة إضافة داود إلى ضمير العظمة في قوله: ﴿وَاذْكُرْ عَبْدَنَا دَاوُودَ﴾؟","answer":"وصف الإنسان نفسه بالعبودية تواضع، أما وصف الله له بأنه «عبدنا» فتكريم ووسام؛ لأنه إثبات للعبودية الاختيارية الكاملة، ثم إن إضافته إلى ضمير العظمة تزيد معنى التشريف والقرب والرعاية.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص163، مبحث «دلالة وصف النبي بالعبد وإضافته إلى ضمير العظمة».","url":""}]},{"id":"s38-98","number":98,"surah":38,"verses":[18],"references":[{"surah":38,"verses":[18]}],"verseLabel":"ص: 18","question":"ما دلالة تقديم ﴿الْجِبَالَ﴾ على الظرف في قوله: ﴿إِنَّا سَخَّرْنَا الْجِبَالَ مَعَهُ﴾؟","answer":"توسع سياق سورة ص في شأن الجبال والطير، فذكر تسبيح الجبال بالعشي والإشراق، ثم حشر الطير وأوبتها؛ لذلك قُدّمت الجبال لتكون موضع العناية. أما آية الأنبياء فأوجزت الخبر، فناسب كل ترتيب مقدار التفصيل في سياقه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص180-181، مبحث «تسخير الجبال مع داود في الأنبياء وص».","url":""}]},{"id":"s38-99","number":99,"surah":38,"verses":[24],"references":[{"surah":38,"verses":[24]}],"verseLabel":"ص: 24","question":"ما سر التعبير بقوله: ﴿وَخَرَّ رَاكِعًا﴾ بدل «خر ساجدًا»؟","answer":"الركوع يأتي بمعنى الخضوع وتطأطؤ الرأس، و«الخرور» هو الهوي إلى الأمام؛ فالمعنى أنه خر من حال خضوعه حتى سجد. كما أن القرآن خص تعبير «خروا سجدًا» غالبًا بسماع آيات الله وتلاوتها، وهنا ذُكر خلاف الأولى في الحكم، فناسبه التعبير بالركوع.","sources":[{"label":"فاضل السامرائي، «الفرق بين الركوع والسجود في: وخر راكعًا»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-100","number":100,"surah":38,"verses":[30],"references":[{"surah":38,"verses":[30]}],"verseLabel":"ص: 30","question":"ما سر حذف المخصوص بالمدح في قوله: ﴿نِعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ﴾؟","answer":"يجوز حذف المخصوص بالمدح إذا كان معلومًا من السياق؛ فقد سبق ذكر سليمان، فلا يحتاج المقام إلى إعادة اسمه. والحذف هنا يشد الانتباه إلى صفة العبودية والأوبة نفسها، ويجعل المدح أسرع وأقوى اتصالًا بما قبله.","sources":[{"label":"فاضل السامرائي، «نعم العبد إنه أواب: من المخصوص بالمدح وما سبب حذفه؟»، منصة باحث.","url":""}]},{"id":"s38-101","number":101,"surah":38,"verses":[32],"references":[{"surah":38,"verses":[32]}],"verseLabel":"ص: 32","question":"ما جمال عودة الضمير في ﴿حَتَّى تَوَارَتْ بِالْحِجَابِ﴾ إلى الشمس مع أنها لم تُذكر؟","answer":"دل السياق على الشمس دلالة تغني عن التصريح بها؛ فالتواري بالحجاب عند العشي لا يلتبس بغير غروبها. والحذف يحقق الإيجاز، ويجعل المشهد حاضرًا في الذهن حتى كأن الشمس معلومة مشاهدة لا تحتاج إلى تسمية.","sources":[{"label":"فاضل السامرائي، «عودة الضمير على غير مذكور دل عليه السياق»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-102","number":102,"surah":38,"verses":[41],"references":[{"surah":38,"verses":[41]}],"verseLabel":"ص: 41","question":"ما الفرق البياني بين ﴿مَسَّنِيَ الشَّيْطَانُ بِنُصْبٍ وَعَذَابٍ﴾ هنا و﴿مَسَّنِيَ الضُّرُّ﴾ في سورة الأنبياء؟","answer":"يعبّر «مسني الشيطان» عن وسوسة الشيطان وما دخل النفس بسببها، أما «مسني الضر» فيعبّر عن المرض والشدة الواقعة في البدن والحال. فليستا عبارتين عن حالة واحدة من كل وجه، بل كل موضع أبرز جانبًا من ابتلاء أيوب يناسب سياقه.","sources":[{"label":"فاضل السامرائي، «ما معنى مسني الشيطان بنصب وعذاب؟»، منصة باحث.","url":""}]},{"id":"s38-103","number":103,"surah":38,"verses":[41],"references":[{"surah":38,"verses":[41]}],"verseLabel":"ص: 41","question":"ما دلالة التصريح بفعل الأمر ﴿وَاذْكُرْ عَبْدَنَا أَيُّوبَ﴾، بينما حُذف «اذكر» في قصص سورة الأنبياء؟","answer":"بنيت سورة ص على محور الذكر منذ مطلعها: ﴿وَالْقُرْآنِ ذِي الذِّكْرِ﴾؛ لذلك تكرر فيها الأمر ﴿واذكر﴾ مع قصص الأنبياء. أما سورة الأنبياء فتعطف أسماءهم على فعل مقدر، فجاء التصريح في ص متسقًا مع خيطها اللفظي والدلالي.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص191-195، مبحث «التناسب بين ذي الذكر وتكرار واذكر في سورة ص».","url":""}]},{"id":"s38-104","number":104,"surah":38,"verses":[43],"references":[{"surah":38,"verses":[43]}],"verseLabel":"ص: 43","question":"ما دلالة ﴿وَذِكْرَى لِأُولِي الْأَلْبَابِ﴾ هنا، مقابل ﴿وَذِكْرَى لِلْعَابِدِينَ﴾ في سورة الأنبياء؟","answer":"العابدون أولو ألباب وزيادة؛ فالعبادة تتضمن العقل الذي يصح به التكليف ثم العمل بمقتضاه. ولما كان سياق الأنبياء أوسع في مشاهد العبادة والاستجابة جاء بـ«العابدين»، أما سورة ص فغلب فيها خطاب التذكر والتدبر، فناسبها «أولو الألباب».","sources":[{"label":"فاضل السامرائي، «ذكرى للعابدين وذكرى لأولي الألباب»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-105","number":105,"surah":38,"verses":[43],"references":[{"surah":38,"verses":[43]}],"verseLabel":"ص: 43","question":"ما دلالة ﴿وَوَهَبْنَا لَهُ أَهْلَهُ﴾ هنا، مقابل ﴿وَآتَيْنَاهُ أَهْلَهُ﴾ في سورة الأنبياء؟","answer":"الإيتاء أعم من الهبة؛ فقد يكون هبة أو تمليكًا أو إعطاء حكم وعلم وكتاب، ولذلك يحمل معنى أوسع. وسياق الأنبياء أتم في إظهار الاستجابة وكشف الضر، فناسبه الأعم «آتيناه»، أما سورة ص فجرى فيها خيط الهبة والوهاب، فناسبها «وهبنا».","sources":[{"label":"فاضل السامرائي، «قصة أيوب بين آتيناه ووهبنا له»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-106","number":106,"surah":38,"verses":[44],"references":[{"surah":38,"verses":[44]}],"verseLabel":"ص: 44","question":"ما أثر حذف اسم أيوب من المدح في ﴿نِعْمَ الْعَبْدُ إِنَّهُ أَوَّابٌ﴾؟","answer":"سبق قوله ﴿إِنَّا وَجَدْنَاهُ صَابِرًا﴾ فعُلم أن الممدوح أيوب، فحُذف اسمه استغناء بالسياق. وبذلك اتصل الجزاء بالسبب مباشرة: صبرٌ أثبته الله، ثم مدحٌ بالعبودية والأوبة، من غير فاصل يبدد قوة الارتباط.","sources":[{"label":"فاضل السامرائي، «من المخصوص بالمدح وما سبب حذفه؟»، منصة باحث.","url":""}]},{"id":"s38-107","number":107,"surah":38,"verses":[45,48],"references":[{"surah":38,"verses":[45,48]}],"verseLabel":"ص: 45، 48","question":"ما سر وصف بعض الأنبياء بـ﴿عِبَادَنَا﴾، ثم حذف هذا الوصف عند إسماعيل واليسع وذي الكفل؟","answer":"مَن وصفهم بالعبودية فصّل أخبارهم وذكر ما تفضل به عليهم من النعم والاصطفاء، فناسب التفصيلُ ذكرَ صفة التكريم. أما إسماعيل واليسع وذو الكفل فذُكروا في آية موجزة بلا تفصيل لتلك المنح، فناسب الإيجازُ الإيجازَ وحُذفت الصفة.","sources":[{"label":"فاضل السامرائي، قبسات من البيان القرآني، ص289-291، مبحث «ذكر صفة العبد لأنبياء سورة ص وحذفها».","url":""}]},{"id":"s38-108","number":108,"surah":38,"verses":[51],"references":[{"surah":38,"verses":[51]}],"verseLabel":"ص: 51","question":"ما دلالة وصف أهل الجنة بأنهم ﴿مُتَّكِئِينَ فِيهَا﴾ قبل ذكر الفاكهة والشراب؟","answer":"الاتكاء غاية الراحة؛ فهو هيئة من لا ينتظر خطرًا ولا يستعد لعمل شاق. وجاء في القرآن غالبًا مع الطعام والشراب والمجالس الآمنة، فتصدره للمشهد يصور طمأنينة أهل الجنة قبل أن يعرض ما يدعونه من فاكهة كثيرة وشراب.","sources":[{"label":"فاضل السامرائي، «دلالة استعمال متكئين لأهل الجنة»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-109","number":109,"surah":38,"verses":[73],"references":[{"surah":38,"verses":[73]}],"verseLabel":"ص: 73","question":"ما سر تذكير الفعل في ﴿فَسَجَدَ الْمَلَائِكَةُ﴾ مع جواز تأنيثه؟","answer":"جمع التكسير يجوز معه التذكير والتأنيث نحويًا، لكن الاستعمال القرآني يختار التذكير للملائكة في أفعال العبادة والقوة والأوامر الصادرة إليهم. ولما كان السجود عبادة وامتثالًا جاء الفعل مذكرًا، موافقًا لهذا الخط التعبيري.","sources":[{"label":"فاضل السامرائي، «سر تذكير الفعل وتأنيثه مع الملائكة»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-110","number":110,"surah":38,"verses":[84,85],"references":[{"surah":38,"verses":[84,85]}],"verseLabel":"ص: 84، 85","question":"ما الدلالة الحاسمة في وصل ﴿فَالْحَقُّ وَالْحَقَّ أَقُولُ﴾ بقوله: ﴿لَأَمْلَأَنَّ جَهَنَّمَ﴾؟","answer":"هذا هو القول الحق الذي ثبت به الوعيد على إبليس وأتباعه؛ ولذلك ارتبطت عبارة «حق القول» في الاستعمال القرآني بثبوت العذاب ووجوبه. واجتماع الحق مع لام القسم ونون التوكيد في ﴿لأملأن﴾ يصور الحكم واقعًا لا مرد له.","sources":[{"label":"فاضل السامرائي، «ما معنى حق القول؟»، تدارس القرآن الكريم.","url":""}]},{"id":"s38-111","number":111,"surah":38,"verses":[87,88],"references":[{"surah":38,"verses":[87,88]}],"verseLabel":"ص: 87، 88","question":"كيف أحكم ختام السورة ﴿إِنْ هُوَ إِلَّا ذِكْرٌ لِلْعَالَمِينَ﴾ صلته بمطلعها ﴿وَالْقُرْآنِ ذِي الذِّكْرِ﴾؟","answer":"افتتحت السورة بوصف القرآن بأنه ذو الذكر، ثم سرت مادة الذكر في أوامر ﴿واذكر﴾، وفي التذكر وذكرى الدار و﴿هذا ذكر﴾، وختمت بكونه ذكرًا للعالمين. فصار الذكر إطارًا يضم السورة كلها، ويجعل ﴿ولتعلمن نبأه بعد حين﴾ خاتمة إنذار لمن أعرض عن ذلك الذكر.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج4، ص191-195، مبحث «التناسب بين مطلع سورة ص وخاتمتها وتردد مادة الذكر».⋮ Top of Form Bottom of Form","url":""}]},{"id":"s39-146","number":146,"surah":39,"verses":[3,75],"references":[{"surah":39,"verses":[3,75]}],"verseLabel":"الزمر: 3، 75","question":"كيف تجيب خاتمة السورة عن مطلعها في الانتقال من ﴿إِنَّ اللَّهَ يَحْكُمُ بَيْنَهُمْ﴾ إلى ﴿وَقُضِيَ بَيْنَهُم بِالْحَقِّ﴾؟","answer":"افتتحت السورة بوعد الحكم في اختلاف المشركين، ثم عرضت الخصومة والموت والبعث ومصير الفريقين، حتى انتهت إلى وقوع ما وُعد به: ﴿وقضي بينهم بالحق﴾. فالحكم في المطلع إعلان لما سيكون، والقضاء في الخاتمة إنجاز وفصل نهائي؛ وبذلك تنغلق بنية السورة على تمام العدل والحمد.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ج1، ص122–125، مبحث «من سورتي المؤمنون والزمر»، عنوان جزئي: «مناسبة الاختصام لمفتتح سورة الزمر وخاتمتها»؛ وانظر المادة الإلكترونية المباشرة بعنوان «تناسب فواتح سورة الزمر مع خواتيمها».","url":""}]},{"id":"s39-147","number":147,"surah":39,"verses":[7],"references":[{"surah":39,"verses":[7]}],"verseLabel":"الزمر: 7","question":"ما دلالة تقديم الكفر على الشكر في قوله ﴿إِن تَكْفُرُوا... وَإِن تَشْكُرُوا﴾، مع أن الغالب في القرآن تقديم الشكر؟","answer":"جاء الترتيب منسجمًا مع جو السورة؛ فقد سبق الحديث عن الكاذب الكفار واتخاذ الأولياء من دون الله، فكان الكفر هو المعنى المتقدم في السياق. وكذلك تعرض الخاتمة مصير الكافرين قبل مصير المتقين، فجاء ترتيب الشرطين في الآية صورة مصغرة للترتيب العام في السورة.","sources":[{"label":"فاضل السامرائي، «سر تقديم الكفر على الشكر في سورة الزمر»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-148","number":148,"surah":39,"verses":[10,53],"references":[{"surah":39,"verses":[10,53]}],"verseLabel":"الزمر: 10، 53","question":"ما سر حذف ياء المتكلم في ﴿قُلْ يَا عِبَادِ الَّذِينَ آمَنُوا﴾، وإثباتها في ﴿قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا﴾؟","answer":"تناسب سعة اللفظ سعة الجماعة في الاستعمال القرآني الذي تتبعه السامرائي؛ فصيغة «عبادي» أطول، وجاءت مع المسرفين وهم أكثر عددًا. أما «عبادِ» المحذوفة الياء فجاءت مع من حققوا الإيمان والتقوى والصبر، وهؤلاء أقل، فوافق قِصر المبنى قلة الجماعة.","sources":[{"label":"فاضل السامرائي، «ما الفرق بين عباد وعبادي؟»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-149","number":149,"surah":39,"verses":[17],"references":[{"surah":39,"verses":[17]}],"verseLabel":"الزمر: 17","question":"ما سر عود ضمير المؤنث الجمع في ﴿أَن يَعْبُدُوهَا﴾ على «الطاغوت»؟","answer":"«الطاغوت» لفظ يستعمل للمفرد والجمع، وللمذكر والمؤنث بحسب السياق. وقد دل قوله قبلها ﴿فَاعْبُدُوا مَا شِئْتُم مِّن دُونِهِ﴾ على تعدد المعبودات، فحُمل الطاغوت هنا على جماعة الأصنام غير العاقلة، ولذلك عاد عليه ضمير المؤنث الجمع «ها».","sources":[{"label":"فاضل السامرائي، «دلالة تأنيث الضمير في: اجتنبوا الطاغوت أن يعبدوها»، برنامج لمسات بيانية، الوقفة الخاصة بالآية 17.","url":""}]},{"id":"s39-150","number":150,"surah":39,"verses":[23],"references":[{"surah":39,"verses":[23]}],"verseLabel":"الزمر: 23","question":"ما سر إطلاق الخشية في ﴿يَخْشَوْنَ رَبَّهُمْ﴾ من غير تقييدها بـ«الغيب»؟","answer":"اقشعرار الجلد ولين القلب حالان باطنتان لا يطلع على حقيقتهما إلا صاحبهما وربه؛ فمعنى الغيب داخل في الصورة نفسها. ولو قيل «بالغيب» لم يضف القيد معنى يحتاجه المقام، فجاء التعبير مطلقًا محكمًا من غير زيادة لا تؤدي وظيفة.","sources":[{"label":"فاضل السامرائي، «سر عدم ذكر بالغيب في آية الزمر»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-151","number":151,"surah":39,"verses":[29],"references":[{"surah":39,"verses":[29]}],"verseLabel":"الزمر: 29","question":"ما دلالة التثنية في ﴿هَلْ يَسْتَوِيَانِ مَثَلًا﴾، بينما جاء في سورة النحل ﴿هَلْ يَسْتَوُونَ﴾؟","answer":"المثل في الزمر عرض رجلين معينين في الصورة: رجلًا تتنازعه شركاء، ورجلًا خالصًا لسيد واحد؛ فناسبت التثنية «يستويان». أما موضع النحل فالتعبير فيه بـ«من» يفتح الوصف لفئة وأفراد متعددين، فناسبه جمع الضمير «يستوون».","sources":[{"label":"فاضل السامرائي، «الفرق بين هل يستويان وهل يستوون»، برنامج لمسات بيانية، الوقفة الخاصة بالآية 29.","url":""}]},{"id":"s39-152","number":152,"surah":39,"verses":[30],"references":[{"surah":39,"verses":[30]}],"verseLabel":"الزمر: 30","question":"ما الفرق البياني بين «مَيِّت» بتشديد الياء و«مَيْت» بتسكينها؟","answer":"«الميْت» بالتسكين يقال في الأصل لمن تحقق موته، حقيقة أو مجازًا. أما «الميّت» بالتشديد فيصح أن يطلق على الحي الذي سيؤول حتمًا إلى الموت؛ ولذلك جاء ﴿إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ﴾ خطابًا لأحياء سيقع عليهم الموت يقينًا.","sources":[{"label":"فاضل السامرائي، «الفرق بين مَيْت ومَيِّت في القرآن»، برنامج لمسات بيانية، الوقفة الخاصة بالآية 30.","url":""}]},{"id":"s39-153","number":153,"surah":39,"verses":[38],"references":[{"surah":39,"verses":[38]}],"verseLabel":"الزمر: 38","question":"ما سر الماضي في ﴿إِنْ أَرَادَنِيَ اللَّهُ بِضُرٍّ﴾، والمضارع واسم «الرحمن» في ﴿إِن يُرِدْنِ الرَّحْمَنُ بِضُرٍّ﴾ بسورة يس؟","answer":"الماضي مع الشرط يصير مستقبل المعنى، لكنه كثيرًا ما يصور افتراض وقوع الحدث مرة، أما المضارع فيحتمل تجدده وتكرره؛ وصاحب يس يتوقع استمرار التهديد والضر، فكأنه يلوذ بالرحمن ويستدعي رحمته. كما وافق اسم «الله» كثرة وروده في الزمر، واسم «الرحمن» جو سورة يس وتكرره فيها.","sources":[{"label":"فاضل السامرائي، «الفرق بين إن أرادني الله وإن يردن الرحمن»، برنامج لمسات بيانية.","url":""}]},{"id":"s39-154","number":154,"surah":39,"verses":[54],"references":[{"surah":39,"verses":[54]}],"verseLabel":"الزمر: 54","question":"ما دلالة الرفع في ﴿ثُمَّ لَا تُنصَرُونَ﴾ بعد الفعل المنصوب ﴿أَن يَأْتِيَكُمُ الْعَذَابُ﴾؟","answer":"«ثم» هنا ليست عاطفة تجعل «لا تنصرون» تابعًا للفعل المنصوب، وإنما هي استئنافية افتتح بها خبر جديد. فالمعنى: أنيبوا وأسلموا قبل مجيء العذاب؛ ثم إن جاءكم فلن تنصروا. واستقلال الجملة يجعل نفي النصرة حكمًا حاسمًا بعد فوات زمن الإنابة.","sources":[{"label":"فاضل السامرائي، «دلالة ثم الاستئنافية في: ثم لا تنصرون»، برنامج لمسات بيانية، الوقفة الخاصة بالآية 54.","url":""}]},{"id":"s39-155","number":155,"surah":39,"verses":[73],"references":[{"surah":39,"verses":[73]}],"verseLabel":"الزمر: 73","question":"أين جواب ﴿حَتَّى إِذَا جَاؤُوهَا﴾، وما السر البلاغي في حذفه؟","answer":"حُذف جواب الشرط تفخيمًا لما يلقاه أهل الجنة؛ لأن تعيين جواب محدود يضيّق صورة النعيم، أما تركه فيفتح الخيال على ما تعجز العبارة عن الإحاطة به. فكأن المعنى: إذا جاؤوها وفتحت أبوابها واستُقبلوا بالسلام رأوا من الكرامة ما لا تبلغه اللغة.","sources":[{"label":"فاضل السامرائي، «اللغة تعجز أن تعبر عن نعيم الجنة: الجواب هناك»، مقطع مباشر على منصة «باحث».","url":""}]},{"id":"s40-200","number":200,"surah":40,"verses":[6],"references":[{"surah":40,"verses":[6]}],"verseLabel":"غافر: 6","question":"ما الذي تحسمه عبارة ﴿حَقَّتْ كَلِمَتُ رَبِّكَ﴾ قبل التصريح بأنهم أصحاب النار؟","answer":"«حقَّ القول» و«حقَّت الكلمة» تعبيران قرآنيان يدلان على ثبوت العذاب ووجوبه على من استحقه، لا على مجرد وقوع قولٍ أو صدور حكم. فجاء التعبير ليصور أن الكفر المتتابع أوصلهم إلى حكم ثابت لا مدفع له، ثم كشفت الجملة التالية مضمون تلك الكلمة: ﴿أَنَّهُمْ أَصْحَابُ النَّارِ﴾.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، ما معنى «حق القول» و«حقت الكلمة»؟ – تدارس القرآن الكريم.","url":""}]},{"id":"s40-201","number":201,"surah":40,"verses":[36,37],"references":[{"surah":40,"verses":[36,37]}],"verseLabel":"غافر: 36، 37","question":"ما دلالة ﴿أَسْبَابَ السَّمَاوَاتِ﴾، وهل طلب فرعون بناء الصرح بحثًا عن الحقيقة أم تمويهًا على قومه؟","answer":"الأسباب هي الوسائل والطرق الموصلة إلى الغاية، فزعم فرعون أنه يريد بلوغ طرق السماوات والاطلاع إلى إله موسى. ولم يكن طلبه ناشئًا عن بحث مخلص؛ فقد كان يجحد ما استيقنته نفسه، وإنما اتخذ الصرح وسيلة للسخرية والتلبيس وإدامة سلطانه، ولذلك عقب النظم بأن سوء عمله زُيّن له وأن كيده في تباب.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، ما معنى «أسباب السماوات»، وهل كان فرعون موحدًا؟ – تدارس القرآن الكريم.","url":""}]},{"id":"s40-202","number":202,"surah":40,"verses":[45],"references":[{"surah":40,"verses":[45]}],"verseLabel":"غافر: 45","question":"ما سر جمع ﴿سَيِّئَاتِ مَا مَكَرُوا﴾ وإفراد ﴿سُوءُ الْعَذَابِ﴾ في آية واحدة؟","answer":"«السيئة» عمل قبيح مخصوص، وتُجمع على «سيئات»؛ ومكر آل فرعون اشتمل على أعمال وخطط قبيحة متعددة، فناسبه الجمع. أما «السوء» فأعم من السيئة، ويقع على كل ما يسوء من فعل أو عذاب، وهو اسم مصدر يشمل القليل والكثير ولا يُجمع إلا عند إرادة الأنواع؛ فناسب إحاطة العذاب بهم أن يقال ﴿سوء العذاب﴾.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، الفرق بين السوء والسيئة في قوله «سيئات ما مكروا... سوء العذاب» – تدارس القرآن الكريم.","url":""}]},{"id":"s40-203","number":203,"surah":40,"verses":[58],"references":[{"surah":40,"verses":[58]}],"verseLabel":"غافر: 58","question":"ما دلالة زيادة التاء في ﴿قَلِيلًا مَا تَتَذَكَّرُونَ﴾، مع ورود «تذكّرون» محذوفة التاء في مواضع أخرى؟","answer":"زيادة المبنى هنا تلائم زيادة زمن التأمل؛ فآية غافر لا تقتصر على المقارنة البديهية بين الأعمى والبصير، بل تنتقل إلى الإيمان والعمل الصالح والإساءة، وهي قضية تحتاج إلى نظر أطول وتذكّر أعمق. أما المقارنة التي يُدرك جوابها فورًا، مثل عدم استواء الأعمى والبصير، فيناسبها اللفظ الأخف: «تذكّرون».","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، الفرق بين «تذكرون» و«تتذكرون» – تدارس القرآن الكريم.","url":""}]},{"id":"s40-204","number":204,"surah":40,"verses":[67],"references":[{"surah":40,"verses":[67]}],"verseLabel":"غافر: 67","question":"ما سر الانتقال من ﴿ثُمَّ مِنْ عَلَقَةٍ﴾ إلى الجملة الفعلية ﴿ثُمَّ يُخْرِجُكُمْ طِفْلًا﴾؟","answer":"المعطوف الحقيقي هو الفعل ﴿يخرجكم﴾ على الفعل الأول ﴿خلقكم﴾، أما «من تراب ثم من نطفة ثم من علقة» فمتعلقات متتابعة بالفعل الأول تصف مواد الخلق ومراحله. وبالعودة إلى الفعل بعد هذه المتعلقات يستأنف النظم الحدث الرئيس: خلقكم، ثم يخرجكم طفلًا؛ فتنتظم المراحل مع بقاء البناء النحوي محكمًا.","sources":[{"label":"فاضل السامرائي، سورة غافر، الآية 67: من أمثلة العطف في القرآن – بوابة إسلاميات.","url":""}]},{"id":"s40-205","number":205,"surah":40,"verses":[78,85],"references":[{"surah":40,"verses":[78,85]}],"verseLabel":"غافر: 78، 85","question":"ما سر ختم المشهد الأول بـ﴿وَخَسِرَ هُنَالِكَ الْمُبْطِلُونَ﴾، وختم السورة بـ﴿وَخَسِرَ هُنَالِكَ الْكَافِرُونَ﴾؟","answer":"الفاصلة الأولى سبقتها عبارة ﴿قُضِيَ بِالْحَقِّ﴾، ومقابل الحق الباطل، فكان الأنسب ﴿المبطلون﴾. أما ختام السورة فسبقته عبارة ﴿فَلَمْ يَكُ يَنْفَعُهُمْ إِيمَانُهُمْ﴾، ومقابل الإيمان الكفر، فكان الأنسب ﴿الكافرون﴾. هكذا تنبثق كل فاصلة من المعنى الأقرب إليها، ولا تؤدي إحداهما دقة الأخرى في موضعها.","sources":[{"label":"فاضل السامرائي، دلالة اختلاف الفاصلة بين «المبطلون» و«الكافرون» في سورة غافر – بوابة إسلاميات.","url":""}]},{"id":"s40-206","number":206,"surah":40,"verses":[79,81],"references":[{"surah":40,"verses":[79,81]}],"verseLabel":"غافر: 79، 81","question":"ما سر التعبير بـ﴿جَعَلَ لَكُمُ الْأَنْعَامَ﴾ في غافر، وبـ﴿خَلَقْنَا لَهُمْ... أَنْعَامًا﴾ في يس؟","answer":"الخلق ابتداءً أدل على العناية والامتنان من مجرد جعل الموجود مسخرًا للانتفاع، وقد فُصّلت النعم في يس بملك الأنعام وتذليلها والمآكل والمشارب، ثم خُتمت بالدعوة إلى الشكر: ﴿أفلا يشكرون﴾؛ فناسبها ﴿خلقنا لهم﴾. أما غافر فسياق عرض الآيات وإنكارها، وتكرر فيه فعل «جعل»، فناسبه ﴿جعل لكم﴾ ثم ﴿فأي آيات الله تنكرون﴾.","sources":[{"label":"فاضل السامرائي، برنامج لمسات بيانية، الفرق بين «خلقنا لهم» في يس و«جعل لكم» في غافر – تدارس القرآن الكريم.","url":""}]},{"id":"s45-119","number":119,"surah":45,"verses":[7,11],"references":[{"surah":45,"verses":[7,11]}],"verseLabel":"الجاثية: 7، 11","question":"ما سر تنوّع أوصاف العذاب في فواصل هذه الآيات: ﴿عَذَابٍ أَلِيمٍ﴾ ثم ﴿عَذَابٌ مُّهِينٌ﴾ ثم ﴿عَذَابٌ عَظِيمٌ﴾ ثم ﴿عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ﴾؟","answer":"كل فاصلة مناسبة لصفة المعذَّب: فالأفّاك الأثيم المستكبر بُشّر بعذاب أليم يقمع استكباره، والمتّخذ الآيات هزوًا له عذاب مهين جزاءً لاستهانته، والمشركون المتّخذون من دون الله أولياء لهم عذاب عظيم هو أشدّه، والرِّجز هو العذاب المقلقل لشدّته كالزلزلة. وفي «روح المعاني» نحو ما ذُكر في وصف العذاب بالإهانة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص100–101.","url":""}]},{"id":"s45-120","number":120,"surah":45,"verses":[16],"references":[{"surah":45,"verses":[16]}],"verseLabel":"الجاثية: 16","question":"ما سر إسناد الإيتاء إلى ضميره سبحانه في قوله: ﴿وَلَقَدْ آتَيْنَا بَنِي إِسْرَائِيلَ الْكِتَابَ وَالْحُكْمَ وَالنُّبُوَّةَ﴾؟","answer":"من عادة القرآن أنه إذا كان المقام مقام مدح وثناء أظهر ذاته ونسب إيتاء الكتاب إلى نفسه «آتَيْنَاهُمُ الكتاب»، وإذا كان مقام ذم وتقريع قال: «أُوتُوا الكتاب». والآية هنا في مقام الامتنان عليهم بالكتاب والحكم والنبوة والرزق والتفضيل على العالمين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص322.","url":""}]},{"id":"s45-121","number":121,"surah":45,"verses":[17],"references":[{"surah":45,"verses":[17]}],"verseLabel":"الجاثية: 17","question":"ما دلالة «يقضي» في قوله: ﴿إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَةِ﴾ مقابل «يحكم» و«يفصل» في مواضع أخرى؟","answer":"الحكم أن تقضي بأن الشيء كذا أو ليس بكذا، ألزمتَ به أم لا. والقضاء أشدّ لأن أصله القطع، وهو إمضاء الحكم وإتمامه والفراغ منه. والفصل أشدّ منهما لأنه إبانة أحد الشيئين من الآخر ويفيد الابتعاد؛ فالقرآن يستعمل الحكم فيما هو أخفّ من القضاء، والقضاء فيما هو أخصّ من الفصل. وفي «الفروق اللغوية» نحو التفريق بين الحكم والقضاء.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص10–12.","url":""}]},{"id":"s45-122","number":122,"surah":45,"verses":[21],"references":[{"surah":45,"verses":[21]}],"verseLabel":"الجاثية: 21","question":"ما دلالة «المَحْيَا» دون «الحياة» في قوله: ﴿سَوَاءً مَّحْيَاهُمْ وَمَمَاتُهُمْ﴾؟","answer":"يستعمل القرآن «الحياة» عامة لجميع أنواع الحياة، أما «المحيا» فخاص بحياة الناس، لم يرد إلا مضافًا إلى ضميرهم ومقابلًا للممات، كهذه الآية وقوله: ﴿وَمَحْيَايَ وَمَمَاتِي لِلَّهِ﴾. وكذلك «الممات» لم يرد إلا مقابلًا للحياة أو المحيا.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص11–12.","url":""}]},{"id":"s46-96","number":96,"surah":46,"verses":[15],"references":[{"surah":46,"verses":[15]}],"verseLabel":"الأحقاف: 15","question":"ما دلالة «الكُرْه» بضم الكاف في قوله: ﴿حَمَلَتْهُ أُمُّهُ كُرْهًا وَوَضَعَتْهُ كُرْهًا﴾؟","answer":"يستعمل القرآن «الكَرْه» بالفتح لما ينال الإنسان من مشقة من الخارج ولذا يقابله بالطوع، و«الكُرْه» بالضم لما يعافه الإنسان من ذاته وطبعه، كقوله: ﴿وَهُوَ كُرْهٌ لَّكُمْ﴾. والحمل والوضع مشقّتان مكروهتان للمرأة بطبعها لما فيهما من الآلام. وفي «المفردات» و«البحر المحيط» نحو هذا التفريق.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص201–202.","url":""}]},{"id":"s46-97","number":97,"surah":46,"verses":[30],"references":[{"surah":46,"verses":[30]}],"verseLabel":"الأحقاف: 30","question":"ما سر قول الجن: ﴿يَهْدِي إِلَى الْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ﴾، وفي سورة الجن: ﴿يَهْدِي إِلَى الرُّشْدِ﴾؟","answer":"الحق أعم من الرشد، فكل رشد حق وليس كل حق رشدًا، وحديث الجن عن القرآن في الأحقاف أوسع فناسبه الأعم. وكلمة «الحق» وردت في الأحقاف ست مرات ولم ترد في الجن، والرشد بالعكس. وزاد ﴿وَإِلَىٰ طَرِيقٍ﴾ لأن السورة ذكرت أنها طريق مسلوكة سلكها الرسل من قبل: ﴿مَا كُنتُ بِدْعًا مِّنَ الرُّسُلِ﴾، ﴿وَقَدْ خَلَتِ النُّذُرُ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص261–263.","url":""}]},{"id":"s46-98","number":98,"surah":46,"verses":[33],"references":[{"surah":46,"verses":[33]}],"verseLabel":"الأحقاف: 33","question":"ما سر ختم قوله: ﴿بِقَادِرٍ عَلَىٰ أَن يُحْيِيَ الْمَوْتَىٰ﴾ بـ﴿إِنَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ﴾، وختم نظيرتها في يس بـ﴿وَهُوَ الْخَلَّاقُ الْعَلِيمُ﴾؟","answer":"قال في يس: ﴿بِقَادِرٍ عَلَىٰ أَنْ يَخْلُقَ مِثْلَهُم﴾ فناسب الختم بالخلّاق العليم، وقال في الأحقاف: ﴿بِقَادِرٍ عَلَىٰ أَن يُحْيِيَ الْمَوْتَىٰ﴾ فناسب الختم بالقدرة العامة على كل شيء، فوُضعت كل خاتمة في موضعها.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص278.","url":""}]},{"id":"s46-99","number":99,"surah":46,"verses":[35],"references":[{"surah":46,"verses":[35]}],"verseLabel":"الأحقاف: 35","question":"ما سر حذف المبتدأ في قوله: ﴿بَلَاغٌ ۚ فَهَلْ يُهْلَكُ إِلَّا الْقَوْمُ الْفَاسِقُونَ﴾، وذكره في إبراهيم: ﴿هَٰذَا بَلَاغٌ لِّلنَّاسِ﴾؟","answer":"المقام في الأحقاف مقام إيجاز، فسياق البلاغ فيها آيتان، والمقام في إبراهيم مقام تفصيل، فسياقه إحدى عشرة آية، وفصّل في آية البلاغ نفسها ﴿وَلِيُنذَرُوا بِهِ وَلِيَعْلَمُوا﴾، فناسب ذكر المبتدأ هناك وحذفه هنا.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص112–113. المصادر","url":""}]},{"id":"s47-114","number":114,"surah":47,"verses":[15],"references":[{"surah":47,"verses":[15]}],"verseLabel":"محمد: 15","question":"ما سر وصف الماء بـ«غير آسن» في قوله: ﴿فِيهَا أَنْهَارٌ مِّن مَّاءٍ غَيْرِ آسِنٍ﴾؟","answer":"الأنهار إذا ذُكرت في الجنة وُصفت بالجريان، كقوله: ﴿تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ﴾، إلا في هذه الآية. ولمّا لم تُوصف بالجريان وكان ذلك مظنة الأُسون، أي تغيّر الماء، قال ﴿غَيْرِ آسِنٍ﴾ ليزيل هذا الظن.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص75–76.","url":""}]},{"id":"s47-115","number":115,"surah":47,"verses":[20],"references":[{"surah":47,"verses":[20]}],"verseLabel":"محمد: 20","question":"ما سر إفراد الدعاء في قوله: ﴿فَأَوْلَىٰ لَهُمْ﴾، وتكريره في القيامة: ﴿أَوْلَىٰ لَكَ فَأَوْلَىٰ ۞ ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰ﴾؟","answer":"المذكورون هنا الذين في قلوبهم مرض، وهم من ضعفة الدين، وأُخبر عنهم أحياءً وباب التوبة مفتوح، ولم يذكر لهم إلا صفة واحدة هي الجبن عن القتال، فهدّدهم مرة واحدة. أما المذكور في القيامة فمكذّب متولٍّ متبختر، أُخبر عنه بعد موته على ذلك، وذُكرت له صفات كفر متعددة، فكرّر تهديده.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص228–229.","url":""}]},{"id":"s47-116","number":116,"surah":47,"verses":[22],"references":[{"surah":47,"verses":[22]}],"verseLabel":"محمد: 22","question":"ما دلالة الاستفهام في قوله: ﴿فَهَلْ عَسَيْتُمْ إِن تَوَلَّيْتُمْ أَن تُفْسِدُوا فِي الْأَرْضِ وَتُقَطِّعُوا أَرْحَامَكُمْ﴾؟","answer":"خرج الاستفهام بـ«هل» هنا إلى معنى التحذير من الإفساد وتقطيع الأرحام، ونظيره في البقرة: ﴿هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ الْقِتَالُ أَلَّا تُقَاتِلُوا﴾. وليس هذا تحذيرًا مجرّدًا، بل يبقى فيه شوب من معنى الاستفهام.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص241.","url":""}]},{"id":"s47-117","number":117,"surah":47,"verses":[26],"references":[{"surah":47,"verses":[26]}],"verseLabel":"محمد: 26","question":"ما سر التعبير بـ«نزّل» في قوله: ﴿قَالُوا لِلَّذِينَ كَرِهُوا مَا نَزَّلَ اللَّهُ﴾، وبـ«أنزل» في الآية 9: ﴿ذَٰلِكَ بِأَنَّهُمْ كَرِهُوا مَا أَنزَلَ اللَّهُ﴾؟","answer":"الآيات الثانية أشدّ في الهجوم على الكفر: فهؤلاء ارتدوا بعد ما تبيّن لهم الهدى، وسوّل لهم الشيطان، واتبعوا ما أسخط الله، وفي قلوبهم مرض وأضغان، والتهديد فيها أشد: ﴿يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَارَهُمْ﴾. فاستعمل «نزّل» المضعّف لما هو أشد وأقوى، و«أنزل» في الموضع الأخف.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص64–66.","url":""}]},{"id":"s47-118","number":118,"surah":47,"verses":[27],"references":[{"surah":47,"verses":[27]}],"verseLabel":"محمد: 27","question":"ما سر تأنيث الفعل في قوله: ﴿فَكَيْفَ إِذَا تَوَفَّتْهُمُ الْمَلَائِكَةُ﴾، وتذكيره في الأنفال: ﴿إِذْ يَتَوَفَّى الَّذِينَ كَفَرُوا الْمَلَائِكَةُ﴾؟","answer":"إذا كان أحد الموقفين أشدّ من الآخر جيء بالأشدّ بالتذكير. وآية الأنفال في سياق وقعة بدر، وزاد فيها ﴿وَذُوقُوا عَذَابَ الْحَرِيقِ﴾، أما آية محمد فليست في سياق حرب ولم يذكر فيها ذلك، فجاء بالتأنيث.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص189–190.","url":""}]},{"id":"s48-126","number":126,"surah":48,"verses":[10],"references":[{"surah":48,"verses":[10]}],"verseLabel":"الفتح: 10","question":"ما سر ضمّ الهاء في قوله: ﴿وَمَنْ أَوْفَىٰ بِمَا عَاهَدَ عَلَيْهُ اللَّهَ﴾ في قراءة حفص؟","answer":"الضمة أثقل الحركات، فجاء بها مجانسةً لثقل هذا العهد: فهي بيعة الحديبية على الموت، والمُبايَع فيها هو الله، و﴿يَدُ اللَّهِ فَوْقَ أَيْدِيهِمْ﴾. ثم إن الضمة يُفخّم معها لفظ الجلالة بخلاف الكسرة، فناسب تفخيمُ الصوت تفخيمَ العهد. وفي «روح المعاني» نحو هذا التوجيه.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص103–104.","url":""}]},{"id":"s48-127","number":127,"surah":48,"verses":[12],"references":[{"surah":48,"verses":[12]}],"verseLabel":"الفتح: 12","question":"ما سر بناء الفعل للمجهول في قوله: ﴿وَزُيِّنَ ذَٰلِكَ فِي قُلُوبِكُمْ وَظَنَنتُمْ ظَنَّ السَّوْءِ﴾؟","answer":"الله ينسب تزيين الخير إلى نفسه كقوله: ﴿وَلَقَدْ زَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ﴾، أما تزيين السوء فيبنيه للمجهول أو يسنده إلى غيره، فلا تجد «زيّنّا لهم سوء أعمالهم»؛ لأن الله لا ينسب السوء إلى نفسه. وفي «بدائع الفوائد» لابن القيم نحو هذا.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص321–322.","url":""}]},{"id":"s48-128","number":128,"surah":48,"verses":[16],"references":[{"surah":48,"verses":[16]}],"verseLabel":"الفتح: 16","question":"ما سر إثبات التاءين في قوله للمخلّفين: ﴿وَإِن تَتَوَلَّوْا كَمَا تَوَلَّيْتُم مِّن قَبْلُ﴾، وحذف إحداهما في خطاب المؤمنين في الأنفال: ﴿وَلَا تَوَلَّوْا عَنْهُ﴾؟","answer":"تولّي المؤمنين أقل فحُذف من الفعل. أما هؤلاء الأعراب فلم يتمكّن الإيمان من قلوبهم، وكان تخلّفهم تخلّف نفاق، وقد وصفهم بأنهم ﴿يَقُولُونَ بِأَلْسِنَتِهِم مَّا لَيْسَ فِي قُلُوبِهِمْ﴾ و﴿ظَنَنتُمْ ظَنَّ السَّوْءِ وَكُنتُمْ قَوْمًا بُورًا﴾، فجاء بالتولّي تامًا.","sources":[{"label":"فاضل السامرائي، بلاغة الكلمة في التعبير القرآني، ص15.","url":""}]},{"id":"s49-92","number":92,"surah":49,"verses":[7],"references":[{"surah":49,"verses":[7]}],"verseLabel":"الحجرات: 7","question":"ما سر التعبير بـ«العصيان» في الآية نفسها، وبـ«المعصية» في المجادلة: ﴿وَيَتَنَاجَوْنَ بِالْإِثْمِ وَالْعُدْوَانِ وَمَعْصِيَتِ الرَّسُولِ﴾؟","answer":"لم يرد «العصيان» في القرآن إلا في هذا الموضع، واستعمله عامًا. ووردت «المعصية» مرتين في المجادلة، وخُصّت فيهما بمعصية الرسول، فاختلف المصدران باختلاف العموم والخصوص.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص18.","url":""}]},{"id":"s50-152","number":152,"surah":50,"verses":[2],"references":[{"surah":50,"verses":[2]}],"verseLabel":"ق: 2","question":"ما سر ترك التوكيد في قوله: ﴿فَقَالَ الْكَافِرُونَ هَٰذَا شَيْءٌ عَجِيبٌ﴾، وهو في هود ﴿إِنَّ هَٰذَا لَشَيْءٌ عَجِيبٌ﴾ وفي ص ﴿إِنَّ هَٰذَا لَشَيْءٌ عُجَابٌ﴾؟","answer":"تدرّج في العجب بحسب قوته: ففي ق عجبوا من مجيء منذر منهم فلم يؤكد. وفي هود كان العجب أكبر لأن امرأة عجوزًا عقيمًا بعلها شيخ تُبشّر بالولد، فأكّد بـ«إنّ» واللام. وفي ص عدل إلى «عُجاب» وهو أبلغ من «عجيب»، مع التوكيد، لأنهم عجبوا من جعل الآلهة إلهًا واحدًا.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص36–37.","url":""}]},{"id":"s50-153","number":153,"surah":50,"verses":[13],"references":[{"surah":50,"verses":[13]}],"verseLabel":"ق: 13","question":"ما سر التعبير بـ«إخوان» في قوله: ﴿وَعَادٌ وَفِرْعَوْنُ وَإِخْوَانُ لُوطٍ﴾، ولم يرد مثله مع غيره من الأنبياء؟","answer":"قوم لوط يختلفون عن بقية الأقوام، فمعصيتهم تخصّ الرجال إذ كانوا يأتون الرجال شهوة من دون النساء، وكلمة «إخوان» للذكور ولا تشمل الإناث، فجاء بها معهم خاصة. أما معاصي الأقوام الأخرى فتعمّ الرجال والنساء فيأتي معهم بـ«قوم»، ويُذكر «قوم لوط» حين يُذكر هلاكهم.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص103.","url":""}]},{"id":"s50-154","number":154,"surah":50,"verses":[14],"references":[{"surah":50,"verses":[14]}],"verseLabel":"ق: 14","question":"ما سر قوله: ﴿كُلٌّ كَذَّبَ الرُّسُلَ فَحَقَّ وَعِيدِ﴾، وفي ص: ﴿إِن كُلٌّ إِلَّا كَذَّبَ الرُّسُلَ فَحَقَّ عِقَابِ﴾؟","answer":"العقاب أشدّ من الوعيد، والكافرون في ص أشدّ وأعتى: وصفهم بأنهم في عزّة وشقاق، وقالوا في الرسول ﴿سَاحِرٌ كَذَّابٌ﴾، وذكر فيها من إهلاك القرون السابقة وتهديد الكافرين ما لم يذكره في ق، فناسب أن يذكر في ص الأشدّ.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص158–159.","url":""}]},{"id":"s51-41","number":41,"surah":51,"verses":[17],"references":[{"surah":51,"verses":[17]}],"verseLabel":"الذاريات: 17","question":"ما دلالة «كانوا» مع المضارع في قوله: ﴿كَانُوا قَلِيلًا مِّنَ اللَّيْلِ مَا يَهْجَعُونَ﴾؟","answer":"«كان» مع المضارع تدل على الماضي المعتاد، أي أن الفاعل كان يعتاد الفعل ويستمر عليه، فالمعنى: هذه عادتهم في الدنيا، لا أنهم فعلوه مرة.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص212.","url":""}]},{"id":"s51-42","number":42,"surah":51,"verses":[28],"references":[{"surah":51,"verses":[28]}],"verseLabel":"الذاريات: 28","question":"ما سر قوله: ﴿فَأَوْجَسَ مِنْهُمْ خِيفَةً﴾، وفي الحجر واجَههم بقوله: ﴿إِنَّا مِنكُمْ وَجِلُونَ﴾؟","answer":"ذكر في الذاريات أنه أوجس الخيفة في نفسه ولم يواجه ضيفه بها، وهذا المناسب لمقام الإكرام الذي بُنيت عليه القصة هنا، إذ لا يحسُن في جوّ التكريم أن يعلن لضيفه أنه غير مطمئن إليهم. أما في الحجر فلم يصفهم بالإكرام فواجههم بوجله.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص85.","url":""}]},{"id":"s51-43","number":43,"surah":51,"verses":[47],"references":[{"surah":51,"verses":[47]}],"verseLabel":"الذاريات: 47","question":"ما سر رسم ﴿بِأَيْيَدٍ﴾ بياءين في قوله: ﴿وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْيَدٍ﴾، ورسم ﴿ذَا الْأَيْدِ﴾ بياء واحدة في ص؟","answer":"رسم المصحف لا يُقاس عليه، والتعليل فيه غير مقطوع به. ومع ذلك فالأيد القوة في الآيتين، لكن لمّا كانت قوة الله زائدة على قوة داود زيد في الرسم. ومما سوّغ ذلك أنه عبّر عن نفسه بضمير الجمع للتعظيم: ﴿بَنَيْنَاهَا﴾ و﴿وَإِنَّا لَمُوسِعُونَ﴾، فناسب جمعُ الياءين موطنَ الجمع.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص163.","url":""}]},{"id":"s51-44","number":44,"surah":51,"verses":[52],"references":[{"surah":51,"verses":[52]}],"verseLabel":"الذاريات: 52","question":"ما سر رسم «ساحر» بالألف في قوله: ﴿مَا أَتَى الَّذِينَ مِن قَبْلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا سَاحِرٌ أَوْ مَجْنُونٌ﴾، وبغير ألف في الآية 39 وفي سائر المواضع؟","answer":"رُسمت «ساحر» النكرة بغير ألف حيثما وقعت إلا هنا، لأن الكلام في جميع الأمم السابقة، فلمّا كثرت الأمم وتطاولت زيد في الرسم. وهذا من خط المصحف الذي لا يُقاس عليه، وهذا التعليل لا يُقطع بصحته فقد يكون من باب الموافقات.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص178–179.","url":""}]},{"id":"s51-45","number":45,"surah":51,"verses":[54],"references":[{"surah":51,"verses":[54]}],"verseLabel":"الذاريات: 54","question":"ما سر التعبير بالتولّي دون الإعراض في قوله: ﴿فَتَوَلَّ عَنْهُمْ فَمَا أَنتَ بِمَلُومٍ﴾؟","answer":"التولّي أشدّ من الإعراض، فهو إعراض مع إدبار ونأي عن الشيء، ولذلك يأتي الأمر به مع الكافرين كهذه الآية. أما الإعراض فقد يكون عامًا مع الكافرين وغيرهم، كقوله في ذوي القربى والمساكين: ﴿وَإِمَّا تُعْرِضَنَّ عَنْهُمُ ابْتِغَاءَ رَحْمَةٍ مِّن رَّبِّكَ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص246–247.","url":""}]},{"id":"s52-46","number":46,"surah":52,"verses":[8],"references":[{"surah":52,"verses":[8]}],"verseLabel":"الطور: 8","question":"ما سر النفي بـ«ما» و«مِن» في قوله: ﴿إِنَّ عَذَابَ رَبِّكَ لَوَاقِعٌ ۝ مَا لَهُ مِن دَافِعٍ﴾، والنفي بـ«ليس» في المعارج: ﴿لَيْسَ لَهُ دَافِعٌ﴾؟","answer":"آية الطور جواب قسم طويل، وقد تُلقّي القسم بجملة اسمية مؤكدة بـ«إنّ» واللام، فجاء نفي الدفع بجملة اسمية مؤكدة كذلك بـ«ما» و«من» الاستغراقية مناسبةً للجواب المؤكد. وفي المعارج لا قسم، والسياق يدل على أن العذاب بعيد في نظرهم ﴿إِنَّهُمْ يَرَوْنَهُ بَعِيدًا﴾، أما في الطور فهم موقوفون على النار يُخاطَبون بها، فكان وقوع العذاب فيها آكد.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص180–181.","url":""}]},{"id":"s52-47","number":47,"surah":52,"verses":[16],"references":[{"surah":52,"verses":[16]}],"verseLabel":"الطور: 16","question":"ما سر التفصيل في قوله: ﴿اصْلَوْهَا فَاصْبِرُوا أَوْ لَا تَصْبِرُوا سَوَاءٌ عَلَيْكُمْ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ﴾، مع الإيجاز في يس: ﴿اصْلَوْهَا الْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ﴾؟","answer":"المقام في يس مقام إيجاز، وفي الطور مقام تفصيل، فقد فصّل في صفات المكذبين وعقوباتهم فأكثر من تبكيتهم. وذكر في الطور أنهم كانوا يكذّبون بالنار نفسها ﴿هَٰذِهِ النَّارُ الَّتِي كُنتُم بِهَا تُكَذِّبُونَ﴾، فناسب أن يطيل الكلام عليها ويبكّتهم بها. ثم إن المذكورين في الطور مكذبون، وفي يس ذكر الإضلال على العموم، والضالّ قد لا يكون كافرًا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص221–222.","url":""}]},{"id":"s52-48","number":48,"surah":52,"verses":[29],"references":[{"surah":52,"verses":[29]}],"verseLabel":"الطور: 29","question":"ما سر زيادة «بكاهن» في قوله: ﴿فَمَا أَنتَ بِنِعْمَتِ رَبِّكَ بِكَاهِنٍ وَلَا مَجْنُونٍ﴾، والاقتصار على ﴿بِمَجْنُونٍ﴾ في القلم؟","answer":"فصّلت الطور أقوال الكفار في الرسول: كاهن ومجنون وشاعر ومتقوّل، ولم تذكر القلم إلا قولهم إنه مجنون. وذكرت الطور ﴿أَمْ لَهُمْ سُلَّمٌ يَسْتَمِعُونَ فِيهِ﴾، والاستماع مما يدّعيه الكهنة، وذكرت السحر ﴿أَفَسِحْرٌ هَٰذَا﴾ وهو قرين الكهانة. وتوسّعت في القسم أول السورة، فناسب ذلك كله هذه الزيادة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص168–169.","url":""}]},{"id":"s52-49","number":49,"surah":52,"verses":[48],"references":[{"surah":52,"verses":[48]}],"verseLabel":"الطور: 48","question":"ما دلالة الجمع «أعين» في قوله: ﴿وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا﴾، وهو على وزن من أوزان القلة؟","answer":"لم يُرد بـ«الأعين» في القرآن القلة، وإنما خُصّت بالعين الباصرة وبمعنى الرعاية، وخُصّت «العيون» بعيون الماء. وقد جاءت «بأعيننا» بمعنى الرعاية في أربعة مواضع، منها هذه الآية، فالمعنى: إنك في رعايتنا وحفظنا.","sources":[{"label":"فاضل السامرائي، معاني الأبنية في العربية، ص122–123.","url":""}]},{"id":"s52-50","number":50,"surah":52,"verses":[49],"references":[{"surah":52,"verses":[49]}],"verseLabel":"الطور: 49","question":"ما سر ختم السورة بقوله: ﴿وَمِنَ اللَّيْلِ فَسَبِّحْهُ وَإِدْبَارَ النُّجُومِ﴾؟","answer":"إدبار النجوم غروبها وهُوِيّها، فناسب ذلك افتتاح السورة التي بعدها بالقسم: ﴿وَالنَّجْمِ إِذَا هَوَىٰ﴾، وهوى أي غرب، فكان أول النجم شديد المناسبة لآخر الطور. وفي «روح المعاني» نحو هذا.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص215. المصادر","url":""}]},{"id":"s53-56","number":56,"surah":53,"verses":[5],"references":[{"surah":53,"verses":[5]}],"verseLabel":"النجم: 5","question":"ما دلالة «علّمه» دون «أعلمه» في قوله: ﴿عَلَّمَهُ شَدِيدُ الْقُوَىٰ﴾؟","answer":"«علّم» يقتضي التكثير ومداومة التعليم واستمراره، أما «أعلم» فقد يكون لوقت قصير ولمسألة واحدة، فتقول: أعلمته الخبر، وتقول: علّمته النحو مسألةً مسألة. فدلّ على أن الوحي تعليم متصل مستمر.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص222.","url":""}]},{"id":"s54-33","number":33,"surah":54,"verses":[1],"references":[{"surah":54,"verses":[1]}],"verseLabel":"القمر: 1","question":"ما دلالة «اقتربت» دون «قربت»، وما صلة مطلع السورة بخاتمتها؟","answer":"«اقترب» أبلغ في القرب من «قرب» لما في «افتعل» من المبالغة، أي اشتدّت قربًا. وافتُتحت السورة بالساعة وخُتمت بها: ﴿بَلِ السَّاعَةُ مَوْعِدُهُمْ﴾، ورُتّبت أحداثها بحسب تسلسلها: الاقتراب ثم الخروج من الأجداث ثم مشهد المجرمين في النار، وخُتمت بمشهد المتقين في الجنة لأنه المشهد الأخير. وفي «روح المعاني» و«نظم الدرر» نحو معنى المبالغة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص232.","url":""}]},{"id":"s54-34","number":34,"surah":54,"verses":[1],"references":[{"surah":54,"verses":[1]}],"verseLabel":"القمر: 1","question":"ما مناسبة افتتاح السورة بقوله: ﴿اقْتَرَبَتِ السَّاعَةُ وَانشَقَّ الْقَمَرُ﴾ لسورة النجم قبلها؟","answer":"خُتمت النجم بقوله: ﴿أَزِفَتِ الْآزِفَةُ﴾ أي دنت القيامة، وافتُتحت القمر باقتراب الساعة، والآزفة والساعة يكادان يكونان بمعنى. وافتُتحت النجم بهُوِيّ النجم وهذه بانشقاق القمر، وكلاهما تغيّر غريب في حال جرم سماوي وذهاب لنوره. وفي «روح المعاني» نحو هذا.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص231.","url":""}]},{"id":"s54-35","number":35,"surah":54,"verses":[2],"references":[{"surah":54,"verses":[2]}],"verseLabel":"القمر: 2","question":"ما سر حذف المبتدأ في ﴿وَيَقُولُوا سِحْرٌ مُّسْتَمِرٌ﴾، وذكره مؤكدًا في المائدة: ﴿إِنْ هَٰذَا إِلَّا سِحْرٌ مُّبِينٌ﴾؟","answer":"الحذف يقتضيه الإيجاز مع وضوح المعنى، والذكر يقتضيه مقام التفصيل أو التوكيد. ففي المائدة فصّل آيات عيسى من النفخ في الطين وإحياء الموتى وإبراء الأكمه فاقتضى الذكر والقصر، أما في القمر فلم يذكر آية بعينها وإنما عقّب به على انشقاق القمر وذكر إعراضهم، فناسب الإيجاز.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص234–235.","url":""}]},{"id":"s54-36","number":36,"surah":54,"verses":[2],"references":[{"surah":54,"verses":[2]}],"verseLabel":"القمر: 2","question":"ما سر وصف السحر هنا بـ«مستمر»، وقد وُصف في مواضع أخرى بـ«مبين» و«مفترى» و«يُؤثر»؟","answer":"«مستمر» أي مطّرد دائم، وهو مناسب للمضارع «يروا» الدال على تكرّر الآيات. ويصفونه بـ«مبين» حيث ترد آيات ظاهرة كقلب العصا، وبـ«مفترى» حين قالوا لم نسمع بهذا في آبائنا، وبـ«يُؤثر» أي يُنقل حين نفى القائلُ أولًا أنه سحر، ويُترك بلا وصف حين يُذكر مجيء الحق على العموم. ومعنى «مستمر» منقول عن «روح المعاني».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص236–237.","url":""}]},{"id":"s54-37","number":37,"surah":54,"verses":[3],"references":[{"surah":54,"verses":[3]}],"verseLabel":"القمر: 3","question":"ما سر الماضي وإطلاق التكذيب في قوله: ﴿وَكَذَّبُوا وَاتَّبَعُوا أَهْوَاءَهُمْ﴾؟","answer":"جاء بالماضي بعد المضارع ليدل على أن التكذيب واتباع الهوى حصلا قبل رؤية الآيات وتحقّقا، لا أنهما معطوفان على جواب الشرط. وأطلق التكذيب فلم يقل «كذّبوا الرسول» ولا «بالآيات» ليعمّ الاثنين، وقال «اتّبعوا» دون «تبعوا» للمبالغة في اتباع الهوى. ومعنى التحقّق منقول عن «روح المعاني».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص238–239.","url":""}]},{"id":"s54-38","number":38,"surah":54,"verses":[4],"references":[{"surah":54,"verses":[4]}],"verseLabel":"القمر: 4","question":"ما سر بناء قوله: ﴿وَلَقَدْ جَاءَهُم مِّنَ الْأَنبَاءِ مَا فِيهِ مُزْدَجَرٌ﴾؟","answer":"أكّد بـ«لقد»، واختار «جاء» لأنه لما هو أثقل، و«الأنباء» لأن النبأ أعظم من الخبر، و«مزدجر» لأنه أبلغ من الزجر ويحتمل المصدر واسمَي المكان والزمان، وأطلقه فلم يقل «لهم» ليعمّ كل من تبلغه الأنباء. وقدّم «من الأنباء» لأن أنباء من عُوقب أدعى إلى الزجر من مجرد النصح. ومعنى النبأ منقول عن «مفردات الراغب».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص240–244.","url":""}]},{"id":"s54-39","number":39,"surah":54,"verses":[7],"references":[{"surah":54,"verses":[7]}],"verseLabel":"القمر: 7","question":"ما سر التعبير بـ«الأجداث» دون «القبور» في قوله: ﴿يَخْرُجُونَ مِنَ الْأَجْدَاثِ كَأَنَّهُمْ جَرَادٌ مُّنتَشِرٌ﴾؟","answer":"الجدث القبر، لكنه قريب في اللفظ من «الجدثة» وهي صوت الحافر والخفّ، وصوت خروج الموتى مسرعين شبيه به. ولذلك خُصّت «الأجداث» بحال الخروج مسرعين إلى المحشر، واستُعملت «القبور» في حال السكون والهمود.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص154.","url":""}]},{"id":"s54-40","number":40,"surah":54,"verses":[7],"references":[{"surah":54,"verses":[7]}],"verseLabel":"القمر: 7","question":"ما سر قوله: ﴿خُشَّعًا أَبْصَارُهُمْ يَخْرُجُونَ﴾ بجمع الحال وتقديمها، وفي القلم والمعارج: ﴿خَاشِعَةً أَبْصَارُهُمْ﴾ مفردة مؤخرة؟","answer":"الموقف في القمر أشدّ هولًا: فالداعي يدعو إلى شيء نكر لم يألفوه، وهم كالجراد المنتشر كثرةً، مهطعون، يقول الكافرون ﴿هَٰذَا يَوْمٌ عَسِرٌ﴾. فجاء بجمع التكسير على «فُعَّل» الدال على المبالغة والتكثير، وقدّمه اهتمامًا، وناسبت الكثرةُ الجمعَ.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص248–251.","url":""}]},{"id":"s54-41","number":41,"surah":54,"verses":[49],"references":[{"surah":54,"verses":[49]}],"verseLabel":"القمر: 49","question":"ما دلالة نصب «كلّ» في قوله: ﴿إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ﴾؟","answer":"النصب تقديره: خلقنا كلّ شيء خلقناه بقدر، فيوجب العموم. ولو رُفع لاحتمل أن تكون «خلقناه» صفةً لـ«شيء» و«بقدر» الخبر، فيكون المعنى أن ما خلقه الله خلقه بقدر، فيُفهم أن ثمة خالقًا غيره، تعالى الله عن ذلك. وهذا التوجيه منقول عن «شرح السيرافي على كتاب سيبويه».","sources":[{"label":"فاضل السامرائي، معاني النحو، ج2، ص136.","url":""}]},{"id":"s55-39","number":39,"surah":55,"verses":[15],"references":[{"surah":55,"verses":[15]}],"verseLabel":"الرحمن: 15","question":"ما دلالة «الجان» في قوله: ﴿وَخَلَقَ الْجَانَّ مِن مَّارِجٍ مِّن نَّارٍ﴾، مقابلًا لـ﴿خَلَقَ الْإِنسَانَ﴾؟","answer":"«الجان» يُستعمل للواحد وللجنس، وهو ما يقابل «الإنسان» الذي يُراد به الجنس أيضًا، فقوبل جنس بجنس. وقد يُستعمل للجمع مقابلًا لـ«الإنس»، كقوله في السورة نفسها: ﴿لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَانٌّ﴾. أما «الجِنِّي» فهو الواحد من الجن ويقابله «الإنسي».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص56.","url":""}]},{"id":"s55-40","number":40,"surah":55,"verses":[26],"references":[{"surah":55,"verses":[26]}],"verseLabel":"الرحمن: 26","question":"ما سر إفراد الخبر في قوله: ﴿كُلُّ مَنْ عَلَيْهَا فَانٍ﴾، وجمعه في مثل: ﴿كُلٌّ فِي فَلَكٍ يَسْبَحُونَ﴾؟","answer":"الإخبار عن «كل» بالجمع يدل على اجتماعهم في الحدث، والإفراد يدل على أن كل واحد قام به على انفراد. فأفرد «فانٍ» لأنهم لا يجتمعون في الفناء بل يفنى كل واحد على حدة، وجمع «يسبحون» لاجتماعها في السبح. وهذا التوجيه منقول عن «بدائع الفوائد».","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص140–141.","url":""}]},{"id":"s56-39","number":39,"surah":56,"verses":[47],"references":[{"surah":56,"verses":[47]}],"verseLabel":"الواقعة: 47","question":"ما سر قوله: ﴿أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا﴾، وفي الإسراء: ﴿أَئِذَا كُنَّا عِظَامًا وَرُفَاتًا﴾؟","answer":"التراب والعظام أدلّ على البِلى من العظام والرفات، فالرفات إذا بَلِي صار ترابًا، فبعثه أبعد في عقولهم وأدعى إلى العجب. ولذلك أضافوا ذكر الموت للزيادة في الاستبعاد، وزادوا هنا ﴿أَوَآبَاؤُنَا الْأَوَّلُونَ﴾، فكيف يُبعث آباؤهم وقد أصابهم من البِلى ما أصابهم؟","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص117–118.","url":""}]},{"id":"s56-40","number":40,"surah":56,"verses":[65],"references":[{"surah":56,"verses":[65]}],"verseLabel":"الواقعة: 65","question":"ما سر حذف إحدى اللامين في قوله: ﴿فَظَلْتُمْ تَفَكَّهُونَ﴾، والأصل «ظَلَلْتم»؟","answer":"معنى «تفكّهون» تقولون ذلك متندّمين، والقول لا يظلّ مستمرًا على الدوام كما قد يستمر الحزن، فناسب الحذفُ من الفعل قصرَ الحدث، كما حُذفت في ﴿ظَلْتَ عَلَيْهِ عَاكِفًا﴾ لقصر مدة عكوفهم على العجل.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص82–83.","url":""}]},{"id":"s57-49","number":49,"surah":57,"verses":[1],"references":[{"surah":57,"verses":[1]}],"verseLabel":"الحديد: 1","question":"ما سر عدم تكرار «ما» في قوله تعالى: ﴿سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾، وقد كُررت في مواضع أخرى من آيات التسبيح؟","answer":"حيث كُررت «ما» في آيات التسبيح فقيل ﴿وَمَا فِي الْأَرْضِ﴾ أعقب ذلك كلام على أهل الأرض، وحيث لم تُكرر لم يُذكر بعدها شيء يتعلق بأهل الأرض. ولما لم يأتِ بعد هذه الآية ما يتعلق بأهل الأرض لم تُكرر «ما».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص98–99؛ وعلى طريق التفسير البياني، ج1، ص236.","url":""}]},{"id":"s57-50","number":50,"surah":57,"verses":[16],"references":[{"surah":57,"verses":[16]}],"verseLabel":"الحديد: 16","question":"ما دلالة بناء الفعل للمجهول في قوله: ﴿كَالَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلُ﴾؟","answer":"يُستعمل «أوتوا الكتاب» بالبناء للمجهول في مواطن الذم، ويُستعمل «آتيناهم الكتاب» بإسناد الفعل إلى الله في مواطن المدح. والسياق هنا ذم، إذ قال بعده: ﴿فَطَالَ عَلَيْهِمُ الْأَمَدُ فَقَسَتْ قُلُوبُهُمْ﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص323–324.","url":""}]},{"id":"s57-51","number":51,"surah":57,"verses":[16],"references":[{"surah":57,"verses":[16]}],"verseLabel":"الحديد: 16","question":"ما سر قوله: ﴿أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَنْ تَخْشَعَ قُلُوبُهُمْ﴾ دون «ألم يأن لقلوب المؤمنين أن تخشع»؟","answer":"من أسباب ذلك أنه حذّرهم من أن يكونوا كالذين أوتوا الكتاب، فقال: ﴿وَلَا يَكُونُوا كَالَّذِينَ أُوتُوا الْكِتَابَ﴾، ولم يقل: كقلوب الذين أوتوا الكتاب، فناسب أن يكون الكلام على المؤمنين في مقابل الذين أوتوا الكتاب. وقد جمعت الآية ثلاثة دواعٍ إلى الخشية: كونهم مؤمنين، وذكر الله، وما نزل من الحق.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص266–267.","url":""}]},{"id":"s57-52","number":52,"surah":57,"verses":[25],"references":[{"surah":57,"verses":[25]}],"verseLabel":"الحديد: 25","question":"ما سر قوله: ﴿إِنَّ اللَّهَ قَوِيٌّ عَزِيزٌ﴾ بلا لام، وفي الحج: ﴿إِنَّ اللَّهَ لَقَوِيٌّ عَزِيزٌ﴾ باللام؟","answer":"آية الحج في سياق القتال ونصرة المظلومين المعتدى عليهم، فناسبها التوكيد باللام. وآية الحديد في نصرة المؤمنين لدعوة الله ورسله: ﴿وَلِيَعْلَمَ اللَّهُ مَنْ يَنْصُرُهُ وَرُسُلَهُ بِالْغَيْبِ﴾، فلم تحتج إلى ذلك التوكيد.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص174–175.","url":""}]},{"id":"s58-55","number":55,"surah":58,"verses":[3],"references":[{"surah":58,"verses":[3]}],"verseLabel":"المجادلة: 3","question":"ما سر الجمع في قوله: ﴿ذَلِكُمْ تُوعَظُونَ بِهِ﴾، والإفراد في البقرة: ﴿ذَلِكَ يُوعَظُ بِهِ﴾، والخطاب للجميع في الموضعين؟","answer":"الوعظ في المجادلة أشد وآكد؛ لأنه في حكم الظهار الذي وصفه بأنه ﴿مُنْكَرًا مِنَ الْقَوْلِ وَزُورًا﴾، وطلب من قائله تحرير رقبة أو صيام شهرين متتابعين أو إطعام ستين مسكينًا، بخلاف سياق الطلاق في البقرة. فجاء بمطابقة الجمع في الموطن المؤكد.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص102–103.","url":""}]},{"id":"s59-31","number":31,"surah":59,"verses":[24],"references":[{"surah":59,"verses":[24]}],"verseLabel":"الحشر: 24","question":"ما سر ترك العطف في قوله: ﴿الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ﴾، والعطف في قوله: ﴿هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ﴾؟","answer":"الصفات المتعددة لا يُعطف بعضها على بعض لاتحاد محلها، ولذا يقل عطف صفات الله في التنزيل. وعُطفت في الحديد لأنها متضادة المعاني، فدفع العطف استبعاد اجتماعها في ذات واحدة. وهذا التوجيه منقول عن «البرهان».","sources":[{"label":"فاضل السامرائي، معاني النحو، ج1، ص204.","url":""}]},{"id":"s59-32","number":32,"surah":59,"verses":[24],"references":[{"surah":59,"verses":[24]}],"verseLabel":"الحشر: 24","question":"ما سر عدم تكرار «ما» في قوله: ﴿يُسَبِّحُ لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾، وقد كُررت في أول السورة؟","answer":"لم يذكر بعد هذه الآية شيئًا عن أهل الأرض فأجمل ولم يكرر. أما في أولها فأعقب التسبيح بذكر إخراج الذين كفروا من أهل الكتاب وأحوالهم فكرر؛ فكرر في أول السورة وأجمل في آخرها.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص99؛ ومعاني النحو، ج1، ص146. المصادر","url":""}]},{"id":"s60-35","number":35,"surah":60,"verses":[4],"references":[{"surah":60,"verses":[4]}],"verseLabel":"الممتحنة: 4","question":"ما دلالة تعدية الإيمان بالباء في قوله: ﴿حَتَّى تُؤْمِنُوا بِاللَّهِ وَحْدَهُ﴾؟","answer":"الإيمان بالله لا يُعدّى في القرآن إلا بالباء، فإذا رأيت الإيمان معدّى باللام فهو لغير الله، وأكثر ما يكون مع الأشخاص، كقوله: ﴿لَنْ نُؤْمِنَ لَكَ حَتَّى نَرَى اللَّهَ جَهْرَةً﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص75.","url":""}]},{"id":"s61-23","number":23,"surah":61,"verses":[1],"references":[{"surah":61,"verses":[1]}],"verseLabel":"الصف: 1","question":"ما دلالة تعدية التسبيح باللام في قوله: ﴿سَبَّحَ لِلَّهِ﴾، وتعديته بنفسه في مثل: ﴿وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا﴾؟","answer":"«سبّحه» نزّهه، و«سبّح له» فعل ذلك لأجله واللام للتعليل، فتدل على الإخلاص. ويستعمل المعدّى باللام للعقلاء وغيرهم ومع ما هو أعم من المسبّحين والأوقات، أما المعدّى بنفسه فلم يرد إلا للعقلاء. وفي «البحر المحيط» نحو هذا في معنى اللام.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص200–201.","url":""}]},{"id":"s61-24","number":24,"surah":61,"verses":[4],"references":[{"surah":61,"verses":[4]}],"verseLabel":"الصف: 4","question":"ما سر تقديم ﴿فِي سَبِيلِهِ﴾ على ﴿صَفًّا﴾، والتعبير بـ﴿بُنْيَانٌ﴾ دون «بناء»؟","answer":"قدّم ﴿فِي سَبِيلِهِ﴾ لتقدم النية وأهميتها قبل الدخول في الصف، وتوحيد النية سبب لتوحيد الصف. والقرآن يستعمل «البناء» للسماء و«البنيان» لما يبنيه البشر، ووصفه بالمرصوص للدلالة على شدة تماسكه وقوته.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص209.","url":""}]},{"id":"s61-25","number":25,"surah":61,"verses":[5],"references":[{"surah":61,"verses":[5]}],"verseLabel":"الصف: 5","question":"ما دلالة النداء بـ«يا قوم» والمضارع في قوله: ﴿يَا قَوْمِ لِمَ تُؤْذُونَنِي وَقَدْ تَعْلَمُونَ أَنِّي رَسُولُ اللَّهِ إِلَيْكُمْ﴾؟","answer":"ناداهم بـ«يا قوم» تألفًا واستصراخًا لداعي القربى، وذكر مانعين من الأذى: كونهم قومه، وعلمهم أنه رسول الله، وقد آذوه مع ذلك. وقال ﴿تُؤْذُونَنِي﴾ ولم يقل «آذيتموني» للدلالة على استمرار الأذى له.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص210–212.","url":""}]},{"id":"s61-26","number":26,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"ما دلالة نصب ﴿مُصَدِّقًا﴾ و﴿مُبَشِّرًا﴾، وقوله: ﴿يَأْتِي مِنْ بَعْدِي﴾ دون «بعدي»؟","answer":"جاء بهما حالين عاملهما ﴿رَسُولُ اللَّهِ﴾ ليدل على أنهما مما أُرسل به، ولو رفعهما لأفاد أنه أخبر عن نفسه بذلك. وقال ﴿مِنْ بَعْدِي﴾ ليدل على أنه ليس بينهما نبي، لأن «مِن» تفيد ابتداء الغاية، و«بعد» وحدها تحتمل القريب والبعيد.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص214.","url":""}]},{"id":"s61-27","number":27,"surah":61,"verses":[8],"references":[{"surah":61,"verses":[8]}],"verseLabel":"الصف: 8","question":"ما دلالة اسم الفاعل في قوله: ﴿وَاللَّهُ مُتِمُّ نُورِهِ﴾، وفي التوبة: ﴿وَيَأْبَى اللَّهُ إِلَّا أَنْ يُتِمَّ نُورَهُ﴾، وما دلالة ﴿بِأَفْوَاهِهِمْ﴾؟","answer":"اسم الفاعل يدل على الثبوت وأن الأمر استقر، و«أن يتم» تنصيص على الاستقبال، فما في الصف آكد. وقال ﴿بِأَفْوَاهِهِمْ﴾ ليدل على الصورة المضحكة لمن ينفخ بفمه في نور الشمس ليطفئه، ولأن كيدهم هنا تكذيب وافتراء وقولهم ﴿هَذَا سِحْرٌ مُبِينٌ﴾، وهذا محاربة بالأفواه.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص220.","url":""}]},{"id":"s61-28","number":28,"surah":61,"verses":[8],"references":[{"surah":61,"verses":[8]}],"verseLabel":"الصف: 8","question":"ما سر اللام في قوله: ﴿يُرِيدُونَ لِيُطْفِئُوا نُورَ اللَّهِ﴾، وفي التوبة: ﴿يُرِيدُونَ أَنْ يُطْفِئُوا﴾؟","answer":"اللام يُؤتى بها مع مفعول فعل الإرادة للتوكيد، والسياق في الصف متجه إلى النبوة وتكذيب البشارة بمجيء أحمد، فاقتضى التوكيد. وآية التوبة في النعي على معتقدات أهل الكتاب في عزير والمسيح. ومعنى زيادة اللام للتوكيد منقول عن «الكشاف».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص219–220.","url":""}]},{"id":"s61-29","number":29,"surah":61,"verses":[9],"references":[{"surah":61,"verses":[9]}],"verseLabel":"الصف: 9","question":"ما سر ختم الآية بـ﴿وَلَوْ كَرِهَ الْمُشْرِكُونَ﴾، ولم تُختم بها آية الفتح: ﴿لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَى بِاللَّهِ شَهِيدًا﴾؟","answer":"لم يُذكر في سياق آية الفتح محادّة المشركين ولا محاربتهم كما في الصف والتوبة، وإنما تقدمها الوعد بدخول المسجد الحرام آمنين، وقد تم بالاتفاق مع المشركين في صلح الحديبية، فلم يقتضِ ذلك الختم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص223–224.","url":""}]},{"id":"s61-30","number":30,"surah":61,"verses":[10],"references":[{"surah":61,"verses":[10]}],"verseLabel":"الصف: 10","question":"ما دلالة التعبير في قوله: ﴿هَلْ أَدُلُّكُمْ عَلَى تِجَارَةٍ تُنْجِيكُمْ مِنْ عَذَابٍ أَلِيمٍ﴾؟","answer":"الاستفهام للتشويق، ولم يقل «قل هل أدلكم» فكان الدالّ هو الله، وخصّ الدلالة والإنجاء بضمير المخاطبين إمحاضًا للنصح. وقال ﴿تُنْجِيكُمْ﴾ بالتخفيف للدلالة على سرعة الإنجاء، ونكّر العذاب وأطلقه ليشمل كل عذاب في الدنيا والآخرة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص224–225.","url":""}]},{"id":"s61-31","number":31,"surah":61,"verses":[11],"references":[{"surah":61,"verses":[11]}],"verseLabel":"الصف: 11","question":"ما سر الجمع في قوله: ﴿ذَلِكُمْ خَيْرٌ لَكُمْ﴾، والإفراد في المجادلة: ﴿ذَلِكَ خَيْرٌ لَكُمْ وَأَطْهَرُ﴾؟","answer":"أراد أن الخير للأمة جميعها وعلى سبيل الدوام، فآية الجهاد لعموم المؤمنين غنيّهم وفقيرهم إلى يوم القيامة، وهي محكمة. أما آية المجادلة فتخص الأغنياء الذين يناجون الرسول، وقد نُسخ حكمها بعد مدة وجيزة.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص228.","url":""}]},{"id":"s61-32","number":32,"surah":61,"verses":[11],"references":[{"surah":61,"verses":[11]}],"verseLabel":"الصف: 11","question":"ما سر تقديم ﴿فِي سَبِيلِ اللَّهِ﴾ على ﴿بِأَمْوَالِكُمْ وَأَنْفُسِكُمْ﴾، وقد أُخّر في الأنفال والحجرات؟","answer":"الكلام في الصف على التجارة التي تنجي من العذاب فقدّم ما يتعلق بها، وقد تقدم في أول السورة ذكر القتال في سبيله وشاع فيها جو القتال. أما الحجرات فالكلام على صفة المؤمنين فقدّم ما يتعلق بهم، وفي الأنفال تقدم ذكر المال والفداء والغنيمة فقدّم المال.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص227.","url":""}]},{"id":"s61-33","number":33,"surah":61,"verses":[12],"references":[{"surah":61,"verses":[12]}],"verseLabel":"الصف: 12","question":"ما سر ذكر المساكن وجنات عدن في قوله: ﴿وَمَسَاكِنَ طَيِّبَةً فِي جَنَّاتِ عَدْنٍ﴾؟","answer":"خُصّت المساكن بالذكر لأن في الجهاد مفارقة المساكن، فوُعدوا بمساكن أبدية، وهذا التعليل منقول عن «التحرير والتنوير». ومعنى «عدن» الإقامة والبقاء، والقتال مظنة مفارقة الحياة، فذكر أن المجاهد ذاهب إلى مساكن أطيب في دار البقاء.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص229.","url":""}]},{"id":"s61-34","number":34,"surah":61,"verses":[13],"references":[{"surah":61,"verses":[13]}],"verseLabel":"الصف: 13","question":"ما دلالة قوله: ﴿وَأُخْرَى تُحِبُّونَهَا نَصْرٌ مِنَ اللَّهِ وَفَتْحٌ قَرِيبٌ وَبَشِّرِ الْمُؤْمِنِينَ﴾؟","answer":"﴿تُحِبُّونَهَا﴾ تقابل قوله في أول السورة ﴿إِنَّ اللَّهَ يُحِبُّ﴾، فكأنه قال: أطيعوا الله بما يحب وتكرهون يُعطِكم ما تحبون، ولم يقل «تجارة تحبونها» لأن فيها القتال. وقال ﴿نَصْرٌ مِنَ اللَّهِ﴾ ليدل على أن النصر منه لا من عدتهم، وأمر بالبشارة لأنها لا تكون إلا لما هو حاصل قطعًا.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص231.","url":""}]},{"id":"s61-35","number":35,"surah":61,"verses":[14],"references":[{"surah":61,"verses":[14]}],"verseLabel":"الصف: 14","question":"ما دلالة الفاء وإسناد التأييد إلى الله في قوله: ﴿فَأَيَّدْنَا الَّذِينَ آمَنُوا عَلَى عَدُوِّهِمْ فَأَصْبَحُوا ظَاهِرِينَ﴾؟","answer":"الحواريون قالوا ﴿نَحْنُ أَنْصَارُ اللَّهِ﴾ أي الآن، وقاموا بالنصرة فعلًا فاستحقوا التأييد بالفاء الدالة على التعقيب لا بـ«ثم». وأسند التأييد إلى نفسه ليدل على أنه منه وحده، وارتبط باسميه ﴿الْعَزِيزُ الْحَكِيمُ﴾ في أول السورة. وفي «تفسير أبي السعود» أن التأييد بالحجة أو بالسيف.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص232–233.","url":""}]},{"id":"s62-25","number":25,"surah":62,"verses":[10],"references":[{"surah":62,"verses":[10]}],"verseLabel":"الجمعة: 10","question":"ما دلالة «إذا» في قوله: ﴿فَإِذَا قُضِيَتِ الصَّلَاةُ فَانْتَشِرُوا فِي الْأَرْضِ﴾ دون «إن»؟","answer":"«إذا» تُستعمل لما هو مقطوع بحصوله ولما يكثر حصوله، ولا تُستعمل للأمر الافتراضي المحض، أما «إن» فلعموم الافتراضات. وانقضاء الصلاة مقطوع بحصوله لا بد منه، فجاء بـ«إذا».","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص159.","url":""}]},{"id":"s63-20","number":20,"surah":63,"verses":[9],"references":[{"surah":63,"verses":[9]}],"verseLabel":"المنافقون: 9","question":"ما سر الختم بقوله: ﴿فَأُولَئِكَ هُمُ الْخَاسِرُونَ﴾، واختيار ﴿عَنْ ذِكْرِ اللَّهِ﴾ دون غيره من العبادات؟","answer":"الخسران أنسب شيء للمنشغل بالمال الذي يريد الربح، وضمير الفصل وتعريف الخبر يفيدان القصر والتوكيد. واختار ذكر الله لأنه يشمل جميع الفرائض، فكان الخسران كبيرًا متناسبًا مع عظم المعصية. وفي «الكشاف» و«روح المعاني» و«البحر المحيط» نحو هذا.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص183–184.","url":""}]},{"id":"s63-21","number":21,"surah":63,"verses":[9],"references":[{"surah":63,"verses":[9]}],"verseLabel":"المنافقون: 9","question":"ما سر قوله: ﴿وَمَنْ يَفْعَلْ ذَلِكَ﴾ دون «ومن تُلهِه تلك» أو «ومن فعل»؟","answer":"نسب الفعل إلى الشخص ليدل على أن الانصراف عن اللهو بمقدوره وأنه من كسبه فينال جزاءه. وجاء بالمضارع لأن الالتهاء بالأموال والأولاد أمر يومي متكرر، ولو قال «ومن فعل» لاحتمل أن ذلك الخسران الكبير يقع ولو فُعل مرة واحدة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص183.","url":""}]},{"id":"s63-22","number":22,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما دلالة «مِن» وإسناد الرزق في قوله: ﴿وَأَنْفِقُوا مِنْ مَا رَزَقْنَاكُمْ﴾؟","answer":"الأمر بالإنفاق يقابل قول المنافقين: ﴿لَا تُنْفِقُوا عَلَى مَنْ عِنْدَ رَسُولِ اللَّهِ﴾. و«مِن» للتبعيض فتستسهل النفوس التخلي عن قسم من المال لا كله، وأسند الرزق إلى نفسه ليدل على أن المال من رزق الله فتطيب النفوس بإخراج بعضه.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص185.","url":""}]},{"id":"s63-23","number":23,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما دلالة «مِن» وتقديم المفعول على الفاعل في قوله: ﴿مِنْ قَبْلِ أَنْ يَأْتِيَ أَحَدَكُمُ الْمَوْتُ﴾؟","answer":"«مِن» تفيد ابتداء الغاية الزمانية، أي الزمن المتصل بالموت، ففيها إشارة إلى قربه وطلب التعجيل، وحذفها يفيد الوقت الذي قبل الموت قريبًا أو بعيدًا. وقدّم المفعول لأنه المهم هنا، فهو المعنيّ بالإنفاق وهو المتحسر النادم إذا عاجله الموت.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص185–186.","url":""}]},{"id":"s63-24","number":24,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما سر إثبات الياء في ﴿أَخَّرْتَنِي﴾، وحذفها في قول إبليس: ﴿لَئِنْ أَخَّرْتَنِ إِلَى يَوْمِ الْقِيَامَةِ﴾؟","answer":"هذا الطالب يريد التأخير لنفسه حقًا ولا شيء ألزم منه لمصلحته فأظهر الضمير، وإبليس لا يريده لنفسه بل ليُضلّ ذرية آدم فحذفه واجتزأ بالكسرة. ثم إن ﴿لَوْلَا أَخَّرْتَنِي﴾ طلب صريح، وكلام إبليس شرط دخل عليه القسم، فصرّح بالضمير في الطلب الصريح.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص188–189؛ وبلاغة الكلمة في التعبير القرآني، ص24.","url":""}]},{"id":"s63-25","number":25,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما سر التعبير بـ«لولا» والفعل الماضي في قوله: ﴿لَوْلَا أَخَّرْتَنِي﴾ دون «لو أخرتني» أو «لولا تؤخرني»؟","answer":"«لولا» أشدّ في الطلب من «لو» وفيها إلحاح وتنديم، و«لو» قد تفيد العرض الخفيف أو التمني الميؤوس منه، وهذا طالب لا متمنٍّ. وجاء بالماضي لأن المحذور وقع، والمضارع قد يفيد أن الأمر لم يقع بعد وأن فيه سعة، مع ما في دخول «لولا» على الماضي من قوة الطلب.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص187.","url":""}]},{"id":"s63-26","number":26,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ما سر قوله: ﴿فَأَصَّدَّقَ﴾ دون «فأتصدّق» الذي هو الأصل؟","answer":"مقاطع «فأصّدّق» خمسة ومقاطع «فأتصدّق» ستة، فاختار الأقصر لتناسب طلب التأخير إلى أجل قريب. وفيها تضعيفان في الصاد والدال، والتضعيف يدل على المبالغة والتكثير، فدلّ على أنه أراد أجلًا قريبًا يُكثر فيه من الصدقة.","sources":[{"label":"فاضل السامرائي، لمسات بيانية في نصوص من التنزيل، ص191–192. المصادر","url":""}]},{"id":"s64-35","number":35,"surah":64,"verses":[9],"references":[{"surah":64,"verses":[9]}],"verseLabel":"التغابن: 9","question":"ما الفرق بين التعبير بالفعل في ﴿يَوْمَ يَجْمَعُكُمْ لِيَوْمِ الْجَمْعِ﴾ وباسم المفعول في ﴿ذَلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ﴾؟","answer":"آثر في هود اسم المفعول «مجموع» على الفعل المستقبل «يُجمَع» لما فيه من الدلالة على ثبات معنى الجمع لليوم وأنه موصوف بهذه الصفة، ويظهر ذلك بالموازنة بآية التغابن التي جاءت بالفعل الدال على الحدوث. وهذا التوجيه منقول عن «المثل السائر».","sources":[{"label":"فاضل السامرائي، معاني الأبنية في العربية، ص13.","url":""}]},{"id":"s64-36","number":36,"surah":64,"verses":[9],"references":[{"surah":64,"verses":[9]}],"verseLabel":"التغابن: 9","question":"ما سر زيادة ﴿يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ﴾ هنا، ولم ترد في نظيرتها من سورة الطلاق؟","answer":"آية التغابن خطاب للكافرين ودعوة لهم إلى الإيمان بعد قوله: ﴿زَعَمَ الَّذِينَ كَفَرُوا﴾ و﴿فَآمِنُوا بِاللَّهِ وَرَسُولِهِ﴾، وآية الطلاق خطاب للمؤمنين ودعوة إلى التقوى. فكان ذكر تكفير السيئات مع الكافرين الذين هم في معصية مستديمة أولى من ذكره مع المؤمنين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص111–112.","url":""}]},{"id":"s64-37","number":37,"surah":64,"verses":[11],"references":[{"surah":64,"verses":[11]}],"verseLabel":"التغابن: 11","question":"ما سر الإجمال في ﴿مَا أَصَابَ مِنْ مُصِيبَةٍ﴾، وقد زاد في الحديد: ﴿فِي الْأَرْضِ وَلَا فِي أَنْفُسِكُمْ﴾؟","answer":"فصّل في سورة الحديد أحوال الدنيا والآخرة في قوله: ﴿اعْلَمُوا أَنَّمَا الْحَيَاةُ الدُّنْيَا لَعِبٌ وَلَهْوٌ﴾ وما بعدها، ولم يرد مثل ذلك في التغابن، فزاد التفصيل هناك موافقةً لما قبلها وأجمل هنا. وهذا التوجيه منقول عن «البرهان» للكرماني.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص116–117.","url":""}]},{"id":"s64-38","number":38,"surah":64,"verses":[17],"references":[{"surah":64,"verses":[17]}],"verseLabel":"التغابن: 17","question":"ما سر التعبير بصيغة المبالغة في قوله: ﴿وَاللَّهُ شَكُورٌ حَلِيمٌ﴾ دون «شاكر»؟","answer":"كل ما ذكر الله فيه عن نفسه أنه «شكور» ورد في سياق مضاعفة الأجور والزيادة من فضله، وهنا قال: ﴿يُضَاعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ﴾، فناسبته صيغة المبالغة. أما اسم الفاعل «شاكر» فيستعمله حيث لا يقتضي المقام المبالغة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص33. المصادر","url":""}]},{"id":"s65-29","number":29,"surah":65,"verses":[4],"references":[{"surah":65,"verses":[4]}],"verseLabel":"الطلاق: 4","question":"ما سر التعبير بـ«أشهر» في قوله: ﴿فَعِدَّتُهُنَّ ثَلَاثَةُ أَشْهُرٍ﴾ دون «شهور»؟","answer":"«أشهر» جمع قلة و«شهور» جمع كثرة، فاستعمل القرآن «الأشهر» للقلة كما هنا وفي ﴿الْحَجُّ أَشْهُرٌ مَعْلُومَاتٌ﴾ و﴿أَرْبَعَةَ أَشْهُرٍ﴾، واستعمل «الشهور» لما زاد على العشرة في ﴿إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللَّهِ اثْنَا عَشَرَ شَهْرًا﴾.","sources":[{"label":"فاضل السامرائي، الصرف العربي أحكام ومعان، ص155؛ ومعاني الأبنية في العربية، ص119.","url":""}]},{"id":"s65-30","number":30,"surah":65,"verses":[4,6],"references":[{"surah":65,"verses":[4,6]}],"verseLabel":"الطلاق: 4، 6","question":"ما سر الجمع في ﴿وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ﴾، والإفراد في ﴿وَإِنْ كُنَّ أُولَاتِ حَمْلٍ فَأَنْفِقُوا عَلَيْهِنَّ﴾؟","answer":"الآيتان في المطلَّقات، غير أن الأولى عامة لا تفاوت فيها، فكل أولات الأحمال أجلهن وضع الحمل فجمع. أما الثانية فهن متفاوتات في مقدار النفقة بحسب سعة الزوج، وفي التوافق على الإرضاع أو التعاسر، فلما شمل الحكم بعضًا دون بعض جاء بالمفرد الذي هو أقل في الدلالة من الجمع.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص104–106.","url":""}]},{"id":"s65-31","number":31,"surah":65,"verses":[8],"references":[{"surah":65,"verses":[8]}],"verseLabel":"الطلاق: 8","question":"ما دلالة التعبير بـ«كأيِّن» في قوله: ﴿وَكَأَيِّنْ مِنْ قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِ﴾ دون «كم»؟","answer":"«كأيّن» تُستعمل في مواطن التفخيم والتعظيم إضافة إلى التكثير، كأنه قال: وكم من قرية أيّة قرية، وفي «أي» المبهمة إشعار بذلك. والتفخيم هنا لله الذي أخذ مثل هذه القرى المتجبرة العاتية، وليس السياق كذلك في آية الأعراف ﴿وَكَمْ مِنْ قَرْيَةٍ أَهْلَكْنَاهَا﴾.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج2، ص342–343.","url":""}]},{"id":"s65-32","number":32,"surah":65,"verses":[8],"references":[{"surah":65,"verses":[8]}],"verseLabel":"الطلاق: 8","question":"ما سر قوله: ﴿عَذَابًا نُكْرًا﴾ بسكون الكاف، وقد قال في القمر: ﴿إِلَى شَيْءٍ نُكُرٍ﴾ بضمتين؟","answer":"«نُكُر» بضمتين أشدّ وأثقل من «نُكْر» لما فيه من توالي ثقيلين، وموقف القمر هول القيامة الذي لم يُعهد له نظير. أما عقوبات آية الطلاق ففي الدنيا، فليست نكارتها كنكارة عذاب الآخرة، فجعل الوصف أخف، وليس ذلك للفاصلة فقط.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص170–171.","url":""}]},{"id":"s65-33","number":33,"surah":65,"verses":[9],"references":[{"surah":65,"verses":[9]}],"verseLabel":"الطلاق: 9","question":"ما دلالة التعبير بـ«الخُسْر» في قوله: ﴿وَكَانَ عَاقِبَةُ أَمْرِهَا خُسْرًا﴾ دون «خَسَارًا» أو «خُسْرَانًا»؟","answer":"استعمل القرآن «الخُسر» لعموم الخسارة قليلةً كانت أو كثيرة، فهو لمطلق الخسارة، وهي هنا خسارة كبيرة. أما «الخَسار» فاستعمله للزيادة على الخسارة القائمة، كقوله: ﴿وَلَا يَزِيدُ الظَّالِمِينَ إِلَّا خَسَارًا﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص12–13.","url":""}]},{"id":"s65-34","number":34,"surah":65,"verses":[11],"references":[{"surah":65,"verses":[11]}],"verseLabel":"الطلاق: 11","question":"ما سر الإفراد في ﴿وَمَنْ يُؤْمِنْ بِاللَّهِ … يُدْخِلْهُ﴾ ثم الجمع في ﴿خَالِدِينَ فِيهَا﴾ ثم الإفراد في ﴿قَدْ أَحْسَنَ اللَّهُ لَهُ رِزْقًا﴾؟","answer":"حمل أولًا على لفظ «مَن» ثم على معناها في ﴿خَالِدِينَ﴾ ليدل على أنهم جمع لا واحد، ولأن الاجتماع أدنى إلى الأنس فهو زيادة في الإنعام. ثم عاد إلى الإفراد في ﴿لَهُ رِزْقًا﴾ للدلالة على رعاية كل فرد بعينه، فلا يضيع في غمرة الكثرة.","sources":[{"label":"فاضل السامرائي، الجملة العربية والمعنى، ص124–125.","url":""}]},{"id":"s65-35","number":35,"surah":65,"verses":[11],"references":[{"surah":65,"verses":[11]}],"verseLabel":"الطلاق: 11","question":"ما سر الاقتصار على ﴿يُدْخِلْهُ جَنَّاتٍ﴾ هنا، وقد زاد في التغابن: ﴿يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ﴾؟","answer":"آية الطلاق خطاب للمؤمنين ودعوة إلى التقوى: ﴿فَاتَّقُوا اللَّهَ يَا أُولِي الْأَلْبَابِ الَّذِينَ آمَنُوا﴾، وآية التغابن خطاب للكافرين ودعوة لهم إلى الإيمان. فكان ذكر تكفير السيئات مع الكافرين الذين هم في معصية مستديمة أولى من ذكره مع المؤمنين.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص111–112.","url":""}]},{"id":"s66-30","number":30,"surah":66,"verses":[1],"references":[{"surah":66,"verses":[1]}],"verseLabel":"التحريم: 1","question":"ما سر التعبير بـ«المرضاة» في قوله: ﴿تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ﴾ دون «الرضوان»؟","answer":"الرضوان أكبر الرضا وأعظمه، ولذلك اختص في القرآن برضا الله ولم يُستعمل مع غيره. أما المرضاة فعامة في مرضاة الله وغيره، خاصة بالابتغاء، ولذا استُعملت هنا في مرضاة الأزواج.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص14–15.","url":""}]},{"id":"s66-31","number":31,"surah":66,"verses":[3],"references":[{"surah":66,"verses":[3]}],"verseLabel":"التحريم: 3","question":"ما سر التعبير بـ﴿نَبَّأَتْ بِهِ﴾ ثم ﴿مَنْ أَنْبَأَكَ هَذَا﴾ ثم ﴿نَبَّأَنِيَ الْعَلِيمُ الْخَبِيرُ﴾؟","answer":"«نبّأ» يقتضي تنبيئًا أكثر من «أنبأ»، كـ«علّم وأعلم». فلما عرّف بعض الحديث وأعرض عن بعض كأنما ذكر قسمًا من النبأ، فقالت: ﴿مَنْ أَنْبَأَكَ هَذَا﴾ أي هذا الجزء منه، فذكر أن العليم الخبير نبّأه به كله.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص106.","url":""}]},{"id":"s66-32","number":32,"surah":66,"verses":[4],"references":[{"surah":66,"verses":[4]}],"verseLabel":"التحريم: 4","question":"ما سر الجمع في قوله: ﴿فَقَدْ صَغَتْ قُلُوبُكُمَا﴾ والقياس «قلباكما»؟","answer":"المثنى المضاف إلى متضمّنه الأحسن أن يُعبَّر عنه بالجمع، كـ«قطعت رؤوس الكبشين»، وذلك لكراهة اجتماع تثنيتين ما لم يُؤدّ إلى اللبس، إذ ليس لكل واحدة منهما إلا قلب واحد. وفي «الكتاب» لسيبويه و«شرح الرضي» نحو هذا.","sources":[{"label":"فاضل السامرائي، الجملة العربية تأليفها وأقسامها، ص123؛ والجملة العربية والمعنى، ص136.","url":""}]},{"id":"s66-33","number":33,"surah":66,"verses":[4],"references":[{"surah":66,"verses":[4]}],"verseLabel":"التحريم: 4","question":"ما سر مجيء الشرط بالمضارع في قوله: ﴿إِنْ تَتُوبَا إِلَى اللَّهِ﴾، وقد جاء بالماضي في ﴿فَإِنْ تَابُوا﴾ و﴿فَإِنْ تَابَا﴾؟","answer":"الماضي في آيتي التوبة والنساء للتوبة العامة، كالدخول في الإسلام أو الانخلاع عن الفاحشة. أما هنا فالكلام موجه إلى زوجَي النبي، والمقصود التوبة الجزئية العارضة التي يتكرر أمثالها من الوقوع في اللمم والصغائر، فجاء بالمضارع الدال على التجدد.","sources":[{"label":"فاضل السامرائي، معاني النحو، ج4، ص59–60.","url":""}]},{"id":"s66-34","number":34,"surah":66,"verses":[5],"references":[{"surah":66,"verses":[5]}],"verseLabel":"التحريم: 5","question":"ما سر التعبير باسم الفاعل في ﴿تَائِبَاتٍ﴾ دون صيغة المبالغة «توّابات»؟","answer":"جاءت الآية تعقيبًا على حديث السر وما وقع من بعض أزواج النبي مما يقع بين الضرائر، وهذا تكفي فيه التوبة ولا يستدعي المبالغة فيها. فالمبالغة في التوبة تكون من الآثام الكبيرة، إذ التوبة على قدر الذنب، بخلاف ﴿إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ﴾ في البقرة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص30.","url":""}]},{"id":"s66-35","number":35,"surah":66,"verses":[12],"references":[{"surah":66,"verses":[12]}],"verseLabel":"التحريم: 12","question":"ما سر ضمير الجمع في ﴿فَنَفَخْنَا فِيهِ مِنْ رُوحِنَا﴾، وقد قال في آدم: ﴿وَنَفَخْتُ فِيهِ مِنْ رُوحِي﴾؟","answer":"لأن النافخ في مريم هو رسوله الذي تمثّل لها بشرًا سويًا، وليس الأمر كذلك في آدم، فجاء فيه بضمير الإفراد: ﴿وَنَفَخْتُ﴾ و﴿وَنَفَخَ فِيهِ مِنْ رُوحِهِ﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص161.","url":""}]},{"id":"s66-36","number":36,"surah":66,"verses":[12],"references":[{"surah":66,"verses":[12]}],"verseLabel":"التحريم: 12","question":"ما سر قوله: ﴿فَنَفَخْنَا فِيهِ﴾ هنا، و﴿فَنَفَخْنَا فِيهَا﴾ في الأنبياء؟","answer":"﴿فِيهَا﴾ أعمّ لأنه يعمّها كلها، و﴿فِيهِ﴾ أخصّ لأنه أشار إلى موضع النفخ. وآية التحريم أخصّ لأنها عيّنتها بالاسم والوصف، وآية الأنبياء أعمّ لأنها بالوصف وحده وذكرت ابنها معها، فناسب العمومُ العمومَ والخصوصُ الخصوصَ.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص160.","url":""}]},{"id":"s67-30","number":30,"surah":67,"verses":[2],"references":[{"surah":67,"verses":[2]}],"verseLabel":"الملك: 2","question":"ما سر التخفيف في ﴿لِيَبْلُوَكُمْ﴾، في حين جاء في سورة الإنسان ﴿نَبْتَلِيهِ﴾ بالصيغة الأطول؟","answer":"سورة الملك ختمت الآية بـ﴿الْغَفُورُ﴾، والمغفرة تلائم التخفيف، كما أنها لم تفصّل وسائل الابتلاء وأعمال الفريقين. أما سورة الإنسان ففصّلت السمع والبصر والهداية وأعمال الأبرار والكافرين وجزاءهم؛ فناسب تفصيلُ المعنى وزيادةُ شدته الصيغةَ الأطول نبتليه، وناسب الإيجاز في الملك ليبلوكم.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج1، ص210–216، مبحث الفرق بين ﴿نبتليه﴾ و﴿ليبلوكم﴾. والنص موثق إلكترونيًا في تدارس القرآن الكريم.","url":""}]},{"id":"s67-31","number":31,"surah":67,"verses":[9],"references":[{"surah":67,"verses":[9]}],"verseLabel":"الملك: 9","question":"ما سر قول أهل النار ﴿مَا نَزَّلَ اللَّهُ مِنْ شَيْءٍ﴾، بينما جاء في يس ﴿وَمَا أَنْزَلَ الرَّحْمَنُ مِنْ شَيْءٍ﴾؟","answer":"سورة الملك يشيع فيها الوعيد ومشاهد النار والتحذير من البطش، فلم يناسب هذا المقام أن تُحكى مقالتهم باسم الرحمن. أما سورة يس فالإرسال فيها رحمة، وذُكر فيها أصحاب الجنة، وتكرر اسم الرحمن؛ فجاء كل اسم موافقًا للجو الغالب في سورته.","sources":[{"label":"فاضل السامرائي، على طريق التفسير البياني، ج2، ص81–82، مبحث ﴿وما أنزل الرحمن من شيء﴾ و﴿ما نزل الله من شيء﴾. والنص موثق إلكترونيًا في تدارس القرآن الكريم.","url":""}]}]);
